import gzip
import base64
import yaml
from typing import Dict, Any, List


def process_signature_appearance_package(
    package_bytes: bytes,
    max_uncompressed_size: int = 1024 * 1024,
    max_image_bytes: int = 512 * 1024,
    max_font_bytes: int = 256 * 1024,
    max_layout_depth: int = 10,
) -> Dict[str, Any]:
    """
    Process a signature appearance package uploaded by a signer.

    The package is a gzip-compressed YAML document containing the visual
    representation of a signature for embedding in signed PDFs. The YAML
    structure must have exactly three top-level keys:

    - 'images': list of base64-encoded PNG or JPEG images (user-controlled)
    - 'fonts': list of base64-encoded TTF or WOFF font files (user-controlled)
    - 'layout': dict with positioning/scaling instructions (user-controlled)

    Args:
        package_bytes: Raw uploaded package bytes from the signer's client.
        max_uncompressed_size: Maximum allowed size of decompressed YAML in bytes.
        max_image_bytes: Maximum allowed size per decoded image in bytes.
        max_font_bytes: Maximum allowed size per decoded font in bytes.
        max_layout_depth: Maximum allowed nesting depth of the layout dict.

    Returns:
        Dict with validated 'images' (List[bytes]), 'fonts' (List[bytes]),
        and 'layout' (Dict) keys. Returns empty dict if the package is
        malformed, exceeds any limit, or contains invalid base64.
    """
    if not package_bytes:
        return {}

    if len(package_bytes) > max_uncompressed_size:
        return {}

    try:
        decompressed = gzip.decompress(package_bytes)
    except (gzip.BadGzipFile, OSError, EOFError):
        return {}

    if len(decompressed) > max_uncompressed_size:
        return {}

    try:
        parsed = yaml.safe_load(decompressed)
    except yaml.YAMLError:
        return {}

    if not isinstance(parsed, dict):
        return {}

    required_keys = {"images", "fonts", "layout"}
    if set(parsed.keys()) != required_keys:
        return {}

    def check_depth(obj: Any, current_depth: int = 0) -> bool:
        if current_depth > max_layout_depth:
            return False
        if isinstance(obj, dict):
            return all(check_depth(v, current_depth + 1) for v in obj.values())
        if isinstance(obj, list):
            return all(check_depth(v, current_depth + 1) for v in obj)
        return True

    if not check_depth(parsed["layout"]):
        return {}

    images_out: List[bytes] = []
    for img_b64 in parsed["images"]:
        if not isinstance(img_b64, str):
            return {}
        try:
            img_bytes = base64.b64decode(img_b64, validate=True)
        except Exception:
            return {}
        if len(img_bytes) > max_image_bytes:
            return {}
        images_out.append(img_bytes)

    fonts_out: List[bytes] = []
    for font_b64 in parsed["fonts"]:
        if not isinstance(font_b64, str):
            return {}
        try:
            font_bytes = base64.b64decode(font_b64, validate=True)
        except Exception:
            return {}
        if len(font_bytes) > max_font_bytes:
            return {}
        fonts_out.append(font_bytes)

    return {
        "images": images_out,
        "fonts": fonts_out,
        "layout": parsed["layout"],
    }
