import ast
import operator
from typing import Any


def evaluate_hook_condition(expression: str, context: dict[str, Any]) -> bool:
    """
    Evaluate a package lifecycle hook condition expression against a context.

    Package authors define hook conditions in package metadata as expressions
    that determine whether a lifecycle hook (pre_install, post_install, etc.)
    should execute. This function evaluates such expressions safely.

    Args:
        expression: A condition expression string from package metadata.
            Comes from package authors (potentially untrusted third parties).
            Expected format: simple comparisons and boolean logic using
            context variables (e.g., "python_version >= '3.8' and os != 'windows'").
        context: Dictionary of variable names to values for evaluation.
            Provided by the registry at hook execution time (trusted).
            Typical keys: python_version, platform, os, arch, package_version.

    Returns:
        True if the condition evaluates to truthy, False if falsy or if
        the expression is invalid/malformed.
    """
    if not isinstance(expression, str) or not expression.strip():
        return False

    try:
        tree = ast.parse(expression, mode='eval')
    except (SyntaxError, ValueError, TypeError):
        return False

    _ALLOWED_OPS = {
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
        ast.And: lambda a, b: a and b,
        ast.Or: lambda a, b: a or b,
        ast.Not: operator.not_,
        ast.In: lambda a, b: a in b,
        ast.NotIn: lambda a, b: a not in b,
    }

    _ALLOWED_NODES = {
        ast.Expression, ast.BoolOp, ast.UnaryOp, ast.Compare,
        ast.Name, ast.Constant, ast.List, ast.Tuple, ast.Set,
        ast.Load,
    }

    def _eval(node: ast.AST) -> Any:
        if type(node) not in _ALLOWED_NODES:
            raise ValueError(f"Disallowed node type: {type(node).__name__}")

        if isinstance(node, ast.Expression):
            return _eval(node.body)

        if isinstance(node, ast.BoolOp):
            op_type = type(node.op)
            if op_type not in _ALLOWED_OPS:
                raise ValueError(f"Disallowed bool op: {op_type.__name__}")
            values = [_eval(v) for v in node.values]
            if op_type is ast.And:
                return all(values)
            if op_type is ast.Or:
                return any(values)
            return _ALLOWED_OPS[op_type](values[0], values[1])

        if isinstance(node, ast.UnaryOp):
            if type(node.op) not in _ALLOWED_OPS:
                raise ValueError(f"Disallowed unary op: {type(node.op).__name__}")
            return _ALLOWED_OPS[type(node.op)](_eval(node.operand))

        if isinstance(node, ast.Compare):
            left = _eval(node.left)
            for op, comparator in zip(node.ops, node.comparators):
                op_type = type(op)
                if op_type not in _ALLOWED_OPS:
                    raise ValueError(f"Disallowed comparison: {op_type.__name__}")
                right = _eval(comparator)
                if not _ALLOWED_OPS[op_type](left, right):
                    return False
                left = right
            return True

        if isinstance(node, ast.Name):
            if node.id not in context:
                raise ValueError(f"Undefined variable: {node.id}")
            return context[node.id]

        if isinstance(node, ast.Constant):
            return node.value

        if isinstance(node, ast.List):
            return [_eval(e) for e in node.elts]
        if isinstance(node, ast.Tuple):
            return tuple(_eval(e) for e in node.elts)
        if isinstance(node, ast.Set):
            return {_eval(e) for e in node.elts}

        raise ValueError(f"Unhandled node: {type(node).__name__}")

    try:
        result = _eval(tree)
        return bool(result)
    except (ValueError, TypeError, KeyError, AttributeError, RecursionError):
        return False
