import ast
from typing import Callable, Dict, Any, Optional, Set


_ALLOWED_STORAGE_CLASSES: Set[str] = {
    'STANDARD', 'INTELLIGENT_TIERING', 'STANDARD_IA', 'ONEZONE_IA',
    'GLACIER_IR', 'GLACIER', 'DEEP_ARCHIVE', 'OUTPOSTS', 'SNOW'
}

_ALLOWED_NODE_TYPES: Set[type] = {
    ast.Expression, ast.BoolOp, ast.BinOp, ast.UnaryOp, ast.Compare,
    ast.IfExp, ast.Call, ast.Attribute, ast.Name, ast.Constant,
    ast.Subscript, ast.Index, ast.Load, ast.And, ast.Or, ast.Not,
    ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE,
    ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Mod, ast.Pow,
    ast.USub, ast.UAdd,
}

_ALLOWED_METHODS: Set[str] = {'get'}


class _RuleValidator(ast.NodeVisitor):
    """Validate that the AST contains only allowed constructs."""

    def __init__(self) -> None:
        self.valid = True
        self._errors: list[str] = []

    def visit(self, node: ast.AST) -> None:
        if not self.valid:
            return
        if type(node) not in _ALLOWED_NODE_TYPES:
            self.valid = False
            self._errors.append(f"Disallowed node type: {type(node).__name__}")
            return
        super().visit(node)

    def visit_Name(self, node: ast.Name) -> None:
        if node.id != 'meta':
            self.valid = False
            self._errors.append(f"Disallowed name: {node.id}")
        self.generic_visit(node)

    def visit_Call(self, node: ast.Call) -> None:
        if not isinstance(node.func, ast.Attribute):
            self.valid = False
            self._errors.append("Only method calls on 'meta' are allowed")
            return
        if not isinstance(node.func.value, ast.Name) or node.func.value.id != 'meta':
            self.valid = False
            self._errors.append("Only methods on 'meta' are allowed")
            return
        if node.func.attr not in _ALLOWED_METHODS:
            self.valid = False
            self._errors.append(f"Disallowed method: {node.func.attr}")
            return
        if len(node.args) > 1 or (len(node.args) == 1 and not isinstance(node.args[0], ast.Constant)):
            self.valid = False
            self._errors.append("meta.get() only accepts a single string literal argument")
            return
        self.generic_visit(node)

    def visit_Attribute(self, node: ast.Attribute) -> None:
        if not isinstance(node.value, ast.Name) or node.value.id != 'meta':
            self.valid = False
            self._errors.append(f"Disallowed attribute access")
            return
        if node.attr != 'get':
            self.valid = False
            self._errors.append(f"Disallowed attribute: {node.attr}")
            return
        self.generic_visit(node)

    def visit_Constant(self, node: ast.Constant) -> None:
        self.generic_visit(node)


def _safe_eval(node: ast.AST, meta: Dict[str, Any]) -> Any:
    """Safely evaluate a validated AST node, mimicking Python semantics."""
    if isinstance(node, ast.Expression):
        return _safe_eval(node.body, meta)

    if isinstance(node, ast.BoolOp):
        if isinstance(node.op, ast.And):
            result = None
            for value in node.values:
                result = _safe_eval(value, meta)
                if not result:
                    return result
            return result
        if isinstance(node.op, ast.Or):
            result = None
            for value in node.values:
                result = _safe_eval(value, meta)
                if result:
                    return result
            return result
        raise ValueError("Unsupported bool op")

    if isinstance(node, ast.Compare):
        left = _safe_eval(node.left, meta)
        for op, comparator in zip(node.ops, node.comparators):
            right = _safe_eval(comparator, meta)
            if isinstance(op, ast.Eq):
                result = left == right
            elif isinstance(op, ast.NotEq):
                result = left != right
            elif isinstance(op, ast.Lt):
                result = left < right
            elif isinstance(op, ast.LtE):
                result = left <= right
            elif isinstance(op, ast.Gt):
                result = left > right
            elif isinstance(op, ast.GtE):
                result = left >= right
            else:
                raise ValueError("Unsupported comparison")
            if not result:
                return False
            left = right
        return True

    if isinstance(node, ast.IfExp):
        test = _safe_eval(node.test, meta)
        return _safe_eval(node.body, meta) if test else _safe_eval(node.orelse, meta)

    if isinstance(node, ast.Call):
        if isinstance(node.func, ast.Attribute) and node.func.attr == 'get':
            key = node.args[0].value if node.args else None
            return meta.get(key)

    if isinstance(node, ast.Constant):
        return node.value

    if isinstance(node, ast.Name):
        if node.id == 'meta':
            return meta
        raise ValueError(f"Unknown name: {node.id}")

    if isinstance(node, ast.BinOp):
        left = _safe_eval(node.left, meta)
        right = _safe_eval(node.right, meta)
        if isinstance(node.op, ast.Add):
            return left + right
        if isinstance(node.op, ast.Sub):
            return left - right
        if isinstance(node.op, ast.Mult):
            return left * right
        if isinstance(node.op, ast.Div):
            return left / right
        if isinstance(node.op, ast.Mod):
            return left % right
        if isinstance(node.op, ast.Pow):
            return left ** right
        raise ValueError("Unsupported binary op")

    if isinstance(node, ast.UnaryOp):
        operand = _safe_eval(node.operand, meta)
        if isinstance(node.op, ast.USub):
            return -operand
        if isinstance(node.op, ast.UAdd):
            return +operand
        if isinstance(node.op, ast.Not):
            return not operand
        raise ValueError("Unsupported unary op")

    raise ValueError(f"Unsupported node type: {type(node).__name__}")


def compile_storage_class_selector(rule_source: str) -> Optional[Callable[[Dict[str, Any]], str]]:
    """
    Compile a user-provided storage class selection rule into a callable.

    The rule source is a restricted Python expression that evaluates to a storage
    class name (string) based on the file's metadata dictionary. The expression
    receives a single variable `meta` which is a dict containing file metadata
    (e.g., size, content_type, tags, custom_fields).

    Allowed constructs in the rule source:
    - Comparisons: ==, !=, <, >, <=, >=
    - Boolean operators: and, or, not
    - Ternary conditional: x if cond else y
    - Attribute access on `meta` via .get() method only (e.g., meta.get('size'))
    - String literals, integer/float literals
    - Parentheses for grouping
    - Standard storage class names: 'STANDARD', 'INTELLIGENT_TIERING', 'STANDARD_IA',
      'ONEZONE_IA', 'GLACIER_IR', 'GLACIER', 'DEEP_ARCHIVE', 'OUTPOSTS', 'SNOW'

    The rule source comes from user configuration (untrusted input).

    Args:
        rule_source: A string containing the selection rule expression.

    Returns:
        A callable that accepts a metadata dict and returns a storage class string,
        or None if the rule source is invalid or contains disallowed constructs.
    """
    if not rule_source or not isinstance(rule_source, str):
        return None

    rule_source = rule_source.strip()
    if not rule_source:
        return None

    try:
        tree = ast.parse(rule_source, mode='eval')
    except SyntaxError:
        return None

    validator = _RuleValidator()
    validator.visit(tree)
    if not validator.valid:
        return None

    def selector(meta: Dict[str, Any]) -> str:
        try:
            result = _safe_eval(tree, meta)
            if isinstance(result, str) and result in _ALLOWED_STORAGE_CLASSES:
                return result
        except Exception:
            pass
        return 'STANDARD'

    return selector
