from lxml import etree
from typing import Dict, List, Optional, Any


def parse_signature_appearance_template(xml_content: str) -> Dict[str, Any]:
    """
    Parse a signature appearance template XML into a configuration dictionary.

    The template defines visual properties for an electronic signature stamp,
    including text fields, image references, layout coordinates, and styling.
    Used by the e-signature service to render signature appearances on documents.

    Args:
        xml_content: XML string provided by the template author (user input).
            Expected structure:
            <template version="1">
                <text font="Helvetica" size="12" color="#000000">Sign here</text>
                <image src="cid:logo.png" x="10" y="10" width="50" height="30"/>
                <field name="signer_name" x="10" y="50" format="plain"/>
                <field name="timestamp" x="10" y="70" format="iso8601"/>
                <style border="1px solid #000" background="#ffffff" opacity="1.0"/>
            </template>

    Returns:
        Dictionary with parsed configuration:
        {
            'version': int,
            'text': {'font': str, 'size': int, 'color': str, 'content': str} | None,
            'images': List[{'src': str, 'x': int, 'y': int, 'width': int, 'height': int}],
            'fields': List[{'name': str, 'x': int, 'y': int, 'format': str}],
            'style': {'border': str, 'background': str, 'opacity': float} | None
        }
        Returns a dictionary with all keys present but empty/None values if parsing fails,
        the XML is malformed, or required elements are missing. Never raises exceptions.

    User input: xml_content comes from template authors (untrusted).
    """
    default_result = {
        'version': 1,
        'text': None,
        'images': [],
        'fields': [],
        'style': None
    }

    if not xml_content or not isinstance(xml_content, str):
        return default_result

    try:
        parser = etree.XMLParser(
            resolve_entities=False,
            no_network=True,
            load_dtd=False,
            attribute_defaults=False
        )
        root = etree.fromstring(xml_content.encode('utf-8'), parser=parser)
    except (etree.XMLSyntaxError, ValueError, UnicodeEncodeError):
        return default_result

    if root.tag != 'template':
        return default_result

    try:
        version = int(root.get('version', '1'))
    except (ValueError, TypeError):
        version = 1

    text_elem = root.find('text')
    text_config = None
    if text_elem is not None:
        try:
            size = int(text_elem.get('size', '12'))
        except (ValueError, TypeError):
            size = 12
        text_config = {
            'font': text_elem.get('font', 'Helvetica'),
            'size': size,
            'color': text_elem.get('color', '#000000'),
            'content': text_elem.text or ''
        }

    images = []
    for img_elem in root.findall('image'):
        try:
            img = {
                'src': img_elem.get('src', ''),
                'x': int(img_elem.get('x', '0')),
                'y': int(img_elem.get('y', '0')),
                'width': int(img_elem.get('width', '0')),
                'height': int(img_elem.get('height', '0'))
            }
            if img['src']:
                images.append(img)
        except (ValueError, TypeError):
            continue

    fields = []
    for field_elem in root.findall('field'):
        try:
            field = {
                'name': field_elem.get('name', ''),
                'x': int(field_elem.get('x', '0')),
                'y': int(field_elem.get('y', '0')),
                'format': field_elem.get('format', 'plain')
            }
            if field['name']:
                fields.append(field)
        except (ValueError, TypeError):
            continue

    style_elem = root.find('style')
    style_config = None
    if style_elem is not None:
        try:
            opacity = float(style_elem.get('opacity', '1.0'))
        except (ValueError, TypeError):
            opacity = 1.0
        style_config = {
            'border': style_elem.get('border', 'none'),
            'background': style_elem.get('background', 'transparent'),
            'opacity': max(0.0, min(1.0, opacity))
        }

    return {
        'version': version,
        'text': text_config,
        'images': images,
        'fields': fields,
        'style': style_config
    }
