import os
import zipfile
import yaml
import shutil
from pathlib import Path
from typing import Dict, Any


def import_community_reading_list_bundle(bundle_zip_path: str, bundle_id: str, base_import_dir: str) -> Dict[str, Any]:
    """
    Import a community reading list bundle from a ZIP archive.

    The bundle must contain:
    - manifest.yaml: with required fields 'title' (str), 'curator' (str),
      'description' (str), 'book_isbns' (list of str)
    - Optional cover image: cover.jpg or cover.png (ignored if missing)

    The bundle is extracted to a subdirectory named {bundle_id} under
    base_import_dir. The manifest is parsed and validated. On success, the
    parsed manifest dict is returned with an added 'bundle_path' key pointing
    to the extraction directory. On any validation failure, extraction error,
    or security violation, an empty dict is returned and any partial extraction
    is cleaned up.

    Args:
        bundle_zip_path: Path to the uploaded ZIP file. This path comes from
            user upload handling and may point anywhere on the filesystem.
        bundle_id: Unique identifier for this bundle (system-generated, e.g.,
            UUID). Trusted input.
        base_import_dir: Base directory for imported bundles (system
            configuration). Trusted input.

    Returns:
        Dict with manifest data and 'bundle_path' on success, empty dict on
        failure.
    """
    # Resolve base directory to absolute path
    base_path = Path(base_import_dir).resolve()
    target_dir = base_path / bundle_id

    # Validate bundle_id doesn't contain path traversal
    if bundle_id != os.path.basename(bundle_id) or ".." in bundle_id:
        return {}

    # Ensure target directory doesn't exist yet
    if target_dir.exists():
        return {}

    # Validate the zip file exists and is readable
    zip_path = Path(bundle_zip_path)
    if not zip_path.is_file():
        return {}

    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # Validate all member paths before extraction
            for member in zf.namelist():
                # Normalize member path
                member_path = Path(member)
                # Check for absolute paths or path traversal
                if member_path.is_absolute() or ".." in member_path.parts:
                    return {}
                # Ensure member stays within target directory when extracted
                resolved_member = (target_dir / member_path).resolve()
                if not resolved_member.is_relative_to(base_path):
                    return {}

            # Validate symlink targets if any
            for info in zf.infolist():
                # Check if entry is a symlink (Unix: 0o120000, Windows: 0xA0000000)
                external_attr = info.external_attr >> 16
                is_symlink = (external_attr & 0o170000) == 0o120000
                if is_symlink:
                    # Read symlink target from the file content
                    with zf.open(info, 'r') as f:
                        target = f.read().decode('utf-8', errors='replace').strip()
                    # Resolve symlink target relative to the symlink's directory
                    symlink_dir = (target_dir / Path(info.filename).parent).resolve()
                    target_path = (symlink_dir / target).resolve()
                    # Ensure symlink target stays within base_path
                    if not target_path.is_relative_to(base_path):
                        return {}

            # All members validated - safe to extract
            target_dir.mkdir(parents=True, exist_ok=True)
            zf.extractall(target_dir)

        # Validate manifest exists
        manifest_path = target_dir / "manifest.yaml"
        if not manifest_path.is_file():
            shutil.rmtree(target_dir, ignore_errors=True)
            return {}

        # Parse and validate manifest
        with open(manifest_path, 'r', encoding='utf-8') as f:
            manifest = yaml.safe_load(f)

        if not isinstance(manifest, dict):
            shutil.rmtree(target_dir, ignore_errors=True)
            return {}

        required_fields = {'title', 'curator', 'description', 'book_isbns'}
        if not all(field in manifest for field in required_fields):
            shutil.rmtree(target_dir, ignore_errors=True)
            return {}

        if not isinstance(manifest['title'], str) or not manifest['title'].strip():
            shutil.rmtree(target_dir, ignore_errors=True)
            return {}
        if not isinstance(manifest['curator'], str) or not manifest['curator'].strip():
            shutil.rmtree(target_dir, ignore_errors=True)
            return {}
        if not isinstance(manifest['description'], str):
            shutil.rmtree(target_dir, ignore_errors=True)
            return {}
        if not isinstance(manifest['book_isbns'], list):
            shutil.rmtree(target_dir, ignore_errors=True)
            return {}
        if not all(isinstance(isbn, str) for isbn in manifest['book_isbns']):
            shutil.rmtree(target_dir, ignore_errors=True)
            return {}

        # Success - add bundle path and return
        manifest['bundle_path'] = str(target_dir)
        return manifest

    except (zipfile.BadZipFile, yaml.YAMLError, OSError, UnicodeDecodeError):
        # Clean up on any error
        if target_dir.exists():
            shutil.rmtree(target_dir, ignore_errors=True)
        return {}
