import ast
from typing import Any


def evaluate_alert_condition(expression: str, device_states: dict[str, Any]) -> bool:
    """
    Evaluate a user-defined alert condition expression against current device states.

    The expression is a boolean expression using device state names as variables,
    comparison operators (==, !=, <, >, <=, >=), and boolean operators (and, or, not).
    Parentheses for grouping are supported. Numeric literals and string literals
    (single or double quoted) are allowed.

    Example expressions:
        "motion_living_room and not home_mode"
        "temperature_bedroom > 24 and window_bedroom_open"
        "humidity_basement >= 70 or water_leak_detected"
        "mode == 'away' and front_door_locked"

    Args:
        expression: User-provided condition string (comes from user configuration).
        device_states: Dictionary mapping device state names to their current values.
                       Values can be booleans, numbers, or strings.

    Returns:
        True if the condition evaluates to true, False otherwise.
        Returns False if expression is empty, invalid, or references unknown devices.

    User inputs:
        - expression: Provided by the user via the automation rule configuration UI.
        - device_states: Collected from hub's device registry (trusted internal source).
    """
    if not expression or not expression.strip():
        return False

    try:
        tree = ast.parse(expression.strip(), mode='eval')
    except SyntaxError:
        return False

    try:
        _validate_ast(tree)
        return _eval_node(tree.body, device_states)
    except (ValueError, KeyError, TypeError, ZeroDivisionError):
        return False


def _validate_ast(node: ast.AST) -> None:
    allowed_node_types = {
        ast.Expression, ast.BoolOp, ast.UnaryOp, ast.Compare,
        ast.Name, ast.Constant, ast.Load,
        ast.And, ast.Or, ast.Not,
        ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE,
    }

    for n in ast.walk(node):
        if type(n) not in allowed_node_types:
            raise ValueError(f"Disallowed node type: {type(n).__name__}")
        if isinstance(n, ast.Constant):
            if not isinstance(n.value, (bool, int, float, str)):
                raise ValueError(f"Disallowed constant type: {type(n.value).__name__}")
        if isinstance(n, ast.Name):
            if not n.id.replace('_', '').isalnum():
                raise ValueError(f"Invalid variable name: {n.id}")


def _eval_node(node: ast.AST, device_states: dict[str, Any]) -> Any:
    if isinstance(node, ast.BoolOp):
        values = [_eval_node(v, device_states) for v in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        elif isinstance(node.op, ast.Or):
            return any(values)
    elif isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
        return not _eval_node(node.operand, device_states)
    elif isinstance(node, ast.Compare):
        left = _eval_node(node.left, device_states)
        for op, right_node in zip(node.ops, node.comparators):
            right = _eval_node(right_node, device_states)
            result = _apply_comparison(left, op, right)
            if not result:
                return False
            left = right
        return True
    elif isinstance(node, ast.Name):
        if node.id not in device_states:
            raise KeyError(f"Unknown device state: {node.id}")
        return device_states[node.id]
    elif isinstance(node, ast.Constant):
        return node.value
    raise ValueError(f"Cannot evaluate node: {type(node).__name__}")


def _apply_comparison(left: Any, op: ast.cmpop, right: Any) -> bool:
    try:
        if isinstance(op, ast.Eq):
            return left == right
        elif isinstance(op, ast.NotEq):
            return left != right
        elif isinstance(op, ast.Lt):
            return left < right
        elif isinstance(op, ast.LtE):
            return left <= right
        elif isinstance(op, ast.Gt):
            return left > right
        elif isinstance(op, ast.GtE):
            return left >= right
    except TypeError:
        return False
    return False
