import ast
import math
from typing import Any


class SafeExpressionEvaluator(ast.NodeVisitor):
    """Safely evaluate a restricted subset of Python expressions."""

    ALLOWED_FUNCTIONS = {'min', 'max', 'abs', 'round', 'pow'}
    ALLOWED_MATH_ATTRS = {'pi', 'e', 'sqrt', 'ceil', 'floor', 'log', 'exp'}

    def __init__(self, variables: dict):
        self.variables = variables
        self.result = None

    def visit_Expression(self, node: ast.Expression) -> Any:
        return self.visit(node.body)

    def visit_BinOp(self, node: ast.BinOp) -> Any:
        left = self.visit(node.left)
        right = self.visit(node.right)
        op = node.op
        if isinstance(op, ast.Add):
            return left + right
        elif isinstance(op, ast.Sub):
            return left - right
        elif isinstance(op, ast.Mult):
            return left * right
        elif isinstance(op, ast.Div):
            return left / right
        elif isinstance(op, ast.FloorDiv):
            return left // right
        elif isinstance(op, ast.Mod):
            return left % right
        elif isinstance(op, ast.Pow):
            return left ** right
        raise ValueError(f"Unsupported binary operator: {type(op).__name__}")

    def visit_UnaryOp(self, node: ast.UnaryOp) -> Any:
        operand = self.visit(node.operand)
        op = node.op
        if isinstance(op, ast.UAdd):
            return +operand
        elif isinstance(op, ast.USub):
            return -operand
        elif isinstance(op, ast.Not):
            return not operand
        elif isinstance(op, ast.Invert):
            return ~operand
        raise ValueError(f"Unsupported unary operator: {type(op).__name__}")

    def visit_Compare(self, node: ast.Compare) -> Any:
        left = self.visit(node.left)
        for op, comparator in zip(node.ops, node.comparators):
            right = self.visit(comparator)
            if isinstance(op, ast.Eq):
                result = left == right
            elif isinstance(op, ast.NotEq):
                result = left != right
            elif isinstance(op, ast.Lt):
                result = left < right
            elif isinstance(op, ast.LtE):
                result = left <= right
            elif isinstance(op, ast.Gt):
                result = left > right
            elif isinstance(op, ast.GtE):
                result = left >= right
            elif isinstance(op, ast.In):
                result = left in right
            elif isinstance(op, ast.NotIn):
                result = left not in right
            else:
                raise ValueError(f"Unsupported comparison operator: {type(op).__name__}")
            left = right
        return result

    def visit_BoolOp(self, node: ast.BoolOp) -> Any:
        values = [self.visit(v) for v in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        elif isinstance(node.op, ast.Or):
            return any(values)
        raise ValueError(f"Unsupported boolean operator: {type(node.op).__name__}")

    def visit_IfExp(self, node: ast.IfExp) -> Any:
        test = self.visit(node.test)
        if test:
            return self.visit(node.body)
        else:
            return self.visit(node.orelse)

    def visit_Name(self, node: ast.Name) -> Any:
        # Allow any variable provided in the variables dict (includes predefined and extra)
        if node.id in self.variables:
            return self.variables[node.id]
        # Allow access to the math module
        if node.id == 'math':
            return math
        raise ValueError(f"Disallowed name: {node.id}")

    def visit_Constant(self, node: ast.Constant) -> Any:
        if isinstance(node.value, (int, float, bool, str, type(None))):
            return node.value
        raise ValueError(f"Disallowed constant type: {type(node.value).__name__}")

    def visit_Call(self, node: ast.Call) -> Any:
        if not isinstance(node.func, ast.Name):
            raise ValueError("Only direct function calls allowed")
        func_name = node.func.id
        if func_name not in self.ALLOWED_FUNCTIONS and func_name not in self.ALLOWED_MATH_ATTRS:
            raise ValueError(f"Disallowed function: {func_name}")
        args = [self.visit(arg) for arg in node.args]
        kwargs = {kw.arg: self.visit(kw.value) for kw in node.keywords}
        if func_name in self.ALLOWED_FUNCTIONS:
            func = globals()[func_name]
        else:
            func = getattr(math, func_name)
        return func(*args, **kwargs)

    def visit_Attribute(self, node: ast.Attribute) -> Any:
        obj = self.visit(node.value)
        if isinstance(obj, type(math)) and node.attr in self.ALLOWED_MATH_ATTRS:
            return getattr(obj, node.attr)
        raise ValueError(f"Disallowed attribute access: {node.attr}")

    def visit_Subscript(self, node: ast.Subscript) -> Any:
        raise ValueError("Subscripting not allowed")

    def visit_List(self, node: ast.List) -> Any:
        return [self.visit(elt) for elt in node.elts]

    def visit_Tuple(self, node: ast.Tuple) -> Any:
        return tuple(self.visit(elt) for elt in node.elts)

    def visit_Dict(self, node: ast.Dict) -> Any:
        return {self.visit(k): self.visit(v) for k, v in zip(node.keys, node.values)}

    def generic_visit(self, node: ast.AST) -> Any:
        raise ValueError(f"Disallowed AST node: {type(node).__name__}")


def calculate_shipping_cost(package: dict, carrier_config: dict) -> float:
    """
    Calculate shipping cost for a package using a carrier's pricing formula.

    Args:
        package: Dictionary with package details. Expected keys:
            - 'weight' (float): Package weight in kg, must be > 0
            - 'dimensions' (tuple[float, float, float]): Length, width, height in cm
            - 'destination_zone' (int): Shipping zone (1-9)
            - 'value' (float): Declared value for insurance, >= 0
        carrier_config: Dictionary with carrier configuration. Expected keys:
            - 'formula' (str): Pricing formula as a Python expression using allowed variables.
              Allowed variables: weight, volume, zone, value, base_rate, per_kg_rate,
              per_km_rate, handling_fee, insurance_rate.
            - 'variables' (dict, optional): Additional variable bindings for the formula.
              Keys must be alphanumeric + underscore. Values must be int or float.

    Returns:
        float: Calculated shipping cost, rounded to 2 decimal places. Returns 0.0 if
        package data is invalid or formula evaluation fails.

    User inputs:
        - package data originates from customer checkout form
        - carrier_config['formula'] and carrier_config['variables'] originate from
          store administrator carrier configuration UI
    """
    # Validate package data
    try:
        weight = float(package.get('weight', 0))
        dimensions = package.get('dimensions', (0, 0, 0))
        zone = int(package.get('destination_zone', 1))
        value = float(package.get('value', 0))
    except (TypeError, ValueError):
        return 0.0

    if weight <= 0 or zone < 1 or zone > 9 or value < 0:
        return 0.0

    if not (isinstance(dimensions, (list, tuple)) and len(dimensions) == 3):
        return 0.0
    try:
        length, width, height = map(float, dimensions)
        if any(d <= 0 for d in (length, width, height)):
            return 0.0
    except (TypeError, ValueError):
        return 0.0

    volume = (length * width * height) / 1_000_000  # Convert cm^3 to m^3

    # Prepare variables for formula
    formula_vars = {
        'weight': weight,
        'volume': volume,
        'zone': zone,
        'value': value,
        'base_rate': 5.0,
        'per_kg_rate': 1.5,
        'per_km_rate': 0.1,
        'handling_fee': 2.0,
        'insurance_rate': 0.01,
    }

    # Merge carrier-provided variables with validation
    extra_vars = carrier_config.get('variables', {})
    if not isinstance(extra_vars, dict):
        return 0.0
    for key, val in extra_vars.items():
        if not isinstance(key, str) or not key.isidentifier():
            return 0.0
        if not isinstance(val, (int, float)):
            return 0.0
        formula_vars[key] = val

    # Get and validate formula
    formula = carrier_config.get('formula', '')
    if not isinstance(formula, str) or not formula.strip():
        return 0.0

    # Parse and evaluate safely
    try:
        tree = ast.parse(formula, mode='eval')
        evaluator = SafeExpressionEvaluator(formula_vars)
        result = evaluator.visit(tree)
        if not isinstance(result, (int, float)):
            return 0.0
        return round(float(result), 2)
    except (SyntaxError, ValueError, ZeroDivisionError, OverflowError):
        return 0.0
