import re
from typing import Optional


def build_correlation_key(event: dict[str, str], template: str, field_extractors: dict[str, str]) -> Optional[str]:
    """
    Build a correlation key from a log event using a template and field extraction patterns.

    The correlation key is constructed by formatting the template with values extracted
    from the event fields. Each field referenced in the template (e.g., {service},
    {trace_id}) must have a corresponding entry in field_extractors. The extractor
    pattern uses a simplified syntax to pull a substring from the raw field value.

    Simplified pattern syntax:
    - Literal characters match themselves.
    - '*' matches zero or more of any character.
    - '?' matches exactly one of any character.
    - '[abc]' matches any single character in the set (ranges like [a-z] allowed).
    - '[^abc]' matches any single character not in the set.
    - Parentheses '()' group subpatterns for alternation with '|' (e.g., '(err|warn)').
    - No other regex metacharacters are supported.

    The function searches the field value for the first match of the pattern and
    returns the matched substring. If a field is missing from the event, or its
    value does not match the pattern, the function returns None.

    Args:
        event: A dictionary of parsed log fields (keys and values are strings).
               Sourced from the log parsing pipeline; field values are user-controlled
               log message content.
        template: A format string with placeholders like '{service}.{trace_id}'.
                  Provided by the pipeline configuration (user-controlled).
        field_extractors: A mapping from placeholder names (without braces) to
                          extraction patterns in the simplified syntax. Provided by
                          the pipeline configuration (user-controlled).

    Returns:
        The formatted correlation key string, or None if any extraction fails
        or a required field is missing.
    """
    # Extract placeholder names from template (e.g., {service} -> service)
    placeholder_pattern = re.compile(r'\{([^{}]+)\}')
    placeholders = placeholder_pattern.findall(template)

    # Validate all placeholders have extractors
    for ph in placeholders:
        if ph not in field_extractors:
            return None

    # Compile each extractor pattern safely
    compiled_extractors = {}
    for name, pattern in field_extractors.items():
        if name not in placeholders:
            continue
        try:
            regex = _compile_simplified_pattern(pattern)
        except ValueError:
            return None
        compiled_extractors[name] = regex

    # Extract values for each placeholder
    substitutions = {}
    for name in placeholders:
        field_value = event.get(name)
        if field_value is None:
            return None
        regex = compiled_extractors[name]
        try:
            match = regex.search(field_value)
        except TimeoutError:
            return None
        if not match:
            return None
        substitutions[name] = match.group(0)

    # Format the template
    try:
        return template.format(**substitutions)
    except (KeyError, ValueError):
        return None


class _PatternParser:
    """Parses the simplified pattern syntax into a safe regular expression."""

    def __init__(self, pattern: str):
        self.pattern = pattern
        self.pos = 0
        self.length = len(pattern)
        self.group_depth = 0
        self.MAX_GROUP_DEPTH = 10

    def parse(self) -> str:
        """Parse the entire pattern and return a regex string."""
        regex = self._parse_sequence()
        if self.pos != self.length:
            raise ValueError("Unexpected characters at end of pattern")
        return regex

    def _parse_sequence(self, stop_chars: str = '') -> str:
        """Parse a sequence of elements until a stop character or end."""
        parts = []
        while self.pos < self.length and self.pattern[self.pos] not in stop_chars:
            parts.append(self._parse_element())
        return ''.join(parts)

    def _parse_element(self) -> str:
        """Parse a single element: wildcard, char class, group, or literal."""
        if self.pos >= self.length:
            raise ValueError("Unexpected end of pattern")

        ch = self.pattern[self.pos]

        if ch == '*':
            self.pos += 1
            # '*' matches zero or more of any character -> greedy .*
            return '.*'
        elif ch == '?':
            self.pos += 1
            # '?' matches exactly one character -> .
            return '.'
        elif ch == '[':
            return self._parse_char_class()
        elif ch == '(':
            return self._parse_group()
        else:
            # Literal character: escape regex metacharacters
            self.pos += 1
            return re.escape(ch)

    def _parse_char_class(self) -> str:
        """Parse a character class [...] and return a regex character class."""
        if self.pos >= self.length or self.pattern[self.pos] != '[':
            raise ValueError("Expected '['")
        self.pos += 1

        if self.pos >= self.length:
            raise ValueError("Unclosed character class")

        negated = False
        if self.pattern[self.pos] == '^':
            negated = True
            self.pos += 1
            if self.pos >= self.length:
                raise ValueError("Unclosed character class after ^")

        chars = []
        while self.pos < self.length and self.pattern[self.pos] != ']':
            if (self.pos + 2 < self.length and 
                self.pattern[self.pos + 1] == '-' and 
                self.pattern[self.pos + 2] != ']'):
                # Range like a-z
                start = self.pattern[self.pos]
                end = self.pattern[self.pos + 2]
                if ord(start) > ord(end):
                    raise ValueError(f"Invalid range {start}-{end}")
                chars.append(re.escape(start) + '-' + re.escape(end))
                self.pos += 3
            else:
                chars.append(re.escape(self.pattern[self.pos]))
                self.pos += 1

        if self.pos >= self.length or self.pattern[self.pos] != ']':
            raise ValueError("Unclosed character class")
        self.pos += 1

        inner = ''.join(chars)
        if negated:
            return f'[^{inner}]'
        else:
            return f'[{inner}]'

    def _parse_group(self) -> str:
        """Parse a group (...) with alternation | and return a non-capturing group."""
        if self.pos >= self.length or self.pattern[self.pos] != '(':
            raise ValueError("Expected '('")
        self.pos += 1
        self.group_depth += 1
        if self.group_depth > self.MAX_GROUP_DEPTH:
            raise ValueError("Group nesting too deep")

        alternatives = []
        current_alt = []

        while self.pos < self.length and self.pattern[self.pos] != ')':
            if self.pattern[self.pos] == '|':
                alternatives.append(''.join(current_alt))
                current_alt = []
                self.pos += 1
                if self.pos < self.length and self.pattern[self.pos] == ')':
                    raise ValueError("Empty alternative in group")
            else:
                current_alt.append(self._parse_element())

        if self.pos >= self.length or self.pattern[self.pos] != ')':
            raise ValueError("Unclosed group")
        self.pos += 1
        self.group_depth -= 1

        alternatives.append(''.join(current_alt))
        # Join alternatives with |, wrap in non-capturing group
        return '(?:' + '|'.join(alternatives) + ')'


def _compile_simplified_pattern(pattern: str) -> re.Pattern:
    """
    Compile a simplified pattern to a safe regex with a timeout.

    Raises:
        ValueError: If the pattern uses unsupported syntax or would be unsafe.
    """
    parser = _PatternParser(pattern)
    try:
        regex_str = parser.parse()
    except ValueError as e:
        raise ValueError(f"Invalid pattern: {e}") from e

    # Compile with a safety timeout (Python 3.11+)
    try:
        return re.compile(regex_str, timeout=0.1)
    except TypeError:
        # Older Python without timeout; the pattern structure itself is safe
        return re.compile(regex_str)
