from lxml import etree
from typing import Dict, List, Any


def parse_signing_policy(policy_xml: str) -> Dict[str, Any]:
    """
    Parse a document signing policy XML into a structured dictionary.

    The policy XML defines constraints for a signing ceremony. This function
    extracts the policy rules for validation during the signing process.

    Args:
        policy_xml: XML string containing the signing policy. This input comes
            from users (policy administrators) who upload policy files through
            the management console or API.

    Returns:
        Dictionary with keys:
        - 'policy_id': str, unique identifier for the policy
        - 'version': int, policy version number
        - 'required_signers': list of dicts with 'role' and 'min_count' keys
        - 'signature_format': str, one of 'PAdES', 'XAdES', 'CAdES'
        - 'hash_algorithm': str, one of 'SHA256', 'SHA384', 'SHA512'
        - 'require_timestamp': bool
        - 'expires_after_days': int, validity period in days
        - 'custom_fields': dict of str->str for arbitrary metadata

        Returns empty dict if XML is malformed or missing required elements.
    """
    if not policy_xml or not policy_xml.strip():
        return {}

    # Reject any XML containing a DOCTYPE declaration to prevent XXE
    if "<!DOCTYPE" in policy_xml.upper():
        return {}

    parser = etree.XMLParser(
        resolve_entities=False,
        no_network=True,
        load_dtd=False,
        dtd_validation=False,
        attribute_defaults=False,
    )

    try:
        root = etree.fromstring(policy_xml.encode("utf-8"), parser=parser)
    except etree.XMLSyntaxError:
        return {}

    if root.tag != "SigningPolicy":
        return {}

    policy_id = root.get("id")
    version_str = root.get("version")

    if not policy_id or not version_str:
        return {}

    try:
        version = int(version_str)
    except ValueError:
        return {}

    required_signers = []
    signers_elem = root.find("RequiredSigners")
    if signers_elem is not None:
        for signer_elem in signers_elem.findall("Signer"):
            role = signer_elem.get("role")
            min_count_str = signer_elem.get("minCount", "1")
            if role:
                try:
                    min_count = int(min_count_str)
                    required_signers.append({"role": role, "min_count": min_count})
                except ValueError:
                    pass

    signature_format_elem = root.find("SignatureFormat")
    signature_format = signature_format_elem.text.strip() if signature_format_elem is not None and signature_format_elem.text else "PAdES"
    if signature_format not in ("PAdES", "XAdES", "CAdES"):
        signature_format = "PAdES"

    hash_algorithm_elem = root.find("HashAlgorithm")
    hash_algorithm = hash_algorithm_elem.text.strip() if hash_algorithm_elem is not None and hash_algorithm_elem.text else "SHA256"
    if hash_algorithm not in ("SHA256", "SHA384", "SHA512"):
        hash_algorithm = "SHA256"

    require_timestamp_elem = root.find("RequireTimestamp")
    require_timestamp = False
    if require_timestamp_elem is not None and require_timestamp_elem.text:
        require_timestamp = require_timestamp_elem.text.strip().lower() in ("true", "yes", "1")

    expires_after_days_elem = root.find("ExpiresAfterDays")
    expires_after_days = 30
    if expires_after_days_elem is not None and expires_after_days_elem.text:
        try:
            expires_after_days = int(expires_after_days_elem.text.strip())
        except ValueError:
            pass

    custom_fields = {}
    custom_elem = root.find("CustomFields")
    if custom_elem is not None:
        for field_elem in custom_elem.findall("Field"):
            key = field_elem.get("key")
            value = field_elem.text
            if key and value is not None:
                custom_fields[key] = value.strip()

    return {
        "policy_id": policy_id,
        "version": version,
        "required_signers": required_signers,
        "signature_format": signature_format,
        "hash_algorithm": hash_algorithm,
        "require_timestamp": require_timestamp,
        "expires_after_days": expires_after_days,
        "custom_fields": custom_fields,
    }
