import yaml
from typing import List, Dict
from collections import deque

def resolve_clause_render_order(manifest_yaml: str) -> List[str]:
    """
    Parse a clause dependency manifest and return clause IDs in topological render order.

    The manifest is a YAML mapping from clause ID (string) to a list of clause IDs
    that this clause depends on (must be rendered before this clause). All referenced
    clause IDs must be defined in the manifest. Cycles are not allowed.

    Args:
        manifest_yaml: YAML string provided by the document vault's indexing service.
                       This input originates from stored document metadata and may be
                       user-influenced through document upload/import workflows.

    Returns:
        List of clause IDs in dependency order (dependencies first). Returns empty
        list if manifest is empty, invalid YAML, missing references, or contains cycles.
    """
    if not manifest_yaml or not manifest_yaml.strip():
        return []

    try:
        manifest = yaml.safe_load(manifest_yaml)
    except yaml.YAMLError:
        return []

    if not isinstance(manifest, dict):
        return []

    # Validate all keys and values are strings/lists of strings
    for clause_id, deps in manifest.items():
        if not isinstance(clause_id, str):
            return []
        if not isinstance(deps, list):
            return []
        for dep in deps:
            if not isinstance(dep, str):
                return []

    # Check all referenced clauses exist
    all_clauses = set(manifest.keys())
    for clause_id, deps in manifest.items():
        for dep in deps:
            if dep not in all_clauses:
                return []

    # Kahn's algorithm for topological sort
    in_degree: Dict[str, int] = {clause: 0 for clause in manifest}
    for clause_id, deps in manifest.items():
        for dep in deps:
            in_degree[clause_id] += 1

    queue = deque([clause for clause, degree in in_degree.items() if degree == 0])
    result = []

    while queue:
        clause = queue.popleft()
        result.append(clause)
        # Find clauses that depend on this one
        for other_clause, deps in manifest.items():
            if clause in deps:
                in_degree[other_clause] -= 1
                if in_degree[other_clause] == 0:
                    queue.append(other_clause)

    if len(result) != len(manifest):
        # Cycle detected
        return []

    return result
