import ast
from typing import Callable, List

def compile_branching_rule(rule: str, question_ids: List[str]) -> Callable[[dict], bool]:
    """
    Compile a survey branching rule into a callable predicate.

    The rule is a boolean expression combining comparisons of question responses
    against literal values. Supported operators: and, or, not, ==, !=, <, <=, >, >=,
    in, not in. Parentheses for grouping are allowed. Question identifiers from
    `question_ids` are the only permitted variables. Example: "age >= 18 and country in ('US', 'CA')".

    Args:
        rule: User-provided branching condition. Comes from the survey designer's
              skip-logic configuration in the form builder.
        question_ids: List of valid question identifiers that may be referenced.
                      Comes from the published form schema.

    Returns:
        A callable accepting a dict of question_id -> value mappings, returning
        True if the branch should be followed (condition met), False otherwise.
        Returns a callable that always returns False if rule is empty or whitespace.

    Raises:
        ValueError: If rule contains disallowed constructs, unknown question IDs,
                    or syntax errors.
    """
    if not rule or not rule.strip():
        return lambda _: False

    allowed_names = set(question_ids)

    try:
        tree = ast.parse(rule.strip(), mode='eval')
    except SyntaxError as e:
        raise ValueError(f"Invalid rule syntax: {e}") from e

    # Allowed operator node types (these appear as separate nodes in ast.walk)
    allowed_operators = {
        ast.And, ast.Or, ast.Not,
        ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.In, ast.NotIn,
    }

    # First pass: validate all node types are allowed
    for node in ast.walk(tree):
        if isinstance(node, ast.Expression):
            continue
        elif isinstance(node, ast.BoolOp):
            if type(node.op) not in allowed_operators:
                raise ValueError(f"Disallowed boolean operator: {type(node.op).__name__}")
        elif isinstance(node, ast.UnaryOp):
            if type(node.op) not in allowed_operators:
                raise ValueError(f"Disallowed unary operator: {type(node.op).__name__}")
        elif isinstance(node, ast.Compare):
            for op in node.ops:
                if type(op) not in allowed_operators:
                    raise ValueError(f"Disallowed comparison operator: {type(op).__name__}")
        elif isinstance(node, ast.Name):
            if node.id not in allowed_names:
                raise ValueError(f"Unknown question ID: {node.id}")
            if not isinstance(node.ctx, ast.Load):
                raise ValueError("Assignment not allowed")
        elif isinstance(node, ast.Constant):
            if not isinstance(node.value, (str, int, float, bool, type(None))):
                raise ValueError(f"Disallowed constant type: {type(node.value).__name__}")
        elif isinstance(node, ast.Tuple):
            for elt in node.elts:
                if not isinstance(elt, ast.Constant):
                    raise ValueError("Tuple elements must be literals")
                if not isinstance(elt.value, (str, int, float, bool, type(None))):
                    raise ValueError(f"Disallowed tuple element type: {type(elt.value).__name__}")
        elif isinstance(node, (ast.Load, ast.Expr)):
            continue
        elif type(node) in allowed_operators:
            continue
        else:
            raise ValueError(f"Disallowed construct: {type(node).__name__}")

    # Second pass: validate Compare structure (left side must be question ID, right side literal/tuple)
    for node in ast.walk(tree):
        if isinstance(node, ast.Compare):
            if not isinstance(node.left, ast.Name):
                raise ValueError("Left side of comparison must be a question identifier")
            if node.left.id not in allowed_names:
                raise ValueError(f"Unknown question ID: {node.left.id}")
            for comp in node.comparators:
                if not isinstance(comp, (ast.Constant, ast.Tuple)):
                    raise ValueError("Right side of comparison must be a literal value or tuple of literals")
                if isinstance(comp, ast.Tuple):
                    for elt in comp.elts:
                        if not isinstance(elt, ast.Constant):
                            raise ValueError("Tuple elements must be literals")

    code = compile(tree, '<rule>', 'eval')

    def evaluator(responses: dict) -> bool:
        local_vars = {}
        for qid in allowed_names:
            local_vars[qid] = responses.get(qid)
        try:
            result = eval(code, {"__builtins__": {}}, local_vars)
        except Exception:
            return False
        return bool(result)

    return evaluator
