import ast
import math
from typing import Callable, Optional

_ALLOWED_FUNCTIONS = {'log', 'sqrt', 'exp', 'min', 'max', 'abs', 'round'}
_ALLOWED_NODE_TYPES = {
    ast.Expression, ast.BinOp, ast.UnaryOp, ast.Compare, ast.BoolOp,
    ast.IfExp, ast.Call, ast.Name, ast.Constant,
    ast.Add, ast.Sub, ast.Mult, ast.Div, ast.FloorDiv, ast.Mod, ast.Pow,
    ast.USub, ast.UAdd, ast.Not,
    ast.And, ast.Or,
    ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE,
    ast.Load,
}

def create_book_ranker(formula: str, variables: list[str]) -> Optional[Callable[[dict], float]]:
    """
    Compile a ranking formula into a callable that scores book records.

    The formula is a Python arithmetic/boolean expression using only the
    variable names listed in `variables` (e.g., 'rating', 'year', 'checkouts').
    Supported operators: + - * / // % **, comparison (== != < > <= >=),
    boolean (and or not), ternary (x if c else y). Supported functions:
    log, sqrt, exp, min, max, abs, round.

    Args:
        formula: A mathematical expression string provided by a librarian.
                 This input comes from an untrusted user.
        variables: List of variable names the formula may reference. These
                   correspond to keys in the book record dict passed to the
                   returned callable.

    Returns:
        A callable that takes a book record dict and returns a float score,
        or None if the formula contains disallowed syntax or names.

    The returned callable evaluates the formula with variables bound to the
    book record's values (defaulting to 0 for missing keys) and the supported
    functions available. Any evaluation error yields a score of 0.0.
    """
    try:
        tree = ast.parse(formula, mode='eval')
    except SyntaxError:
        return None

    allowed_names = set(variables) | _ALLOWED_FUNCTIONS

    for node in ast.walk(tree):
        if type(node) not in _ALLOWED_NODE_TYPES:
            return None
        if isinstance(node, ast.Name):
            if node.id not in allowed_names:
                return None
        elif isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Name):
                return None
            if node.func.id not in _ALLOWED_FUNCTIONS:
                return None
            if node.keywords:
                return None
            for arg in node.args:
                if isinstance(arg, ast.Starred):
                    return None

    try:
        code = compile(tree, '<ranking_formula>', 'eval')
    except Exception:
        return None

    safe_globals = {
        'log': math.log,
        'sqrt': math.sqrt,
        'exp': math.exp,
        'min': min,
        'max': max,
        'abs': abs,
        'round': round,
    }

    def ranker(book: dict) -> float:
        local_vars = {var: book.get(var, 0) for var in variables}
        try:
            result = eval(code, {"__builtins__": {}}, {**safe_globals, **local_vars})
            return float(result)
        except Exception:
            return 0.0

    return ranker
