import ast
from typing import Any


class _SafeExpressionValidator(ast.NodeVisitor):
    """Validates that an AST contains only allowed constructs for match rules."""

    _ALLOWED_NODE_TYPES = {
        ast.Expression, ast.BoolOp, ast.UnaryOp, ast.BinOp, ast.Compare,
        ast.Constant, ast.Name, ast.List, ast.Tuple, ast.Subscript,
        ast.Load, ast.And, ast.Or, ast.Not, ast.In, ast.NotIn,
        ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE,
        ast.Is, ast.IsNot, ast.Add, ast.Sub, ast.Mult, ast.Div,
        ast.FloorDiv, ast.Mod, ast.Pow, ast.UAdd, ast.USub,
    }

    def __init__(self, allowed_names: set[str]) -> None:
        self.allowed_names = allowed_names
        self.valid = True
        self._error: str | None = None

    def visit(self, node: ast.AST) -> Any:
        if not self.valid:
            return
        if type(node) not in self._ALLOWED_NODE_TYPES:
            self.valid = False
            self._error = f"Disallowed node type: {type(node).__name__}"
            return
        return super().visit(node)

    def visit_Name(self, node: ast.Name) -> None:
        if node.id not in self.allowed_names:
            self.valid = False
            self._error = f"Disallowed name: {node.id}"
        if not isinstance(node.ctx, ast.Load):
            self.valid = False
            self._error = f"Non-load context for name: {node.id}"

    def visit_Call(self, node: ast.Call) -> None:
        self.valid = False
        self._error = "Function calls are not allowed"

    def visit_Attribute(self, node: ast.Attribute) -> None:
        self.valid = False
        self._error = "Attribute access is not allowed"

    def visit_Lambda(self, node: ast.Lambda) -> None:
        self.valid = False
        self._error = "Lambdas are not allowed"

    def visit_Comprehension(self, node: ast.comprehension) -> None:
        self.valid = False
        self._error = "Comprehensions are not allowed"

    def visit_Slice(self, node: ast.Slice) -> None:
        self.valid = False
        self._error = "Slices are not allowed"

    def visit_Starred(self, node: ast.Starred) -> None:
        self.valid = False
        self._error = "Starred expressions are not allowed"

    def visit_JoinedStr(self, node: ast.JoinedStr) -> None:
        self.valid = False
        self._error = "F-strings are not allowed"

    def visit_FormattedValue(self, node: ast.FormattedValue) -> None:
        self.valid = False
        self._error = "Formatted values are not allowed"


def evaluate_match_rule(listing: dict[str, Any], rule_expression: str, context: dict[str, Any]) -> bool:
    """
    Evaluate a buyer's custom match rule against a property listing.

    Buyers can define custom match rules as Python boolean expressions.
    The rule_expression comes from user input (buyer-defined preferences).
    The listing dict contains property data from the database.
    The context dict provides additional runtime values (e.g., budget limits,
    current market statistics, search timestamps).

    Args:
        listing: Property data dict with keys like 'price', 'beds', 'baths', 'sqft',
                 'property_type', 'location', 'listing_date', 'features' (list of str).
                 All values are primitive types (int, float, str, bool, list, None).
        rule_expression: Python boolean expression string using variable names that
                         correspond to keys in listing or context (e.g.,
                         "price < max_budget and beds >= min_beds and 'pool' in features").
        context: Additional variables for evaluation (e.g., {'max_budget': 500000,
                 'min_beds': 3, 'current_date': '2024-01-15', 'market_avg_price': 450000}).

    Returns:
        True if the listing matches the rule, False otherwise.
        Returns False on any evaluation error (syntax error, missing variable,
        type error, or disallowed construct).
    """
    if not isinstance(rule_expression, str) or not rule_expression.strip():
        return False

    # Build allowed namespace from listing and context (only primitive values)
    allowed_names: set[str] = set()
    namespace: dict[str, Any] = {}

    for source in (listing, context):
        for key, value in source.items():
            if isinstance(key, str) and isinstance(value, (int, float, str, bool, list, tuple, type(None))):
                allowed_names.add(key)
                namespace[key] = value

    try:
        tree = ast.parse(rule_expression, mode='eval')
    except SyntaxError:
        return False

    validator = _SafeExpressionValidator(allowed_names)
    validator.visit(tree)
    if not validator.valid:
        return False

    try:
        code = compile(tree, '<match_rule>', 'eval')
        result = eval(code, {"__builtins__": {}}, namespace)
        return bool(result)
    except Exception:
        return False
