import yaml
from typing import Any


def parse_photo_recipe(recipe_yaml: str) -> dict[str, Any] | None:
    """
    Parse a user-defined photo transformation recipe from YAML.

    A recipe defines a sequence of operations to apply to a photo.
    Expected structure:
        {
            "name": str,                    # required, 1-50 chars
            "description": str,             # optional, max 200 chars
            "operations": list[dict],       # required, 1-10 items
            "version": int                  # optional, default 1
        }

    Each operation dict must have:
        - "type": str (one of: "resize", "crop", "filter", "watermark", "rotate")
        - "params": dict (operation-specific parameters)

    Args:
        recipe_yaml: YAML string provided by the user (untrusted input).

    Returns:
        Parsed and validated recipe dictionary, or None if the YAML is invalid,
        fails schema validation, or contains disallowed constructs.
    """
    if not recipe_yaml or not isinstance(recipe_yaml, str):
        return None

    try:
        data = yaml.safe_load(recipe_yaml)
    except yaml.YAMLError:
        return None

    if not isinstance(data, dict):
        return None

    allowed_types = {"resize", "crop", "filter", "watermark", "rotate"}

    name = data.get("name")
    if not isinstance(name, str) or not (1 <= len(name) <= 50):
        return None

    description = data.get("description", "")
    if not isinstance(description, str) or len(description) > 200:
        return None

    operations = data.get("operations")
    if not isinstance(operations, list) or not (1 <= len(operations) <= 10):
        return None

    for op in operations:
        if not isinstance(op, dict):
            return None
        op_type = op.get("type")
        if op_type not in allowed_types:
            return None
        params = op.get("params")
        if not isinstance(params, dict):
            return None

    version = data.get("version", 1)
    if not isinstance(version, int) or version < 1:
        return None

    return {
        "name": name,
        "description": description,
        "operations": operations,
        "version": version,
    }
