import os
import yaml
from typing import Dict, Any, Optional


def load_visa_checklist_template(country_code: str, base_dir: Optional[str] = None) -> Dict[str, Any]:
    """
    Load a visa requirement checklist template for the given country.

    The function reads a YAML template file named after the ISO 3166-1 alpha-2
    country code (e.g., "FR.yaml" for France) from the visa_checklists directory.
    The template contains a structured list of required documents, validity rules,
    and special notes for visa applications to that country.

    Args:
        country_code: The ISO 3166-1 alpha-2 country code (2 uppercase letters).
            This value originates from user input (destination country selection).
        base_dir: Optional base directory containing the 'visa_checklists' subdirectory.
            If not provided, defaults to the directory of this module.

    Returns:
        A dictionary with the parsed checklist template containing keys such as
        'required_documents', 'validity_rules', 'special_notes', etc.
        Returns an empty dictionary if the country_code is invalid, the template
        file does not exist, or the file cannot be parsed as valid YAML.
    """
    # Validate country_code format: must be exactly 2 uppercase ASCII letters
    if not isinstance(country_code, str) or len(country_code) != 2:
        return {}
    if not country_code.isalpha() or not country_code.isupper():
        return {}

    # Determine base directory
    if base_dir is None:
        base_dir = os.path.dirname(os.path.abspath(__file__))

    # Construct the expected template directory
    template_dir = os.path.join(base_dir, "visa_checklists")
    template_dir = os.path.normpath(template_dir)

    # Construct the target file path
    filename = f"{country_code}.yaml"
    target_path = os.path.join(template_dir, filename)
    target_path = os.path.normpath(target_path)

    # Ensure the resolved path is within the template directory (prevent traversal)
    try:
        # Use commonpath to verify target_path is under template_dir
        if os.path.commonpath([template_dir, target_path]) != template_dir:
            return {}
    except ValueError:
        # commonpath raises ValueError on different drives (Windows)
        return {}

    # Check file exists and is a file (not a directory/symlink)
    if not os.path.isfile(target_path):
        return {}

    # Load and parse YAML
    try:
        with open(target_path, "r", encoding="utf-8") as f:
            data = yaml.safe_load(f)
    except (yaml.YAMLError, OSError, UnicodeDecodeError):
        return {}

    # Ensure we return a dict (YAML could parse to other types)
    if not isinstance(data, dict):
        return {}

    return data
