import ast
import builtins
import operator
from typing import Any, Dict, Union

_ALLOWED_NAMES = {
    'current_grade', 'projected_final', 'attendance_rate',
    'homework_avg', 'quiz_avg', 'exam_avg', 'participation_score',
    'min', 'max', 'abs', 'round', 'True', 'False', 'None'
}

_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}

_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
    ast.Not: operator.not_,
}

_CMP_OPS = {
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
}

_BOOL_OPS = {
    ast.And: all,
    ast.Or: any,
}

_ALLOWED_FUNCTIONS = {'min', 'max', 'abs', 'round'}

class SafeEvalVisitor(ast.NodeVisitor):
    def __init__(self, context: Dict[str, float]):
        self.context = context

    def visit_Expression(self, node: ast.Expression) -> Any:
        return self.visit(node.body)

    def visit_Constant(self, node: ast.Constant) -> Any:
        return node.value

    def visit_Name(self, node: ast.Name) -> Any:
        if node.id not in _ALLOWED_NAMES:
            raise ValueError(f"Disallowed name: {node.id}")
        if node.id in ('True', 'False', 'None'):
            return {'True': True, 'False': False, 'None': None}[node.id]
        if node.id in _ALLOWED_FUNCTIONS:
            return getattr(builtins, node.id)
        return self.context.get(node.id, 0.0)

    def visit_BinOp(self, node: ast.BinOp) -> Any:
        left = self.visit(node.left)
        right = self.visit(node.right)
        op_type = type(node.op)
        if op_type not in _BIN_OPS:
            raise ValueError(f"Disallowed binary operator: {op_type}")
        return _BIN_OPS[op_type](left, right)

    def visit_UnaryOp(self, node: ast.UnaryOp) -> Any:
        operand = self.visit(node.operand)
        op_type = type(node.op)
        if op_type not in _UNARY_OPS:
            raise ValueError(f"Disallowed unary operator: {op_type}")
        return _UNARY_OPS[op_type](operand)

    def visit_Compare(self, node: ast.Compare) -> Any:
        left = self.visit(node.left)
        results = []
        for op, comparator in zip(node.ops, node.comparators):
            right = self.visit(comparator)
            op_type = type(op)
            if op_type not in _CMP_OPS:
                raise ValueError(f"Disallowed comparison operator: {op_type}")
            results.append(_CMP_OPS[op_type](left, right))
            left = right
        return all(results)

    def visit_BoolOp(self, node: ast.BoolOp) -> Any:
        values = [self.visit(v) for v in node.values]
        op_type = type(node.op)
        if op_type not in _BOOL_OPS:
            raise ValueError(f"Disallowed boolean operator: {op_type}")
        return _BOOL_OPS[op_type](values)

    def visit_IfExp(self, node: ast.IfExp) -> Any:
        test = self.visit(node.test)
        return self.visit(node.body) if test else self.visit(node.orelse)

    def visit_Call(self, node: ast.Call) -> Any:
        if not isinstance(node.func, ast.Name) or node.func.id not in _ALLOWED_FUNCTIONS:
            raise ValueError(f"Disallowed function call: {ast.dump(node.func)}")
        func = self.visit(node.func)
        args = [self.visit(arg) for arg in node.args]
        if node.keywords:
            raise ValueError("Keyword arguments not allowed")
        return func(*args)

    def generic_visit(self, node: ast.AST) -> Any:
        raise ValueError(f"Disallowed AST node: {type(node).__name__}")

def predict_grade_trajectory(formula: str, student_data: Dict[str, float]) -> float:
    """
    Evaluate a teacher-provided grade prediction formula against student metrics.

    The formula is a mathematical expression using student metric names as variables.
    Supported metrics: 'current_grade', 'projected_final', 'attendance_rate',
    'homework_avg', 'quiz_avg', 'exam_avg', 'participation_score'.
    Supported operations: +, -, *, /, //, %, **, min, max, abs, round.
    Comparison operators (>, <, >=, <=, ==, !=) and boolean operators (and, or, not)
    are allowed for conditional expressions using Python's ternary syntax:
    'value_if_true if condition else value_if_false'.

    Args:
        formula: A string expression provided by the teacher (user input).
                 Example: "current_grade * 0.7 + projected_final * 0.3"
                 Example: "max(current_grade, projected_final) if attendance_rate > 0.9 else current_grade"
        student_data: Dictionary containing the student's current metrics.
                      Required keys: 'current_grade', 'projected_final', 'attendance_rate',
                      'homework_avg', 'quiz_avg', 'exam_avg', 'participation_score'.
                      All values are floats between 0 and 100 (except attendance_rate 0-1).

    Returns:
        The computed predicted grade as a float, clamped to range [0, 100].
        Returns 0.0 if formula is empty, invalid, or evaluation fails.
    """
    if not formula or not formula.strip():
        return 0.0

    required_keys = {
        'current_grade', 'projected_final', 'attendance_rate',
        'homework_avg', 'quiz_avg', 'exam_avg', 'participation_score'
    }
    if not all(k in student_data for k in required_keys):
        return 0.0

    try:
        tree = ast.parse(formula.strip(), mode='eval')
        visitor = SafeEvalVisitor(student_data)
        result = visitor.visit(tree)
        result = float(result)
    except (SyntaxError, ValueError, TypeError, ZeroDivisionError, OverflowError, RecursionError):
        return 0.0

    return max(0.0, min(100.0, result))
