import ast
import math
from typing import Any


def calculate_custom_adjustment(formula: str, parameters: dict[str, float]) -> float | None:
    """
    Calculate a custom claim adjustment using a provided formula and parameters.

    This function evaluates a mathematical formula string with the given parameter
    values to compute a supplemental adjustment amount for a claim. The formula
    should use only the parameter names as variables and standard arithmetic
    operators.

    Args:
        formula: A mathematical expression string provided by the claims adjuster.
            Example: "base * multiplier + offset"
        parameters: A dictionary of parameter names to numeric values, provided by
            the claims adjuster. Keys must be valid Python identifiers.
            Example: {"base": 1000.0, "multiplier": 1.5, "offset": 50.0}

    Returns:
        The calculated adjustment as a float, or None if the formula is invalid,
        contains disallowed constructs, or evaluation fails for any reason.

    User-controlled inputs:
        Both `formula` and `parameters` are supplied by the claims adjuster (user).
    """
    if not isinstance(formula, str) or not formula.strip():
        return None

    if not isinstance(parameters, dict):
        return None

    # Validate parameter values are numeric (int or float, not bool)
    validated_params: dict[str, float] = {}
    for key, value in parameters.items():
        if not isinstance(key, str) or not key.isidentifier():
            return None
        # Reject bool since it's a subclass of int
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            return None
        if math.isnan(value) or math.isinf(value):
            return None
        validated_params[key] = float(value)

    try:
        tree = ast.parse(formula.strip(), mode="eval")
    except SyntaxError:
        return None

    # Allowed AST node types for a safe mathematical expression
    allowed_nodes = {
        ast.Expression,
        ast.BinOp,
        ast.UnaryOp,
        ast.Constant,
        ast.Name,
        ast.Call,
        ast.Load,
        ast.Add,
        ast.Sub,
        ast.Mult,
        ast.Div,
        ast.Pow,
        ast.Mod,
        ast.FloorDiv,
        ast.USub,
        ast.UAdd,
    }

    # Allowed function names for Call nodes
    allowed_functions = {"min", "max", "abs", "round", "pow"}

    for node in ast.walk(tree):
        if type(node) not in allowed_nodes:
            return None

        if isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Name):
                return None
            if node.func.id not in allowed_functions:
                return None
            # No keyword arguments allowed
            if node.keywords:
                return None

        if isinstance(node, ast.Name):
            if node.id not in validated_params and node.id not in allowed_functions:
                return None

        if isinstance(node, ast.Constant):
            if not isinstance(node.value, (int, float)):
                return None
            if isinstance(node.value, bool) or math.isnan(node.value) or math.isinf(node.value):
                return None

    # Build safe evaluation namespace
    safe_namespace: dict[str, Any] = {}
    safe_namespace.update(validated_params)
    safe_namespace["min"] = min
    safe_namespace["max"] = max
    safe_namespace["abs"] = abs
    safe_namespace["round"] = round
    safe_namespace["pow"] = pow

    try:
        code = compile(tree, "<formula>", "eval")
        result = eval(code, {"__builtins__": {}}, safe_namespace)
    except (ZeroDivisionError, OverflowError, ValueError, TypeError, MemoryError, RecursionError):
        return None

    if isinstance(result, bool) or not isinstance(result, (int, float)):
        return None
    if math.isnan(result) or math.isinf(result):
        return None

    return float(result)
