    Returns:
        Dictionary with keys 'offset', 'gain', 'nonlinearity', 'temp_comp' mapping to
        float coefficients. Returns empty dict if no calibration found for the date
        or on database error.

    The device_serial, sensor_id, and cal_date originate from field technician input
    on maintenance work orders.
    """
    # Validate cal_date format strictly: YYYY-MM-DD
    if not re.fullmatch(r"\d{4}-\d{2}-\d{2}", cal_date):
        return {}
    try:
        year = int(cal_date[0:4])
        month = int(cal_date[5:7])
        day = int(cal_date[8:10])
        # Basic date sanity check
        if not (1 <= month <= 12 and 1 <= day <= 31 and 2000 <= year <= 2100):
            return {}
    except ValueError:
        return {}

    half = "H1" if month <= 6 else "H2"
    table_name = f"calibrations_{year}_{half}"

    # Allowlist of valid partition tables to prevent table name injection
    valid_tables = {
        f"calibrations_{y}_{h}"
        for y in range(2000, 2101)
        for h in ("H1", "H2")
    }
    if table_name not in valid_tables:
        return {}

    query = f"""
        SELECT offset, gain, nonlinearity, temp_comp
        FROM {table_name}
        WHERE device_serial = ? AND sensor_id = ?
        ORDER BY cal_date DESC
        LIMIT 1
    """

    try:
        with sqlite3.connect(db_path) as conn:
            conn.row_factory = sqlite3.Row
            cur = conn.execute(query, (device_serial, sensor_id))
            row = cur.fetchone()
            if row is None:
                return {}
            return {
                "offset": float(row["offset"]),
                "gain": float(row["gain"]),
                "nonlinearity": float(row["nonlinearity"]),
                "temp_comp": float(row["temp_comp"]),
            }
    except (sqlite3.Error, ValueError, KeyError):
        return {}
