from typing import Optional


def build_notebook_export_headers(
    format: str,
    filename: str,
    custom_metadata: Optional[dict[str, str]] = None,
    inline: bool = False
) -> dict[str, str]:
    """
    Build HTTP response headers for notebook export/download.

    Args:
        format: Export format (e.g., 'ipynb', 'py', 'html', 'pdf', 'md').
        filename: User-provided base filename (without extension).
        custom_metadata: Optional user-provided key-value pairs to include
            as X-Notebook-Meta-* headers. Keys and values must be ASCII.
        inline: If True, use Content-Disposition: inline; otherwise attachment.

    Returns:
        Dictionary of HTTP headers suitable for a notebook export response.
        Always includes Content-Type and Content-Disposition when format is recognized.
        Returns empty dict if format is unrecognized.

    User-controlled inputs: filename, custom_metadata keys and values.
    """
    format = format.lower().strip()
    content_types = {
        'ipynb': 'application/x-ipynb+json',
        'py': 'text/x-python',
        'html': 'text/html',
        'pdf': 'application/pdf',
        'md': 'text/markdown',
    }

    if format not in content_types:
        return {}

    def sanitize_header_value(value: str) -> str:
        # Truncate at first CR or LF to prevent header injection
        for i, ch in enumerate(value):
            if ch == '\r' or ch == '\n':
                return value[:i]
        return value

    def sanitize_header_key(key: str) -> str:
        # Truncate at first CR or LF, then keep only safe characters
        truncated = []
        for ch in key:
            if ch == '\r' or ch == '\n':
                break
            truncated.append(ch)
        return ''.join(c for c in truncated if c.isalnum() or c in '_-')

    def sanitize_filename(name: str) -> str:
        # Truncate at first CR or LF
        for i, ch in enumerate(name):
            if ch == '\r' or ch == '\n':
                return name[:i]
        return name

    safe_filename = sanitize_filename(filename)
    if not safe_filename:
        safe_filename = 'notebook'

    extension_map = {
        'ipynb': '.ipynb',
        'py': '.py',
        'html': '.html',
        'pdf': '.pdf',
        'md': '.md',
    }
    full_filename = safe_filename + extension_map[format]

    disposition = 'inline' if inline else 'attachment'
    content_disposition = f'{disposition}; filename="{full_filename}"'

    headers = {
        'Content-Type': content_types[format],
        'Content-Disposition': content_disposition,
    }

    if custom_metadata:
        for key, value in custom_metadata.items():
            safe_key = sanitize_header_key(key)
            safe_value = sanitize_header_value(value)
            if safe_key:
                headers[f'X-Notebook-Meta-{safe_key}'] = safe_value

    return headers
