import yaml
from typing import Any


def parse_device_personality(yaml_content: str) -> dict[str, Any] | None:
    """
    Parse a device personality profile from YAML content.

    A personality profile defines custom behavioral scripts for a smart device
    (e.g., "party mode" for lights, "vacation simulator" for blinds).
    Expected structure:
    {
        'name': str,                    # required, 1-64 chars, alphanumeric + underscore/hyphen
        'version': int,                 # required, >= 1
        'triggers': list[str],          # optional, event names that activate this personality (max 20)
        'actions': list[dict[str, Any]],# optional, each dict has 'type' (str) and 'params' (dict)
        'metadata': dict[str, str]      # optional, arbitrary string key-value pairs
    }

    Args:
        yaml_content: Raw YAML string provided by the user (e.g., uploaded file content).

    Returns:
        Parsed and validated personality dict, or None if invalid/malformed.
    """
    if not yaml_content or not isinstance(yaml_content, str):
        return None

    try:
        data = yaml.safe_load(yaml_content)
    except yaml.YAMLError:
        return None

    if not isinstance(data, dict):
        return None

    name = data.get("name")
    if not isinstance(name, str) or not (1 <= len(name) <= 64):
        return None
    if not all(c.isalnum() or c in "_-" for c in name):
        return None

    version = data.get("version")
    if not isinstance(version, int) or version < 1:
        return None

    triggers = data.get("triggers", [])
    if not isinstance(triggers, list) or len(triggers) > 20:
        return None
    if not all(isinstance(t, str) and 1 <= len(t) <= 64 for t in triggers):
        return None

    actions = data.get("actions", [])
    if not isinstance(actions, list):
        return None
    for action in actions:
        if not isinstance(action, dict):
            return None
        if "type" not in action or not isinstance(action["type"], str):
            return None
        if "params" not in action or not isinstance(action["params"], dict):
            return None

    metadata = data.get("metadata", {})
    if not isinstance(metadata, dict):
        return None
    if not all(isinstance(k, str) and isinstance(v, str) for k, v in metadata.items()):
        return None

    return {
        "name": name,
        "version": version,
        "triggers": triggers,
        "actions": actions,
        "metadata": metadata,
    }
