import ast
import time
from typing import Callable, Optional


def create_jwt_claim_validator(rule_expression: str) -> Optional[Callable[[dict], bool]]:
    """
    Compile a JWT claim validation rule into a callable predicate.

    The rule_expression is a Python boolean expression that can reference
    the 'claims' dict (the JWT payload) and 'now' (current Unix timestamp).
    Example: "claims.get('role') == 'admin' and claims.get('exp', 0) > now"

    Args:
        rule_expression: Validation rule as a Python expression string.
            Comes from tenant configuration via the gateway admin API.
            Tenant admins can create custom validation rules for their APIs.

    Returns:
        A callable that takes a claims dict and returns True if valid,
        False otherwise. Returns None if the rule_expression is invalid
        or cannot be compiled.
    """
    ALLOWED_NODES = {
        ast.Expression, ast.BoolOp, ast.UnaryOp, ast.Compare,
        ast.Call, ast.Attribute, ast.Subscript, ast.Constant,
        ast.Name, ast.Load, ast.And, ast.Or, ast.Not,
        ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE,
        ast.In, ast.NotIn, ast.Is, ast.IsNot,
        ast.List, ast.Tuple, ast.Set, ast.Dict,
        ast.keyword,
    }
    ALLOWED_FUNCTIONS = {'get', 'keys', 'values', 'items'}
    ALLOWED_NAMES = {'claims', 'now', 'True', 'False', 'None'}

    try:
        tree = ast.parse(rule_expression, mode='eval')
    except SyntaxError:
        return None

    for node in ast.walk(tree):
        if type(node) not in ALLOWED_NODES:
            return None

        if isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Attribute):
                return None
            if node.func.attr not in ALLOWED_FUNCTIONS:
                return None
            if not (isinstance(node.func.value, ast.Name) and node.func.value.id == 'claims'):
                return None

        if isinstance(node, ast.Attribute):
            if not (isinstance(node.value, ast.Name) and node.value.id == 'claims'):
                return None
            if node.attr not in ALLOWED_FUNCTIONS:
                return None

        if isinstance(node, ast.Name):
            if node.id not in ALLOWED_NAMES:
                return None

    try:
        code = compile(tree, '<policy>', 'eval')
    except Exception:
        return None

    def validator(claims: dict) -> bool:
        try:
            return bool(eval(code, {"__builtins__": {}}, {"claims": claims, "now": time.time()}))
        except Exception:
            return False

    return validator
