import ast
from typing import Dict, Union

def evaluate_guild_ranking_formula(formula: str, player_stats: Dict[str, Union[int, float]]) -> Union[float, None]:
    """
    Evaluate a guild ranking formula against player statistics.

    The formula is a mathematical expression using player stat keys as variables.
    Supported operations: +, -, *, /, //, %, **, parentheses.
    Supported functions: min, max, abs, round, pow.
    Variables must be alphanumeric with underscores, matching keys in player_stats.

    Args:
        formula: The ranking formula string, provided by the guild leader via the admin panel.
                 Example: "kills * 10 + assists * 5 - deaths * 2 + objectives * 50"
        player_stats: Dictionary mapping stat names to numeric values for a specific player.
                      Keys are stat identifiers (e.g., "kills", "deaths", "assists").
                      Values are integers or floats.

    Returns:
        The computed ranking score as a float, or None if the formula is invalid,
        references unknown stats, or would cause a runtime error (e.g., division by zero).

    User inputs:
        - formula: comes from the guild leader configuring their guild's leaderboard.
        - player_stats: comes from the game server's statistics database (trusted).
    """
    if not isinstance(formula, str) or not formula.strip():
        return None

    try:
        tree = ast.parse(formula, mode='eval')
    except SyntaxError:
        return None

    allowed_node_types = {
        ast.Expression, ast.BinOp, ast.UnaryOp, ast.Name, ast.Constant,
        ast.Call, ast.Load, ast.Add, ast.Sub, ast.Mult, ast.Div,
        ast.FloorDiv, ast.Mod, ast.Pow, ast.USub, ast.UAdd,
        ast.Tuple, ast.List
    }
    allowed_functions = {'min', 'max', 'abs', 'round', 'pow'}

    for node in ast.walk(tree):
        node_type = type(node)
        if node_type not in allowed_node_types:
            return None
        if isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Name) or node.func.id not in allowed_functions:
                return None
            if node.keywords:
                return None
        if isinstance(node, ast.Name):
            if node.id not in player_stats and node.id not in allowed_functions:
                return None

    safe_namespace = dict(player_stats)
    safe_namespace.update({
        'min': min, 'max': max, 'abs': abs, 'round': round, 'pow': pow
    })

    try:
        code = compile(tree, '<formula>', 'eval')
        result = eval(code, {"__builtins__": {}}, safe_namespace)
        return float(result)
    except Exception:
        return None
