import ast
import math
from typing import Dict, Any

_ALLOWED_NODE_TYPES = {
    ast.Expression, ast.BinOp, ast.UnaryOp, ast.Constant, ast.Name, ast.Load,
    ast.Call, ast.keyword, ast.Add, ast.Sub, ast.Mult, ast.Div, ast.FloorDiv,
    ast.Mod, ast.Pow, ast.USub, ast.UAdd, ast.Compare, ast.Eq, ast.NotEq,
    ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.BoolOp, ast.And, ast.Or, ast.IfExp,
}

_ALLOWED_FUNCTIONS = {
    'abs', 'min', 'max', 'round', 'pow',
    'ceil', 'floor', 'sqrt', 'log', 'log10', 'exp', 'sin', 'cos', 'tan',
}
_ALLOWED_CONSTANTS = {'pi', 'e'}

def _validate_ast(node: ast.AST, allowed_names: set) -> bool:
    for n in ast.walk(node):
        if type(n) not in _ALLOWED_NODE_TYPES:
            return False
        if isinstance(n, ast.Name):
            if n.id not in allowed_names and n.id not in _ALLOWED_CONSTANTS:
                return False
        if isinstance(n, ast.Call):
            if not isinstance(n.func, ast.Name) or n.func.id not in _ALLOWED_FUNCTIONS:
                return False
    return True


def calculate_adjusted_priority(base_priority: int, customer_formula: str, business_metrics: Dict[str, Any]) -> int:
    """
    Calculate adjusted ticket priority using a customer-provided formula.

    Premium customers can define custom priority adjustment formulas that incorporate
    their business metrics. The formula should evaluate to a numeric adjustment value.

    Args:
        base_priority: The ticket's base priority (1-5, where 5 is highest).
                       Comes from the ticketing system (trusted).
        customer_formula: A mathematical expression provided by the customer via API
                          (e.g., "revenue_impact * 0.1 + user_count * 0.05").
                          Comes from an untrusted external user (customer input).
        business_metrics: Dictionary of the customer's business metrics like
                          'revenue_impact' (float), 'user_count' (int), 'sla_tier' (int).
                          Comes from the customer's profile (trusted source but user-controlled data).

    Returns:
        The adjusted priority as an integer (1-5), clamped to valid range.
        Returns base_priority if formula is invalid or evaluation fails.
    """
    try:
        tree = ast.parse(customer_formula, mode='eval')
    except SyntaxError:
        return base_priority

    allowed_names = set(business_metrics.keys()) | _ALLOWED_FUNCTIONS | _ALLOWED_CONSTANTS
    if not _validate_ast(tree, allowed_names):
        return base_priority

    safe_dict = {**business_metrics}
    safe_dict.update({k: getattr(math, k) for k in _ALLOWED_FUNCTIONS if hasattr(math, k)})
    safe_dict.update({'pi': math.pi, 'e': math.e, 'abs': abs, 'min': min, 'max': max, 'round': round, 'pow': pow})

    try:
        adjustment = eval(compile(tree, '<string>', 'eval'), {"__builtins__": {}}, safe_dict)
        result = base_priority + int(adjustment)
        return max(1, min(5, result))
    except Exception:
        return base_priority
