import os
import secrets
import re
from pathlib import Path
from typing import Dict


def create_attestation_workspace(
    package_name: str,
    version: str,
    base_path: str,
    policy_digest: str = ""
) -> Dict[str, str]:
    """
    Creates an isolated workspace directory for package attestation verification.

    The workspace holds attestation bundles, supporting evidence, policy files,
    and verification results for a single package version. The caller writes
    attestation materials into the returned directories, then runs verification.

    Args:
        package_name: Name of the package (user-controlled, validated by caller).
        version: Version string of the package (user-controlled, validated by caller).
        base_path: Root directory for workspace creation (trusted configuration).
        policy_digest: Optional SHA-256 hex digest of the policy bundle to apply.

    Returns:
        Dictionary with keys: 'root', 'attestations', 'evidence', 'policy', 'results'.
        Each value is an absolute path string. Returns empty dict if inputs are
        invalid (empty name/version, base_path not a directory, traversal attempt).
    """
    if not package_name or not version:
        return {}

    if not re.fullmatch(r"[A-Za-z0-9._+-]+", package_name):
        return {}
    if not re.fullmatch(r"[A-Za-z0-9._+-]+", version):
        return {}

    base = Path(base_path).resolve()
    if not base.is_dir():
        return {}

    nonce = secrets.token_hex(8)
    workspace_name = f"{package_name}-{version}-{nonce}"
    workspace_root = base / workspace_name

    try:
        workspace_root.mkdir(mode=0o700, exist_ok=False)
    except (OSError, FileExistsError):
        return {}

    subdirs = {
        "attestations": workspace_root / "attestations",
        "evidence": workspace_root / "evidence",
        "policy": workspace_root / "policy",
        "results": workspace_root / "results",
    }

    try:
        for subdir in subdirs.values():
            subdir.mkdir(mode=0o700, exist_ok=False)
    except OSError:
        for subdir in reversed(list(subdirs.values())):
            try:
                subdir.rmdir()
            except OSError:
                pass
        try:
            workspace_root.rmdir()
        except OSError:
            pass
        return {}

    if policy_digest:
        policy_file = subdirs["policy"] / "policy.digest"
        try:
            policy_file.write_text(policy_digest + "\n", encoding="utf-8")
            policy_file.chmod(0o600)
        except OSError:
            for subdir in reversed(list(subdirs.values())):
                try:
                    subdir.rmdir()
                except OSError:
                    pass
            try:
                workspace_root.rmdir()
            except OSError:
                pass
            return {}

    return {
        "root": str(workspace_root),
        "attestations": str(subdirs["attestations"]),
        "evidence": str(subdirs["evidence"]),
        "policy": str(subdirs["policy"]),
        "results": str(subdirs["results"]),
    }
