import re
from typing import Dict

def extract_device_identifiers(config_text: str, id_patterns: Dict[str, str]) -> Dict[str, str]:
    """
    Extract device identifiers from configuration text using user-defined patterns.

    Args:
        config_text: Raw device configuration text (trusted, from device)
        id_patterns: Mapping of identifier names to regex patterns with one 
                     capture group (USER INPUT - from admin configuration)

    Returns:
        Dict mapping identifier names to extracted values. Missing identifiers
        are omitted. Returns empty dict if config_text empty or no patterns.

    Raises:
        ValueError: If any pattern is invalid regex, lacks exactly one capture group,
                    or is rejected by pattern policy.
    """
    if not config_text or not id_patterns:
        return {}

    def _is_safe_pattern(pattern: str) -> bool:
        if len(pattern) > 200:
            return False
        nested_quantifier = re.compile(r'\(([^)]*[+*?{][^)]*)\)[+*?{]')
        if nested_quantifier.search(pattern):
            return False
        if pattern.count('|') > 10:
            return False
        quantifier_count = len(re.findall(r'[+*?{]', pattern))
        if quantifier_count > 20:
            return False
        return True

    compiled_patterns = {}
    for name, pattern in id_patterns.items():
        if not _is_safe_pattern(pattern):
            raise ValueError(f"Pattern for '{name}' rejected by policy")
        try:
            compiled = re.compile(pattern)
        except re.error as e:
            raise ValueError(f"Invalid regex for '{name}': {e}")
        if compiled.groups != 1:
            raise ValueError(f"Pattern for '{name}' must have exactly one capture group")
        compiled_patterns[name] = compiled

    results = {}
    for name, compiled in compiled_patterns.items():
        match = compiled.search(config_text)
        if match:
            results[name] = match.group(1)
    return results
