import json
import sqlite3
from datetime import datetime, timezone
from typing import Any


def process_user_presence_update(user_id: int, payload: dict[str, Any], db_connection: sqlite3.Connection) -> dict[str, Any]:
    """
    Process a user presence update from the client and persist changes.

    The client sends a payload dictionary with presence fields to update.
    Allowed client-controlled fields:
      - status: one of "online", "away", "busy", "offline", "invisible"
      - custom_status: optional string, max 128 characters
      - idle_since: optional ISO 8601 timestamp string when user went idle
      - client_type: optional string, one of "web", "desktop", "mobile", "api"
      - capabilities: optional list of strings, subset of ["voice", "video", "screen_share", "file_transfer"]

    Server-side fields (never set by client):
      - connection_id, session_id, ip_address, device_fingerprint
      - last_seen_at, last_ping_at, trust_score, is_verified, privilege_level
      - created_at, updated_at

    Args:
        user_id: The internal user ID (validated by auth middleware).
        payload: Dictionary of presence fields from the client request body.
        db_connection: Open SQLite connection to the users database.

    Returns:
        Dictionary with the updated presence record, containing only fields
        safe to return to the client: user_id, status, custom_status, idle_since,
        client_type, capabilities, last_seen_at (ISO string), updated_at (ISO string).
        Returns empty dict if user_id not found, payload has no allowed fields,
        or any allowed field is present with an invalid value.
    """
    allowed_statuses = {"online", "away", "busy", "offline", "invisible"}
    allowed_client_types = {"web", "desktop", "mobile", "api"}
    allowed_capabilities = {"voice", "video", "screen_share", "file_transfer"}

    updates: dict[str, Any] = {}

    if "status" in payload:
        status = payload["status"]
        if isinstance(status, str) and status in allowed_statuses:
            updates["status"] = status
        else:
            return {}

    if "custom_status" in payload:
        custom_status = payload["custom_status"]
        if custom_status is None or (isinstance(custom_status, str) and len(custom_status) <= 128):
            updates["custom_status"] = custom_status
        else:
            return {}

    if "idle_since" in payload:
        idle_since = payload["idle_since"]
        if idle_since is None or (isinstance(idle_since, str) and _is_valid_iso8601(idle_since)):
            updates["idle_since"] = idle_since
        else:
            return {}

    if "client_type" in payload:
        client_type = payload["client_type"]
        if isinstance(client_type, str) and client_type in allowed_client_types:
            updates["client_type"] = client_type
        else:
            return {}

    if "capabilities" in payload:
        capabilities = payload["capabilities"]
        if isinstance(capabilities, list) and all(isinstance(c, str) and c in allowed_capabilities for c in capabilities):
            updates["capabilities"] = json.dumps(capabilities)
        else:
            return {}

    if not updates:
        return {}

    updates["updated_at"] = datetime.now(timezone.utc).isoformat()

    set_clause = ", ".join(f"{key} = ?" for key in updates.keys())
    values = list(updates.values()) + [user_id]

    cursor = db_connection.execute(
        f"UPDATE user_presence SET {set_clause} WHERE user_id = ?",
        values,
    )
    db_connection.commit()

    if cursor.rowcount == 0:
        return {}

    row = db_connection.execute(
        """
        SELECT user_id, status, custom_status, idle_since, client_type,
               capabilities, last_seen_at, updated_at
        FROM user_presence WHERE user_id = ?
        """,
        (user_id,),
    ).fetchone()

    if not row:
        return {}

    capabilities_json = row[5]
    try:
        capabilities_list = json.loads(capabilities_json) if capabilities_json else []
    except json.JSONDecodeError:
        capabilities_list = []

    return {
        "user_id": row[0],
        "status": row[1],
        "custom_status": row[2],
        "idle_since": row[3],
        "client_type": row[4],
        "capabilities": capabilities_list,
        "last_seen_at": row[6],
        "updated_at": row[7],
    }


def _is_valid_iso8601(value: str) -> bool:
    try:
        datetime.fromisoformat(value.replace("Z", "+00:00"))
        return True
    except (ValueError, AttributeError):
        return False
