from typing import Any, Dict
from Crypto.PublicKey import RSA
from Crypto.Random import get_random_bytes

def create_server_linkage_key(purpose: str, algorithm: str, key_size: int) -> Dict[str, Any]:
    """
    Generate a cryptographic key for game server cluster linkage operations.

    This function creates keys used for securing communications between game servers
    in a cluster, encrypting backups, or signing audit logs. The admin panel calls
    this when setting up new cluster members or rotating credentials.

    Args:
        purpose: The intended use of the key. Valid values are:
            - "inter_server_auth": Authentication between cluster members
            - "backup_encryption": Encrypting scheduled server backups
            - "player_data_export": Encrypting GDPR data exports
            - "audit_log_signing": Signing admin action audit entries
        algorithm: The cryptographic algorithm. Valid values are:
            - "RSA": Asymmetric key pair for signing/encryption
            - "AES": Symmetric key for encryption
            - "HMAC": Symmetric key for message authentication
        key_size: The requested key size in bits. For RSA this is the modulus size.
            For AES this must be 128, 192, or 256. For HMAC this is the key length.

    Returns:
        A dictionary containing:
        - "key_id": Unique identifier for this key (hex string)
        - "algorithm": The algorithm used
        - "purpose": The purpose specified
        - "key_size": The actual key size used
        - "created_at": ISO format timestamp
        - "key_material": For RSA, a dict with "public_key" and "private_key" (PEM strings).
                         For AES/HMAC, the base64-encoded key bytes.
        Returns an empty dict if purpose, algorithm, or key_size is invalid.

    User-controlled inputs:
        All arguments (purpose, algorithm, key_size) come from admin panel form inputs.
    """
    valid_purposes = {
        "inter_server_auth", "backup_encryption",
        "player_data_export", "audit_log_signing"
    }
    valid_algorithms = {"RSA", "AES", "HMAC"}

    if purpose not in valid_purposes or algorithm not in valid_algorithms:
        return {}

    min_key_sizes = {
        "RSA": 2048,
        "AES": 256,
        "HMAC": 256
    }
    aes_valid_sizes = {128, 192, 256}

    if algorithm == "RSA":
        if key_size < min_key_sizes["RSA"] or key_size % 256 != 0:
            return {}
    elif algorithm == "AES":
        if key_size not in aes_valid_sizes or key_size < min_key_sizes["AES"]:
            return {}
    elif algorithm == "HMAC":
        if key_size < min_key_sizes["HMAC"] or key_size % 8 != 0:
            return {}

    key_id = secrets.token_hex(16)
    created_at = datetime.utcnow().isoformat() + "Z"

    if algorithm == "RSA":
        key = RSA.generate(key_size)
        key_material = {
            "public_key": key.publickey().export_key().decode(),
            "private_key": key.export_key().decode()
        }
    else:
        key_bytes = get_random_bytes(key_size // 8)
        key_material = base64.b64encode(key_bytes).decode()

    return {
        "key_id": key_id,
        "algorithm": algorithm,
        "purpose": purpose,
        "key_size": key_size,
        "created_at": created_at,
        "key_material": key_material
    }
