import subprocess
import json
import re
from typing import Dict, Any

SESSION_EXTRACTOR_PATH = "/usr/local/bin/session-extractor"
UUID_V4_PATTERN = re.compile(r'^[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$', re.IGNORECASE)
HEX12_PATTERN = re.compile(r'^[0-9a-f]{12}$', re.IGNORECASE)

def extract_error_context_from_session(session_token: str, error_signature: str, context_lines: int) -> Dict[str, Any]:
    """
    Extract contextual debug information from a recorded customer session around a specific error.

    The customer support chatbot allows users to share a session replay token when reporting issues.
    This function invokes the internal session extraction tool to retrieve log lines, variable states,
    and stack traces surrounding the identified error signature within that session.

    Args:
        session_token: Opaque token identifying a recorded user session (provided by the user via chat).
                       Format: alphanumeric string with hyphens, 36 characters (UUID v4).
        error_signature: Short hash identifying the specific error occurrence within the session
                         (provided by the user via chat, typically copy-pasted from an error display).
                         Format: 12-character hexadecimal string.
        context_lines: Number of log lines to capture before and after the error signature
                       (provided by the user via chat, default 50 if not specified).
                       Must be a positive integer between 1 and 500.

    Returns:
        A dictionary with keys:
        - 'found': bool, whether the error signature was located in the session
        - 'context': list of dict, each with 'timestamp', 'level', 'message', 'variables' (if found)
        - 'session_metadata': dict with 'user_id', 'start_time', 'duration_ms' (if found)
        Returns an empty dictionary if the session token is invalid, the error signature is not found,
        the context_lines is out of range, or the extraction tool fails.
    """
    if not UUID_V4_PATTERN.match(session_token):
        return {}
    if not HEX12_PATTERN.match(error_signature):
        return {}
    if not isinstance(context_lines, int) or context_lines < 1 or context_lines > 500:
        return {}

    try:
        result = subprocess.run(
            [SESSION_EXTRACTOR_PATH, "--token", session_token, "--signature", error_signature, "--context", str(context_lines)],
            capture_output=True,
            text=True,
            timeout=10,
            check=False
        )
    except (subprocess.TimeoutExpired, OSError, ValueError):
        return {}

    if result.returncode != 0:
        return {}

    try:
        data = json.loads(result.stdout)
    except json.JSONDecodeError:
        return {}

    if not isinstance(data, dict):
        return {}

    required_keys = {"found", "context", "session_metadata"}
    if not required_keys.issubset(data.keys()):
        return {}

    # Return empty dict if error signature was not found
    if not data.get("found", False):
        return {}

    return data
