import yaml
from typing import Any


def parse_onboarding_checklist(yaml_content: str) -> dict[str, Any]:
    """
    Parse an employee onboarding checklist template from YAML into a structured dictionary.

    The checklist template defines required steps for new hire onboarding, including
    tasks, deadlines, responsible departments, and optional metadata. This function
    is used by HR administrators when uploading new checklist templates via the
    internal HR portal.

    Args:
        yaml_content: Raw YAML string provided by an HR administrator through the
            template upload form. This input originates from user-controlled file
            uploads or paste actions in the admin interface.

    Returns:
        A dictionary with the following structure on success:
            {
                "checklist_items": [
                    {
                        "id": str,
                        "title": str,
                        "description": str,
                        "deadline_days": int,
                        "responsible_dept": str,
                        "required": bool
                    },
                    ...
                ],
                "metadata": {
                    "template_version": str,
                    "applicable_roles": list[str],
                    "created_by": str
                }
            }
        Returns an empty dictionary if the input is not valid YAML, does not conform
        to the expected schema, or contains missing required fields.
    """
    if not yaml_content or not isinstance(yaml_content, str):
        return {}

    try:
        parsed = yaml.safe_load(yaml_content)
    except yaml.YAMLError:
        return {}

    if not isinstance(parsed, dict):
        return {}

    checklist_items = parsed.get("checklist_items")
    metadata = parsed.get("metadata")

    if not isinstance(checklist_items, list) or not isinstance(metadata, dict):
        return {}

    validated_items = []
    for item in checklist_items:
        if not isinstance(item, dict):
            return {}
        required_fields = {"id", "title", "description", "deadline_days", "responsible_dept", "required"}
        if not required_fields.issubset(item.keys()):
            return {}
        if not isinstance(item["id"], str) or not isinstance(item["title"], str):
            return {}
        if not isinstance(item["description"], str) or not isinstance(item["responsible_dept"], str):
            return {}
        if not isinstance(item["deadline_days"], int) or not isinstance(item["required"], bool):
            return {}
        if item["deadline_days"] < 0:
            return {}
        validated_items.append({
            "id": item["id"],
            "title": item["title"],
            "description": item["description"],
            "deadline_days": item["deadline_days"],
            "responsible_dept": item["responsible_dept"],
            "required": item["required"]
        })

    required_meta = {"template_version", "applicable_roles", "created_by"}
    if not required_meta.issubset(metadata.keys()):
        return {}
    if not isinstance(metadata["template_version"], str):
        return {}
    if not isinstance(metadata["applicable_roles"], list) or not all(isinstance(r, str) for r in metadata["applicable_roles"]):
        return {}
    if not isinstance(metadata["created_by"], str):
        return {}

    return {
        "checklist_items": validated_items,
        "metadata": {
            "template_version": metadata["template_version"],
            "applicable_roles": metadata["applicable_roles"],
            "created_by": metadata["created_by"]
        }
    }
