import gzip
import yaml
from typing import Optional


def accept_ticket_transfer(compressed_payload: bytes, max_tickets: int = 10) -> Optional[dict]:
    """
    Accept a ticket transfer by decompressing and parsing a gzip-compressed YAML payload.

    The payload is expected to be a gzip-compressed YAML document containing:
    - transfer_id: string identifier for the transfer
    - event_id: string identifier for the event
    - tickets: list of ticket objects, each with 'ticket_id' (str) and 'seat' (str)
    - recipient_email: string email of the recipient accepting the transfer

    Args:
        compressed_payload: Gzip-compressed bytes received from the transfer sender.
                            This input comes from an untrusted user (the transfer sender).
        max_tickets: Maximum number of tickets allowed in a single transfer (default 10).

    Returns:
        A dictionary with keys 'transfer_id', 'event_id', 'tickets', 'recipient_email'
        if the payload is valid and within limits. Returns None if the payload is
        malformed, exceeds limits, or fails validation.
    """
    MAX_DECOMPRESSED_SIZE = 1024 * 1024  # 1 MiB limit on decompressed data
    MAX_YAML_DEPTH = 10
    MAX_YAML_NODES = 1000

    if not compressed_payload:
        return None

    if max_tickets <= 0:
        return None

    try:
        decompressed_chunks = []
        total_size = 0
        with gzip.GzipFile(fileobj=__import__('io').BytesIO(compressed_payload), mode='rb') as gz:
            while True:
                chunk = gz.read(8192)
                if not chunk:
                    break
                total_size += len(chunk)
                if total_size > MAX_DECOMPRESSED_SIZE:
                    return None
                decompressed_chunks.append(chunk)
        decompressed = b''.join(decompressed_chunks)
    except (gzip.BadGzipFile, OSError, EOFError):
        return None

    try:
        class LimitedLoader(yaml.SafeLoader):
            def __init__(self, *args, **kwargs):
                super().__init__(*args, **kwargs)
                self._node_count = 0
                self._depth = 0

            def compose_node(self, parent, index):
                self._node_count += 1
                if self._node_count > MAX_YAML_NODES:
                    raise yaml.YAMLError("Node limit exceeded")
                self._depth += 1
                if self._depth > MAX_YAML_DEPTH:
                    raise yaml.YAMLError("Depth limit exceeded")
                try:
                    return super().compose_node(parent, index)
                finally:
                    self._depth -= 1

        data = yaml.load(decompressed.decode('utf-8'), Loader=LimitedLoader)
    except (yaml.YAMLError, UnicodeDecodeError, RecursionError):
        return None

    if not isinstance(data, dict):
        return None

    required_keys = {'transfer_id', 'event_id', 'tickets', 'recipient_email'}
    if not required_keys.issubset(data.keys()):
        return None

    if not isinstance(data['transfer_id'], str) or not data['transfer_id']:
        return None
    if not isinstance(data['event_id'], str) or not data['event_id']:
        return None
    if not isinstance(data['recipient_email'], str) or '@' not in data['recipient_email']:
        return None

    tickets = data['tickets']
    if not isinstance(tickets, list) or len(tickets) > max_tickets:
        return None

    for ticket in tickets:
        if not isinstance(ticket, dict):
            return None
        if 'ticket_id' not in ticket or 'seat' not in ticket:
            return None
        if not isinstance(ticket['ticket_id'], str) or not ticket['ticket_id']:
            return None
        if not isinstance(ticket['seat'], str) or not ticket['seat']:
            return None

    return {
        'transfer_id': data['transfer_id'],
        'event_id': data['event_id'],
        'tickets': tickets,
        'recipient_email': data['recipient_email']
    }
