import importlib
import logging
from typing import Callable, Any

logger = logging.getLogger(__name__)

def _default_calculator(employee_data: dict) -> dict:
    """Safe fallback calculator that returns zero amounts."""
    return {'gross': 0.0, 'deductions': 0.0, 'net': 0.0}

_BUILTIN_CALCULATORS = {
    'standard': lambda d: {
        'gross': d.get('base_pay', 0.0) + d.get('overtime_pay', 0.0),
        'deductions': d.get('base_pay', 0.0) * 0.2,
        'net': 0.0
    },
    'overtime': lambda d: {
        'gross': d.get('base_pay', 0.0) + d.get('overtime_pay', 0.0) * 1.5,
        'deductions': d.get('base_pay', 0.0) * 0.22,
        'net': 0.0
    },
}

def load_payroll_calculator(calculator_spec: dict, allowed_prefixes: list[str]) -> Callable[[dict], dict]:
    """
    Load a payroll calculator callable from a specification dictionary.

    The calculator_spec may contain:
    - 'type': 'builtin' or 'custom'
    - 'name': for builtin, the name of a standard calculator (e.g., 'standard', 'overtime')
    - 'module': for custom, a dotted module path to import (e.g., 'payroll.custom.calculators.bonus')
    - 'function': for custom, the function name within the module (default: 'calculate')

    The function validates that custom module paths start with one of the allowed_prefixes
    before importing. If validation fails or import fails, returns a safe default calculator
    that logs the issue and returns zero amounts.

    Args:
        calculator_spec: Calculator specification from payroll run config (USER INPUT)
        allowed_prefixes: List of allowed module path prefixes (trusted config)

    Returns:
        A callable(employee_data: dict) -> dict with keys 'gross', 'deductions', 'net'

    User inputs: calculator_spec (specifically 'module' and 'function' fields when type='custom')
    """
    if not isinstance(calculator_spec, dict):
        logger.warning("Invalid calculator_spec: not a dict")
        return _default_calculator

    calc_type = calculator_spec.get('type')

    if calc_type == 'builtin':
        name = calculator_spec.get('name', 'standard')
        if name in _BUILTIN_CALCULATORS:
            base_calc = _BUILTIN_CALCULATORS[name]
            def wrapper(emp_data: dict) -> dict:
                result = base_calc(emp_data)
                result['net'] = result['gross'] - result['deductions']
                return result
            return wrapper
        logger.warning(f"Unknown builtin calculator: {name}")
        return _default_calculator

    elif calc_type == 'custom':
        module_path = calculator_spec.get('module', '')
        func_name = calculator_spec.get('function', 'calculate')

        if not module_path or not isinstance(module_path, str):
            logger.warning("Custom calculator missing module path")
            return _default_calculator

        # Validate module path against allowed prefixes
        allowed = False
        for prefix in allowed_prefixes:
            if module_path == prefix or module_path.startswith(prefix + '.'):
                allowed = True
                break

        if not allowed:
            logger.warning(f"Module path not in allowed prefixes: {module_path}")
            return _default_calculator

        # Additional safety: reject paths with suspicious patterns
        if any(part.startswith('_') for part in module_path.split('.')):
            logger.warning(f"Module path contains private components: {module_path}")
            return _default_calculator

        try:
            module = importlib.import_module(module_path)
        except ImportError as e:
            logger.warning(f"Failed to import calculator module {module_path}: {e}")
            return _default_calculator

        if not hasattr(module, func_name):
            logger.warning(f"Function {func_name} not found in module {module_path}")
            return _default_calculator

        func = getattr(module, func_name)
        if not callable(func):
            logger.warning(f"Attribute {func_name} in {module_path} is not callable")
            return _default_calculator

        def wrapper(emp_data: dict) -> dict:
            try:
                result = func(emp_data)
                if not isinstance(result, dict):
                    raise ValueError("Calculator must return a dict")
                return {
                    'gross': float(result.get('gross', 0.0)),
                    'deductions': float(result.get('deductions', 0.0)),
                    'net': float(result.get('net', result.get('gross', 0.0) - result.get('deductions', 0.0)))
                }
            except Exception as e:
                logger.error(f"Calculator {module_path}.{func_name} failed: {e}")
                return _default_calculator(emp_data)

        return wrapper

    else:
        logger.warning(f"Unknown calculator type: {calc_type}")
        return _default_calculator
