import ast
import operator
from typing import Any


class _SafeExpressionEvaluator:
    """Evaluates boolean expressions in a restricted, side-effect-free environment."""

    _BIN_OPS = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
        ast.In: lambda a, b: a in b,
        ast.NotIn: lambda a, b: a not in b,
    }

    _UNARY_OPS = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
        ast.Not: operator.not_,
        ast.Invert: operator.inv,
    }

    _BOOL_OPS = {
        ast.And: all,
        ast.Or: any,
    }

    _ALLOWED_METHODS = {
        'startswith', 'endswith', 'lower', 'upper', 'strip',
        'isdigit', 'isalpha', 'isalnum',
    }

    def __init__(self):
        self._context: dict[str, Any] = {}

    def evaluate(self, expression: str, context: dict[str, Any]) -> bool:
        """
        Parse and evaluate a boolean expression safely.

        Args:
            expression: The expression string to evaluate.
            context: Variable bindings for the expression.

        Returns:
            Boolean result of the expression.

        Raises:
            ValueError: If expression contains disallowed constructs or fails to evaluate.
        """
        self._context = context
        try:
            tree = ast.parse(expression, mode='eval')
        except SyntaxError as e:
            raise ValueError(f"Invalid expression syntax: {e}") from e

        return self._eval_node(tree.body)

    def _eval_node(self, node: ast.AST) -> Any:
        if isinstance(node, ast.Constant):
            return node.value

        if isinstance(node, ast.Name):
            if node.id not in self._context:
                raise ValueError(f"Undefined variable: {node.id}")
            return self._context[node.id]

        if isinstance(node, ast.BinOp):
            op_type = type(node.op)
            if op_type not in self._BIN_OPS:
                raise ValueError(f"Disallowed binary operator: {op_type.__name__}")
            left = self._eval_node(node.left)
            right = self._eval_node(node.right)
            return self._BIN_OPS[op_type](left, right)

        if isinstance(node, ast.UnaryOp):
            op_type = type(node.op)
            if op_type not in self._UNARY_OPS:
                raise ValueError(f"Disallowed unary operator: {op_type.__name__}")
            operand = self._eval_node(node.operand)
            return self._UNARY_OPS[op_type](operand)

        if isinstance(node, ast.BoolOp):
            op_type = type(node.op)
            if op_type not in self._BOOL_OPS:
                raise ValueError(f"Disallowed boolean operator: {op_type.__name__}")
            values = [self._eval_node(v) for v in node.values]
            return self._BOOL_OPS[op_type](values)

        if isinstance(node, ast.Compare):
            left = self._eval_node(node.left)
            for op, comparator in zip(node.ops, node.comparators):
                op_type = type(op)
                if op_type not in self._BIN_OPS:
                    raise ValueError(f"Disallowed comparison operator: {op_type.__name__}")
                right = self._eval_node(comparator)
                if not self._BIN_OPS[op_type](left, right):
                    return False
                left = right
            return True

        if isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Attribute):
                raise ValueError("Only method calls on variables are allowed")
            obj = self._eval_node(node.func.value)
            method_name = node.func.attr
            if method_name not in self._ALLOWED_METHODS:
                raise ValueError(f"Disallowed method: {method_name}")
            args = [self._eval_node(arg) for arg in node.args]
            if node.keywords:
                raise ValueError("Keyword arguments not allowed")
            try:
                method = getattr(obj, method_name)
                return method(*args)
            except (AttributeError, TypeError) as e:
                raise ValueError(f"Method call failed: {e}") from e

        if isinstance(node, ast.Subscript):
            container = self._eval_node(node.value)
            if isinstance(node.slice, ast.Constant):
                key = node.slice.value
            elif isinstance(node.slice, ast.Slice):
                lower = self._eval_node(node.slice.lower) if node.slice.lower else None
                upper = self._eval_node(node.slice.upper) if node.slice.upper else None
                step = self._eval_node(node.slice.step) if node.slice.step else None
                key = slice(lower, upper, step)
            else:
                key = self._eval_node(node.slice)
            try:
                return container[key]
            except (KeyError, IndexError, TypeError) as e:
                raise ValueError(f"Subscript failed: {e}") from e

        if isinstance(node, ast.List):
            return [self._eval_node(e) for e in node.elts]

        if isinstance(node, ast.Tuple):
            return tuple(self._eval_node(e) for e in node.elts)

        raise ValueError(f"Disallowed expression construct: {type(node).__name__}")


_EVALUATOR = _SafeExpressionEvaluator()


def categorize_transactions(
    transactions: list[dict[str, Any]],
    category_rules: list[dict[str, str]],
) -> list[dict[str, Any]]:
    """
    Apply user-defined categorization rules to a list of banking transactions.

    Each transaction is a dictionary with at least the following keys:
    - 'amount': float (positive for credit, negative for debit)
    - 'description': str (transaction description text)
    - 'merchant': str (merchant name, may be empty)
    - 'date': str (ISO format YYYY-MM-DD)

    Each category rule is a dictionary with:
    - 'category': str (category name to assign when rule matches)
    - 'expression': str (user-provided boolean expression evaluated per transaction)

    The expression runs in a restricted context with these variables:
    - amount: float (transaction amount)
    - description: str
    - merchant: str
    - date: str
    - is_debit: bool (True if amount < 0)
    - is_credit: bool (True if amount > 0)
    - abs_amount: float (absolute value of amount)

    Expressions may use comparison operators (==, !=, <, >, <=, >=),
    logical operators (and, or, not), arithmetic (+, -, *, /, //, %),
    string methods (startswith, endswith, contains via 'in'),
    and parentheses for grouping.

    Rules are evaluated in order; the first matching rule assigns its category.
    If no rule matches, the transaction gets category 'Uncategorized'.

    The function returns a new list of transaction dictionaries with an added
    'category' key. Input lists are not modified.

    Arguments:
        transactions: List of transaction dictionaries from the banking system.
        category_rules: List of rule dictionaries; 'expression' comes from user configuration.

    Returns:
        List of transaction dictionaries with 'category' field added.
    """
    if not isinstance(transactions, list) or not isinstance(category_rules, list):
        return []

    result = []
    for txn in transactions:
        if not isinstance(txn, dict):
            result.append({**txn, 'category': 'Uncategorized'} if isinstance(txn, dict) else {'category': 'Uncategorized'})
            continue

        amount = txn.get('amount', 0.0)
        context = {
            'amount': float(amount),
            'description': str(txn.get('description', '')),
            'merchant': str(txn.get('merchant', '')),
            'date': str(txn.get('date', '')),
            'is_debit': amount < 0,
            'is_credit': amount > 0,
            'abs_amount': abs(float(amount)),
        }

        category = 'Uncategorized'
        for rule in category_rules:
            if not isinstance(rule, dict):
                continue
            expr = rule.get('expression', '')
            cat = rule.get('category', '')
            if not isinstance(expr, str) or not isinstance(cat, str):
                continue
            if not expr.strip():
                continue
            try:
                if _EVALUATOR.evaluate(expr, context):
                    category = cat
                    break
            except ValueError:
                continue

        result.append({**txn, 'category': category})

    return result
