import ast
from typing import Callable, Any, Set


class FilterExpressionValidator(ast.NodeVisitor):
    """AST visitor that validates filter expressions contain only allowed constructs."""

    ALLOWED_NAMES: Set[str] = {'event', 'True', 'False', 'None'}
    ALLOWED_STRING_METHODS: Set[str] = {'startswith', 'endswith', 'lower', 'upper', 'strip'}
    ALLOWED_COMPARISONS: Set[type] = {ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE, ast.In, ast.NotIn}
    ALLOWED_BOOL_OPS: Set[type] = {ast.And, ast.Or}
    ALLOWED_UNARY_OPS: Set[type] = {ast.Not}

    def __init__(self) -> None:
        self.valid = True
        self.errors: list[str] = []

    def visit(self, node: ast.AST) -> Any:
        if not self.valid:
            return
        return super().visit(node)

    def visit_Expression(self, node: ast.Expression) -> None:
        self.visit(node.body)

    def visit_BoolOp(self, node: ast.BoolOp) -> None:
        if type(node.op) not in self.ALLOWED_BOOL_OPS:
            self.valid = False
            self.errors.append(f"Disallowed boolean operator: {type(node.op).__name__}")
            return
        for value in node.values:
            self.visit(value)

    def visit_UnaryOp(self, node: ast.UnaryOp) -> None:
        if type(node.op) not in self.ALLOWED_UNARY_OPS:
            self.valid = False
            self.errors.append(f"Disallowed unary operator: {type(node.op).__name__}")
            return
        self.visit(node.operand)

    def visit_Compare(self, node: ast.Compare) -> None:
        for op in node.ops:
            if type(op) not in self.ALLOWED_COMPARISONS:
                self.valid = False
                self.errors.append(f"Disallowed comparison operator: {type(op).__name__}")
                return
        self.visit(node.left)
        for comparator in node.comparators:
            self.visit(comparator)

    def visit_Call(self, node: ast.Call) -> None:
        # Only allow method calls on strings: event.ref.startswith('foo')
        if not isinstance(node.func, ast.Attribute):
            self.valid = False
            self.errors.append("Only attribute method calls allowed")
            return
        if node.func.attr not in self.ALLOWED_STRING_METHODS:
            self.valid = False
            self.errors.append(f"Disallowed method: {node.func.attr}")
            return
        if node.keywords:
            self.valid = False
            self.errors.append("Keyword arguments not allowed")
            return
        if len(node.args) != 1:
            self.valid = False
            self.errors.append("String methods require exactly one argument")
            return
        self.visit(node.func.value)
        for arg in node.args:
            self.visit(arg)

    def visit_Attribute(self, node: ast.Attribute) -> None:
        # Allow event.ref, event.pusher.name, etc.
        self.visit(node.value)

    def visit_Subscript(self, node: ast.Subscript) -> None:
        # Allow event['ref'], event['pusher']['name']
        self.visit(node.value)
        self.visit(node.slice)

    def visit_Name(self, node: ast.Name) -> None:
        if node.id not in self.ALLOWED_NAMES:
            self.valid = False
            self.errors.append(f"Disallowed name: {node.id}")

    def visit_Constant(self, node: ast.Constant) -> None:
        # Allow string, number, bool, None constants
        if not isinstance(node.value, (str, int, float, bool, type(None))):
            self.valid = False
            self.errors.append(f"Disallowed constant type: {type(node.value).__name__}")

    def visit_List(self, node: ast.List) -> None:
        for elt in node.elts:
            self.visit(elt)

    def visit_Tuple(self, node: ast.Tuple) -> None:
        for elt in node.elts:
            self.visit(elt)

    def visit_Set(self, node: ast.Set) -> None:
        for elt in node.elts:
            self.visit(elt)

    # Explicitly disallow all other node types
    def visit_Lambda(self, node: ast.Lambda) -> None:
        self.valid = False
        self.errors.append("Lambda expressions not allowed")

    def visit_IfExp(self, node: ast.IfExp) -> None:
        self.valid = False
        self.errors.append("Ternary expressions not allowed")

    def visit_BinOp(self, node: ast.BinOp) -> None:
        self.valid = False
        self.errors.append(f"Binary operations not allowed: {type(node.op).__name__}")

    def generic_visit(self, node: ast.AST) -> None:
        allowed_types = {
            ast.Expression, ast.BoolOp, ast.UnaryOp, ast.Compare, ast.Call,
            ast.Attribute, ast.Subscript, ast.Name, ast.Constant, ast.List,
            ast.Tuple, ast.Set, ast.Load, ast.Store, ast.Del,
        }
        if type(node) not in allowed_types:
            self.valid = False
            self.errors.append(f"Disallowed construct: {type(node).__name__}")
        else:
            super().generic_visit(node)


def _safe_eval(node: ast.AST, event: dict) -> Any:
    """Evaluate a validated AST node against the event data."""
    if isinstance(node, ast.Expression):
        return _safe_eval(node.body, event)

    if isinstance(node, ast.BoolOp):
        values = [_safe_eval(v, event) for v in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        elif isinstance(node.op, ast.Or):
            return any(values)

    if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
        return not _safe_eval(node.operand, event)

    if isinstance(node, ast.Compare):
        left = _safe_eval(node.left, event)
        for op, comparator in zip(node.ops, node.comparators):
            right = _safe_eval(comparator, event)
            if isinstance(op, ast.Eq):
                result = left == right
            elif isinstance(op, ast.NotEq):
                result = left != right
            elif isinstance(op, ast.Lt):
                result = left < right
            elif isinstance(op, ast.LtE):
                result = left <= right
            elif isinstance(op, ast.Gt):
                result = left > right
            elif isinstance(op, ast.GtE):
                result = left >= right
            elif isinstance(op, ast.In):
                result = left in right
            elif isinstance(op, ast.NotIn):
                result = left not in right
            else:
                return False
            if not result:
                return False
            left = right
        return True

    if isinstance(node, ast.Call):
        obj = _safe_eval(node.func.value, event)
        method = node.func.attr
        arg = _safe_eval(node.args[0], event)
        if method == 'startswith':
            return str(obj).startswith(str(arg))
        elif method == 'endswith':
            return str(obj).endswith(str(arg))
        elif method == 'lower':
            return str(obj).lower()
        elif method == 'upper':
            return str(obj).upper()
        elif method == 'strip':
            return str(obj).strip()

    if isinstance(node, ast.Attribute):
        obj = _safe_eval(node.value, event)
        if isinstance(obj, dict):
            return obj.get(node.attr)
        return getattr(obj, node.attr, None)

    if isinstance(node, ast.Subscript):
        obj = _safe_eval(node.value, event)
        key = _safe_eval(node.slice, event)
        if isinstance(obj, (dict, list, tuple, str)):
            try:
                return obj[key]
            except (KeyError, IndexError, TypeError):
                return None
        return None

    if isinstance(node, ast.Name):
        if node.id == 'event':
            return event
        elif node.id == 'True':
            return True
        elif node.id == 'False':
            return False
        elif node.id == 'None':
            return None

    if isinstance(node, ast.Constant):
        return node.value

    if isinstance(node, ast.List):
        return [_safe_eval(elt, event) for elt in node.elts]
    if isinstance(node, ast.Tuple):
        return tuple(_safe_eval(elt, event) for elt in node.elts)
    if isinstance(node, ast.Set):
        return {_safe_eval(elt, event) for elt in node.elts}

    return None


def compile_webhook_filter(filter_expression: str) -> Callable[[dict], bool]:
    """
    Compile a webhook filter expression into a callable predicate.

    The filter expression is a restricted Python-like boolean expression
    that can access event data fields via the 'event' variable.
    Supported operations: comparisons (==, !=, <, >, <=, >=), boolean
    operators (and, or, not), membership (in), attribute access (event.ref),
    subscript access (event['ref']), and string methods (startswith, endswith).

    Args:
        filter_expression: User-defined filter string from webhook configuration.
            Example: "event.ref == 'refs/heads/main' and event.pusher.name in allowed_users"
            THIS INPUT COMES FROM USERS (repository maintainers configuring webhooks).

    Returns:
        A callable that takes an event dict and returns True if the event
        matches the filter, False otherwise. Returns a callable that always
        returns False if the expression is invalid, empty, or contains
        unsupported constructs.

    The returned callable must not raise exceptions for any event dict.
    """
    if not filter_expression or not filter_expression.strip():
        return lambda event: False

    try:
        tree = ast.parse(filter_expression.strip(), mode='eval')
    except SyntaxError:
        return lambda event: False

    validator = FilterExpressionValidator()
    validator.visit(tree)

    if not validator.valid:
        return lambda event: False

    def predicate(event: dict) -> bool:
        try:
            result = _safe_eval(tree, event)
            return bool(result)
        except Exception:
            return False

    return predicate
