import ast
import operator
from typing import Any


def evaluate_pricing_formula(formula: str, variables: dict[str, float]) -> float | None:
    """
    Evaluate a custom pricing formula for dynamic ticket pricing tiers.

    Event organizers can define pricing formulas as strings to implement
    dynamic pricing strategies (e.g., demand-based, time-based, quantity-based).
    The formula is evaluated against a provided set of numeric variables.

    Args:
        formula: A pricing formula string provided by the event organizer.
            Example: "base_price * demand_multiplier * (1 - volume_discount)"
            This input comes from the event organizer (user).
        variables: A dictionary mapping variable names to numeric values.
            Expected keys: 'base_price', 'demand_multiplier', 'volume_discount',
            'quantity', 'days_until_event', 'is_weekend' (as 0.0 or 1.0).
            All values must be int or float.

    Returns:
        The computed price as a float, rounded to 2 decimal places.
        Returns None if the formula is invalid, references undefined variables,
        contains disallowed constructs, or produces a non-numeric result.

    The formula may use:
        - Arithmetic operators: +, -, *, /, //, %, **
        - Comparison operators: ==, !=, <, >, <=, >= (returning 1.0 or 0.0)
        - Logical operators: and, or, not (with numeric operands)
        - Parentheses for grouping
        - Ternary conditional: x if condition else y
        - Variable references from the provided variables dict

    The formula must not:
        - Call functions or methods
        - Access attributes or subscripts
        - Use comprehensions, lambdas, or assignments
        - Reference any names not in the variables dict
    """
    if not isinstance(formula, str) or not formula.strip():
        return None

    if not isinstance(variables, dict):
        return None

    for v in variables.values():
        if not isinstance(v, (int, float)):
            return None

    allowed_variables = set(variables.keys())

    try:
        tree = ast.parse(formula, mode='eval')
    except SyntaxError:
        return None

    class FormulaValidator(ast.NodeVisitor):
        def __init__(self):
            self.valid = True
            self.used_names: set[str] = set()

        def visit(self, node: ast.AST) -> Any:
            if not self.valid:
                return
            return super().visit(node)

        def visit_Expression(self, node: ast.Expression) -> None:
            self.visit(node.body)

        def visit_BinOp(self, node: ast.BinOp) -> None:
            allowed_ops = (ast.Add, ast.Sub, ast.Mult, ast.Div, ast.FloorDiv, ast.Mod, ast.Pow)
            if not isinstance(node.op, allowed_ops):
                self.valid = False
                return
            self.visit(node.left)
            self.visit(node.right)

        def visit_UnaryOp(self, node: ast.UnaryOp) -> None:
            allowed_ops = (ast.UAdd, ast.USub, ast.Not)
            if not isinstance(node.op, allowed_ops):
                self.valid = False
                return
            self.visit(node.operand)

        def visit_Compare(self, node: ast.Compare) -> None:
            allowed_ops = (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE)
            if not all(isinstance(op, allowed_ops) for op in node.ops):
                self.valid = False
                return
            self.visit(node.left)
            for comparator in node.comparators:
                self.visit(comparator)

        def visit_BoolOp(self, node: ast.BoolOp) -> None:
            if not isinstance(node.op, (ast.And, ast.Or)):
                self.valid = False
                return
            for value in node.values:
                self.visit(value)

        def visit_IfExp(self, node: ast.IfExp) -> None:
            self.visit(node.test)
            self.visit(node.body)
            self.visit(node.orelse)

        def visit_Name(self, node: ast.Name) -> None:
            if node.id not in allowed_variables:
                self.valid = False
                return
            self.used_names.add(node.id)

        def visit_Constant(self, node: ast.Constant) -> None:
            if not isinstance(node.value, (int, float)):
                self.valid = False

        def visit_Call(self, node: ast.Call) -> None:
            self.valid = False

        def visit_Attribute(self, node: ast.Attribute) -> None:
            self.valid = False

        def visit_Subscript(self, node: ast.Subscript) -> None:
            self.valid = False

        def visit_Lambda(self, node: ast.Lambda) -> None:
            self.valid = False

        def visit_ListComp(self, node: ast.ListComp) -> None:
            self.valid = False

        def visit_DictComp(self, node: ast.DictComp) -> None:
            self.valid = False

        def visit_SetComp(self, node: ast.SetComp) -> None:
            self.valid = False

        def visit_GeneratorExp(self, node: ast.GeneratorExp) -> None:
            self.valid = False

        def visit_Assign(self, node: ast.Assign) -> None:
            self.valid = False

        def visit_AugAssign(self, node: ast.AugAssign) -> None:
            self.valid = False

        def visit_AnnAssign(self, node: ast.AnnAssign) -> None:
            self.valid = False

        def generic_visit(self, node: ast.AST) -> None:
            self.valid = False

    validator = FormulaValidator()
    validator.visit(tree)

    if not validator.valid:
        return None

    if not validator.used_names.issubset(allowed_variables):
        return None

    class FormulaEvaluator(ast.NodeVisitor):
        def __init__(self, vars_dict: dict[str, float]):
            self.vars = vars_dict

        def visit_Expression(self, node: ast.Expression) -> float:
            return self.visit(node.body)

        def visit_BinOp(self, node: ast.BinOp) -> float:
            left = self.visit(node.left)
            right = self.visit(node.right)
            ops = {
                ast.Add: operator.add,
                ast.Sub: operator.sub,
                ast.Mult: operator.mul,
                ast.Div: operator.truediv,
                ast.FloorDiv: operator.floordiv,
                ast.Mod: operator.mod,
                ast.Pow: operator.pow,
            }
            return ops[type(node.op)](left, right)

        def visit_UnaryOp(self, node: ast.UnaryOp) -> float:
            operand = self.visit(node.operand)
            ops = {
                ast.UAdd: operator.pos,
                ast.USub: operator.neg,
                ast.Not: operator.not_,
            }
            return ops[type(node.op)](operand)

        def visit_Compare(self, node: ast.Compare) -> float:
            left = self.visit(node.left)
            results = []
            for op, comparator in zip(node.ops, node.comparators):
                right = self.visit(comparator)
                ops = {
                    ast.Eq: operator.eq,
                    ast.NotEq: operator.ne,
                    ast.Lt: operator.lt,
                    ast.LtE: operator.le,
                    ast.Gt: operator.gt,
                    ast.GtE: operator.ge,
                }
                results.append(1.0 if ops[type(op)](left, right) else 0.0)
                left = right
            return 1.0 if all(r == 1.0 for r in results) else 0.0

        def visit_BoolOp(self, node: ast.BoolOp) -> float:
            values = [self.visit(v) for v in node.values]
            if isinstance(node.op, ast.And):
                return 1.0 if all(v != 0.0 for v in values) else 0.0
            else:
                return 1.0 if any(v != 0.0 for v in values) else 0.0

        def visit_IfExp(self, node: ast.IfExp) -> float:
            test = self.visit(node.test)
            return self.visit(node.body) if test != 0.0 else self.visit(node.orelse)

        def visit_Name(self, node: ast.Name) -> float:
            return float(self.vars[node.id])

        def visit_Constant(self, node: ast.Constant) -> float:
            return float(node.value)

    try:
        evaluator = FormulaEvaluator(variables)
        result = evaluator.visit(tree)
        if not isinstance(result, (int, float)):
            return None
        return round(float(result), 2)
    except (ZeroDivisionError, OverflowError, ValueError, KeyError):
        return None
