from typing import Callable
from urllib.parse import urlparse, urlunparse, parse_qsl, urlencode
import ipaddress
import socket
import time


def _is_public_ip(ip: ipaddress.IPv4Address | ipaddress.IPv6Address) -> bool:
    if ip.is_loopback or ip.is_private or ip.is_link_local:
        return False
    if ip.is_multicast or ip.is_reserved or ip.is_unspecified:
        return False
    if isinstance(ip, ipaddress.IPv4Address):
        if ip in ipaddress.IPv4Network("169.254.0.0/16"):
            return False
        if ip in ipaddress.IPv4Network("100.64.0.0/10"):
            return False
    if isinstance(ip, ipaddress.IPv6Address):
        if ip.ipv4_mapped and not _is_public_ip(ip.ipv4_mapped):
            return False
        if ip in ipaddress.IPv6Network("fc00::/7"):
            return False
        if ip in ipaddress.IPv6Network("fe80::/10"):
            return False
    return True


def _validate_webhook_url(
    url: str,
    resolve: Callable[[str], list[ipaddress.IPv4Address | ipaddress.IPv6Address]],
) -> bool:
    try:
        parsed = urlparse(url)
    except Exception:
        return False

    if parsed.scheme != "https":
        return False

    hostname = parsed.hostname
    if not hostname:
        return False

    if hostname.lower() in {"localhost", "localhost.localdomain"}:
        return False

    try:
        ipaddress.ip_address(hostname)
        return False
    except ValueError:
        pass

    try:
        addrs = resolve(hostname)
    except Exception:
        return False

    ips: list[ipaddress.IPv4Address | ipaddress.IPv6Address] = []
    for family, _, _, _, sockaddr in addrs:
        ip_str = sockaddr[0]
        try:
            ips.append(ipaddress.ip_address(ip_str))
        except ValueError:
            continue

    if not ips:
        return False

    return all(_is_public_ip(ip) for ip in ips)


def send_delivery_notification(
    webhook_url: str,
    tracking_number: str,
    event: str,
    fetch: Callable[[str], tuple[int, str]],
    resolve: Callable[[str], list[ipaddress.IPv4Address | ipaddress.IPv6Address]] = socket.getaddrinfo,
) -> bool:
    """
    Send a delivery status notification to a shipper-configured webhook.

    The shipper provides a base webhook URL in their carrier integration settings.
    This function appends the tracking number, event type, and a timestamp as
    query parameters, then calls the provided fetch callable with the constructed
    URL.

    Args:
        webhook_url: The base webhook URL from shipper configuration (user input).
        tracking_number: Carrier tracking number (user input). Must start with
            carrier prefix "627150" followed by 8-24 alphanumeric characters.
        event: Delivery event type (system-generated). One of: "pickup", "transit",
            "delivered", "exception".
        fetch: Callable taking a URL string, returning (status_code, response_body).
            In production this is an HTTP client; in tests it is a mock.
        resolve: Callable taking a hostname, returning a list of IP addresses.
            Defaults to socket.getaddrinfo; injectable for testing.

    Returns:
        True if fetch returns a 2xx status code, False otherwise (including
        invalid inputs, network errors, or non-2xx responses).

    The function validates that tracking_number matches the required format.
    The function validates that event is one of the four allowed values.
    The webhook_url must use HTTPS and point to a publicly routable host.
    """
    allowed_events = {"pickup", "transit", "delivered", "exception"}
    if event not in allowed_events:
        return False

    if not tracking_number.startswith("627150"):
        return False
    suffix = tracking_number[6:]
    if not (8 <= len(suffix) <= 24 and suffix.isalnum()):
        return False

    if not _validate_webhook_url(webhook_url, resolve):
        return False

    timestamp = str(int(time.time()))
    parsed = urlparse(webhook_url)
    query_params = parse_qsl(parsed.query, keep_blank_values=True)
    query_params.extend([
        ("tracking_number", tracking_number),
        ("event", event),
        ("timestamp", timestamp),
    ])
    new_query = urlencode(query_params)
    final_url = urlunparse(parsed._replace(query=new_query))

    try:
        status_code, _ = fetch(final_url)
    except Exception:
        return False

    return 200 <= status_code < 300
