import json
import os
import re
from datetime import datetime
from pathlib import Path
from typing import Any


def write_cold_chain_verification_log(
    shipment_id: str,
    temperature_readings: list[dict[str, Any]],
    output_dir: str,
) -> str:
    """
    Write a cold chain temperature verification log for a shipment.

    Creates a JSON log file containing temperature readings for regulatory compliance.
    The file is named using the shipment ID and current UTC timestamp.

    Args:
        shipment_id: Unique identifier for the shipment (user-supplied).
        temperature_readings: List of dicts with 'timestamp' (ISO format string),
            'temperature_celsius' (float or int), and 'location' (str) keys. User-supplied.
        output_dir: Directory where the log file should be created. User-supplied.

    Returns:
        Absolute path to the created log file, or empty string if input validation fails.

    The function validates that shipment_id contains only alphanumeric characters,
    hyphens, and underscores. It validates that each reading has the required keys
    and that temperature_celsius is a number. On validation failure, returns empty string.
    """
    if not re.fullmatch(r"[A-Za-z0-9_-]+", shipment_id):
        return ""

    if not isinstance(temperature_readings, list):
        return ""

    required_keys = {"timestamp", "temperature_celsius", "location"}
    for reading in temperature_readings:
        if not isinstance(reading, dict):
            return ""
        if not required_keys.issubset(reading.keys()):
            return ""
        if not isinstance(reading["temperature_celsius"], (int, float)):
            return ""
        if not isinstance(reading["timestamp"], str):
            return ""
        if not isinstance(reading["location"], str):
            return ""
        try:
            datetime.fromisoformat(reading["timestamp"].replace("Z", "+00:00"))
        except ValueError:
            return ""

    try:
        output_path = Path(output_dir).resolve()
        output_path.mkdir(parents=True, exist_ok=True)
    except (OSError, ValueError):
        return ""

    timestamp = datetime.utcnow().strftime("%Y%m%dT%H%M%SZ")
    filename = f"{shipment_id}_{timestamp}_coldchain.json"
    file_path = output_path / filename

    log_data = {
        "shipment_id": shipment_id,
        "generated_at": datetime.utcnow().isoformat() + "Z",
        "readings": temperature_readings,
    }

    try:
        fd = os.open(file_path, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(log_data, f, separators=(",", ":"))
        except Exception:
            os.close(fd)
            try:
                file_path.unlink()
            except OSError:
                pass
            return ""
    except (OSError, ValueError):
        return ""

    return str(file_path.resolve())
