import ast
import builtins
from collections.abc import Callable
from typing import Any


def compile_skip_logic(
    skip_expression: str,
    allowed_vars: frozenset[str],
    allowed_functions: frozenset[str] | None = None,
) -> Callable[[dict[str, Any]], bool] | None:
    """
    Compile a skip-logic expression into a callable predicate for multi-page surveys.

    A skip-logic expression determines whether a survey page should be skipped based on
    the respondent's answers so far and page metadata. The expression is evaluated in a
    restricted environment containing only the explicitly allowed variables and functions.

    The expression language supports:
    - Comparisons: ==, !=, <, <=, >, >=, in, not in, is, is not
    - Boolean operators: and, or, not
    - Subscript access on mappings/sequences (e.g., answers['q1'])
    - Attribute access on allowed variables (e.g., metadata.page_number)
    - Calls to allowed functions with literal arguments (e.g., len(answers['items']))
    - Literals: strings, numbers, booleans, None, lists, tuples, sets, dicts
    - Parentheses for grouping

    The returned callable accepts a single context dictionary mapping variable names to
    values. It returns True if the page should be skipped, False otherwise. If the
    expression is syntactically invalid, uses disallowed constructs, or references
    variables/functions not in the allowed sets, the function returns None.

    Args:
        skip_expression: User-provided expression string from the form builder UI.
            Example: "answers['age'] >= 18 and metadata.page_number > 1"
        allowed_vars: Frozen set of variable names permitted in the expression.
            Typically includes 'answers', 'metadata', 'response_id'.
        allowed_functions: Optional frozen set of function names permitted for calls.
            If None, defaults to {'len', 'str', 'int', 'float', 'bool', 'min', 'max',
            'sum', 'any', 'all'}. Functions are looked up in the builtins namespace.

    Returns:
        A callable (context: dict[str, Any]) -> bool, or None if compilation fails.
        The callable never raises; evaluation errors (KeyError, TypeError, etc.)
        are caught and treated as False (do not skip).

    User inputs:
        skip_expression comes directly from the form designer's skip-logic field.
        allowed_vars and allowed_functions are configured by the survey administrator.
    """
    # Functions that are never permitted, even if explicitly listed in allowed_functions
    FORBIDDEN_FUNCTIONS = frozenset({"eval", "exec", "compile", "__import__"})

    if allowed_functions is None:
        allowed_functions = frozenset(
            {"len", "str", "int", "float", "bool", "min", "max", "sum", "any", "all"}
        )

    # Remove any forbidden functions from the allowed set
    allowed_functions = allowed_functions - FORBIDDEN_FUNCTIONS

    try:
        tree = ast.parse(skip_expression, mode="eval")
    except SyntaxError:
        return None

    class Validator(ast.NodeVisitor):
        def __init__(self) -> None:
            self.valid = True

        def visit(self, node: ast.AST) -> None:
            if not self.valid:
                return
            super().visit(node)

        def generic_visit(self, node: ast.AST) -> None:
            self.valid = False

        def visit_Expression(self, node: ast.Expression) -> None:
            self.visit(node.body)

        def visit_BoolOp(self, node: ast.BoolOp) -> None:
            for value in node.values:
                self.visit(value)

        def visit_UnaryOp(self, node: ast.UnaryOp) -> None:
            if not isinstance(node.op, ast.Not):
                self.valid = False
                return
            self.visit(node.operand)

        def visit_Compare(self, node: ast.Compare) -> None:
            self.visit(node.left)
            for comparator in node.comparators:
                self.visit(comparator)

        def visit_Call(self, node: ast.Call) -> None:
            if not isinstance(node.func, ast.Name):
                self.valid = False
                return
            if node.func.id not in allowed_functions:
                self.valid = False
                return
            for arg in node.args:
                self.visit(arg)
            if node.keywords:
                self.valid = False

        def visit_Name(self, node: ast.Name) -> None:
            if isinstance(node.ctx, ast.Load):
                if node.id not in allowed_vars:
                    self.valid = False
            else:
                self.valid = False

        def visit_Attribute(self, node: ast.Attribute) -> None:
            self.visit(node.value)

        def visit_Subscript(self, node: ast.Subscript) -> None:
            self.visit(node.value)
            self.visit(node.slice)

        def visit_Constant(self, node: ast.Constant) -> None:
            if not isinstance(node.value, (str, int, float, bool, type(None))):
                self.valid = False

        def visit_List(self, node: ast.List) -> None:
            for elt in node.elts:
                self.visit(elt)

        def visit_Tuple(self, node: ast.Tuple) -> None:
            for elt in node.elts:
                self.visit(elt)

        def visit_Set(self, node: ast.Set) -> None:
            for elt in node.elts:
                self.visit(elt)

        def visit_Dict(self, node: ast.Dict) -> None:
            for key, value in zip(node.keys, node.values):
                if key is not None:
                    self.visit(key)
                self.visit(value)

    validator = Validator()
    validator.visit(tree)
    if not validator.valid:
        return None

    code = compile(tree, "<skip_logic>", "eval")

    allowed_builtins = {name: getattr(builtins, name) for name in allowed_functions}

    def evaluator(context: dict[str, Any]) -> bool:
        try:
            # Restrict globals to only allowed builtins; locals come from context
            result = eval(code, {"__builtins__": allowed_builtins}, context)
            return bool(result)
        except Exception:
            return False

    return evaluator
