import yaml
from typing import Dict, Any, Optional

def _has_yaml_aliases(yaml_text: str) -> bool:
    """Return True if the YAML text contains any alias events (*anchor)."""
    try:
        for event in yaml.parse(yaml_text):
            if isinstance(event, yaml.AliasEvent):
                return True
    except yaml.YAMLError:
        return True
    return False

def parse_encoding_preset(preset_data: bytes, max_size: int = 65536) -> Optional[Dict[str, Any]]:
    """
    Parse and validate a user-provided video encoding preset configuration.

    The preset is a YAML document with the following structure:
    {
        "name": "string",           # required, 1-64 chars
        "version": 1,               # required, must be 1
        "video": {                  # required
            "codec": "h264|hevc|vp9|av1",
            "bitrate": int,         # 100-50000 kbps
            "resolution": "WxH"     # e.g. "1920x1080", max 7680x4320
        },
        "audio": {                  # required
            "codec": "aac|opus|mp3",
            "bitrate": int          # 32-512 kbps
        },
        "filters": [                # optional, max 10 items
            "filter_name"           # string, 1-32 chars
        ]
    }

    Args:
        preset_data: Raw bytes of the uploaded preset file (user-controlled).
                     Must be UTF-8 encoded YAML.
        max_size: Maximum allowed size of preset_data in bytes. Default 65536.

    Returns:
        Validated preset dict, or None if validation fails (malformed YAML,
        invalid structure, limits exceeded, encoding error).

    User-controlled inputs: preset_data (entire content), max_size if exposed via API.
    """
    if not preset_data or len(preset_data) > max_size:
        return None
    try:
        text = preset_data.decode('utf-8')
    except UnicodeDecodeError:
        return None
    if _has_yaml_aliases(text):
        return None
    try:
        preset = yaml.load(text, Loader=yaml.SafeLoader)
    except yaml.YAMLError:
        return None
    if not isinstance(preset, dict):
        return None
    if not (isinstance(preset.get('name'), str) and 1 <= len(preset['name']) <= 64):
        return None
    if preset.get('version') != 1:
        return None
    video = preset.get('video')
    if not (isinstance(video, dict) and video.get('codec') in {'h264', 'hevc', 'vp9', 'av1'}):
        return None
    if not (isinstance(video.get('bitrate'), int) and 100 <= video['bitrate'] <= 50000):
        return None
    res = video.get('resolution', '')
    if not (isinstance(res, str) and 'x' in res):
        return None
    try:
        w, h = map(int, res.split('x', 1))
        if not (16 <= w <= 7680 and 16 <= h <= 4320 and w % 2 == 0 and h % 2 == 0):
            return None
    except ValueError:
        return None
    audio = preset.get('audio')
    if not (isinstance(audio, dict) and audio.get('codec') in {'aac', 'opus', 'mp3'}):
        return None
    if not (isinstance(audio.get('bitrate'), int) and 32 <= audio['bitrate'] <= 512):
        return None
    filters = preset.get('filters', [])
    if not (isinstance(filters, list) and len(filters) <= 10):
        return None
    for f in filters:
        if not (isinstance(f, str) and 1 <= len(f) <= 32):
            return None
    return preset
