import gzip
import io
import json
from typing import Any

def process_inventory_adjustments(gzipped_ndjson: bytes, max_events: int = 10000) -> dict[str, Any]:
    """
    Process a gzipped NDJSON (newline-delimited JSON) payload containing inventory adjustment events.

    Each line in the decompressed payload must be a JSON object with the following required fields:
    - "sku": string, product stock-keeping unit (non-empty)
    - "quantity_delta": integer, change in quantity (positive for receipts, negative for shipments)
    - "reason": string, adjustment reason code (non-empty, e.g. "receipt", "shipment", "damage", "count")
    - "warehouse_id": string, warehouse identifier (non-empty)

    Lines that are not valid JSON are counted as errors. Lines missing required fields or having
    invalid field types are counted as skipped. Valid events are collected up to max_events.

    Arguments:
        gzipped_ndjson: Gzipped bytes containing NDJSON lines. This input originates from an
            external warehouse management system upload and is untrusted.
        max_events: Maximum number of valid events to include in the returned adjustments list.
            Must be positive. Defaults to 10000.

    Returns:
        A dictionary with keys:
        - "processed": int, number of valid events parsed (capped at max_events for the list)
        - "skipped": int, number of lines with missing/invalid required fields
        - "errors": int, number of lines that failed JSON parsing
        - "adjustments": list[dict], validated event objects (up to max_events entries)
          Each adjustment dict contains the four required fields with verified types.

    If gzipped_ndjson is empty or decompresses to empty content, returns zero counts and empty list.
    If max_events <= 0, treats it as 10000.
    """
    if not gzipped_ndjson:
        return {"processed": 0, "skipped": 0, "errors": 0, "adjustments": []}

    if max_events <= 0:
        max_events = 10000

    MAX_DECOMPRESSED_SIZE = 1024 * 1024  # 1 MB limit
    CHUNK_SIZE = 64 * 1024  # 64 KB chunks

    processed = 0
    skipped = 0
    errors = 0
    adjustments: list[dict] = []
    total_decompressed = 0
    buffer = b""

    try:
        with gzip.GzipFile(fileobj=io.BytesIO(gzipped_ndjson), mode="rb") as gz:
            while True:
                chunk = gz.read(CHUNK_SIZE)
                if not chunk:
                    break
                total_decompressed += len(chunk)
                if total_decompressed > MAX_DECOMPRESSED_SIZE:
                    break
                buffer += chunk
                lines = buffer.split(b"\n")
                buffer = lines[-1]
                for line in lines[:-1]:
                    if not line.strip():
                        continue
                    try:
                        event = json.loads(line.decode("utf-8"))
                    except (json.JSONDecodeError, UnicodeDecodeError):
                        errors += 1
                        continue

                    if not _validate_event(event):
                        skipped += 1
                        continue

                    processed += 1
                    if len(adjustments) < max_events:
                        adjustments.append({
                            "sku": event["sku"],
                            "quantity_delta": event["quantity_delta"],
                            "reason": event["reason"],
                            "warehouse_id": event["warehouse_id"],
                        })

            if buffer.strip():
                try:
                    event = json.loads(buffer.decode("utf-8"))
                except (json.JSONDecodeError, UnicodeDecodeError):
                    errors += 1
                else:
                    if _validate_event(event):
                        processed += 1
                        if len(adjustments) < max_events:
                            adjustments.append({
                                "sku": event["sku"],
                                "quantity_delta": event["quantity_delta"],
                                "reason": event["reason"],
                                "warehouse_id": event["warehouse_id"],
                            })
                    else:
                        skipped += 1

    except (gzip.BadGzipFile, OSError, EOFError):
        return {"processed": 0, "skipped": 0, "errors": 0, "adjustments": []}

    return {"processed": processed, "skipped": skipped, "errors": errors, "adjustments": adjustments}


def _validate_event(event: Any) -> bool:
    if not isinstance(event, dict):
        return False
    required = ("sku", "quantity_delta", "reason", "warehouse_id")
    for field in required:
        if field not in event:
            return False
    if not isinstance(event["sku"], str) or not event["sku"]:
        return False
    if not isinstance(event["quantity_delta"], int):
        return False
    if not isinstance(event["reason"], str) or not event["reason"]:
        return False
    if not isinstance(event["warehouse_id"], str) or not event["warehouse_id"]:
        return False
    return True
