import tempfile
import os
import yaml
import subprocess
import sys
from typing import Dict, Any


def validate_automation_script(script_yaml: str, policy_version: int = 1) -> Dict[str, Any]:
    """
    Validates a user-provided automation script against the current safety policy.

    The script is provided as YAML containing a 'code' field with Python source.
    The function compiles the code to bytecode, writes it to a temporary file,
    and runs a policy checker on that file.

    Args:
        script_yaml: YAML string with required 'code' (str) and optional 'metadata' (dict).
                     The 'code' field comes from the user (untrusted).
        policy_version: Policy version to validate against (1 or 2).

    Returns:
        Dict with keys:
            'valid' (bool): whether the script passes policy checks
            'policy_version' (int): the policy version used
            'compiled_size' (int): size of compiled bytecode in bytes, 0 if invalid
        Returns {'valid': False, 'policy_version': policy_version, 'compiled_size': 0}
        on validation failure, compilation error, or invalid input.
    """
    if policy_version not in (1, 2):
        return {'valid': False, 'policy_version': policy_version, 'compiled_size': 0}

    try:
        parsed = yaml.safe_load(script_yaml)
        if not isinstance(parsed, dict) or 'code' not in parsed:
            return {'valid': False, 'policy_version': policy_version, 'compiled_size': 0}
        code = parsed['code']
        if not isinstance(code, str):
            return {'valid': False, 'policy_version': policy_version, 'compiled_size': 0}
    except yaml.YAMLError:
        return {'valid': False, 'policy_version': policy_version, 'compiled_size': 0}

    try:
        compiled = compile(code, '<automation>', 'exec')
        bytecode = compiled.co_code
    except (SyntaxError, ValueError, TypeError):
        return {'valid': False, 'policy_version': policy_version, 'compiled_size': 0}

    temp_path = None
    try:
        with tempfile.NamedTemporaryFile(mode='wb', suffix='.pyc', delete=False) as tmp:
            temp_path = tmp.name
            tmp.write(bytecode)
            tmp.flush()
            os.fsync(tmp.fileno())

        result = subprocess.run(
            [sys.executable, '-m', 'hub.policy_checker', '--version', str(policy_version), temp_path],
            capture_output=True,
            timeout=5,
        )
        valid = result.returncode == 0
        return {'valid': valid, 'policy_version': policy_version, 'compiled_size': len(bytecode)}
    except (subprocess.TimeoutExpired, subprocess.SubprocessError, OSError):
        return {'valid': False, 'policy_version': policy_version, 'compiled_size': 0}
    finally:
        if temp_path and os.path.exists(temp_path):
            try:
                os.unlink(temp_path)
            except OSError:
                pass
