import ast
import operator
from datetime import date
from typing import Any


def compute_retention_years(
    metadata: dict[str, Any],
    expression: str,
    default_years: int = 7,
) -> int:
    """
    Compute the document retention period in years by evaluating a policy expression
    against the document's metadata.

    The expression is a Python-like arithmetic/boolean formula that can reference
    metadata fields. It must evaluate to a non-negative integer number of years.
    Supported metadata fields include:
    - case_type: str (e.g., "litigation", "corporate", "regulatory")
    - jurisdiction: str (e.g., "US-FED", "US-CA", "EU")
    - sensitivity: str (e.g., "public", "confidential", "privileged")
    - created_year: int (extracted from created_date if present)
    - amount_usd: float (monetary value associated with the document)
    - party_count: int (number of parties involved)

    The expression may use: +, -, *, /, //, %, **, min(), max(), abs(), comparison
    operators (==, !=, <, <=, >, >=), boolean operators (and, or, not), ternary
    (x if cond else y), and parentheses. Function calls other than min/max/abs
    are not permitted. Names not in the metadata are treated as zero.

    Args:
        metadata: Dictionary of document metadata fields (user-controlled content).
        expression: Retention policy expression string (provided by legal admin).
        default_years: Fallback retention period if expression is invalid or
            evaluates to a non-integer/negative value.

    Returns:
        Non-negative integer years to retain the document, or default_years if
        the expression cannot be safely evaluated.
    """
    # Normalize metadata: ensure created_year exists if created_date present
    safe_metadata = dict(metadata)
    if "created_date" in safe_metadata and "created_year" not in safe_metadata:
        created = safe_metadata["created_date"]
        if isinstance(created, date):
            safe_metadata["created_year"] = created.year
        elif isinstance(created, str):
            try:
                safe_metadata["created_year"] = int(created[:4])
            except (ValueError, IndexError):
                safe_metadata["created_year"] = 0

    # Allowed AST node types for safe evaluation
    ALLOWED_NODES = {
        ast.Expression,
        ast.BinOp,
        ast.UnaryOp,
        ast.Compare,
        ast.BoolOp,
        ast.IfExp,
        ast.Call,
        ast.Name,
        ast.Constant,
        ast.Load,
        ast.Add,
        ast.Sub,
        ast.Mult,
        ast.Div,
        ast.FloorDiv,
        ast.Mod,
        ast.Pow,
        ast.USub,
        ast.UAdd,
        ast.Not,
        ast.And,
        ast.Or,
        ast.Eq,
        ast.NotEq,
        ast.Lt,
        ast.LtE,
        ast.Gt,
        ast.GtE,
    }

    ALLOWED_FUNCTIONS = {"min", "max", "abs"}

    def eval_node(node: ast.AST) -> Any:
        if type(node) not in ALLOWED_NODES:
            raise ValueError(f"Disallowed node type: {type(node).__name__}")

        if isinstance(node, ast.Expression):
            return eval_node(node.body)

        if isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float, bool, str)):
                return node.value
            raise ValueError("Invalid constant type")

        if isinstance(node, ast.Name):
            # Metadata variables or boolean constants
            if node.id in safe_metadata:
                return safe_metadata[node.id]
            if node.id in ("True", "False", "None"):
                return {"True": True, "False": False, "None": None}[node.id]
            # Unknown names evaluate to 0 (numeric context) or False (boolean)
            return 0

        if isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            op_type = type(node.op)
            if op_type == ast.Add:
                return left + right
            if op_type == ast.Sub:
                return left - right
            if op_type == ast.Mult:
                return left * right
            if op_type == ast.Div:
                if right == 0:
                    raise ZeroDivisionError
                return left / right
            if op_type == ast.FloorDiv:
                if right == 0:
                    raise ZeroDivisionError
                return left // right
            if op_type == ast.Mod:
                if right == 0:
                    raise ZeroDivisionError
                return left % right
            if op_type == ast.Pow:
                # Limit exponent to prevent resource exhaustion
                if isinstance(right, (int, float)) and right > 10:
                    raise ValueError("Exponent too large")
                return left**right
            raise ValueError(f"Unsupported binary operator: {op_type}")

        if isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            if isinstance(node.op, ast.USub):
                return -operand
            if isinstance(node.op, ast.UAdd):
                return +operand
            if isinstance(node.op, ast.Not):
                return not operand
            raise ValueError(f"Unsupported unary operator: {type(node.op)}")

        if isinstance(node, ast.Compare):
            left = eval_node(node.left)
            for op, comparator in zip(node.ops, node.comparators):
                right = eval_node(comparator)
                op_type = type(op)
                if op_type == ast.Eq:
                    result = left == right
                elif op_type == ast.NotEq:
                    result = left != right
                elif op_type == ast.Lt:
                    result = left < right
                elif op_type == ast.LtE:
                    result = left <= right
                elif op_type == ast.Gt:
                    result = left > right
                elif op_type == ast.GtE:
                    result = left >= right
                else:
                    raise ValueError(f"Unsupported comparison: {op_type}")
                if not result:
                    return False
                left = right
            return True

        if isinstance(node, ast.BoolOp):
            values = [eval_node(v) for v in node.values]
            if isinstance(node.op, ast.And):
                return all(values)
            if isinstance(node.op, ast.Or):
                return any(values)
            raise ValueError(f"Unsupported boolean operator: {type(node.op)}")

        if isinstance(node, ast.IfExp):
            test = eval_node(node.test)
            return eval_node(node.body) if test else eval_node(node.orelse)

        if isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Name):
                raise ValueError("Only direct function calls allowed")
            func_name = node.func.id
            if func_name not in ALLOWED_FUNCTIONS:
                raise ValueError(f"Function '{func_name}' not allowed")
            args = [eval_node(arg) for arg in node.args]
            if node.keywords:
                raise ValueError("Keyword arguments not allowed")
            if func_name == "min":
                return min(args)
            if func_name == "max":
                return max(args)
            if func_name == "abs":
                if len(args) != 1:
                    raise ValueError("abs() takes exactly one argument")
                return abs(args[0])

        raise ValueError(f"Unhandled node: {type(node).__name__}")

    try:
        tree = ast.parse(expression, mode="eval")
        result = eval_node(tree)
        # Result must be a non-negative integer
        if isinstance(result, bool):
            result = int(result)
        if isinstance(result, (int, float)):
            years = int(result)
            return max(0, years)
        return default_years
    except (SyntaxError, ValueError, ZeroDivisionError, TypeError, OverflowError, RecursionError):
        return default_years
```

