import subprocess
import json
import re
from pathlib import Path
from typing import List, Dict, Any


def generate_waitlist_report(
    term_code: str,
    course_code: str,
    student_ids: List[str],
    report_binary: str
) -> Dict[str, Any]:
    """
    Generate a waitlist position report by invoking the legacy report generator binary.

    The binary outputs JSON to stdout with the following structure:
    {
        "course": "CS101",
        "term": "2024F",
        "waitlist": [
            {"student_id": "S12345", "position": 1, "status": "active"},
            {"student_id": "S12346", "position": 2, "status": "active"}
        ],
        "generated_at": "2024-01-15T10:30:00Z"
    }

    Args:
        term_code: Academic term code (e.g., "2024F", "2025S"). User-provided.
        course_code: Course identifier (e.g., "CS101", "MATH200"). User-provided.
        student_ids: List of student university IDs to include in the report. User-provided.
        report_binary: Absolute path to the legacy report generator executable. Trusted configuration.

    Returns:
        Dictionary with keys: 'course', 'term', 'waitlist' (list of dicts), 'generated_at'.
        Returns empty dict {} if the binary is not found, times out, returns non-zero exit code,
        or produces invalid JSON output.
    """
    # Validate term_code: alphanumeric, 4-6 chars, format like 2024F, 2025S, 2024SU
    if not re.fullmatch(r'\d{4}[A-Z]{1,2}', term_code):
        return {}

    # Validate course_code: dept (2-4 letters) + number (3-4 digits), optional section letter
    if not re.fullmatch(r'[A-Z]{2,4}\d{3,4}[A-Z]?', course_code):
        return {}

    # Validate student_ids: each must be 'S' followed by 5-8 digits
    for sid in student_ids:
        if not re.fullmatch(r'S\d{5,8}', sid):
            return {}

    # Validate report_binary is an absolute path and exists
    binary_path = Path(report_binary)
    if not binary_path.is_absolute() or not binary_path.exists() or not binary_path.is_file():
        return {}

    # Build argument list - no shell, no string interpolation
    args = [str(binary_path), '--term', term_code, '--course', course_code]
    if student_ids:
        args.extend(['--students'] + student_ids)

    try:
        result = subprocess.run(
            args,
            capture_output=True,
            text=True,
            timeout=10,
            check=False
        )
    except (subprocess.TimeoutExpired, OSError, ValueError):
        return {}

    if result.returncode != 0:
        return {}

    try:
        data = json.loads(result.stdout)
    except json.JSONDecodeError:
        return {}

    # Validate expected structure
    required_keys = {'course', 'term', 'waitlist', 'generated_at'}
    if not isinstance(data, dict) or not required_keys.issubset(data.keys()):
        return {}
    if not isinstance(data['waitlist'], list):
        return {}

    return data
