import re
import sys
from typing import Any


def filter_webhook_events(
    events: list[dict[str, Any]],
    branch_pattern: str | None,
    tag_pattern: str | None,
) -> list[dict[str, Any]]:
    """
    Filter webhook events based on user-configured branch and tag regex patterns.

    Args:
        events: List of webhook event dictionaries. Each event must contain a 'ref'
            field (str, e.g. 'refs/heads/main', 'refs/tags/v1.0.0') and an 'event_type'
            field (str, either 'push' or 'tag_push'). Other fields are preserved.
        branch_pattern: User-supplied regex pattern to match against branch names
            (the part after 'refs/heads/'). If None or empty string, all branches match.
            Comes from the webhook configuration form in the UI.
        tag_pattern: User-supplied regex pattern to match against tag names
            (the part after 'refs/tags/'). If None or empty string, all tags match.
            Comes from the webhook configuration form in the UI.

    Returns:
        List of events that match the configured patterns. Events with ref values
        not starting with 'refs/heads/' or 'refs/tags/' are excluded. Returns an
        empty list if no events match, if events is empty, or if both patterns
        are provided but match nothing.
    """
    if not events:
        return []

    MAX_REF_NAME_LENGTH = 256
    MAX_PATTERN_LENGTH = 500
    MATCH_TIMEOUT = 1.0

    def _compile_safe(pattern: str | None) -> re.Pattern | None:
        if not pattern:
            return None
        if len(pattern) > MAX_PATTERN_LENGTH:
            return None
        try:
            return re.compile(pattern)
        except re.error:
            return None

    def _matches(pattern: re.Pattern | None, value: str) -> bool:
        if pattern is None:
            return True
        if len(value) > MAX_REF_NAME_LENGTH:
            return False
        try:
            if sys.version_info >= (3, 11):
                return pattern.fullmatch(value, timeout=MATCH_TIMEOUT) is not None
            return pattern.fullmatch(value) is not None
        except (re.error, TimeoutError):
            return False

    branch_re = _compile_safe(branch_pattern)
    tag_re = _compile_safe(tag_pattern)

    if branch_re is None and branch_pattern:
        return []
    if tag_re is None and tag_pattern:
        return []

    filtered = []
    for event in events:
        ref = event.get("ref", "")
        if ref.startswith("refs/heads/"):
            name = ref[len("refs/heads/") :]
            if _matches(branch_re, name):
                filtered.append(event)
        elif ref.startswith("refs/tags/"):
            name = ref[len("refs/tags/") :]
            if _matches(tag_re, name):
                filtered.append(event)
    return filtered
