import yaml
from pathlib import Path
from typing import Any


def load_measurement_session(manifest_path: str, allowed_sensors: list[str]) -> dict[str, Any] | None:
    """
    Load a measurement session from a YAML manifest file.

    The manifest describes a scientific data acquisition session including sensor
    configurations, calibration coefficients, and processing parameters. This
    function validates the manifest structure and returns a normalized session
    dictionary suitable for downstream analysis pipelines.

    Args:
        manifest_path: Path to the YAML manifest file. This file is provided by
            researchers uploading experiment data to the archive and may originate
            from external collaborators or automated instruments.
        allowed_sensors: List of sensor type identifiers that are permitted in
            this archive instance. Any sensor type not in this list will cause
            the session to be rejected.

    Returns:
        A dictionary with keys:
            - 'session_id': str, unique identifier for the measurement session
            - 'timestamp': str, ISO 8601 timestamp of session start
            - 'sensors': list[dict], each dict has 'type', 'serial', 'config' (dict)
            - 'calibration': dict mapping sensor serial to calibration coefficients (dict)
            - 'processing': dict with pipeline parameters
        Returns None if the manifest is missing, malformed, contains disallowed
        sensor types, or fails structural validation.

    The function does not raise exceptions for invalid input; it returns None.
    """
    path = Path(manifest_path)
    if not path.is_file():
        return None

    try:
        with path.open("r", encoding="utf-8") as f:
            data = yaml.safe_load(f)
    except (yaml.YAMLError, OSError, UnicodeDecodeError):
        return None

    if not isinstance(data, dict):
        return None

    required_keys = {"session_id", "timestamp", "sensors", "calibration", "processing"}
    if not required_keys.issubset(data.keys()):
        return None

    session_id = data.get("session_id")
    timestamp = data.get("timestamp")
    sensors = data.get("sensors")
    calibration = data.get("calibration")
    processing = data.get("processing")

    if not isinstance(session_id, str) or not session_id.strip():
        return None
    if not isinstance(timestamp, str) or not timestamp.strip():
        return None
    if not isinstance(sensors, list):
        return None
    if not isinstance(calibration, dict):
        return None
    if not isinstance(processing, dict):
        return None

    normalized_sensors = []
    for sensor in sensors:
        if not isinstance(sensor, dict):
            return None
        s_type = sensor.get("type")
        s_serial = sensor.get("serial")
        s_config = sensor.get("config")
        if not isinstance(s_type, str) or s_type not in allowed_sensors:
            return None
        if not isinstance(s_serial, str) or not s_serial.strip():
            return None
        if not isinstance(s_config, dict):
            return None
        normalized_sensors.append({
            "type": s_type,
            "serial": s_serial,
            "config": _sanitize_config(s_config),
        })

    normalized_calibration = {}
    for serial, coeffs in calibration.items():
        if not isinstance(serial, str) or not serial.strip():
            return None
        if not isinstance(coeffs, dict):
            return None
        normalized_calibration[serial] = _sanitize_calibration(coeffs)

    return {
        "session_id": session_id.strip(),
        "timestamp": timestamp.strip(),
        "sensors": normalized_sensors,
        "calibration": normalized_calibration,
        "processing": _sanitize_processing(processing),
    }


def _sanitize_config(config: dict[str, Any]) -> dict[str, Any]:
    """Recursively keep only safe scalar types and nested dicts/lists."""
    safe = {}
    for k, v in config.items():
        if not isinstance(k, str):
            continue
        if isinstance(v, (str, int, float, bool)) or v is None:
            safe[k] = v
        elif isinstance(v, dict):
            safe[k] = _sanitize_config(v)
        elif isinstance(v, list):
            safe[k] = [_sanitize_list_item(item) for item in v if _sanitize_list_item(item) is not None]
    return safe


def _sanitize_list_item(item: Any) -> Any:
    if isinstance(item, (str, int, float, bool)) or item is None:
        return item
    if isinstance(item, dict):
        return _sanitize_config(item)
    if isinstance(item, list):
        return [_sanitize_list_item(i) for i in item if _sanitize_list_item(i) is not None]
    return None


def _sanitize_calibration(coeffs: dict[str, Any]) -> dict[str, Any]:
    """Calibration coefficients must be numeric scalars or lists of numbers."""
    safe = {}
    for k, v in coeffs.items():
        if not isinstance(k, str):
            continue
        if isinstance(v, (int, float)):
            safe[k] = v
        elif isinstance(v, list) and all(isinstance(x, (int, float)) for x in v):
            safe[k] = v
    return safe


def _sanitize_processing(processing: dict[str, Any]) -> dict[str, Any]:
    """Processing parameters: keep only known safe keys with validated types."""
    allowed = {
        "filter_window": (int, float),
        "baseline_correction": bool,
        "downsample_factor": int,
        "quality_threshold": (int, float),
    }
    safe = {}
    for k, v in processing.items():
        if k in allowed:
            expected = allowed[k]
            if isinstance(expected, tuple):
                if isinstance(v, expected):
                    safe[k] = v
            elif isinstance(v, expected):
                safe[k] = v
    return safe
