import ast
from typing import Any, Dict, Optional


class SafeEvalVisitor(ast.NodeVisitor):
    """AST visitor that validates only allowed nodes are present."""

    ALLOWED_BINOPS = {
        ast.Add, ast.Sub, ast.Mult, ast.Div, ast.FloorDiv, ast.Mod, ast.Pow
    }
    ALLOWED_CMPOPS = {
        ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE
    }
    ALLOWED_BOOL_OPS = {ast.And, ast.Or}
    ALLOWED_UNARY_OPS = {ast.UAdd, ast.USub, ast.Not}
    ALLOWED_FUNCTIONS = {'min', 'max', 'abs', 'round', 'sum', 'len'}

    # Node types allowed in the AST (including operators and context markers)
    ALLOWED_NODE_TYPES = {
        ast.Expression,
        ast.BinOp, ast.UnaryOp, ast.Compare, ast.BoolOp, ast.IfExp,
        ast.Name, ast.Call, ast.Attribute, ast.Subscript,
        ast.Constant, ast.List, ast.Tuple, ast.Dict,
        ast.Load,
        # Operator nodes (appear as 'op' field in BinOp, UnaryOp, etc.)
        ast.Add, ast.Sub, ast.Mult, ast.Div, ast.FloorDiv, ast.Mod, ast.Pow,
        ast.UAdd, ast.USub, ast.Not,
        ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE,
        ast.And, ast.Or,
    }

    def __init__(self):
        self.valid = True
        self.error = None

    def visit(self, node):
        if not self.valid:
            return
        return super().visit(node)

    def visit_BinOp(self, node):
        if type(node.op) not in self.ALLOWED_BINOPS:
            self.valid = False
            self.error = f"Disallowed binary operator: {type(node.op).__name__}"
            return
        self.generic_visit(node)

    def visit_Compare(self, node):
        for op in node.ops:
            if type(op) not in self.ALLOWED_CMPOPS:
                self.valid = False
                self.error = f"Disallowed comparison operator: {type(op).__name__}"
                return
        self.generic_visit(node)

    def visit_BoolOp(self, node):
        if type(node.op) not in self.ALLOWED_BOOL_OPS:
            self.valid = False
            self.error = f"Disallowed boolean operator: {type(node.op).__name__}"
            return
        self.generic_visit(node)

    def visit_UnaryOp(self, node):
        if type(node.op) not in self.ALLOWED_UNARY_OPS:
            self.valid = False
            self.error = f"Disallowed unary operator: {type(node.op).__name__}"
            return
        self.generic_visit(node)

    def visit_Call(self, node):
        if not isinstance(node.func, ast.Name):
            self.valid = False
            self.error = "Only direct function calls allowed"
            return
        if node.func.id not in self.ALLOWED_FUNCTIONS:
            self.valid = False
            self.error = f"Disallowed function call: {node.func.id}"
            return
        if node.keywords:
            self.valid = False
            self.error = "Keyword arguments not allowed"
            return
        self.generic_visit(node)

    def visit_IfExp(self, node):
        self.generic_visit(node)

    def visit_Attribute(self, node):
        self.generic_visit(node)

    def visit_Subscript(self, node):
        self.generic_visit(node)

    def visit_Name(self, node):
        self.generic_visit(node)

    def visit_Constant(self, node):
        pass

    def visit_List(self, node):
        self.generic_visit(node)

    def visit_Tuple(self, node):
        self.generic_visit(node)

    def visit_Dict(self, node):
        self.generic_visit(node)

    def generic_visit(self, node):
        if type(node) not in self.ALLOWED_NODE_TYPES:
            self.valid = False
            self.error = f"Disallowed AST node: {type(node).__name__}"
            return
        super().generic_visit(node)


def evaluate_grading_rule(
    rule_script: str,
    student_data: Dict[str, Any],
    course_context: Optional[Dict[str, Any]] = None
) -> Any:
    """
    Evaluate a teacher-defined grading rule script against a student's data.

    The rule script is a restricted Python expression that computes a grade result
    (numeric score, letter grade, or pass/fail boolean) from student metrics.
    Teachers author these scripts in the grading portal's rule editor.

    Allowed constructs in rule_script:
    - Arithmetic: +, -, *, /, //, %, **
    - Comparisons: ==, !=, <, <=, >, >=
    - Logical: and, or, not
    - Ternary: x if cond else y
    - Attribute access on provided data objects (e.g., student.attendance)
    - Subscript access on provided data objects (e.g., scores['midterm'])
    - Calls to whitelisted safe functions: min, max, abs, round, sum, len

    Arguments:
        rule_script: The grading expression string authored by a teacher.
                     This input comes from a user (teacher) via the portal UI.
        student_data: Dictionary containing the student's recorded metrics
                      (e.g., {'attendance': 0.85, 'scores': {'hw': 90, 'exam': 78}}).
        course_context: Optional dictionary with course-level constants
                        (e.g., {'passing_threshold': 60, 'max_extra_credit': 5}).

    Returns:
        The result of evaluating the expression (int, float, str, or bool),
        or None if the rule_script is empty, invalid, or contains disallowed constructs.

    Raises:
        Nothing. All errors result in a None return value.
    """
    if not rule_script or not rule_script.strip():
        return None

    try:
        tree = ast.parse(rule_script.strip(), mode='eval')
    except SyntaxError:
        return None

    validator = SafeEvalVisitor()
    validator.visit(tree)
    if not validator.valid:
        return None

    safe_builtins = {
        'min': min, 'max': max, 'abs': abs, 'round': round,
        'sum': sum, 'len': len
    }

    namespace = {'student': student_data}
    if course_context:
        namespace.update(course_context)

    try:
        code = compile(tree, '<grading_rule>', 'eval')
        result = eval(code, {"__builtins__": {}}, {**safe_builtins, **namespace})
        return result
    except Exception:
        return None
