from pathlib import Path
from typing import Optional
import yaml


def resolve_ticket_template(theme_name: str, template_name: str, base_themes_dir: Path) -> Optional[str]:
    """
    Resolve the full path to a ticket template file within a theme directory.

    Ticket themes can inherit from a parent theme via a 'parent' key in theme.yaml.
    This function walks the inheritance chain to find the requested template.

    Args:
        theme_name: Name of the theme (user-controlled input from event organizer).
        template_name: Name of the template file to find (user-controlled input).
        base_themes_dir: Root directory containing all themes (trusted configuration).

    Returns:
        Absolute path to the template file as a string if found, None otherwise.

    The function searches for template_name in the theme's templates/ directory,
    then recursively in parent themes. Theme names and template names come from
    event organizer input via the ticket design editor.
    """
    try:
        base_themes_dir = base_themes_dir.resolve(strict=True)
    except (OSError, ValueError):
        return None

    visited: set[Path] = set()
    current_theme = theme_name.strip()

    while current_theme:
        if not current_theme or current_theme.startswith('.') or '..' in current_theme:
            return None

        theme_dir = (base_themes_dir / current_theme).resolve()
        try:
            theme_dir.relative_to(base_themes_dir)
        except ValueError:
            return None

        if theme_dir in visited:
            return None
        visited.add(theme_dir)

        if not theme_dir.is_dir():
            return None

        templates_dir = (theme_dir / "templates").resolve()
        try:
            templates_dir.relative_to(theme_dir)
        except ValueError:
            return None

        if not templates_dir.is_dir():
            current_theme = None
            theme_config = theme_dir / "theme.yaml"
            parent_theme = None
            if theme_config.is_file():
                try:
                    with theme_config.open("r", encoding="utf-8") as f:
                        config = yaml.safe_load(f) or {}
                    parent_theme = config.get("parent")
                    if not isinstance(parent_theme, str):
                        parent_theme = None
                except (yaml.YAMLError, OSError, UnicodeDecodeError):
                    pass
            current_theme = parent_theme.strip() if parent_theme else None
            continue

        template_path = (templates_dir / template_name).resolve()
        try:
            template_path.relative_to(templates_dir)
        except ValueError:
            pass
        else:
            if template_path.is_file():
                return str(template_path)

        theme_config = theme_dir / "theme.yaml"
        parent_theme = None
        if theme_config.is_file():
            try:
                with theme_config.open("r", encoding="utf-8") as f:
                    config = yaml.safe_load(f) or {}
                parent_theme = config.get("parent")
                if not isinstance(parent_theme, str):
                    parent_theme = None
            except (yaml.YAMLError, OSError, UnicodeDecodeError):
                pass

        current_theme = parent_theme.strip() if parent_theme else None

    return None
