import ast
from typing import Any, Callable


def create_sort_key_function(expression: str, allowed_attributes: list[str]) -> Callable[[dict], Any] | None:
    """
    Create a sort key function from a user-provided expression for book collection sorting.

    Args:
        expression: A Python expression string that evaluates to a sort key for a single book.
                    Comes from librarian user input via the advanced sort configuration UI.
                    Examples: "book['author'].lower()", "-book['year']", "book['title'][::-1]".
        allowed_attributes: List of book dictionary keys that the expression may access.
                            Provided by the system configuration, not user input.
                            Example: ['title', 'author', 'year', 'isbn', 'genre'].

    Returns:
        A callable that takes a book dict and returns the computed sort key, or None if the
        expression is invalid, references disallowed attributes, or contains unsafe constructs.

    The expression is evaluated in a restricted context where only the 'book' variable (a dict)
    is available. Attribute access is limited to keys listed in allowed_attributes.
    """
    if not expression or not isinstance(expression, str):
        return None

    allowed_attrs = set(allowed_attributes)

    class ExpressionValidator(ast.NodeVisitor):
        def __init__(self):
            self.valid = True
            self.errors: list[str] = []

        def visit_Name(self, node: ast.Name):
            if node.id != 'book':
                self.valid = False
                self.errors.append(f"Disallowed name: {node.id}")
            self.generic_visit(node)

        def visit_Attribute(self, node: ast.Attribute):
            # Block dunder attributes (e.g., __class__, __globals__)
            if node.attr.startswith('__') and node.attr.endswith('__'):
                self.valid = False
                self.errors.append(f"Dunder attribute access not allowed: {node.attr}")
            # Block attribute access directly on the book dict (use subscript instead)
            elif isinstance(node.value, ast.Name) and node.value.id == 'book':
                self.valid = False
                self.errors.append("Attribute access on 'book' not allowed, use subscript")
            else:
                self.generic_visit(node)

        def visit_Subscript(self, node: ast.Subscript):
            # If subscripting the book dict, key must be an allowed string constant
            if isinstance(node.value, ast.Name) and node.value.id == 'book':
                key = node.slice
                # Handle Python 3.9+ (slice is the value directly) and older (ast.Index)
                if isinstance(key, ast.Index):
                    key = key.value
                if isinstance(key, ast.Constant) and isinstance(key.value, str):
                    if key.value not in allowed_attrs:
                        self.valid = False
                        self.errors.append(f"Disallowed book key: {key.value}")
                else:
                    self.valid = False
                    self.errors.append("Book key must be a string constant")
            # Subscripting other values (e.g., string slicing) is allowed
            self.generic_visit(node)

        def visit_Call(self, node: ast.Call):
            # Calls are allowed (e.g., str.lower()) but arguments will be validated recursively
            self.generic_visit(node)

        def visit_Lambda(self, node: ast.Lambda):
            self.valid = False
            self.errors.append("Lambda expressions not allowed")
            self.generic_visit(node)

        def visit_ListComp(self, node: ast.ListComp):
            self.valid = False
            self.errors.append("Comprehensions not allowed")
            self.generic_visit(node)

        def visit_DictComp(self, node: ast.DictComp):
            self.valid = False
            self.errors.append("Comprehensions not allowed")
            self.generic_visit(node)

        def visit_GeneratorExp(self, node: ast.GeneratorExp):
            self.valid = False
            self.errors.append("Generator expressions not allowed")
            self.generic_visit(node)

        def visit_SetComp(self, node: ast.SetComp):
            self.valid = False
            self.errors.append("Comprehensions not allowed")
            self.generic_visit(node)

        def visit_Import(self, node: ast.Import):
            self.valid = False
            self.errors.append("Imports not allowed")
            self.generic_visit(node)

        def visit_ImportFrom(self, node: ast.ImportFrom):
            self.valid = False
            self.errors.append("Imports not allowed")
            self.generic_visit(node)

    try:
        tree = ast.parse(expression, mode='eval')
    except SyntaxError:
        return None

    validator = ExpressionValidator()
    validator.visit(tree)

    if not validator.valid:
        return None

    try:
        code = compile(tree, '<sort_expression>', 'eval')
    except (SyntaxError, ValueError, TypeError):
        return None

    def sort_key(book: dict) -> Any:
        try:
            return eval(code, {"__builtins__": {}}, {"book": book})
        except Exception:
            return ()

    return sort_key
