from Crypto.PublicKey import RSA
from typing import Dict


def generate_deed_signing_keypair(modulus_bits: int, signing_context: str) -> Dict[str, str]:
    """
    Generates an RSA key pair for digitally signing property deed documents.

    The modulus_bits parameter specifies the RSA modulus size in bits. The signing_context
    is embedded in the key comment for audit trail purposes and should uniquely identify
    the deed transaction (e.g., "warranty_deed_CA_2024_12345").

    Args:
        modulus_bits: RSA modulus size in bits. Must be a positive integer.
                      This value comes from user configuration.
        signing_context: Contextual identifier for the deed signing. Must be non-empty.
                         This value comes from user input.

    Returns:
        A dictionary with keys "private_key_pem" and "public_key_pem" containing
        PEM-encoded RSA keys as strings. Returns an empty dictionary if modulus_bits
        is not a positive integer or signing_context is empty.
    """
    if not isinstance(modulus_bits, int) or modulus_bits <= 0:
        return {}
    if not isinstance(signing_context, str) or not signing_context.strip():
        return {}

    # Enforce minimum key size per current cryptographic standards
    # RSA-2048 is the minimum recommended; RSA-3072 or RSA-4096 preferred for long-term validity
    if modulus_bits < 2048:
        return {}

    try:
        key = RSA.generate(modulus_bits)
        comment = f"deed-signing:{signing_context.strip()}"
        private_pem = key.export_key(passphrase=None, pkcs=8, protection=None, randfunc=None).decode('ascii')
        public_pem = key.publickey().export_key().decode('ascii')
        return {
            "private_key_pem": private_pem,
            "public_key_pem": public_pem
        }
    except (ValueError, TypeError):
        return {}
