import yaml
from typing import Any


def parse_customer_preference_profile(yaml_string: str) -> dict[str, Any]:
    """
    Parse a customer preference profile from a YAML string.

    Customers can export their preference profiles as YAML and import them
    on other devices or share with family members. The profile contains
    dining preferences used to personalize menu recommendations and
    filtering.

    Args:
        yaml_string: A YAML-formatted string containing the preference profile.
            This input comes directly from the user (file upload or paste).

    Returns:
        A dictionary with the following keys (all optional in input, defaults applied):
        - dietary_restrictions: list[str] (default: [])
        - spice_tolerance: int 1-10 (default: 5)
        - favorite_cuisines: list[str] (default: [])
        - allergens: list[str] (default: [])
        - preferred_price_range: tuple[float, float] | None (default: None)
        - delivery_instructions: str (default: "")
        - notification_preferences: dict[str, bool] (default: {"email": True, "push": True, "sms": False})

        Returns an empty dictionary if the input is not valid YAML, not a mapping,
        or contains type mismatches for any field.
    """
    if not isinstance(yaml_string, str):
        return {}

    try:
        parsed = yaml.safe_load(yaml_string)
    except yaml.YAMLError:
        return {}

    if not isinstance(parsed, dict):
        return {}

    result: dict[str, Any] = {}

    dietary = parsed.get("dietary_restrictions")
    if isinstance(dietary, list) and all(isinstance(x, str) for x in dietary):
        result["dietary_restrictions"] = dietary
    else:
        result["dietary_restrictions"] = []

    spice = parsed.get("spice_tolerance")
    if isinstance(spice, int) and 1 <= spice <= 10:
        result["spice_tolerance"] = spice
    else:
        result["spice_tolerance"] = 5

    cuisines = parsed.get("favorite_cuisines")
    if isinstance(cuisines, list) and all(isinstance(x, str) for x in cuisines):
        result["favorite_cuisines"] = cuisines
    else:
        result["favorite_cuisines"] = []

    allergens = parsed.get("allergens")
    if isinstance(allergens, list) and all(isinstance(x, str) for x in allergens):
        result["allergens"] = allergens
    else:
        result["allergens"] = []

    price_range = parsed.get("preferred_price_range")
    if (
        isinstance(price_range, (list, tuple))
        and len(price_range) == 2
        and all(isinstance(x, (int, float)) for x in price_range)
    ):
        result["preferred_price_range"] = (float(price_range[0]), float(price_range[1]))
    else:
        result["preferred_price_range"] = None

    delivery = parsed.get("delivery_instructions")
    if isinstance(delivery, str):
        result["delivery_instructions"] = delivery
    else:
        result["delivery_instructions"] = ""

    notif = parsed.get("notification_preferences")
    default_notif = {"email": True, "push": True, "sms": False}
    if isinstance(notif, dict):
        result["notification_preferences"] = {
            "email": bool(notif.get("email", True)),
            "push": bool(notif.get("push", True)),
            "sms": bool(notif.get("sms", False)),
        }
    else:
        result["notification_preferences"] = default_notif

    return result
