import hashlib
import yaml
from pathlib import Path

def save_chapter_manifest(
    video_id: str,
    manifest_content: bytes,
    client_filename: str,
    manifest_dir: Path
) -> str:
    """
    Save a user-uploaded chapter manifest for a video.

    The manifest defines chapter markers (timestamps, titles, optional thumbnail references)
    for video navigation. Content creators upload YAML manifests to customize chapter points.

    Args:
        video_id: Internal video identifier (alphanumeric, provided by system).
        manifest_content: Raw bytes of the uploaded manifest file (user-controlled).
        client_filename: Original filename from the upload request (user-controlled).
        manifest_dir: Directory where manifests are stored (system-controlled).

    Returns:
        The stored manifest filename (without directory) on success, empty string on failure.
        Failure cases: invalid YAML, missing required fields, video_id mismatch,
        client_filename indicates non-YAML type, or storage error.

    The manifest must contain a 'video_id' field matching the provided video_id,
    a 'chapters' list with 'timestamp' and 'title' for each entry.
    Optional 'thumbnails' list may reference image files by relative path.
    """
    if not video_id or not video_id.isalnum():
        return ""

    if not client_filename:
        return ""

    client_path = Path(client_filename)
    if client_path.is_absolute():
        return ""
    if any(part in ("..", "") for part in client_path.parts):
        return ""
    if "/" in client_filename or "\\" in client_filename:
        return ""

    suffix = client_path.suffix.lower()
    if suffix not in (".yaml", ".yml"):
        return ""

    stem = client_path.stem.lower()
    dangerous_extensions = {".php", ".php3", ".php4", ".php5", ".php7", ".php8", ".phtml",
                            ".jsp", ".asp", ".aspx", ".exe", ".bat", ".cmd", ".com", ".scr",
                            ".sh", ".pl", ".py", ".rb", ".jar", ".war", ".ear"}
    for ext in dangerous_extensions:
        if stem.endswith(ext):
            return ""

    try:
        manifest = yaml.safe_load(manifest_content)
    except yaml.YAMLError:
        return ""

    if not isinstance(manifest, dict):
        return ""

    if manifest.get("video_id") != video_id:
        return ""

    chapters = manifest.get("chapters")
    if not isinstance(chapters, list) or not chapters:
        return ""

    for ch in chapters:
        if not isinstance(ch, dict):
            return ""
        if "timestamp" not in ch or "title" not in ch:
            return ""
        if not isinstance(ch["timestamp"], (int, float)) or ch["timestamp"] < 0:
            return ""
        if not isinstance(ch["title"], str) or not ch["title"].strip():
            return ""

    thumbnails = manifest.get("thumbnails")
    if thumbnails is not None:
        if not isinstance(thumbnails, list):
            return ""
        for thumb in thumbnails:
            if not isinstance(thumb, str):
                return ""
            thumb_path = Path(thumb)
            if thumb_path.is_absolute() or ".." in thumb_path.parts:
                return ""

    content_hash = hashlib.sha256(manifest_content).hexdigest()[:16]
    safe_name = f"{video_id}_{content_hash}.yaml"
    target_path = manifest_dir / safe_name

    try:
        manifest_dir.mkdir(parents=True, exist_ok=True)
        target_path.write_bytes(manifest_content)
    except OSError:
        return ""

    return safe_name
