import yaml
import json
from typing import Any, Dict, Optional, List, Union

def apply_response_transform(
    response_body: str,
    transform_spec: str,
    *,
    max_depth: int = 10,
    allow_unsafe: bool = False
) -> str:
    """
    Apply a YAML-defined transformation to an API response body.

    The transform_spec is a YAML document that specifies how to transform the
    response. It supports the following operations:
    - 'jsonpath': extract a value using a JSONPath expression (requires response to be JSON)
    - 'template': format a string using {value} placeholder with the extracted value
    - 'replace': simple string replacement with 'from' and 'to' fields
    - 'chain': a list of transformation specs to apply in sequence

    Example transform_spec:
        jsonpath: "$.data.user.name"
        template: "User: {value}"

    Or for chaining:
        chain:
          - jsonpath: "$.data"
          - replace:
              from: "old_value"
              to: "new_value"

    Args:
        response_body: The raw response body string from the upstream service.
        transform_spec: YAML string defining the transformation. This input comes
            from the gateway administrator via the configuration API and may be
            stored in the service discovery system.
        max_depth: Maximum recursion depth for chained transformations (default 10).
        allow_unsafe: Reserved for future use; must be False.

    Returns:
        The transformed response body as a string. If the transformation cannot
        be applied (invalid spec, missing data, non-JSON input for jsonpath, etc.),
        returns the original response_body unchanged.

    Raises:
        ValueError: If max_depth is exceeded or allow_unsafe is True.
    """
    if allow_unsafe:
        raise ValueError("allow_unsafe must be False")
    if max_depth <= 0:
        raise ValueError("max_depth exceeded")

    # Parse YAML safely - only allow basic YAML constructs, no Python objects
    try:
        spec = yaml.safe_load(transform_spec)
    except yaml.YAMLError:
        return response_body

    if spec is None:
        return response_body

    def _apply(spec: Any, body: str, depth: int) -> str:
        if depth <= 0:
            raise ValueError("max_depth exceeded")

        if not isinstance(spec, dict):
            return body

        # Handle chained transformations
        if "chain" in spec:
            chain = spec["chain"]
            if not isinstance(chain, list):
                return body
            current = body
            for step in chain:
                current = _apply(step, current, depth - 1)
            return current

        # Handle jsonpath extraction
        if "jsonpath" in spec:
            jsonpath_expr = spec["jsonpath"]
            if not isinstance(jsonpath_expr, str):
                return body
            try:
                data = json.loads(body)
            except json.JSONDecodeError:
                return body

            # Simple JSONPath implementation for $.path.to.value
            if not jsonpath_expr.startswith("$."):
                return body
            path_parts = jsonpath_expr[2:].split(".")
            current = data
            for part in path_parts:
                if isinstance(current, dict) and part in current:
                    current = current[part]
                elif isinstance(current, list) and part.isdigit():
                    idx = int(part)
                    if 0 <= idx < len(current):
                        current = current[idx]
                    else:
                        return body
                else:
                    return body

            # If template is also specified in the same spec, apply it with raw value
            if "template" in spec and isinstance(spec["template"], str):
                return spec["template"].format(value=current)
            # Otherwise return the extracted value as JSON
            return json.dumps(current)

        # Handle template formatting (requires a 'value' field in spec or previous extraction)
        if "template" in spec:
            template = spec["template"]
            if not isinstance(template, str):
                return body
            value = spec.get("value", body)
            return template.format(value=value)

        # Handle string replacement
        if "replace" in spec:
            replace_spec = spec["replace"]
            if not isinstance(replace_spec, dict):
                return body
            from_str = replace_spec.get("from")
            to_str = replace_spec.get("to", "")
            if not isinstance(from_str, str) or not isinstance(to_str, str):
                return body
            return body.replace(from_str, to_str)

        return body

    try:
        return _apply(spec, response_body, max_depth)
    except (ValueError, KeyError, IndexError, TypeError, AttributeError):
        return response_body
