import zipfile
import io
from pathlib import Path
import yaml


def extract_alert_bundle(bundle_data: bytes, staging_root: Path, bundle_id: str) -> dict[str, Path]:
    """
    Extract a validated alert rule bundle from raw bytes into an isolated staging area.

    The bundle is a ZIP archive that must contain a 'manifest.yaml' at its root
    describing the enclosed rule files and notification templates. Only entries
    with extensions .yaml, .yml, .j2, .md, or .txt are extracted. The manifest
    is parsed to verify all declared files are present.

    Args:
        bundle_data: Raw bytes of the uploaded bundle archive (user-supplied).
        staging_root: Root directory for tenant-isolated staging (configured, trusted).
        bundle_id: Unique identifier for this bundle, used as subdirectory name
            under staging_root (user-supplied, alphanumeric expected but not enforced).

    Returns:
        Mapping from each extracted entry's archive-relative path to its resolved
        absolute Path on disk. Returns empty dict if the archive is invalid,
        manifest is missing or malformed, declared files are missing, or any
        entry has a disallowed extension.

    User-controlled inputs: bundle_data (entire archive content and structure),
        bundle_id (used in path construction).
    """
    allowed_extensions = {".yaml", ".yml", ".j2", ".md", ".txt"}

    # Resolve staging_root first to have a canonical base
    try:
        staging_root_resolved = staging_root.resolve()
    except OSError:
        return {}

    # Compute extract directory and verify it stays within staging_root
    try:
        extract_dir = (staging_root_resolved / bundle_id).resolve()
        extract_dir.relative_to(staging_root_resolved)
    except (ValueError, OSError):
        return {}

    try:
        extract_dir.mkdir(parents=True, exist_ok=True)
    except OSError:
        return {}

    try:
        with zipfile.ZipFile(io.BytesIO(bundle_data), "r") as zf:
            # First pass: validate all entries
            manifest_content = None
            declared_files: set[str] = set()
            entry_infos = []

            for info in zf.infolist():
                # Skip directories
                if info.is_dir():
                    continue

                # Validate extension
                entry_path = Path(info.filename)
                if entry_path.suffix.lower() not in allowed_extensions:
                    return {}

                # Resolve target path and ensure it stays within extract_dir
                try:
                    target_path = (extract_dir / info.filename).resolve()
                    target_path.relative_to(extract_dir)
                except (ValueError, OSError):
                    return {}

                entry_infos.append((info, target_path))

                # Capture manifest
                if info.filename == "manifest.yaml":
                    try:
                        manifest_content = zf.read(info).decode("utf-8")
                    except (UnicodeDecodeError, zipfile.BadZipFile):
                        return {}

            if manifest_content is None:
                return {}

            # Parse manifest and verify declared files exist in archive
            try:
                manifest = yaml.safe_load(manifest_content)
                if not isinstance(manifest, dict) or "files" not in manifest:
                    return {}
                declared_files = set(manifest["files"])
            except yaml.YAMLError:
                return {}

            archive_files = {info.filename for info, _ in entry_infos}
            if not declared_files.issubset(archive_files):
                return {}

            # Second pass: extract validated entries
            result = {}
            for info, target_path in entry_infos:
                try:
                    target_path.parent.mkdir(parents=True, exist_ok=True)
                    with zf.open(info) as src, target_path.open("wb") as dst:
                        dst.write(src.read())
                    result[info.filename] = target_path
                except (OSError, zipfile.BadZipFile):
                    return {}

            return result

    except (zipfile.BadZipFile, OSError):
        return {}
