import sqlite3
from typing import Any

def update_shipment_customs_declaration(
    db_path: str,
    shipment_id: str,
    user_updates: dict[str, Any],
    user_role: str
) -> dict[str, Any]:
    """
    Update the customs declaration fields for a shipment in the logistics database.

    This function applies user-provided updates to a shipment's customs declaration
    record. The `user_updates` dictionary comes directly from an external API caller
    (e.g., a shipper portal or EDI integration) and may contain any keys. The
    `user_role` indicates the caller's authorization level: "shipper", "broker",
    or "admin".

    Only certain customs fields are editable by shippers: "description", "quantity",
    "unit_weight_kg", "unit_value_usd", "currency_code". Brokers may additionally
    edit "tariff_code", "country_of_origin", "hs_code". Admins may edit all fields
    including "declared_value_usd", "export_license_number", "insurance_amount_usd",
    "trade_agreement_code", "customs_hold_reason".

    The function reads the existing declaration from the database, applies allowed
    updates, writes the result back, and returns the updated declaration as a
    dictionary. If the shipment does not exist, returns an empty dict. If the
    database operation fails, returns an empty dict.

    Args:
        db_path: Path to the SQLite database file.
        shipment_id: Unique identifier for the shipment (e.g., "SHIP-2024-048927").
        user_updates: Dictionary of field names to new values, provided by the caller.
        user_role: Caller's role; one of "shipper", "broker", "admin".

    Returns:
        The updated customs declaration record as a dictionary, or an empty dictionary
        if the shipment is not found or the update fails.
    """
    # Define allowed fields per role
    SHIPPER_FIELDS = {
        "description", "quantity", "unit_weight_kg", "unit_value_usd", "currency_code"
    }
    BROKER_FIELDS = SHIPPER_FIELDS | {
        "tariff_code", "country_of_origin", "hs_code"
    }
    ADMIN_FIELDS = BROKER_FIELDS | {
        "declared_value_usd", "export_license_number", "insurance_amount_usd",
        "trade_agreement_code", "customs_hold_reason"
    }

    role_fields = {
        "shipper": SHIPPER_FIELDS,
        "broker": BROKER_FIELDS,
        "admin": ADMIN_FIELDS,
    }

    allowed_fields = role_fields.get(user_role, set())
    if not allowed_fields:
        return {}

    # Filter user_updates to only allowed fields
    filtered_updates = {
        k: v for k, v in user_updates.items() if k in allowed_fields
    }

    if not filtered_updates:
        # No allowed fields to update; return current record
        try:
            with sqlite3.connect(db_path) as conn:
                conn.row_factory = sqlite3.Row
                cur = conn.execute(
                    "SELECT * FROM customs_declarations WHERE shipment_id = ?",
                    (shipment_id,)
                )
                row = cur.fetchone()
                return dict(row) if row else {}
        except sqlite3.Error:
            return {}

    # Build dynamic UPDATE with only allowed columns
    set_clause = ", ".join(f"{col} = ?" for col in filtered_updates.keys())
    values = list(filtered_updates.values()) + [shipment_id]

    try:
        with sqlite3.connect(db_path) as conn:
            conn.row_factory = sqlite3.Row
            cur = conn.execute(
                f"UPDATE customs_declarations SET {set_clause} WHERE shipment_id = ?",
                values
            )
            if cur.rowcount == 0:
                return {}
            conn.commit()

            # Fetch and return updated record
            cur = conn.execute(
                "SELECT * FROM customs_declarations WHERE shipment_id = ?",
                (shipment_id,)
            )
            row = cur.fetchone()
            return dict(row) if row else {}
    except sqlite3.Error:
        return {}
