import re
from urllib.parse import urlparse, urlunparse, urlencode
from uuid import UUID


APPROVED_REGISTRY_HOSTS = {
    "registry.company-internal.com",
    "enrichment-registry.prod.example.com",
    "rules.example.org",
}


def build_enrichment_fetch_url(registry_config: dict, rule_set: str, job_id: str) -> str:
    """
    Build a validated URL for fetching log enrichment rules from a registry.

    The registry configuration is sourced from user-controlled pipeline settings.
    The rule_set and job_id come from the log processing job specification.

    Args:
        registry_config: Dictionary with keys 'base_url' (str) and 'api_version' (str).
            'base_url' must be a valid HTTPS URL to an approved enrichment registry.
            'api_version' must be a non-empty alphanumeric string.
        rule_set: Name of the enrichment rule set to fetch. Must be non-empty,
            alphanumeric with hyphens/underscores only, max 64 chars.
        job_id: Unique identifier for the log processing job. Must be a valid UUID string.

    Returns:
        A fully qualified HTTPS URL string for fetching the enrichment rules, or
        an empty string if any input fails validation.

    The returned URL follows the pattern:
        {base_url}/v{api_version}/rulesets/{rule_set}/enrich?job_id={job_id}
    """
    if not isinstance(registry_config, dict):
        return ""

    base_url = registry_config.get("base_url", "")
    api_version = registry_config.get("api_version", "")

    if not base_url or not isinstance(base_url, str):
        return ""

    parsed = urlparse(base_url)
    if parsed.scheme != "https":
        return ""
    if not parsed.netloc:
        return ""
    if parsed.netloc not in APPROVED_REGISTRY_HOSTS:
        return ""
    if parsed.path not in ("", "/"):
        return ""
    if parsed.query or parsed.fragment:
        return ""

    if not api_version or not isinstance(api_version, str):
        return ""
    if not re.fullmatch(r"[A-Za-z0-9]+", api_version):
        return ""

    if not rule_set or not isinstance(rule_set, str):
        return ""
    if len(rule_set) > 64:
        return ""
    if not re.fullmatch(r"[A-Za-z0-9_-]+", rule_set):
        return ""

    try:
        UUID(job_id)
    except (ValueError, TypeError):
        return ""

    path = f"/v{api_version}/rulesets/{rule_set}/enrich"
    query = urlencode({"job_id": job_id})
    return urlunparse(("https", parsed.netloc, path, "", query, ""))
