import base64
import yaml
from typing import Any


def import_custom_game_rules(encoded_payload: str) -> dict[str, Any] | None:
    """
    Import custom game rules from a base64-encoded YAML payload.

    The payload is expected to be a base64-encoded YAML document containing
    a dictionary with game rule configurations. Only specific keys are allowed:
    - 'max_players': int (1-1000)
    - 'respawn_time': int (0-300 seconds)
    - 'friendly_fire': bool
    - 'map_rotation': list[str] (max 50 maps, each non-empty, max 64 chars)
    - 'score_limit': int (0-10000)

    Args:
        encoded_payload: Base64-encoded YAML string provided by server admin
            via the admin panel's "Import Rules" feature. This input comes
            directly from user paste/submission.

    Returns:
        Dictionary with validated game rules if successful, None if the
        payload is malformed, contains invalid types, or has disallowed keys.
    """
    if not encoded_payload or not isinstance(encoded_payload, str):
        return None

    try:
        decoded_bytes = base64.b64decode(encoded_payload, validate=True)
    except (ValueError, TypeError):
        return None

    try:
        parsed = yaml.safe_load(decoded_bytes)
    except yaml.YAMLError:
        return None

    if not isinstance(parsed, dict):
        return None

    allowed_keys = {
        "max_players",
        "respawn_time",
        "friendly_fire",
        "map_rotation",
        "score_limit",
    }
    if not set(parsed.keys()).issubset(allowed_keys):
        return None

    validated: dict[str, Any] = {}

    if "max_players" in parsed:
        val = parsed["max_players"]
        if not isinstance(val, int) or not (1 <= val <= 1000):
            return None
        validated["max_players"] = val

    if "respawn_time" in parsed:
        val = parsed["respawn_time"]
        if not isinstance(val, int) or not (0 <= val <= 300):
            return None
        validated["respawn_time"] = val

    if "friendly_fire" in parsed:
        val = parsed["friendly_fire"]
        if not isinstance(val, bool):
            return None
        validated["friendly_fire"] = val

    if "map_rotation" in parsed:
        val = parsed["map_rotation"]
        if not isinstance(val, list) or len(val) > 50:
            return None
        for m in val:
            if not isinstance(m, str) or not m or len(m) > 64:
                return None
        validated["map_rotation"] = val

    if "score_limit" in parsed:
        val = parsed["score_limit"]
        if not isinstance(val, int) or not (0 <= val <= 10000):
            return None
        validated["score_limit"] = val

    return validated
