import ast
import operator
from typing import Callable, Any

_ALLOWED_BINOPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.In: lambda a, b: a in b,
    ast.NotIn: lambda a, b: a not in b,
}

_ALLOWED_UNOPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
    ast.Not: operator.not_,
}

_ALLOWED_BOOL_OPS = {
    ast.And: all,
    ast.Or: any,
}

def _validate_and_eval(node: ast.AST, available_fields: set[str], context: dict) -> Any:
    if isinstance(node, ast.Expression):
        return _validate_and_eval(node.body, available_fields, context)
    elif isinstance(node, ast.Constant):
        if isinstance(node.value, (str, int, float, bool, type(None))):
            return node.value
        raise ValueError("Unsupported constant type")
    elif isinstance(node, ast.Name):
        if node.id in available_fields:
            return context.get(node.id)
        raise ValueError(f"Unknown field: {node.id}")
    elif isinstance(node, ast.Tuple):
        return tuple(_validate_and_eval(elt, available_fields, context) for elt in node.elts)
    elif isinstance(node, ast.List):
        return [_validate_and_eval(elt, available_fields, context) for elt in node.elts]
    elif isinstance(node, ast.Set):
        return {_validate_and_eval(elt, available_fields, context) for elt in node.elts}
    elif isinstance(node, ast.BinOp):
        if type(node.op) not in _ALLOWED_BINOPS:
            raise ValueError("Unsupported binary operator")
        left = _validate_and_eval(node.left, available_fields, context)
        right = _validate_and_eval(node.right, available_fields, context)
        return _ALLOWED_BINOPS[type(node.op)](left, right)
    elif isinstance(node, ast.UnaryOp):
        if type(node.op) not in _ALLOWED_UNOPS:
            raise ValueError("Unsupported unary operator")
        operand = _validate_and_eval(node.operand, available_fields, context)
        return _ALLOWED_UNOPS[type(node.op)](operand)
    elif isinstance(node, ast.BoolOp):
        if type(node.op) not in _ALLOWED_BOOL_OPS:
            raise ValueError("Unsupported boolean operator")
        values = [_validate_and_eval(v, available_fields, context) for v in node.values]
        return _ALLOWED_BOOL_OPS[type(node.op)](values)
    elif isinstance(node, ast.Compare):
        left = _validate_and_eval(node.left, available_fields, context)
        for op, comparator in zip(node.ops, node.comparators):
            if type(op) not in _ALLOWED_BINOPS:
                raise ValueError("Unsupported comparison operator")
            right = _validate_and_eval(comparator, available_fields, context)
            if not _ALLOWED_BINOPS[type(op)](left, right):
                return False
            left = right
        return True
    elif isinstance(node, ast.IfExp):
        test = _validate_and_eval(node.test, available_fields, context)
        if test:
            return _validate_and_eval(node.body, available_fields, context)
        else:
            return _validate_and_eval(node.orelse, available_fields, context)
    else:
        raise ValueError(f"Unsupported AST node: {type(node).__name__}")

def compile_visibility_condition(condition: str, available_fields: set[str]) -> Callable[[dict], bool]:
    """
    Compile a field visibility condition into a callable that evaluates whether a field should be shown.

    The condition is a Python boolean expression that can reference field names as variables.
    Supported operations: comparison (==, !=, <, >, <=, >=), logical (and, or, not),
    membership (in, not in), arithmetic (+, -, *, /, //, %, **), unary (+, -, not),
    parentheses for grouping, and ternary conditional (x if cond else y).
    String literals and numeric literals are allowed. Field names must be valid Python identifiers.

    Args:
        condition: A string containing the boolean expression. Provided by the form builder.
        available_fields: Set of field names that may be referenced in the condition.

    Returns:
        A callable that takes a dict mapping field names to values (str, int, float, bool, or None)
        and returns True if the field should be visible, False otherwise. Returns a callable that
        always returns False if the condition is invalid, references unknown fields, or raises
        an exception during evaluation.
    """
    try:
        tree = ast.parse(condition, mode='eval')
    except SyntaxError:
        return lambda _: False

    def evaluator(context: dict) -> bool:
        try:
            result = _validate_and_eval(tree, available_fields, context)
            return bool(result)
        except Exception:
            return False

    return evaluator
