import sqlite3
import time
from typing import Any

def update_live_ops_bundle(bundle_id: str, updates: dict[str, Any], admin_id: str, db_path: str) -> dict[str, Any]:
    """
    Update a live-ops bundle configuration in the game server admin panel.

    Args:
        bundle_id: Unique identifier of the bundle to update (from URL path).
        updates: Dictionary of fields to modify. User-provided input from the admin panel form.
        admin_id: Identifier of the admin making the change (from session, for audit logging).
        db_path: Path to the SQLite database file.

    Returns:
        The updated bundle configuration as a dictionary, or an empty dictionary if the bundle
        does not exist. The returned dictionary includes all bundle fields.

    User-provided inputs: bundle_id (from URL), updates (all keys and values from form),
        admin_id (from session, treat as untrusted for field selection purposes).
    """
    ALLOWED_FIELDS = {
        "display_name", "description", "price", "currency_type",
        "items", "start_time", "end_time", "is_active"
    }
    PROTECTED_FIELDS = {
        "bundle_id", "internal_sku", "platform_override",
        "fraud_check_enabled", "signature", "created_at", "updated_at"
    }

    with sqlite3.connect(db_path) as conn:
        conn.row_factory = sqlite3.Row
        cur = conn.execute("SELECT * FROM live_ops_bundles WHERE bundle_id = ?", (bundle_id,))
        row = cur.fetchone()
        if not row:
            return {}

        bundle = dict(row)
        filtered_updates = {k: v for k, v in updates.items() if k in ALLOWED_FIELDS}
        if not filtered_updates:
            return bundle

        for field, value in filtered_updates.items():
            if field == "items" and not isinstance(value, list):
                continue
            if field == "price":
                try:
                    value = int(value)
                    if value < 0:
                        continue
                except (ValueError, TypeError):
                    continue
            if field in ("start_time", "end_time"):
                try:
                    value = int(value)
                except (ValueError, TypeError):
                    continue
            if field == "currency_type" and value not in ("premium", "standard", "event"):
                continue
            if field == "is_active" and not isinstance(value, bool):
                continue
            bundle[field] = value

        bundle["updated_at"] = int(time.time())
        set_clause = ", ".join(f"{k} = ?" for k in filtered_updates.keys())
        set_clause += ", updated_at = ?"
        values = list(filtered_updates.values()) + [bundle["updated_at"], bundle_id]
        conn.execute(f"UPDATE live_ops_bundles SET {set_clause} WHERE bundle_id = ?", values)
        conn.commit()

        cur = conn.execute("SELECT * FROM live_ops_bundles WHERE bundle_id = ?", (bundle_id,))
        return dict(cur.fetchone())
