import ast

def assess_alert_trigger_expression(expression: str, metric_values: dict[str, float]) -> bool:
    """
    Assess whether an alert trigger expression evaluates to true given current metric values.

    The expression is a boolean combination of metric comparisons using:
    - Metric names as variables (must match keys in metric_values)
    - Comparison operators: ==, !=, <, <=, >, >=
    - Logical operators: and, or, not
    - Parentheses for grouping
    - Numeric literals (int, float) and boolean literals (True, False)

    Args:
        expression: Alert trigger expression from the alerting rule configuration
                    (user-provided via policy-as-code or UI).
        metric_values: Current metric snapshot mapping metric names to values.
                       Metric names are user-defined in the monitoring schema.

    Returns:
        True if the expression evaluates to true (alert should trigger),
        False if false, empty, syntactically invalid, references unknown metrics,
        or contains disallowed constructs.
    """
    if not expression or not expression.strip():
        return False

    try:
        tree = ast.parse(expression, mode='eval')
    except SyntaxError:
        return False

    allowed_node_types = {
        ast.Expression, ast.BoolOp, ast.UnaryOp, ast.Compare,
        ast.Name, ast.Constant, ast.Load,
        ast.And, ast.Or, ast.Not,
        ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE,
    }

    for node in ast.walk(tree):
        node_type = type(node)
        if node_type not in allowed_node_types:
            return False
        if isinstance(node, ast.Name):
            if node.id not in metric_values:
                return False
            if not isinstance(node.ctx, ast.Load):
                return False
        if isinstance(node, ast.Constant):
            if not isinstance(node.value, (int, float, bool)):
                return False

    try:
        code = compile(tree, '<alert_trigger>', 'eval')
        result = eval(code, {"__builtins__": {}}, metric_values)
        return bool(result)
    except Exception:
        return False
