import yaml
from typing import Optional, Dict, Any, List

def parse_canary_routing_config(config_yaml: str) -> Optional[Dict[str, Any]]:
    """
    Parse a canary deployment routing configuration from YAML.

    The configuration defines traffic splitting rules for gradual rollouts
    in an API gateway. Input comes from API gateway administrators via
    the management API or configuration file uploads.

    Expected YAML structure:
        version: string (required, must be "1.0")
        service: string (required, target service name)
        canary: object (required) containing:
            weight: integer 0-100 (required, percentage of traffic to canary)
            conditions: list of objects (optional) each with either:
                header: string and value: string (match request header)
                path_prefix: string (match request path prefix)
            headers: object (optional) mapping header names to values
                to inject into canary requests

    Args:
        config_yaml: YAML string provided by the API gateway administrator.

    Returns:
        Parsed configuration dictionary with validated structure, or None
        if the YAML is invalid, fails validation, or contains unsupported
        constructs.
    """
    if not config_yaml or not isinstance(config_yaml, str):
        return None

    try:
        parsed = yaml.safe_load(config_yaml)
    except yaml.YAMLError:
        return None

    if not isinstance(parsed, dict):
        return None

    # Validate required top-level fields
    if parsed.get("version") != "1.0":
        return None

    service = parsed.get("service")
    if not isinstance(service, str) or not service:
        return None

    canary = parsed.get("canary")
    if not isinstance(canary, dict):
        return None

    # Validate weight
    weight = canary.get("weight")
    if not isinstance(weight, int) or weight < 0 or weight > 100:
        return None

    # Validate conditions if present
    conditions = canary.get("conditions")
    if conditions is not None:
        if not isinstance(conditions, list):
            return None
        for cond in conditions:
            if not isinstance(cond, dict):
                return None
            has_header = "header" in cond and "value" in cond
            has_path = "path_prefix" in cond
            if not (has_header ^ has_path):  # Must have exactly one
                return None
            if has_header:
                if not isinstance(cond["header"], str) or not isinstance(cond["value"], str):
                    return None
            if has_path:
                if not isinstance(cond["path_prefix"], str):
                    return None

    # Validate headers if present
    headers = canary.get("headers")
    if headers is not None:
        if not isinstance(headers, dict):
            return None
        for k, v in headers.items():
            if not isinstance(k, str) or not isinstance(v, str):
                return None

    return {
        "version": "1.0",
        "service": service,
        "canary": {
            "weight": weight,
            "conditions": conditions or [],
            "headers": headers or {}
        }
    }
