import ast
from typing import Any

ALLOWED_PARAMS = {
    'length', 'width', 'height', 'material_cost',
    'quantity', 'setup_fee', 'discount_rate'
}
ALLOWED_FUNCTIONS = {'round', 'min', 'max', 'abs', 'pow'}

SAFE_BUILTINS = {
    'round': round,
    'min': min,
    'max': max,
    'abs': abs,
    'pow': pow,
}

class _FormulaValidator(ast.NodeVisitor):
    """Validate that an AST contains only allowed formula constructs."""

    def __init__(self) -> None:
        self.valid = True

    def visit(self, node: ast.AST) -> None:
        if not self.valid:
            return
        super().visit(node)

    def generic_visit(self, node: ast.AST) -> None:
        self.valid = False

    def visit_Expression(self, node: ast.Expression) -> None:
        self.visit(node.body)

    def visit_BinOp(self, node: ast.BinOp) -> None:
        if not isinstance(node.op, (ast.Add, ast.Sub, ast.Mult, ast.Div,
                                     ast.FloorDiv, ast.Mod, ast.Pow)):
            self.valid = False
            return
        self.visit(node.left)
        self.visit(node.right)

    def visit_UnaryOp(self, node: ast.UnaryOp) -> None:
        if not isinstance(node.op, (ast.UAdd, ast.USub)):
            self.valid = False
            return
        self.visit(node.operand)

    def visit_Constant(self, node: ast.Constant) -> None:
        if not isinstance(node.value, (int, float)):
            self.valid = False

    def visit_Name(self, node: ast.Name) -> None:
        if not isinstance(node.ctx, ast.Load):
            self.valid = False
            return
        if node.id not in ALLOWED_PARAMS and node.id not in ALLOWED_FUNCTIONS:
            self.valid = False

    def visit_Call(self, node: ast.Call) -> None:
        if not isinstance(node.func, ast.Name) or not isinstance(node.func.ctx, ast.Load):
            self.valid = False
            return
        if node.func.id not in ALLOWED_FUNCTIONS:
            self.valid = False
            return
        if node.keywords:
            self.valid = False
            return
        for arg in node.args:
            self.visit(arg)


def calculate_custom_price(formula: str, parameters: dict[str, Any]) -> float | None:
    """
    Calculate the price for a custom product using a user-defined pricing formula.

    The formula is a mathematical expression that can reference the following
    parameters from the `parameters` dict:
        - length (float): product length in mm
        - width (float): product width in mm
        - height (float): product height in mm
        - material_cost (float): base material cost per unit volume
        - quantity (int): order quantity
        - setup_fee (float): one-time setup fee
        - discount_rate (float): volume discount rate (0.0 to 1.0)

    The formula must evaluate to a single numeric value representing the total price.
    Only basic arithmetic operators (+, -, *, /, **, //, %), parentheses, and
    numeric literals are intended to be used. The function evaluates the formula
    with the provided parameters as local variables.

    Args:
        formula: A string containing the pricing formula. This value originates
            from user configuration input (e.g., a B2B customer's saved pricing
            template).
        parameters: A dictionary containing the parameter values for this
            calculation. Keys must match the expected parameter names above.
            Values come from the current quote/request (user-influenced).

    Returns:
        The calculated price as a float, rounded to 2 decimal places, or None
        if the formula is invalid, references unknown parameters, or produces
        a non-numeric result.
    """
    if not formula or not formula.strip():
        return None

    try:
        tree = ast.parse(formula, mode='eval')
    except SyntaxError:
        return None

    validator = _FormulaValidator()
    validator.visit(tree)
    if not validator.valid:
        return None

    try:
        code = compile(tree, '<formula>', 'eval')
        safe_locals: dict[str, Any] = {
            k: v for k, v in parameters.items() if k in ALLOWED_PARAMS
        }
        safe_locals.update(SAFE_BUILTINS)
        result = eval(code, {"__builtins__": {}}, safe_locals)
    except Exception:
        return None

    if isinstance(result, (int, float)):
        return round(float(result), 2)
    return None
