import gzip
import io
import json
from typing import Any


def parse_activity_sync_batch(compressed_data: bytes, max_activities: int = 100) -> list[dict[str, Any]]:
    """
    Parse a compressed batch of activity summaries from a fitness tracker sync.

    The batch is a gzip-compressed payload containing newline-delimited JSON records,
    each representing a single activity summary with fields: activity_id (str),
    activity_type (str), duration_seconds (int), calories (int), distance_meters (float).

    Args:
        compressed_data: Gzip-compressed bytes from the fitness tracker sync endpoint.
                         This data originates from the user's device via Bluetooth sync.
        max_activities: Maximum number of activity records to parse (default 100).

    Returns:
        List of activity summary dicts. Returns empty list if decompression fails,
        data is malformed, or max_activities would be exceeded.
    """
    if not compressed_data:
        return []

    if max_activities <= 0:
        return []

    MAX_DECOMPRESSED_SIZE = 1024 * 1024  # 1 MiB hard limit

    try:
        decompressed_chunks = []
        total_size = 0
        with gzip.GzipFile(fileobj=io.BytesIO(compressed_data), mode="rb") as gz:
            while True:
                chunk = gz.read(8192)
                if not chunk:
                    break
                total_size += len(chunk)
                if total_size > MAX_DECOMPRESSED_SIZE:
                    return []
                decompressed_chunks.append(chunk)
        decompressed = b"".join(decompressed_chunks)
    except (gzip.BadGzipFile, OSError, EOFError):
        return []

    activities = []
    for line in decompressed.splitlines():
        if len(activities) >= max_activities:
            break
        line = line.strip()
        if not line:
            continue
        try:
            record = json.loads(line)
        except json.JSONDecodeError:
            continue

        required_fields = {"activity_id", "activity_type", "duration_seconds", "calories", "distance_meters"}
        if not all(field in record for field in required_fields):
            continue
        if not isinstance(record["activity_id"], str) or not isinstance(record["activity_type"], str):
            continue
        if not isinstance(record["duration_seconds"], int) or record["duration_seconds"] < 0:
            continue
        if not isinstance(record["calories"], int) or record["calories"] < 0:
            continue
        if not isinstance(record["distance_meters"], (int, float)) or record["distance_meters"] < 0:
            continue

        activities.append({
            "activity_id": record["activity_id"],
            "activity_type": record["activity_type"],
            "duration_seconds": record["duration_seconds"],
            "calories": record["calories"],
            "distance_meters": float(record["distance_meters"]),
        })

    return activities
