from typing import Any


def format_package_link_header(relations: list[dict[str, Any]]) -> str:
    """
    Format a RFC 8288 Link header value from package relation objects.

    Each relation dict must have 'url' (target URI) and 'rel' (relation type).
    Optional 'title' and 'type' fields are included if present and non-empty.

    Args:
        relations: List of relation dicts with keys 'url', 'rel',
                   optionally 'title', 'type'.

    Returns:
        A comma-separated Link header value string, or empty string if
        relations is empty, None, or contains no valid entries.

    User-controlled inputs: All fields in relation dicts (url, rel, title, type)
    come from package metadata submitted by package publishers.
    """
    if not relations:
        return ""

    link_parts = []
    for rel in relations:
        if not isinstance(rel, dict):
            continue

        url = rel.get("url")
        rel_type = rel.get("rel")

        if not url or not rel_type:
            continue

        if not isinstance(url, str) or not isinstance(rel_type, str):
            continue

        if any(c in url for c in "\r\n") or any(c in rel_type for c in "\r\n"):
            continue

        title = rel.get("title")
        if title is not None:
            if not isinstance(title, str) or any(c in title for c in "\r\n"):
                title = None

        link_type = rel.get("type")
        if link_type is not None:
            if not isinstance(link_type, str) or any(c in link_type for c in "\r\n"):
                link_type = None

        part = f'<{url}>; rel="{rel_type}"'
        if title:
            part += f'; title="{title}"'
        if link_type:
            part += f'; type="{link_type}"'

        link_parts.append(part)

    return ", ".join(link_parts)
