import ast
import operator
from typing import Any


def evaluate_row_filter(
    rows: list[dict[str, Any]],
    columns: list[str],
    filter_expression: str,
) -> list[dict[str, Any]]:
    """
    Filter a list of data rows by evaluating a user-provided boolean expression against each row.

    The filter expression is a Python-like boolean expression that can reference column names
    as variables. Supported operations: comparisons (==, !=, <, <=, >, >=), logical operators
    (and, or, not), arithmetic (+, -, *, /, //, %, **), parentheses, and numeric/string literals.
    Column names must match exactly one of the provided column identifiers.

    Arguments:
        rows: List of dictionaries representing data rows. Each dict maps column names to values.
              All dicts should have keys matching the provided columns list.
        columns: List of valid column names that may be referenced in the filter expression.
                 These are the only identifiers allowed as variables in the expression.
        filter_expression: User-provided string containing a boolean expression to evaluate
                           for each row. This input comes directly from the notebook user.

    Returns:
        A new list containing only the rows for which the filter expression evaluates to True.
        Returns an empty list if the filter_expression is empty, invalid, contains disallowed
        constructs, or if any evaluation error occurs (e.g., type mismatch, missing column).
        The original rows list is never modified.
    """
    if not filter_expression or not filter_expression.strip():
        return []

    allowed_columns = set(columns)

    # AST node types we permit
    allowed_node_types = {
        ast.Expression,
        ast.BoolOp,   # and, or
        ast.UnaryOp,  # not, -, +
        ast.BinOp,    # +, -, *, /, //, %, **
        ast.Compare,  # ==, !=, <, <=, >, >=
        ast.Constant, # literals (numbers, strings, True, False, None)
        ast.Name,     # variable references (column names)
        ast.Load,     # load context for names
        ast.And,
        ast.Or,
        ast.Not,
        ast.Invert,
        ast.UAdd,
        ast.USub,
        ast.Add,
        ast.Sub,
        ast.Mult,
        ast.Div,
        ast.FloorDiv,
        ast.Mod,
        ast.Pow,
        ast.Eq,
        ast.NotEq,
        ast.Lt,
        ast.LtE,
        ast.Gt,
        ast.GtE,
    }

    # Allowed operators for BinOp and Compare
    allowed_binops = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
    }
    allowed_cmpops = {
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
    }
    allowed_unaryops = {
        ast.Not: operator.not_,
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
        ast.Invert: operator.inv,
    }
    allowed_boolops = {
        ast.And: all,
        ast.Or: any,
    }

    def validate_node(node: ast.AST) -> None:
        """Recursively validate that the AST contains only allowed constructs."""
        if type(node) not in allowed_node_types:
            raise ValueError(f"Disallowed AST node type: {type(node).__name__}")

        if isinstance(node, ast.Name):
            if node.id not in allowed_columns:
                raise ValueError(f"Reference to undefined column: {node.id}")

        if isinstance(node, ast.BinOp):
            if type(node.op) not in allowed_binops:
                raise ValueError(f"Disallowed binary operator: {type(node.op).__name__}")

        if isinstance(node, ast.Compare):
            for op in node.ops:
                if type(op) not in allowed_cmpops:
                    raise ValueError(f"Disallowed comparison operator: {type(op).__name__}")

        if isinstance(node, ast.UnaryOp):
            if type(node.op) not in allowed_unaryops:
                raise ValueError(f"Disallowed unary operator: {type(node.op).__name__}")

        if isinstance(node, ast.BoolOp):
            if type(node.op) not in allowed_boolops:
                raise ValueError(f"Disallowed boolean operator: {type(node.op).__name__}")

        if isinstance(node, ast.Constant):
            # Only allow basic literal types
            if not isinstance(node.value, (int, float, str, bool, type(None))):
                raise ValueError(f"Disallowed constant type: {type(node.value).__name__}")

        for child in ast.iter_child_nodes(node):
            validate_node(child)

    def eval_node(node: ast.AST, row: dict[str, Any]) -> Any:
        """Evaluate a validated AST node against a single row's data."""
        if isinstance(node, ast.Expression):
            return eval_node(node.body, row)

        if isinstance(node, ast.Constant):
            return node.value

        if isinstance(node, ast.Name):
            return row.get(node.id)

        if isinstance(node, ast.BinOp):
            left = eval_node(node.left, row)
            right = eval_node(node.right, row)
            op_func = allowed_binops[type(node.op)]
            return op_func(left, right)

        if isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand, row)
            op_func = allowed_unaryops[type(node.op)]
            return op_func(operand)

        if isinstance(node, ast.Compare):
            left = eval_node(node.left, row)
            results = []
            for op, comparator in zip(node.ops, node.comparators):
                right = eval_node(comparator, row)
                op_func = allowed_cmpops[type(op)]
                results.append(op_func(left, right))
                left = right  # chained comparisons: a < b < c
            return all(results)

        if isinstance(node, ast.BoolOp):
            values = [eval_node(v, row) for v in node.values]
            op_func = allowed_boolops[type(node.op)]
            return op_func(values)

        raise ValueError(f"Unexpected node type during evaluation: {type(node).__name__}")

    try:
        tree = ast.parse(filter_expression, mode="eval")
    except SyntaxError:
        return []

    try:
        validate_node(tree)
    except ValueError:
        return []

    filtered = []
    for row in rows:
        try:
            result = eval_node(tree, row)
            if result:
                filtered.append(row)
        except Exception:
            # Any evaluation error (TypeError, ZeroDivisionError, etc.) excludes the row
            continue

    return filtered
```

