from typing import Callable, Any
import requests
import re
from urllib.parse import urlparse, urljoin
import ipaddress


def fetch_virtual_race_results(
    timing_service_url: str,
    race_id: str,
    fetch: Callable[..., Any] = requests.get
) -> dict:
    """
    Fetch virtual race results from a user-configured timing service endpoint.

    The fitness tracker allows athletes to connect custom timing providers for
    virtual races. This function constructs the results URL and retrieves the
    payload.

    Args:
        timing_service_url: Base URL of the timing service API (user-configured
            in the athlete's integrations settings). Must use HTTP or HTTPS.
        race_id: Race identifier selected by the athlete from their race calendar
            (user-provided). Alphanumeric with hyphens and underscores only.
        fetch: Injectable HTTP client callable for testing. Defaults to
            requests.get. Must accept a URL string and return an object with
            a .json() method returning a dict.

    Returns:
        Dictionary containing the parsed JSON race results. Returns an empty
        dictionary if the URL is invalid, the request fails, or the response
        is not valid JSON.
    """
    # Validate race_id format: alphanumeric, hyphen, underscore only
    if not re.fullmatch(r'[A-Za-z0-9_-]+', race_id):
        return {}

    # Parse and validate the base URL
    try:
        parsed = urlparse(timing_service_url)
    except Exception:
        return {}

    # Only allow HTTP/HTTPS schemes
    if parsed.scheme not in ('http', 'https'):
        return {}

    # Reject empty netloc
    if not parsed.netloc:
        return {}

    # Resolve hostname to IP and block private/internal addresses
    hostname = parsed.hostname
    if hostname is None:
        return {}

    try:
        # Handle IPv4 and IPv6 literals
        ip = ipaddress.ip_address(hostname)
    except ValueError:
        # Hostname is a domain name; we'll rely on DNS resolution but block
        # known dangerous patterns. In production, you'd resolve and check IPs.
        # For this exercise, we block localhost and internal-looking names.
        if hostname.lower() in ('localhost', 'localhost.localdomain'):
            return {}
        if hostname.endswith('.local') or hostname.endswith('.internal'):
            return {}
    else:
        # Block private, loopback, link-local, multicast, reserved ranges
        if (ip.is_private or ip.is_loopback or ip.is_link_local
                or ip.is_multicast or ip.is_reserved or ip.is_unspecified):
            return {}

    # Construct the final URL safely using urljoin
    # Ensure base ends with slash for proper joining
    base = timing_service_url.rstrip('/') + '/'
    # Race ID is already validated as safe path segment
    results_url = urljoin(base, f'api/v1/races/{race_id}/results')

    # Final sanity check: result URL must still be HTTP/HTTPS and same host
    final_parsed = urlparse(results_url)
    if final_parsed.scheme not in ('http', 'https'):
        return {}
    if final_parsed.hostname != parsed.hostname:
        return {}

    # Perform the request with a timeout
    try:
        response = fetch(results_url, timeout=5)
        response.raise_for_status()
        return response.json()
    except Exception:
        return {}
