import re
import ast
import operator
from typing import Any, Dict, Optional


class SafeExpressionEvaluator(ast.NodeVisitor):
    """AST visitor that evaluates expressions using only safe operations."""

    BINARY_OPS = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
        ast.LShift: operator.lshift,
        ast.RShift: operator.rshift,
        ast.BitOr: operator.or_,
        ast.BitXor: operator.xor,
        ast.BitAnd: operator.and_,
    }

    UNARY_OPS = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
        ast.Not: operator.not_,
        ast.Invert: operator.inv,
    }

    COMPARE_OPS = {
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
        ast.Is: operator.is_,
        ast.IsNot: operator.is_not,
        ast.In: lambda a, b: a in b,
        ast.NotIn: lambda a, b: a not in b,
    }

    def __init__(self, variables: Dict[str, Any], functions: Dict[str, Any]):
        self.variables = variables
        self.functions = functions
        self.result = None

    def visit(self, node: ast.AST) -> Any:
        if isinstance(node, ast.Expression):
            return self.visit(node.body)
        return super().visit(node)

    def visit_Constant(self, node: ast.Constant) -> Any:
        if isinstance(node.value, (int, float, str, bool, type(None))):
            return node.value
        raise ValueError(f"Unsupported constant type: {type(node.value)}")

    def visit_Name(self, node: ast.Name) -> Any:
        if node.id in self.variables:
            return self.variables[node.id]
        raise NameError(f"Undefined variable: {node.id}")

    def visit_BinOp(self, node: ast.BinOp) -> Any:
        left = self.visit(node.left)
        right = self.visit(node.right)
        op_type = type(node.op)
        if op_type in self.BINARY_OPS:
            return self.BINARY_OPS[op_type](left, right)
        raise ValueError(f"Unsupported binary operation: {op_type}")

    def visit_UnaryOp(self, node: ast.UnaryOp) -> Any:
        operand = self.visit(node.operand)
        op_type = type(node.op)
        if op_type in self.UNARY_OPS:
            return self.UNARY_OPS[op_type](operand)
        raise ValueError(f"Unsupported unary operation: {op_type}")

    def visit_Compare(self, node: ast.Compare) -> Any:
        left = self.visit(node.left)
        for op, comparator in zip(node.ops, node.comparators):
            right = self.visit(comparator)
            op_type = type(op)
            if op_type in self.COMPARE_OPS:
                if not self.COMPARE_OPS[op_type](left, right):
                    return False
                left = right
            else:
                raise ValueError(f"Unsupported comparison: {op_type}")
        return True

    def visit_BoolOp(self, node: ast.BoolOp) -> Any:
        values = [self.visit(v) for v in node.values]
        if isinstance(node.op, ast.And):
            return all(values)
        elif isinstance(node.op, ast.Or):
            return any(values)
        raise ValueError(f"Unsupported boolean operation: {type(node.op)}")

    def visit_Call(self, node: ast.Call) -> Any:
        if not isinstance(node.func, ast.Name):
            raise ValueError("Only direct function calls are allowed")
        func_name = node.func.id
        if func_name not in self.functions:
            raise NameError(f"Function not allowed: {func_name}")
        func = self.functions[func_name]
        args = [self.visit(arg) for arg in node.args]
        keywords = {kw.arg: self.visit(kw.value) for kw in node.keywords}
        return func(*args, **keywords)

    def visit_Subscript(self, node: ast.Subscript) -> Any:
        value = self.visit(node.value)
        if isinstance(node.slice, ast.Constant):
            key = node.slice.value
        elif isinstance(node.slice, ast.Index):  # Python <3.9 compat
            key = self.visit(node.slice.value)
        else:
            key = self.visit(node.slice)
        return value[key]

    def visit_Attribute(self, node: ast.Attribute) -> Any:
        raise ValueError("Attribute access is not allowed")

    def visit_Lambda(self, node: ast.Lambda) -> Any:
        raise ValueError("Lambda expressions are not allowed")

    def visit_List(self, node: ast.List) -> Any:
        return [self.visit(elt) for elt in node.elts]

    def visit_Tuple(self, node: ast.Tuple) -> Any:
        return tuple(self.visit(elt) for elt in node.elts)

    def visit_Dict(self, node: ast.Dict) -> Any:
        result = {}
        for k, v in zip(node.keys, node.values):
            if k is None:
                raise ValueError("Dict unpacking not allowed")
            result[self.visit(k)] = self.visit(v)
        return result


def render_clinical_note_template(
    template: str,
    patient_data: Dict[str, Any],
    allowed_functions: Optional[Dict[str, Any]] = None,
) -> str:
    """
    Render a clinical note template by evaluating embedded expressions.

    The template is a string containing placeholders of the form {{expression}}
    where expression is a Python expression that can reference keys from
    patient_data as variables (e.g., {{age}}, {{creatinine}}, {{weight_kg / (height_m ** 2)}}).

    Expressions may also call functions provided in allowed_functions (e.g.,
    {{calculate_gfr(creatinine, age, sex)}}). If allowed_functions is None,
    no external functions are available.

    The function evaluates each expression and substitutes its string representation
    into the template. If an expression raises an exception during evaluation,
    the placeholder is replaced with "[ERROR]".

    Args:
        template: The template string containing {{...}} placeholders.
            This input originates from clinical configuration files edited by
            authorized staff (treated as user-controlled).
        patient_data: Dictionary mapping variable names to values (numbers,
            strings, booleans). Sourced from the patient record database.
        allowed_functions: Optional dictionary mapping function names to callables.
            Sourced from application configuration.

    Returns:
        The rendered template string with all placeholders substituted.
        Returns an empty string if template is not a string.
    """
    if not isinstance(template, str):
        return ""

    if allowed_functions is None:
        allowed_functions = {}

    # Validate that allowed_functions only contains callables
    safe_functions = {k: v for k, v in allowed_functions.items() if callable(v)}

    pattern = re.compile(r'\{\{(.+?)\}\}')
    evaluator = SafeExpressionEvaluator(patient_data, safe_functions)

    def replace_match(match: re.Match) -> str:
        expr = match.group(1).strip()
        if not expr:
            return "[ERROR]"
        try:
            tree = ast.parse(expr, mode='eval')
            result = evaluator.visit(tree)
            return str(result)
        except Exception:
            return "[ERROR]"

    return pattern.sub(replace_match, template)
