import ast
import operator
from typing import Any


def calculate_shipping_cost(formula: str, order_data: dict) -> float:
    """
    Calculate shipping cost using a merchant-defined formula.

    The formula is a restricted arithmetic expression that can reference
    order properties. Supported variables: weight (float, kg), distance (float, km),
    item_count (int), subtotal (float, USD), zone (str). Supported operators:
    +, -, *, /, //, %, **, parentheses, and comparison operators (==, !=, <, <=, >, >=)
    returning 1.0 for true and 0.0 for false. Supported functions: min, max, abs, round.

    Merchant formulas are stored in the database and applied at checkout.
    The formula string comes from merchant configuration (user-controlled).

    Args:
        formula: Arithmetic expression string defined by the merchant.
        order_data: Dictionary with keys 'weight', 'distance', 'item_count',
            'subtotal', 'zone'. All values are numeric except 'zone' (string).

    Returns:
        Calculated shipping cost as float, rounded to 2 decimal places.
        Returns 0.0 if formula is empty, evaluates to negative, or contains
        disallowed constructs (e.g., function calls other than min/max/abs/round,
        attribute access, subscript, comprehensions, lambdas, or names not in
        the allowed variable set).
    """
    if not formula or not formula.strip():
        return 0.0

    allowed_vars = {"weight", "distance", "item_count", "subtotal", "zone"}
    allowed_funcs = {
        "min": min,
        "max": max,
        "abs": abs,
        "round": round,
    }
    allowed_binops = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
    }
    allowed_unaryops = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }
    allowed_cmpops = {
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
    }

    def eval_node(node: ast.AST, variables: dict) -> Any:
        if isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float, str)):
                return node.value
            raise ValueError("Unsupported constant type")

        if isinstance(node, ast.Name):
            if node.id in variables:
                return variables[node.id]
            raise ValueError(f"Unknown variable: {node.id}")

        if isinstance(node, ast.BinOp):
            if type(node.op) not in allowed_binops:
                raise ValueError("Disallowed binary operator")
            left = eval_node(node.left, variables)
            right = eval_node(node.right, variables)
            return allowed_binops[type(node.op)](left, right)

        if isinstance(node, ast.UnaryOp):
            if type(node.op) not in allowed_unaryops:
                raise ValueError("Disallowed unary operator")
            operand = eval_node(node.operand, variables)
            return allowed_unaryops[type(node.op)](operand)

        if isinstance(node, ast.Compare):
            if len(node.ops) != 1 or len(node.comparators) != 1:
                raise ValueError("Chained comparisons not allowed")
            if type(node.ops[0]) not in allowed_cmpops:
                raise ValueError("Disallowed comparison operator")
            left = eval_node(node.left, variables)
            right = eval_node(node.comparators[0], variables)
            return 1.0 if allowed_cmpops[type(node.ops[0])](left, right) else 0.0

        if isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Name) or node.func.id not in allowed_funcs:
                raise ValueError("Disallowed function call")
            if node.keywords:
                raise ValueError("Keyword arguments not allowed")
            args = [eval_node(arg, variables) for arg in node.args]
            func = allowed_funcs[node.func.id]
            return func(*args)

        if isinstance(node, ast.IfExp):
            test = eval_node(node.test, variables)
            if test:
                return eval_node(node.body, variables)
            else:
                return eval_node(node.orelse, variables)

        raise ValueError(f"Disallowed AST node: {type(node).__name__}")

    try:
        tree = ast.parse(formula.strip(), mode="eval")
        result = eval_node(tree.body, order_data)
        if not isinstance(result, (int, float)):
            return 0.0
        result = float(result)
        return round(max(0.0, result), 2)
    except (SyntaxError, ValueError, TypeError, ZeroDivisionError, KeyError):
        return 0.0
