import os
from pathlib import Path
from typing import Any
import yaml
import json


def resolve_plugin_config(plugin_name: str, tenant_id: str, config_file: str, config_root: str | Path = "/etc/gateway/plugins") -> dict[str, Any] | None:
    """
    Resolve and load a plugin configuration file for a specific tenant.

    The API gateway stores plugin configurations in a hierarchical structure:
    {config_root}/plugins/{plugin_name}/tenants/{tenant_id}/{config_file}

    If config_file has no extension, the function searches for .yaml, .yml,
    then .json extensions in that order.

    Args:
        plugin_name: Name of the plugin (from route/plugin configuration).
        tenant_id: Tenant identifier (from request context or auth token).
        config_file: Configuration filename (from plugin manifest).
        config_root: Root directory for plugin configurations (default: /etc/gateway/plugins).

    Returns:
        Parsed configuration as a dictionary (YAML/JSON), or None if not found
        or if any input contains invalid characters (empty, whitespace-only,
        or characters not in the allowed set: alphanumeric, hyphen, underscore, dot).
    """
    allowed_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_.")

    def validate_segment(name: str) -> bool:
        if not name or not name.strip():
            return False
        if any(c not in allowed_chars for c in name):
            return False
        if name in (".", ".."):
            return False
        return True

    if not (validate_segment(plugin_name) and validate_segment(tenant_id) and validate_segment(config_file)):
        return None

    config_root_path = Path(config_root).resolve()
    base_plugins_dir = (config_root_path / "plugins").resolve()

    if not str(base_plugins_dir).startswith(str(config_root_path)):
        return None

    plugin_dir = (base_plugins_dir / plugin_name / "tenants" / tenant_id).resolve()

    if not str(plugin_dir).startswith(str(base_plugins_dir)):
        return None

    if not plugin_dir.exists() or not plugin_dir.is_dir():
        return None

    candidates: list[Path] = []
    config_path = Path(config_file)
    if config_path.suffix:
        candidates.append(plugin_dir / config_file)
    else:
        for ext in (".yaml", ".yml", ".json"):
            candidates.append(plugin_dir / f"{config_file}{ext}")

    for candidate in candidates:
        try:
            resolved = candidate.resolve()
        except (OSError, RuntimeError):
            continue
        if not str(resolved).startswith(str(plugin_dir)):
            continue
        if not resolved.exists() or not resolved.is_file():
            continue
        try:
            content = resolved.read_text(encoding="utf-8")
        except (OSError, UnicodeDecodeError):
            continue
        try:
            if resolved.suffix in (".yaml", ".yml"):
                return yaml.safe_load(content) or {}
            elif resolved.suffix == ".json":
                return json.loads(content)
        except (yaml.YAMLError, json.JSONDecodeError):
            continue
    return None
