import ast
from typing import Any


def evaluate_price_alert_condition(condition: str, product_data: dict) -> bool:
    """
    Evaluate a customer-defined price alert condition against product data.

    Customers enter free-form conditions when creating price alerts, such as
    "price < 50 and 'clearance' in tags" or "rating >= 4.5 and stock > 0".
    This function determines whether a given product matches the condition.

    Args:
        condition: A boolean expression string provided by the customer.
            Comes directly from user input (price alert creation form).
            Expected to reference keys in product_data (e.g., price, tags, rating, stock).
        product_data: Dictionary with current product attributes. Keys typically include
            'price' (float), 'tags' (list[str]), 'rating' (float), 'stock' (int),
            'category' (str), 'brand' (str). May contain additional keys.

    Returns:
        True if the condition evaluates to True for the given product_data,
        False if the condition evaluates to False, has invalid syntax,
        references missing keys, or contains disallowed constructs.
    """
    try:
        tree = ast.parse(condition, mode='eval')
    except SyntaxError:
        return False

    allowed_node_types = {
        ast.Expression, ast.BoolOp, ast.UnaryOp, ast.Compare,
        ast.Name, ast.Constant, ast.Attribute, ast.Subscript,
        ast.List, ast.Tuple, ast.Set, ast.Dict,
        ast.Load, ast.And, ast.Or, ast.Not,
        ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE,
        ast.In, ast.NotIn, ast.Is, ast.IsNot,
        ast.Slice,
    }

    for node in ast.walk(tree):
        if type(node) not in allowed_node_types:
            return False

    # Attributes that enable sandbox escape or access to internals
    FORBIDDEN_ATTRIBUTES = {
        '__class__', '__mro__', '__bases__', '__subclasses__',
        '__globals__', '__code__', '__reduce__', '__reduce_ex__',
        '__getinitargs__', '__getnewargs__', '__getstate__', '__setstate__',
        '__delattr__', '__dict__', '__dir__', '__doc__',
        '__getattribute__', '__setattr__', '__sizeof__', '__weakref__',
    }

    def eval_node(node: ast.AST) -> Any:
        if isinstance(node, ast.Expression):
            return eval_node(node.body)
        elif isinstance(node, ast.BoolOp):
            values = [eval_node(v) for v in node.values]
            if isinstance(node.op, ast.And):
                return all(values)
            elif isinstance(node.op, ast.Or):
                return any(values)
        elif isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            if isinstance(node.op, ast.Not):
                return not operand
        elif isinstance(node, ast.Compare):
            left = eval_node(node.left)
            results = []
            for op, comparator in zip(node.ops, node.comparators):
                right = eval_node(comparator)
                if isinstance(op, ast.Eq):
                    results.append(left == right)
                elif isinstance(op, ast.NotEq):
                    results.append(left != right)
                elif isinstance(op, ast.Lt):
                    results.append(left < right)
                elif isinstance(op, ast.LtE):
                    results.append(left <= right)
                elif isinstance(op, ast.Gt):
                    results.append(left > right)
                elif isinstance(op, ast.GtE):
                    results.append(left >= right)
                elif isinstance(op, ast.In):
                    results.append(left in right)
                elif isinstance(op, ast.NotIn):
                    results.append(left not in right)
                elif isinstance(op, ast.Is):
                    results.append(left is right)
                elif isinstance(op, ast.IsNot):
                    results.append(left is not right)
                left = right
            return all(results)
        elif isinstance(node, ast.Name):
            if node.id in product_data:
                return product_data[node.id]
            raise KeyError(node.id)
        elif isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.Attribute):
            obj = eval_node(node.value)
            attr_name = node.attr
            if attr_name in FORBIDDEN_ATTRIBUTES:
                raise KeyError(attr_name)
            return getattr(obj, attr_name, None)
        elif isinstance(node, ast.Subscript):
            obj = eval_node(node.value)
            key = eval_node(node.slice)
            try:
                return obj[key]
            except (KeyError, IndexError, TypeError):
                raise KeyError(key)
        elif isinstance(node, (ast.List, ast.Tuple, ast.Set)):
            return type(node)([eval_node(e) for e in node.elts])
        elif isinstance(node, ast.Dict):
            return {eval_node(k): eval_node(v) for k, v in zip(node.keys, node.values)}
        elif isinstance(node, ast.Slice):
            lower = eval_node(node.lower) if node.lower else None
            upper = eval_node(node.upper) if node.upper else None
            step = eval_node(node.step) if node.step else None
            return slice(lower, upper, step)
        return None

    try:
        result = eval_node(tree)
        return bool(result)
    except (KeyError, TypeError, ValueError, AttributeError, ZeroDivisionError):
        return False
