import yaml
from typing import Any
import re
from datetime import date


def parse_legal_hold_policy(yaml_content: str) -> dict[str, Any] | None:
    """
    Parse a legal hold policy from YAML content.

    A legal hold policy defines document preservation requirements for litigation
    or regulatory compliance. The policy must contain:
    - 'hold_id': unique identifier string (alphanumeric, hyphens, underscores)
    - 'custodians': list of email strings for document custodians
    - 'date_range': object with 'start' and 'end' ISO 8601 date strings
    - 'document_filters': list of filter objects, each with 'field' and 'value'
    - 'preservation_actions': list of action strings from allowed set:
      'prevent_deletion', 'prevent_modification', 'audit_access', 'export_copy'

    The function validates structure and allowed values. On any validation
    failure, returns None.

    Args:
        yaml_content: YAML string uploaded by a compliance officer via the
            policy management UI. This input comes directly from user uploads.

    Returns:
        Dictionary with parsed and validated policy fields, or None if the
        YAML is malformed, missing required fields, or contains invalid values.
    """
    if not yaml_content or not isinstance(yaml_content, str):
        return None

    try:
        policy = yaml.safe_load(yaml_content)
    except yaml.YAMLError:
        return None

    if not isinstance(policy, dict):
        return None

    required_fields = {
        'hold_id', 'custodians', 'date_range',
        'document_filters', 'preservation_actions'
    }
    if not required_fields.issubset(policy.keys()):
        return None

    hold_id = policy['hold_id']
    if not isinstance(hold_id, str) or not re.fullmatch(r'[A-Za-z0-9_-]+', hold_id):
        return None

    custodians = policy['custodians']
    if not isinstance(custodians, list) or not all(
        isinstance(c, str) and re.fullmatch(r'[^@]+@[^@]+\.[^@]+', c) for c in custodians
    ):
        return None

    date_range = policy['date_range']
    if not isinstance(date_range, dict) or 'start' not in date_range or 'end' not in date_range:
        return None
    try:
        start_date = date.fromisoformat(date_range['start'])
        end_date = date.fromisoformat(date_range['end'])
        if start_date > end_date:
            return None
    except (ValueError, TypeError):
        return None

    document_filters = policy['document_filters']
    if not isinstance(document_filters, list):
        return None
    for f in document_filters:
        if not isinstance(f, dict) or 'field' not in f or 'value' not in f:
            return None
        if not isinstance(f['field'], str) or not isinstance(f['value'], str):
            return None

    allowed_actions = {
        'prevent_deletion', 'prevent_modification', 'audit_access', 'export_copy'
    }
    preservation_actions = policy['preservation_actions']
    if not isinstance(preservation_actions, list) or not all(
        isinstance(a, str) and a in allowed_actions for a in preservation_actions
    ):
        return None

    return {
        'hold_id': hold_id,
        'custodians': custodians,
        'date_range': {'start': date_range['start'], 'end': date_range['end']},
        'document_filters': document_filters,
        'preservation_actions': preservation_actions
    }
