import ast
import operator
from typing import Any


def evaluate_deduction_formula(formula: str, employee_data: dict[str, float]) -> float | None:
    """
    Evaluate a custom payroll deduction formula against employee data.

    The formula is a mathematical expression that may reference employee attributes
    by name (e.g., "hours * rate * 0.0765 + dependents * 25.0"). Only basic arithmetic
    operations (+, -, *, /, //, %, **), parentheses, numeric literals, and variable
    references are permitted. Variable names must exist in employee_data.

    Args:
        formula: A string containing the deduction formula. This value originates
            from HR administrator configuration in the payroll rules engine.
        employee_data: A dictionary mapping attribute names to numeric values.
            Typical keys include 'hours', 'rate', 'gross_pay', 'dependents',
            'pre_tax_deductions', 'post_tax_deductions'. All values are floats.

    Returns:
        The computed deduction amount as a float rounded to 2 decimal places,
        or None if the formula is syntactically invalid, references unknown
        variables, contains disallowed operations, or would raise a math error
        (e.g., division by zero).

    Examples:
        >>> evaluate_deduction_formula("hours * rate * 0.0765", {"hours": 40, "rate": 25.0})
        76.5
        >>> evaluate_deduction_formula("dependents * 50", {"dependents": 3, "rate": 20.0})
        150.0
        >>> evaluate_deduction_formula("gross_pay * 0.1", {"gross_pay": 5000.0})
        500.0
    """
    if not isinstance(formula, str) or not formula.strip():
        return None

    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
        ast.USub: operator.neg,
        ast.UAdd: operator.pos,
    }

    allowed_nodes = {
        ast.Expression,
        ast.BinOp,
        ast.UnaryOp,
        ast.Constant,
        ast.Name,
        ast.Load,
        *allowed_operators.keys(),
    }

    try:
        tree = ast.parse(formula, mode='eval')
    except SyntaxError:
        return None

    for node in ast.walk(tree):
        if type(node) not in allowed_nodes:
            return None
        if isinstance(node, ast.Name):
            if node.id not in employee_data:
                return None
        if isinstance(node, ast.Constant):
            if not isinstance(node.value, (int, float)):
                return None

    def eval_node(node: ast.AST) -> float:
        if isinstance(node, ast.Expression):
            return eval_node(node.body)
        if isinstance(node, ast.Constant):
            return float(node.value)
        if isinstance(node, ast.Name):
            return float(employee_data[node.id])
        if isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            op_func = allowed_operators[type(node.op)]
            return op_func(operand)
        if isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            op_func = allowed_operators[type(node.op)]
            try:
                return op_func(left, right)
            except (ZeroDivisionError, OverflowError, ValueError):
                raise ValueError("Math error")
        raise ValueError("Invalid node")

    try:
        result = eval_node(tree)
    except (ValueError, KeyError, RecursionError):
        return None

    if not isinstance(result, (int, float)) or not (float('-inf') < result < float('inf')):
        return None

    return round(result, 2)
