import ast
import operator
from typing import Any


_ALLOWED_NAMES = {
    "weight_kg",
    "distance_km",
    "is_fragile",
    "is_express",
    "base_rate",
    "zone",
}

_BIN_OPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
    ast.FloorDiv: operator.floordiv,
}

_UNARY_OPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
    ast.Not: operator.not_,
}

_COMPARE_OPS = {
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.Is: operator.is_,
    ast.IsNot: operator.is_not,
    ast.In: lambda a, b: a in b,
    ast.NotIn: lambda a, b: a not in b,
}

_BOOL_OPS = {
    ast.And: all,
    ast.Or: any,
}


def _validate_node(node: ast.AST) -> None:
    """Recursively validate that the AST contains only allowed constructs."""
    if isinstance(node, ast.Expression):
        _validate_node(node.body)
        return

    if isinstance(node, ast.Constant):
        if not isinstance(node.value, (int, float, bool, str, type(None))):
            raise ValueError("Disallowed constant type")
        return

    if isinstance(node, ast.Name):
        if node.id not in _ALLOWED_NAMES:
            raise ValueError(f"Disallowed name: {node.id}")
        return

    if isinstance(node, ast.BinOp):
        if type(node.op) not in _BIN_OPS:
            raise ValueError("Disallowed binary operator")
        _validate_node(node.left)
        _validate_node(node.right)
        return

    if isinstance(node, ast.UnaryOp):
        if type(node.op) not in _UNARY_OPS:
            raise ValueError("Disallowed unary operator")
        _validate_node(node.operand)
        return

    if isinstance(node, ast.Compare):
        for op in node.ops:
            if type(op) not in _COMPARE_OPS:
                raise ValueError("Disallowed comparison operator")
        _validate_node(node.left)
        for comparator in node.comparators:
            _validate_node(comparator)
        return

    if isinstance(node, ast.BoolOp):
        if type(node.op) not in _BOOL_OPS:
            raise ValueError("Disallowed boolean operator")
        for value in node.values:
            _validate_node(value)
        return

    if isinstance(node, ast.IfExp):
        _validate_node(node.test)
        _validate_node(node.body)
        _validate_node(node.orelse)
        return

    if isinstance(node, ast.Call):
        raise ValueError("Function calls are not allowed")

    if isinstance(node, (ast.Subscript, ast.Attribute, ast.List, ast.Tuple, ast.Dict, ast.Set)):
        raise ValueError("Container access is not allowed")

    raise ValueError(f"Disallowed AST node type: {type(node).__name__}")


def _eval_node(node: ast.AST, context: dict[str, Any]) -> Any:
    """Safely evaluate a validated AST node."""
    if isinstance(node, ast.Expression):
        return _eval_node(node.body, context)

    if isinstance(node, ast.Constant):
        return node.value

    if isinstance(node, ast.Name):
        return context[node.id]

    if isinstance(node, ast.BinOp):
        left = _eval_node(node.left, context)
        right = _eval_node(node.right, context)
        return _BIN_OPS[type(node.op)](left, right)

    if isinstance(node, ast.UnaryOp):
        operand = _eval_node(node.operand, context)
        return _UNARY_OPS[type(node.op)](operand)

    if isinstance(node, ast.Compare):
        left = _eval_node(node.left, context)
        results = []
        for op, comparator in zip(node.ops, node.comparators):
            right = _eval_node(comparator, context)
            results.append(_COMPARE_OPS[type(op)](left, right))
            left = right
        return all(results)

    if isinstance(node, ast.BoolOp):
        values = [_eval_node(v, context) for v in node.values]
        return _BOOL_OPS[type(node.op)](values)

    if isinstance(node, ast.IfExp):
        test = _eval_node(node.test, context)
        return _eval_node(node.body, context) if test else _eval_node(node.orelse, context)

    raise ValueError(f"Cannot evaluate node type: {type(node).__name__}")


def calculate_custom_surcharge(shipment_data: dict, surcharge_expression: str) -> float:
    """
    Calculate a custom surcharge for a shipment based on a user-defined expression.

    The surcharge_expression is a Python-like expression provided by the customer
    (e.g., via a web portal) that can reference shipment attributes.

    Args:
        shipment_data: Dictionary containing shipment attributes:
            - weight_kg: float, package weight in kilograms
            - distance_km: float, delivery distance in kilometers
            - is_fragile: bool, whether package is marked fragile
            - is_express: bool, whether express delivery requested
            - base_rate: float, base shipping rate
            - zone: str, delivery zone code
        surcharge_expression: String expression provided by the customer
            defining the surcharge calculation. Can use arithmetic operators,
            comparisons, and ternary expressions. Example:
            "15.0 if distance_km > 500 else 0.0"
            "base_rate * 0.1 if is_fragile and weight_kg > 10 else 0.0"

    Returns:
        The calculated surcharge amount as a float. Returns 0.0 if the
        expression is invalid, references unknown attributes, or would
        produce a negative value.

    User-controlled inputs:
        surcharge_expression comes directly from customer configuration.
    """
    if not isinstance(surcharge_expression, str) or not surcharge_expression.strip():
        return 0.0

    try:
        tree = ast.parse(surcharge_expression, mode="eval")
    except SyntaxError:
        return 0.0

    try:
        _validate_node(tree)
    except ValueError:
        return 0.0

    context = {k: shipment_data.get(k) for k in _ALLOWED_NAMES}

    try:
        result = _eval_node(tree, context)
    except (ZeroDivisionError, TypeError, ValueError, KeyError):
        return 0.0

    if not isinstance(result, (int, float)) or result < 0:
        return 0.0

    return float(result)
