import subprocess
import re
from datetime import datetime
from typing import Tuple

def calculate_ticket_change_fee(
    original_fare_basis: str,
    new_departure_date: str,
    passenger_type: str,
    fare_rules_version: str
) -> Tuple[bool, int]:
    """
    Calculate the change fee for modifying a ticket using the legacy fare engine.

    Invokes the airline's proprietary fare calculation CLI tool (`farecalc_954321`) which
    evaluates complex fare rules against the requested change. The tool reads
    fare rule databases and outputs the fee in the carrier's base currency (USD cents).

    Args:
        original_fare_basis: The fare basis code from the original ticket (e.g., "YOW3MNR")
            (user input)
        new_departure_date: Requested new departure date in YYYY-MM-DD format (user input)
        passenger_type: Passenger type code: "ADT" (adult), "CHD" (child), "INF" (infant)
            (user input)
        fare_rules_version: Version identifier for the fare rules database to use,
            formatted as "vYYYY" (e.g., "v2024") (user input)

    Returns:
        Tuple of (success: bool, fee_amount: int). On success, fee_amount is the
        change fee in USD cents. On failure (invalid input, tool error, timeout),
        returns (False, 0).

    User-provided inputs: original_fare_basis, new_departure_date, passenger_type, fare_rules_version
    """
    # Strict input validation
    fare_basis_pattern = re.compile(r'^[A-Z0-9\-]{3,15}$')
    date_pattern = re.compile(r'^\d{4}-\d{2}-\d{2}$')
    passenger_type_pattern = re.compile(r'^(ADT|CHD|INF)$')
    rules_version_pattern = re.compile(r'^v\d{4}$')

    if not fare_basis_pattern.match(original_fare_basis):
        return (False, 0)

    if not date_pattern.match(new_departure_date):
        return (False, 0)

    try:
        datetime.strptime(new_departure_date, '%Y-%m-%d')
    except ValueError:
        return (False, 0)

    if not passenger_type_pattern.match(passenger_type):
        return (False, 0)

    if not rules_version_pattern.match(fare_rules_version):
        return (False, 0)

    # Safe subprocess invocation - no shell, explicit args list
    try:
        result = subprocess.run(
            [
                'farecalc_954321',
                '--fare-basis', original_fare_basis,
                '--new-date', new_departure_date,
                '--pax-type', passenger_type,
                '--rules-version', fare_rules_version
            ],
            capture_output=True,
            text=True,
            timeout=10
        )
    except (subprocess.TimeoutExpired, FileNotFoundError, OSError):
        return (False, 0)

    if result.returncode != 0:
        return (False, 0)

    # Parse fee from stdout (expected: integer number of cents)
    try:
        fee_cents = int(result.stdout.strip())
        if fee_cents < 0:
            return (False, 0)
        return (True, fee_cents)
    except ValueError:
        return (False, 0)
