import re
from typing import Callable, Optional
from urllib.parse import urljoin

FetchFunc = Callable[[str], Optional[dict]]


# Reserved service names that could be used for SSRF or confusion attacks.
# These are blocked even when they match the naming pattern.
_RESERVED_SERVICE_NAMES = frozenset({
    "localhost",
    "localhost.localdomain",
    "127.0.0.1",
    "0.0.0.0",
    "::1",
    "metadata",
    "metadata.google.internal",
    "169.254.169.254",
    "internal",
    "admin",
    "health",
    "healthz",
    "ready",
    "metrics",
    "debug",
    "actuator",
    "console",
    "management",
})


def fetch_service_dependencies(
    service_name: str,
    base_topology_url: str,
    fetch: FetchFunc,
    *,
    allowed_services: Optional[list[str]] = None,
) -> dict:
    """
    Fetch the dependency graph for a given service from the internal topology service.

    This function constructs a request URL to the topology service's dependency endpoint
    using the provided service name, then uses the injected fetch callable to retrieve
    the dependency data. The service name originates from the `X-Service-Name` HTTP header
    set by API gateway clients and is therefore user-controlled input.

    Args:
        service_name: The logical name of the service to query dependencies for.
            Comes from the `X-Service-Name` header (user-controlled).
        base_topology_url: Base URL of the internal topology service (e.g.,
            "http://topology-service.internal/api/v1/"). This is a trusted
            configuration value, not user input.
        fetch: An injectable callable that performs the HTTP GET request and returns
            the parsed JSON response as a dict, or None on network/parsing error.
            Signature: fetch(url: str) -> dict | None
        allowed_services: Optional allowlist of service names. If provided, only
            service names in this list are permitted. If omitted, a strict naming
            pattern is enforced instead.

    Returns:
        A dictionary representing the service dependency graph on success.
        Returns an empty dictionary if the service name is invalid, the fetch fails,
        or the response is not a valid dependency graph.

    The dependency graph dict has the following structure when present:
        {
            "service": str,
            "dependencies": list[str],
            "version": str
        }
    """
    if not service_name or not isinstance(service_name, str):
        return {}

    service_name = service_name.strip()
    if not service_name:
        return {}

    # Block reserved names that could indicate SSRF attempts or confusion attacks.
    if service_name.lower() in _RESERVED_SERVICE_NAMES:
        return {}

    if allowed_services is not None:
        if service_name not in allowed_services:
            return {}
    else:
        if not re.fullmatch(r"[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?", service_name):
            return {}

    if not base_topology_url.endswith("/"):
        base_topology_url += "/"

    endpoint = f"dependencies/{service_name}"
    request_url = urljoin(base_topology_url, endpoint)

    parsed = fetch(request_url)
    if not isinstance(parsed, dict):
        return {}

    required_keys = {"service", "dependencies", "version"}
    if not required_keys.issubset(parsed.keys()):
        return {}

    if not isinstance(parsed["service"], str) or parsed["service"] != service_name:
        return {}

    if not isinstance(parsed["dependencies"], list) or not all(
        isinstance(d, str) for d in parsed["dependencies"]
    ):
        return {}

    if not isinstance(parsed["version"], str):
        return {}

    return parsed
