import ast
from typing import Dict, Union, Set


def resolve_ticket_pricing_expression(expression: str, context: Dict[str, Union[float, int, str]], max_depth: int = 50) -> float:
    """
    Resolve a ticket pricing expression by substituting variables from context.

    The expression is a simple arithmetic expression using +, -, *, /, parentheses,
    and variable names. Context values can be numbers or strings containing nested
    expressions referencing other context keys. Nested expressions are resolved
    recursively before evaluating the final expression.

    Args:
        expression: Arithmetic expression string (e.g., "base_price * multiplier + fee").
                    Variable names must match [a-zA-Z_][a-zA-Z0-9_]*.
                    Comes from venue pricing configuration (admin input).
        context: Dictionary mapping variable names to values (int, float, or expression strings).
                 Expression strings use the same syntax and can reference other context keys.
                 Comes from venue pricing configuration (admin input).
        max_depth: Maximum recursion depth for nested expression resolution (default: 50).

    Returns:
        The computed price as a float, or 0.0 if expression is invalid, context is
        missing required variables, contains circular references, or max_depth is exceeded.
    """
    if not isinstance(expression, str) or not isinstance(context, dict) or max_depth <= 0:
        return 0.0

    def safe_eval(node: ast.AST, vars: Dict[str, float]) -> float:
        if isinstance(node, ast.Constant):
            return float(node.value)
        if isinstance(node, ast.Name):
            if node.id not in vars:
                raise ValueError("undefined")
            return vars[node.id]
        if isinstance(node, ast.BinOp):
            l, r = safe_eval(node.left, vars), safe_eval(node.right, vars)
            if isinstance(node.op, ast.Add): return l + r
            if isinstance(node.op, ast.Sub): return l - r
            if isinstance(node.op, ast.Mult): return l * r
            if isinstance(node.op, ast.Div):
                if r == 0: raise ValueError("div0")
                return l / r
            raise ValueError("op")
        if isinstance(node, ast.UnaryOp):
            v = safe_eval(node.operand, vars)
            if isinstance(node.op, ast.UAdd): return +v
            if isinstance(node.op, ast.USub): return -v
            raise ValueError("uop")
        if isinstance(node, ast.Expression): return safe_eval(node.body, vars)
        raise ValueError("node")

    def parse_expr(expr: str):
        try: return ast.parse(expr, mode='eval')
        except SyntaxError: raise ValueError("syntax")

    def get_names(tree: ast.AST) -> Set[str]:
        return {n.id for n in ast.walk(tree) if isinstance(n, ast.Name)}

    cache: Dict[str, float] = {}
    visiting: Set[str] = set()

    def resolve(key: str, depth: int) -> float:
        if depth > max_depth: raise ValueError("depth")
        if key in cache: return cache[key]
        if key in visiting: raise ValueError("cycle")
        if key not in context: raise ValueError("missing")
        visiting.add(key)
        try:
            val = context[key]
            if isinstance(val, (int, float)): res = float(val)
            elif isinstance(val, str):
                tree = parse_expr(val)
                res = safe_eval(tree, {n: resolve(n, depth+1) for n in get_names(tree)})
            else: raise ValueError("type")
            cache[key] = res
            return res
        finally: visiting.remove(key)

    try:
        tree = parse_expr(expression)
        return safe_eval(tree, {n: resolve(n, 0) for n in get_names(tree)})
    except (ValueError, SyntaxError, RecursionError, MemoryError):
        return 0.0
