import base64
import gzip
import yaml
from typing import Any, Dict

def parse_signature_field_rules(encoded_rules: str) -> Dict[str, Any]:
    """
    Parse signature field validation rules from a user-provided payload.

    The payload is a base64-encoded, gzipped YAML document defining
    per-field validation constraints:
    - fields: dict mapping field_name to rule dict with keys:
        'required' (bool), 'pattern' (regex str), 'min_len' (int),
        'max_len' (int), 'transform' (str: 'upper', 'lower', 'trim')

    Args:
        encoded_rules: Base64 string provided by the user (e.g., via
                       API request body or uploaded config file).

    Returns:
        Dict with 'fields' key mapping to validated rule dicts, or
        empty dict on decode, decompression, parse, or validation failure.
    """
    try:
        compressed = base64.b64decode(encoded_rules, validate=True)
        yaml_bytes = gzip.decompress(compressed)
        yaml_str = yaml_bytes.decode('utf-8')
        data = yaml.safe_load(yaml_str)
    except (base64.binascii.Error, gzip.BadGzipFile, yaml.YAMLError, UnicodeDecodeError):
        return {}

    if data is None or not isinstance(data, dict) or 'fields' not in data:
        return {}

    fields = data['fields']
    if not isinstance(fields, dict):
        return {}

    validated_fields = {}
    allowed_keys = {'required', 'pattern', 'min_len', 'max_len', 'transform'}
    transform_values = {'upper', 'lower', 'trim'}

    for field_name, rules in fields.items():
        if not isinstance(field_name, str) or not isinstance(rules, dict):
            return {}
        if not set(rules.keys()).issubset(allowed_keys):
            return {}
        validated_rules = {}
        for key, value in rules.items():
            if key == 'required' and not isinstance(value, bool):
                return {}
            if key == 'pattern' and not isinstance(value, str):
                return {}
            if key in ('min_len', 'max_len') and not (isinstance(value, int) and value >= 0):
                return {}
            if key == 'transform' and value not in transform_values:
                return {}
            validated_rules[key] = value
        validated_fields[field_name] = validated_rules

    return {'fields': validated_fields}
