import ast
import operator
from typing import Any, Callable

_ALLOWED_FUNCTIONS = {
    'abs': abs,
    'min': min,
    'max': max,
    'round': round,
    'pow': pow,
}

_BINOPS = {
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
    ast.FloorDiv: operator.floordiv,
    ast.Mod: operator.mod,
    ast.Pow: operator.pow,
}

_UNARYOPS = {
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
    ast.Not: operator.not_,
}

_CMPOPS = {
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
}

_BOOL_OPS = {
    ast.And: all,
    ast.Or: any,
}


class _TransformValidator(ast.NodeVisitor):
    def __init__(self, allowed_vars: frozenset[str]) -> None:
        self.allowed_vars = allowed_vars
        self.valid = True

    def visit(self, node: ast.AST) -> None:
        if not self.valid:
            return
        super().visit(node)

    def visit_Expression(self, node: ast.Expression) -> None:
        self.visit(node.body)

    def visit_BinOp(self, node: ast.BinOp) -> None:
        if type(node.op) not in _BINOPS:
            self.valid = False
            return
        self.visit(node.left)
        self.visit(node.right)

    def visit_UnaryOp(self, node: ast.UnaryOp) -> None:
        if type(node.op) not in _UNARYOPS:
            self.valid = False
            return
        self.visit(node.operand)

    def visit_Compare(self, node: ast.Compare) -> None:
        for op in node.ops:
            if type(op) not in _CMPOPS:
                self.valid = False
                return
        self.visit(node.left)
        for comparator in node.comparators:
            self.visit(comparator)

    def visit_BoolOp(self, node: ast.BoolOp) -> None:
        if type(node.op) not in _BOOL_OPS:
            self.valid = False
            return
        for value in node.values:
            self.visit(value)

    def visit_IfExp(self, node: ast.IfExp) -> None:
        self.visit(node.test)
        self.visit(node.body)
        self.visit(node.orelse)

    def visit_Call(self, node: ast.Call) -> None:
        if not isinstance(node.func, ast.Name) or node.func.id not in _ALLOWED_FUNCTIONS:
            self.valid = False
            return
        if node.keywords:
            self.valid = False
            return
        for arg in node.args:
            self.visit(arg)

    def visit_Name(self, node: ast.Name) -> None:
        if isinstance(node.ctx, ast.Load):
            if node.id not in self.allowed_vars and node.id not in _ALLOWED_FUNCTIONS:
                self.valid = False
        else:
            self.valid = False

    def visit_Constant(self, node: ast.Constant) -> None:
        if not isinstance(node.value, (int, float)):
            self.valid = False

    def visit_Expr(self, node: ast.Expr) -> None:
        self.visit(node.value)

    def generic_visit(self, node: ast.AST) -> None:
        self.valid = False


def compile_device_transform(expression: str, allowed_vars: frozenset[str]) -> Callable[[dict[str, Any]], Any] | None:
    """
    Compile a device telemetry transformation expression into a callable for efficient repeated evaluation.

    IoT devices report raw telemetry (e.g., raw ADC values, scaled integers). This function compiles
    user-defined transformation expressions that convert raw values into engineering units or derived
    metrics. The compiled callable is cached and invoked for each incoming telemetry message.

    The expression language supports:
    - Arithmetic: +, -, *, /, //, %, **
    - Comparisons: ==, !=, <, <=, >, >=
    - Logical: and, or, not
    - Ternary: x if cond else y
    - Parentheses for grouping
    - Variable references (must be declared in allowed_vars)
    - Numeric constants (int, float)
    - Calls to a restricted set of pure functions: abs, min, max, round, pow

    The function validates that the expression contains only allowed constructs and variable names.
    If validation fails, returns None. The returned callable accepts a context dict mapping variable
    names to values and returns the evaluated result. Evaluation errors (e.g., division by zero,
    missing variables) propagate as exceptions.

    User-controlled inputs: `expression` (transformation rule string from device template config).
    Configuration inputs: `allowed_vars` (set of permitted variable names from device schema).
    """
    try:
        tree = ast.parse(expression, mode='eval')
    except SyntaxError:
        return None

    validator = _TransformValidator(allowed_vars)
    validator.visit(tree)
    if not validator.valid:
        return None

    code = compile(tree, '<transform>', 'eval')

    def evaluator(context: dict[str, Any]) -> Any:
        namespace = {**_ALLOWED_FUNCTIONS, **context}
        return eval(code, {"__builtins__": {}}, namespace)

    return evaluator
