import ast
import operator
from typing import Any


def evaluate_valuation_formula(formula: str, property_data: dict[str, Any], market_context: dict[str, Any]) -> float | None:
    """
    Evaluate a user-provided property valuation adjustment formula against property and market data.

    This function allows premium agents to define custom investment scoring formulas for ranking
    listings. The formula is evaluated once per property to produce a numeric score.

    Args:
        formula: A mathematical expression string provided by the agent (user input).
                 Supported syntax: arithmetic (+, -, *, /, //, %, **), comparisons (==, !=, <, >, <=, >=),
                 boolean operators (and, or, not), parentheses, numeric literals, and variable references
                 to keys in property_data and market_context.
                 Example: "(price * 0.95) + (monthly_rent * 12 * 0.8) - (hoa_fee * 12)"
        property_data: Dictionary of property attributes (e.g., price, beds, baths, sqft, monthly_rent,
                       hoa_fee, tax_rate, year_built). Keys are strings, values are int/float/str.
        market_context: Dictionary of market-level parameters (e.g., cap_rate, vacancy_rate,
                        appreciation_rate, interest_rate). Keys are strings, values are int/float.

    Returns:
        The formula result as a float if evaluation succeeds, or None if the formula is syntactically
        invalid, references unknown variables, attempts disallowed operations, or produces a non-numeric result.

    User-controlled inputs:
        - formula: fully controlled by the agent (premium user)
        - property_data: sourced from listing database (trusted)
        - market_context: sourced from market data service (trusted)
    """
    if not isinstance(formula, str) or not formula.strip():
        return None

    # Merge contexts: property_data takes precedence for overlapping keys
    allowed_names = {**market_context, **property_data}

    # Validate all values in context are safe types
    for key, value in allowed_names.items():
        if not isinstance(value, (int, float, str)):
            return None

    try:
        tree = ast.parse(formula, mode='eval')
    except SyntaxError:
        return None

    # Allowed AST node types
    allowed_nodes = {
        ast.Expression, ast.BinOp, ast.UnaryOp, ast.Compare, ast.BoolOp,
        ast.Name, ast.Constant, ast.Load, ast.Subscript, ast.Index,
        ast.Tuple, ast.List, ast.Slice,
        # Operators
        ast.Add, ast.Sub, ast.Mult, ast.Div, ast.FloorDiv, ast.Mod, ast.Pow,
        ast.UAdd, ast.USub, ast.Not,
        ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE,
        ast.And, ast.Or,
    }

    # Walk the tree and reject any disallowed nodes
    for node in ast.walk(tree):
        if type(node) not in allowed_nodes:
            return None
        # Additional check: reject attribute access (e.g., obj.__class__)
        if isinstance(node, ast.Attribute):
            return None
        # Reject function calls
        if isinstance(node, ast.Call):
            return None
        # Reject comprehensions, lambdas, etc.
        if isinstance(node, (ast.Lambda, ast.ListComp, ast.DictComp, ast.SetComp, ast.GeneratorExp)):
            return None
        # Reject named constants like True/False/None if not using ast.Constant (py3.8+)
        # but ast.Constant covers them. Just ensure no Name nodes for them.
        if isinstance(node, ast.Name) and node.id in ('True', 'False', 'None'):
            return None

    # Verify all Name nodes reference allowed variables
    for node in ast.walk(tree):
        if isinstance(node, ast.Name):
            if node.id not in allowed_names:
                return None

    # Safe evaluation using a restricted operator mapping
    operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
        ast.Not: operator.not_,
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
        ast.And: lambda a, b: a and b,
        ast.Or: lambda a, b: a or b,
    }

    def eval_node(node: ast.AST) -> Any:
        if isinstance(node, ast.Expression):
            return eval_node(node.body)
        elif isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.Name):
            return allowed_names[node.id]
        elif isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            op_type = type(node.op)
            if op_type not in operators:
                raise ValueError(f"Disallowed operator: {op_type}")
            try:
                return operators[op_type](left, right)
            except (ZeroDivisionError, OverflowError, ValueError, TypeError):
                raise ValueError("Arithmetic error")
        elif isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            op_type = type(node.op)
            if op_type not in operators:
                raise ValueError(f"Disallowed unary operator: {op_type}")
            try:
                return operators[op_type](operand)
            except (ValueError, TypeError):
                raise ValueError("Arithmetic error")
        elif isinstance(node, ast.Compare):
            left = eval_node(node.left)
            results = []
            for op, comparator in zip(node.ops, node.comparators):
                right = eval_node(comparator)
                op_type = type(op)
                if op_type not in operators:
                    raise ValueError(f"Disallowed comparison: {op_type}")
                try:
                    results.append(operators[op_type](left, right))
                except (ValueError, TypeError):
                    raise ValueError("Comparison error")
                left = right
            return all(results)
        elif isinstance(node, ast.BoolOp):
            values = [eval_node(v) for v in node.values]
            op_type = type(node.op)
            if op_type not in operators:
                raise ValueError(f"Disallowed boolean operator: {op_type}")
            if op_type is ast.And:
                return all(values)
            elif op_type is ast.Or:
                return any(values)
            else:
                raise ValueError("Unknown bool op")
        elif isinstance(node, (ast.Subscript, ast.Index)):
            # Allow simple indexing like var[0] but restrict to safe types
            value = eval_node(node.value)
            if isinstance(node.slice, ast.Index):  # Python < 3.9
                index = eval_node(node.slice)
            else:  # Python 3.9+
                index = eval_node(node.slice)
            try:
                return value[index]
            except (IndexError, KeyError, TypeError):
                raise ValueError("Index error")
        elif isinstance(node, (ast.Tuple, ast.List)):
            return type(node)([eval_node(e) for e in node.elts])
        elif isinstance(node, ast.Slice):
            lower = eval_node(node.lower) if node.lower else None
            upper = eval_node(node.upper) if node.upper else None
            step = eval_node(node.step) if node.step else None
            return slice(lower, upper, step)
        else:
            raise ValueError(f"Unexpected node type: {type(node)}")

    try:
        result = eval_node(tree)
    except (ValueError, TypeError, KeyError, IndexError, ZeroDivisionError, OverflowError):
        return None

    # Only return numeric results (bool is a subclass of int, so included)
    if isinstance(result, (int, float)):
        return float(result)
    return None
