from lxml import etree
from typing import Dict, List, Any


def import_syndication_config(xml_content: str) -> Dict[str, Any]:
    """
    Parse and validate a content syndication configuration XML.

    The XML defines targets where blog content should be automatically
    syndicated (e.g., social media accounts, newsletter services, partner sites).

    Args:
        xml_content: XML string uploaded by a content administrator.
                     Comes from a user-controlled file upload.

    Returns:
        Dictionary with parsed configuration containing:
        - 'targets': list of dicts with 'name', 'type', 'endpoint', 'filters'
        - 'default_filters': dict of default content filters
        - 'schedule': dict with 'frequency', 'timezone', 'active_hours'

        Returns empty dict on parse failure or validation error.

    Expected XML structure:
        <syndication>
            <targets>
                <target name="..." type="twitter|mastodon|webhook|newsletter" endpoint="...">
                    <filters>
                        <filter name="..." value="..."/>
                    </filters>
                </target>
            </targets>
            <defaults>
                <filter name="..." value="..."/>
            </defaults>
            <schedule frequency="daily|hourly|manual" timezone="UTC" active_hours="9-17"/>
        </syndication>
    """
    if not xml_content or not xml_content.strip():
        return {}

    stripped = xml_content.lstrip()
    if stripped.startswith('<!DOCTYPE') or '<!DOCTYPE' in stripped[:200]:
        return {}

    try:
        parser = etree.XMLParser(
            resolve_entities=False,
            no_network=True,
            load_dtd=False,
            attribute_defaults=False,
            dtd_validation=False
        )
        root = etree.fromstring(xml_content.encode('utf-8'), parser=parser)
    except (etree.XMLSyntaxError, ValueError, UnicodeDecodeError):
        return {}

    if root.tag != 'syndication':
        return {}

    config: Dict[str, Any] = {
        'targets': [],
        'default_filters': {},
        'schedule': {}
    }

    targets_elem = root.find('targets')
    if targets_elem is not None:
        for target_elem in targets_elem.findall('target'):
            name = target_elem.get('name', '').strip()
            target_type = target_elem.get('type', '').strip()
            endpoint = target_elem.get('endpoint', '').strip()

            if not name or not target_type or not endpoint:
                continue

            if target_type not in ('twitter', 'mastodon', 'webhook', 'newsletter'):
                continue

            filters: Dict[str, str] = {}
            filters_elem = target_elem.find('filters')
            if filters_elem is not None:
                for filter_elem in filters_elem.findall('filter'):
                    fname = filter_elem.get('name', '').strip()
                    fvalue = filter_elem.get('value', '').strip()
                    if fname:
                        filters[fname] = fvalue

            config['targets'].append({
                'name': name,
                'type': target_type,
                'endpoint': endpoint,
                'filters': filters
            })

    defaults_elem = root.find('defaults')
    if defaults_elem is not None:
        for filter_elem in defaults_elem.findall('filter'):
            fname = filter_elem.get('name', '').strip()
            fvalue = filter_elem.get('value', '').strip()
            if fname:
                config['default_filters'][fname] = fvalue

    schedule_elem = root.find('schedule')
    if schedule_elem is not None:
        freq = schedule_elem.get('frequency', '').strip()
        tz = schedule_elem.get('timezone', '').strip()
        hours = schedule_elem.get('active_hours', '').strip()

        if freq in ('daily', 'hourly', 'manual'):
            config['schedule']['frequency'] = freq
        if tz:
            config['schedule']['timezone'] = tz
        if hours:
            config['schedule']['active_hours'] = hours

    return config
