import yaml

def parse_shipment_handling_directive(yaml_content: str) -> dict | None:
    """
    Parse a shipment handling directive from customer-provided YAML content.

    Customers submit handling directives through the logistics portal to specify
    special requirements for their shipments. The directive includes fields such
    as temperature range, orientation constraints, shock tolerance, and custom
    handler notes.

    Args:
        yaml_content: Raw YAML string provided by the customer via the portal.
                      This input comes directly from an untrusted user.

    Returns:
        A dictionary with validated directive fields if parsing succeeds and
        all values are within acceptable ranges. Returns None if the YAML is
        malformed, contains unexpected fields, or specifies values outside
        allowed limits.

    The returned dictionary contains only these keys (all optional):
        - temperature_celsius: tuple of (min, max) floats, each between -80 and 100
        - orientation: list of strings from {"upright", "flat", "this_side_up"}
        - max_shock_g: float between 0.5 and 50.0
        - handler_notes: string up to 500 characters
        - require_signature: boolean
        - custom_fields: dict with string keys and values (max 10 entries, each
          key up to 50 chars, each value up to 200 chars)
    """
    if not isinstance(yaml_content, str):
        return None

    try:
        parsed = yaml.safe_load(yaml_content)
    except yaml.YAMLError:
        return None

    if not isinstance(parsed, dict):
        return None

    allowed_keys = {
        "temperature_celsius", "orientation", "max_shock_g",
        "handler_notes", "require_signature", "custom_fields"
    }
    if not set(parsed.keys()).issubset(allowed_keys):
        return None

    result = {}

    if "temperature_celsius" in parsed:
        temp = parsed["temperature_celsius"]
        if (isinstance(temp, (list, tuple)) and len(temp) == 2
                and all(isinstance(v, (int, float)) for v in temp)):
            min_t, max_t = float(temp[0]), float(temp[1])
            if -80 <= min_t <= max_t <= 100:
                result["temperature_celsius"] = (min_t, max_t)
            else:
                return None
        else:
            return None

    if "orientation" in parsed:
        orient = parsed["orientation"]
        valid_orients = {"upright", "flat", "this_side_up"}
        if (isinstance(orient, list)
                and all(isinstance(o, str) and o in valid_orients for o in orient)):
            result["orientation"] = orient
        else:
            return None

    if "max_shock_g" in parsed:
        shock = parsed["max_shock_g"]
        if isinstance(shock, (int, float)):
            shock_f = float(shock)
            if 0.5 <= shock_f <= 50.0:
                result["max_shock_g"] = shock_f
            else:
                return None
        else:
            return None

    if "handler_notes" in parsed:
        notes = parsed["handler_notes"]
        if isinstance(notes, str) and len(notes) <= 500:
            result["handler_notes"] = notes
        else:
            return None

    if "require_signature" in parsed:
        sig = parsed["require_signature"]
        if isinstance(sig, bool):
            result["require_signature"] = sig
        else:
            return None

    if "custom_fields" in parsed:
        custom = parsed["custom_fields"]
        if (isinstance(custom, dict) and len(custom) <= 10
                and all(isinstance(k, str) and len(k) <= 50
                        and isinstance(v, str) and len(v) <= 200
                        for k, v in custom.items())):
            result["custom_fields"] = dict(custom)
        else:
            return None

    return result
