from urllib.parse import urlparse
from typing import Callable, Optional
import re


def validate_branding_asset_url(
    asset_url: str,
    customer_id: str,
    allowed_domains: dict[str, list[str]],
    fetch: Optional[Callable[[str], bytes]] = None
) -> tuple[bool, str]:
    """
    Validate that a branding asset URL is safe to fetch and embed in the signing ceremony.

    The e-signature service allows customers to customize the signing UI with their own
    branding assets (logos, favicons, CSS files). This function validates that the provided
    asset URL points to an allowed domain for the given customer before the asset is fetched
    and served in the signing iframe.

    Args:
        asset_url: The URL to the branding asset (provided by the customer during branding setup).
        customer_id: The unique identifier of the customer configuring the branding.
        allowed_domains: A mapping from customer_id to a list of allowed domain suffixes
            (e.g., {"cust_123": ["cdn.customer.com", "assets.customer.com"]}).
            Domains are matched as suffixes (e.g., "cdn.customer.com" matches "sub.cdn.customer.com").
        fetch: Optional callable to fetch the URL content. If provided, the function will
            attempt to fetch the asset to verify it's accessible and returns a valid
            content type (image/*, text/css). The callable takes a URL string and returns
            the response body as bytes, or raises an exception on network error.

    Returns:
        A tuple of (is_valid, error_message). If valid, is_valid is True and error_message
        is an empty string. If invalid, is_valid is False and error_message describes why.

    User-controlled inputs: asset_url, customer_id (from customer's branding configuration).
    """
    if not asset_url or not isinstance(asset_url, str):
        return False, "asset_url must be a non-empty string"

    if not customer_id or not isinstance(customer_id, str):
        return False, "customer_id must be a non-empty string"

    if customer_id not in allowed_domains:
        return False, f"customer_id '{customer_id}' not configured in allowed_domains"

    allowed = allowed_domains[customer_id]
    if not allowed:
        return False, f"no allowed domains configured for customer '{customer_id}'"

    parsed = urlparse(asset_url.strip())

    if parsed.scheme.lower() != "https":
        return False, "only HTTPS URLs are allowed"

    # Reject URLs with userinfo (e.g., https://user@host)
    if parsed.username is not None or parsed.password is not None:
        return False, "URLs with userinfo are not allowed"

    hostname = parsed.hostname
    if not hostname:
        return False, "URL must contain a valid hostname"

    hostname = hostname.lower().rstrip('.')

    if re.search(r'[^\x00-\x7F]', hostname):
        return False, "internationalized domain names must be provided in ASCII (punycode) form"

    if not any(_domain_match(hostname, allowed_domain.lower()) for allowed_domain in allowed):
        return False, f"hostname '{hostname}' is not under an allowed domain for this customer"

    if parsed.port is not None and parsed.port not in (80, 443, None):
        return False, "non-standard ports are not allowed"

    if fetch is not None:
        try:
            content = fetch(asset_url)
        except Exception as e:
            return False, f"fetch failed: {type(e).__name__}"

        content_type = _detect_content_type(content, asset_url)
        if not content_type:
            return False, "unable to determine content type"
        if not (content_type.startswith("image/") or content_type == "text/css"):
            return False, f"content type '{content_type}' is not allowed (only image/* and text/css)"

    return True, ""


def _domain_match(hostname: str, allowed_suffix: str) -> bool:
    if hostname == allowed_suffix:
        return True
    if hostname.endswith("." + allowed_suffix):
        return True
    return False


def _detect_content_type(content: bytes, url: str) -> str:
    if len(content) < 12:
        return ""

    if content[:8] == b'\x89PNG\r\n\x1a\n':
        return "image/png"
    if content[:3] == b'\xff\xd8\xff':
        return "image/jpeg"
    if content[:6] in (b'GIF87a', b'GIF89a'):
        return "image/gif"
    if content[:4] == b'RIFF' and content[8:12] == b'WEBP':
        return "image/webp"
    if content[:4] == b'\x00\x00\x00\x0c' and content[4:8] == b'jP  ':
        return "image/jpeg2000"
    if content[:4] == b'<?xml' or content[:5] == b'<svg ':
        return "image/svg+xml"

    try:
        text = content[:1024].decode('utf-8', errors='ignore').strip().lower()
        if text.startswith('@charset') or text.startswith('/*') or '{' in text or ':' in text:
            return "text/css"
    except Exception:
        pass

    return ""
