import re
import ast
import builtins
from typing import Any


class SafeExpressionEvaluator(ast.NodeVisitor):
    """Evaluates a restricted subset of Python expressions safely."""

    ALLOWED_BUILTINS = {'len', 'str', 'int', 'float', 'bool', 'min', 'max', 'abs', 'round'}

    def __init__(self, patient: dict):
        self.patient = patient
        self.result = None
        self._error = False

    def visit_Expression(self, node: ast.Expression) -> Any:
        self.visit(node.body)
        return self.result

    def visit_Constant(self, node: ast.Constant) -> Any:
        self.result = node.value

    def visit_Name(self, node: ast.Name) -> Any:
        if node.id == 'patient':
            self.result = self.patient
        else:
            self._error = True
            self.result = ''

    def visit_Attribute(self, node: ast.Attribute) -> Any:
        self.visit(node.value)
        if self._error or not isinstance(self.result, dict):
            self._error = True
            self.result = ''
            return
        self.result = self.result.get(node.attr, '')

    def visit_Subscript(self, node: ast.Subscript) -> Any:
        self.visit(node.value)
        if self._error:
            return
        try:
            key = self._eval_slice(node.slice)
            if isinstance(self.result, dict):
                self.result = self.result.get(key, '')
            elif isinstance(self.result, list) and isinstance(key, int):
                self.result = self.result[key] if 0 <= key < len(self.result) else ''
            else:
                self.result = ''
        except Exception:
            self._error = True
            self.result = ''

    def _eval_slice(self, slice_node: ast.AST) -> Any:
        if isinstance(slice_node, ast.Constant):
            return slice_node.value
        elif isinstance(slice_node, ast.Index):  # Python <3.9 compat
            return self._eval_slice(slice_node.value)
        self._error = True
        return None

    def visit_BinOp(self, node: ast.BinOp) -> Any:
        self.visit(node.left)
        left = self.result
        if self._error:
            return
        self.visit(node.right)
        right = self.result
        if self._error:
            return
        try:
            op_map = {
                ast.Add: lambda a, b: a + b,
                ast.Sub: lambda a, b: a - b,
                ast.Mult: lambda a, b: a * b,
                ast.Div: lambda a, b: a / b,
                ast.FloorDiv: lambda a, b: a // b,
                ast.Mod: lambda a, b: a % b,
                ast.Pow: lambda a, b: a ** b,
            }
            if type(node.op) in op_map:
                self.result = op_map[type(node.op)](left, right)
            else:
                self._error = True
                self.result = ''
        except Exception:
            self._error = True
            self.result = ''

    def visit_Compare(self, node: ast.Compare) -> Any:
        self.visit(node.left)
        left = self.result
        if self._error:
            return
        for op, comparator in zip(node.ops, node.comparators):
            self.visit(comparator)
            right = self.result
            if self._error:
                return
            try:
                op_map = {
                    ast.Eq: lambda a, b: a == b,
                    ast.NotEq: lambda a, b: a != b,
                    ast.Lt: lambda a, b: a < b,
                    ast.LtE: lambda a, b: a <= b,
                    ast.Gt: lambda a, b: a > b,
                    ast.GtE: lambda a, b: a >= b,
                    ast.Is: lambda a, b: a is b,
                    ast.IsNot: lambda a, b: a is not b,
                    ast.In: lambda a, b: a in b,
                    ast.NotIn: lambda a, b: a not in b,
                }
                if type(op) not in op_map:
                    self._error = True
                    self.result = ''
                    return
                left = op_map[type(op)](left, right)
            except Exception:
                self._error = True
                self.result = ''
                return
        self.result = left

    def visit_BoolOp(self, node: ast.BoolOp) -> Any:
        values = []
        for value_node in node.values:
            self.visit(value_node)
            if self._error:
                return
            values.append(self.result)
        if isinstance(node.op, ast.And):
            self.result = all(values)
        elif isinstance(node.op, ast.Or):
            self.result = any(values)
        else:
            self._error = True
            self.result = ''

    def visit_UnaryOp(self, node: ast.UnaryOp) -> Any:
        self.visit(node.operand)
        if self._error:
            return
        try:
            if isinstance(node.op, ast.Not):
                self.result = not self.result
            elif isinstance(node.op, ast.UAdd):
                self.result = +self.result
            elif isinstance(node.op, ast.USub):
                self.result = -self.result
            else:
                self._error = True
                self.result = ''
        except Exception:
            self._error = True
            self.result = ''

    def visit_Call(self, node: ast.Call) -> Any:
        if not isinstance(node.func, ast.Name) or node.func.id not in self.ALLOWED_BUILTINS:
            self._error = True
            self.result = ''
            return
        func = getattr(builtins, node.func.id, None)
        if func is None:
            self._error = True
            self.result = ''
            return
        args = []
        for arg_node in node.args:
            self.visit(arg_node)
            if self._error:
                return
            args.append(self.result)
        kwargs = {}
        for kw in node.keywords:
            self.visit(kw.value)
            if self._error:
                return
            kwargs[kw.arg] = self.result
        try:
            self.result = func(*args, **kwargs)
        except Exception:
            self._error = True
            self.result = ''

    def visit_List(self, node: ast.List) -> Any:
        elements = []
        for elt in node.elts:
            self.visit(elt)
            if self._error:
                return
            elements.append(self.result)
        self.result = elements

    def visit_Tuple(self, node: ast.Tuple) -> Any:
        elements = []
        for elt in node.elts:
            self.visit(elt)
            if self._error:
                return
            elements.append(self.result)
        self.result = tuple(elements)

    def visit_Dict(self, node: ast.Dict) -> Any:
        result = {}
        for k, v in zip(node.keys, node.values):
            self.visit(k)
            if self._error:
                return
            key = self.result
            self.visit(v)
            if self._error:
                return
            result[key] = self.result
        self.result = result

    def generic_visit(self, node: ast.AST) -> Any:
        # Disallow any node type not explicitly handled
        self._error = True
        self.result = ''


def _resolve_field_reference(record: dict, path: str) -> str:
    """Resolve a dot-notation field reference against the patient record."""
    current: Any = record
    for part in path.split('.'):
        if isinstance(current, dict):
            current = current.get(part, '')
        elif isinstance(current, list) and part.isdigit():
            idx = int(part)
            current = current[idx] if 0 <= idx < len(current) else ''
        else:
            return ''
    return str(current) if current != '' else ''


def resolve_patient_data_macros(template: str, patient_record: dict, macro_defs: dict[str, str]) -> str:
    """
    Resolve macros in a patient record template string.

    Macros are of the form {{macro_name}} and are replaced with their evaluated values.
    Macro definitions in macro_defs can be:
    - Field references: dot-notation paths into patient_record (e.g., "patient.name.given").
    - Python expressions: prefixed with "py:" (e.g., "py:len(patient.diagnoses) > 3").

    Field references traverse dictionaries and lists using dot notation. List indices
    can be accessed with numeric keys (e.g., "diagnoses.0.code"). Field references
    that cannot be resolved evaluate to an empty string.

    Args:
        template: Template string containing {{macro_name}} placeholders. May come from
                  user-selected report templates.
        patient_record: Dictionary with patient data (e.g., {'name': {'given': 'John'},
                          'age': 45, 'mrn': 'MRN123', 'diagnoses': [...]}).
        macro_defs: Dictionary mapping macro names to definition strings. Definition
                    strings come from user-configured template definitions (e.g., loaded
                    from YAML/JSON config files authored by clinic administrators).

    Returns:
        Template string with all known macros resolved to their string values.
        Unknown macro names are left as-is in the output. If a Python expression raises
        an exception, the macro resolves to an empty string. Returns empty string if
        template is not a string.
    """
    if not isinstance(template, str):
        return ''

    pattern = re.compile(r'\{\{(\w+)\}\}')
    result = template

    for match in pattern.finditer(template):
        macro_name = match.group(1)
        if macro_name not in macro_defs:
            continue

        definition = macro_defs[macro_name]
        value = ''

        if definition.startswith('py:'):
            expr = definition[3:].strip()
            try:
                tree = ast.parse(expr, mode='eval')
                evaluator = SafeExpressionEvaluator(patient_record)
                evaluated = evaluator.visit(tree)
                if not evaluator._error:
                    value = str(evaluated)
                else:
                    value = ''
            except Exception:
                value = ''
        else:
            # Field reference: strip optional "patient." prefix
            path = definition
            if path.startswith('patient.'):
                path = path[8:]
            value = _resolve_field_reference(patient_record, path)

        result = result.replace(f'{{{{{macro_name}}}}}', value)

    return result
