import yaml
from typing import Dict, Any, List

SUPPORTED_STEP_TYPES = {"rename_field", "normalize_case", "derive_field", "filter", "map_value"}

def parse_subscriber_transform_pipeline(yaml_config: str) -> Dict[str, Any]:
    """
    Parse a subscriber data transformation pipeline from YAML configuration.

    The pipeline defines a sequence of transformation steps to apply to raw
    subscriber records during import or sync operations. Each step specifies
    a transformation type and its parameters.

    Expected YAML structure:
        version: 1
        steps:
          - type: "rename_field"
            params:
              from: "email_address"
              to: "email"
          - type: "normalize_case"
            params:
              fields: ["first_name", "last_name"]
              case: "title"
          - type: "derive_field"
            params:
              name: "engagement_tier"
              expression: "score > 50 ? 'high' : 'low'"

    Supported step types: "rename_field", "normalize_case", "derive_field",
    "filter", "map_value". Unrecognized step types are ignored.

    Args:
        yaml_config: YAML string containing the pipeline definition.
            This input comes from the newsletter administrator via the
            pipeline configuration UI.

    Returns:
        Dictionary with keys 'version' (int) and 'steps' (list of step dicts),
        or an empty dictionary if the YAML is invalid, missing required
        structure, or contains no valid steps. The function never raises
        exceptions for malformed input.
    """
    if not yaml_config or not isinstance(yaml_config, str):
        return {}

    try:
        parsed = yaml.safe_load(yaml_config)
    except yaml.YAMLError:
        return {}

    if not isinstance(parsed, dict):
        return {}

    version = parsed.get("version")
    if not isinstance(version, int) or version != 1:
        return {}

    raw_steps = parsed.get("steps")
    if not isinstance(raw_steps, list):
        return {}

    valid_steps = []
    for step in raw_steps:
        if not isinstance(step, dict):
            continue
        step_type = step.get("type")
        if step_type not in SUPPORTED_STEP_TYPES:
            continue
        params = step.get("params")
        if not isinstance(params, dict):
            continue
        valid_steps.append({"type": step_type, "params": params})

    if not valid_steps:
        return {}

    return {"version": version, "steps": valid_steps}
