import ast
import re
from typing import Any


class SafeExpressionEvaluator(ast.NodeVisitor):
    """AST visitor that evaluates a restricted subset of Python expressions safely."""

    ALLOWED_BUILTINS = {
        'len', 'str', 'int', 'float', 'bool', 'list', 'dict', 'tuple', 'set',
        'min', 'max', 'sum', 'abs', 'round', 'sorted', 'reversed', 'enumerate',
        'zip', 'range', 'isinstance', 'hasattr', 'getattr'
    }

    ALLOWED_METHODS = {
        'str': {'upper', 'lower', 'strip', 'lstrip', 'rstrip', 'split', 'join',
                'replace', 'startswith', 'endswith', 'find', 'index', 'count',
                'format', 'capitalize', 'title', 'swapcase', 'casefold'},
        'list': {'append', 'extend', 'index', 'count', 'pop', 'remove', 'reverse', 'sort'},
        'dict': {'get', 'keys', 'values', 'items', 'pop', 'update', 'setdefault'},
        'set': {'add', 'remove', 'discard', 'pop', 'clear', 'update', 'union', 'intersection', 'difference'},
    }

    def __init__(self, context: dict[str, Any]):
        self.context = context
        self.result = None
        self._error = False

    def evaluate(self, node: ast.AST) -> Any:
        self._error = False
        self.visit(node)
        if self._error:
            raise ValueError("Evaluation error")
        return self.result

    def visit(self, node: ast.AST) -> Any:
        if self._error:
            return None
        return super().visit(node)

    def visit_Expression(self, node: ast.Expression) -> Any:
        return self.visit(node.body)

    def visit_Constant(self, node: ast.Constant) -> Any:
        self.result = node.value
        return node.value

    def visit_Name(self, node: ast.Name) -> Any:
        if node.id in self.context:
            self.result = self.context[node.id]
        elif node.id in self.ALLOWED_BUILTINS:
            self.result = __builtins__[node.id] if isinstance(__builtins__, dict) else getattr(__builtins__, node.id)
        else:
            self._error = True
            raise NameError(f"Name '{node.id}' not allowed")
        return self.result

    def visit_BinOp(self, node: ast.BinOp) -> Any:
        left = self.visit(node.left)
        right = self.visit(node.right)
        if self._error:
            return None
        op_map = {
            ast.Add: lambda a, b: a + b,
            ast.Sub: lambda a, b: a - b,
            ast.Mult: lambda a, b: a * b,
            ast.Div: lambda a, b: a / b,
            ast.FloorDiv: lambda a, b: a // b,
            ast.Mod: lambda a, b: a % b,
            ast.Pow: lambda a, b: a ** b,
            ast.LShift: lambda a, b: a << b,
            ast.RShift: lambda a, b: a >> b,
            ast.BitOr: lambda a, b: a | b,
            ast.BitXor: lambda a, b: a ^ b,
            ast.BitAnd: lambda a, b: a & b,
        }
        op_type = type(node.op)
        if op_type in op_map:
            try:
                self.result = op_map[op_type](left, right)
            except Exception:
                self._error = True
        else:
            self._error = True
        return self.result

    def visit_UnaryOp(self, node: ast.UnaryOp) -> Any:
        operand = self.visit(node.operand)
        if self._error:
            return None
        op_map = {
            ast.UAdd: lambda a: +a,
            ast.USub: lambda a: -a,
            ast.Not: lambda a: not a,
            ast.Invert: lambda a: ~a,
        }
        op_type = type(node.op)
        if op_type in op_map:
            try:
                self.result = op_map[op_type](operand)
            except Exception:
                self._error = True
        else:
            self._error = True
        return self.result

    def visit_Compare(self, node: ast.Compare) -> Any:
        left = self.visit(node.left)
        if self._error:
            return None
        result = True
        for op, comparator in zip(node.ops, node.comparators):
            right = self.visit(comparator)
            if self._error:
                return None
            op_map = {
                ast.Eq: lambda a, b: a == b,
                ast.NotEq: lambda a, b: a != b,
                ast.Lt: lambda a, b: a < b,
                ast.LtE: lambda a, b: a <= b,
                ast.Gt: lambda a, b: a > b,
                ast.GtE: lambda a, b: a >= b,
                ast.In: lambda a, b: a in b,
                ast.NotIn: lambda a, b: a not in b,
                ast.Is: lambda a, b: a is b,
                ast.IsNot: lambda a, b: a is not b,
            }
            op_type = type(op)
            if op_type in op_map:
                try:
                    result = result and op_map[op_type](left, right)
                except Exception:
                    self._error = True
                    return None
            else:
                self._error = True
                return None
            left = right
        self.result = result
        return result

    def visit_BoolOp(self, node: ast.BoolOp) -> Any:
        values = []
        for value in node.values:
            v = self.visit(value)
            if self._error:
                return None
            values.append(v)
        if isinstance(node.op, ast.And):
            self.result = all(values)
        elif isinstance(node.op, ast.Or):
            self.result = any(values)
        else:
            self._error = True
        return self.result

    def visit_IfExp(self, node: ast.IfExp) -> Any:
        test = self.visit(node.test)
        if self._error:
            return None
        if test:
            self.result = self.visit(node.body)
        else:
            self.result = self.visit(node.orelse)
        return self.result

    def visit_Subscript(self, node: ast.Subscript) -> Any:
        value = self.visit(node.value)
        if self._error:
            return None
        key = self.visit(node.slice)
        if self._error:
            return None
        try:
            self.result = value[key]
        except Exception:
            self._error = True
        return self.result

    def visit_Attribute(self, node: ast.Attribute) -> Any:
        value = self.visit(node.value)
        if self._error:
            return None
        attr_name = node.attr
        value_type = type(value).__name__
        if value_type in self.ALLOWED_METHODS and attr_name in self.ALLOWED_METHODS[value_type]:
            try:
                self.result = getattr(value, attr_name)
            except Exception:
                self._error = True
        else:
            self._error = True
        return self.result

    def visit_Call(self, node: ast.Call) -> Any:
        func = self.visit(node.func)
        if self._error:
            return None
        args = []
        for arg in node.args:
            a = self.visit(arg)
            if self._error:
                return None
            args.append(a)
        keywords = {}
        for kw in node.keywords:
            k = self.visit(kw.value)
            if self._error:
                return None
            keywords[kw.arg] = k
        try:
            self.result = func(*args, **keywords)
        except Exception:
            self._error = True
        return self.result

    def visit_List(self, node: ast.List) -> Any:
        elements = []
        for elt in node.elts:
            e = self.visit(elt)
            if self._error:
                return None
            elements.append(e)
        self.result = elements
        return self.result

    def visit_Tuple(self, node: ast.Tuple) -> Any:
        elements = []
        for elt in node.elts:
            e = self.visit(elt)
            if self._error:
                return None
            elements.append(e)
        self.result = tuple(elements)
        return self.result

    def visit_Dict(self, node: ast.Dict) -> Any:
        result = {}
        for key, value in zip(node.keys, node.values):
            k = self.visit(key)
            if self._error:
                return None
            v = self.visit(value)
            if self._error:
                return None
            result[k] = v
        self.result = result
        return self.result

    def visit_Set(self, node: ast.Set) -> Any:
        elements = []
        for elt in node.elts:
            e = self.visit(elt)
            if self._error:
                return None
            elements.append(e)
        self.result = set(elements)
        return self.result

    def visit_Slice(self, node: ast.Slice) -> Any:
        lower = self.visit(node.lower) if node.lower else None
        if self._error:
            return None
        upper = self.visit(node.upper) if node.upper else None
        if self._error:
            return None
        step = self.visit(node.step) if node.step else None
        if self._error:
            return None
        self.result = slice(lower, upper, step)
        return self.result

    def generic_visit(self, node: ast.AST) -> Any:
        self._error = True
        raise TypeError(f"Unsupported AST node: {type(node).__name__}")


def render_message_template(
    template: str,
    context: dict[str, Any],
    user_expressions: dict[str, str]
) -> str:
    """
    Render a message template by evaluating user-defined expressions against a message context.

    This function processes templates for a chat application's auto-responder feature.
    Placeholders in the template use `{name}` syntax. Each placeholder is resolved as follows:
    1. If `name` exists in `user_expressions`, the corresponding expression string is evaluated
       with the `context` dict available as local variables. The result is converted to string.
    2. Else if `name` exists in `context`, the context value is used directly (converted to string).
    3. Otherwise, the placeholder `{name}` is left unchanged in the output.

    User-provided inputs (potentially untrusted):
    - `template`: the template string containing placeholders, configured by chat admins.
    - `user_expressions`: a mapping from placeholder names to expression strings, configured by chat admins.

    System-provided inputs (trusted):
    - `context`: a dictionary containing message data with keys such as:
        - 'sender': str (username)
        - 'content': str (message text)
        - 'timestamp': float (UNIX timestamp)
        - 'metadata': dict (arbitrary message metadata)
      Additional keys may be present.

    Expression semantics:
    - Expressions are Python-like and may reference context keys as variables.
    - Examples: "sender.upper()", "len(content)", "metadata.get('priority', 'normal')",
      "int(timestamp) % 86400", "'urgent' in content.lower()".
    - If evaluation fails for any reason (syntax error, name error, attribute error, etc.),
      the placeholder is left unchanged in the output.

    Args:
        template: Template string with `{placeholder}` markers.
        context: Dictionary of message context variables.
        user_expressions: Mapping from placeholder name to expression string.

    Returns:
        The rendered template string with all resolvable placeholders substituted.
    """
    placeholder_pattern = re.compile(r'\{([^{}]+)\}')

    def replace_placeholder(match: re.Match) -> str:
        name = match.group(1)
        if name in user_expressions:
            expr = user_expressions[name]
            try:
                tree = ast.parse(expr, mode='eval')
                evaluator = SafeExpressionEvaluator(context)
                value = evaluator.evaluate(tree)
                return str(value)
            except Exception:
                return match.group(0)
        elif name in context:
            return str(context[name])
        else:
            return match.group(0)

    return placeholder_pattern.sub(replace_placeholder, template)
