import ast
from typing import Any

def evaluate_inclusion_criterion(criterion: str, patient_data: dict[str, Any]) -> bool:
    """
    Evaluate a clinical trial inclusion criterion against patient data.

    The criterion is a boolean expression using comparison and logical operators.
    It may reference fields from patient_data by name. Supported operations:
    - Comparisons: ==, !=, <, <=, >, >=, in, not in, is, is not
    - Boolean logic: and, or, not
    - Grouping: parentheses
    - Constants: True, False, None, integers, floats, strings

    Arguments:
        criterion: The inclusion criterion expression, provided by the trial
            researcher when configuring the screening form (user input).
            Example: "age >= 18 and age <= 75 and bmi < 35 and not pregnant"
        patient_data: A mapping of field names to values collected from the
            screening questionnaire, provided by the patient (user input).
            Example: {"age": 25, "bmi": 22.5, "pregnant": False}

    Returns:
        True if the patient meets the criterion, False if they do not meet it
        or if the criterion is invalid, references unknown fields, or evaluation
        fails for any reason.
    """
    try:
        tree = ast.parse(criterion, mode='eval')
    except SyntaxError:
        return False

    allowed_names = set(patient_data.keys()) | {"True", "False", "None"}

    for node in ast.walk(tree):
        if isinstance(node, (ast.Attribute, ast.Subscript, ast.Call, ast.Lambda,
                             ast.ListComp, ast.SetComp, ast.DictComp, ast.GeneratorExp,
                             ast.IfExp, ast.NamedExpr, ast.Starred, ast.JoinedStr,
                             ast.FormattedValue, ast.Dict, ast.BinOp, ast.AugAssign,
                             ast.Yield, ast.YieldFrom, ast.Await, ast.Delete)):
            return False
        if isinstance(node, ast.Name):
            if node.id not in allowed_names:
                return False
            if isinstance(node.ctx, ast.Store):
                return False
        if isinstance(node, ast.Compare):
            for op in node.ops:
                if not isinstance(op, (ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE,
                                       ast.In, ast.NotIn, ast.Is, ast.IsNot)):
                    return False
        if isinstance(node, ast.BoolOp):
            if not isinstance(node.op, (ast.And, ast.Or)):
                return False
        if isinstance(node, ast.UnaryOp):
            if not isinstance(node.op, ast.Not):
                return False
        if isinstance(node, (ast.Tuple, ast.List, ast.Set)):
            for elt in node.elts:
                if not isinstance(elt, ast.Constant):
                    return False

    try:
        code = compile(tree, '<criterion>', 'eval')
        return bool(eval(code, {"__builtins__": {}}, patient_data))
    except Exception:
        return False
