import zlib
import json
import hashlib
import hmac
from typing import Any

# Hard limits for resource consumption control
MAX_COMPRESSED_SIZE = 65536          # 64 KiB max compressed input
MAX_UNCOMPRESSED_SIZE = 1048576      # 1 MiB max decompressed JSON
MAX_CHANGES = 256                    # Max changes per delta
MAX_PATH_LENGTH = 128                # Max config path length
MAX_JSON_DEPTH = 32                  # Max JSON nesting depth
REQUIRED_DEVICE_ID_LEN = 16
REQUIRED_CHECKSUM_LEN = 32
ALLOWED_OPS = frozenset({"set", "delete", "increment"})

def _canonical_json(obj: Any) -> bytes:
    """Encode JSON with sorted keys, no whitespace, for canonical checksum."""
    return json.dumps(obj, separators=(',', ':'), sort_keys=True).encode('utf-8')

def _compute_checksum(json_obj: dict) -> bytes:
    """Compute SHA-256 of JSON object with 'checksum' field removed."""
    filtered = {k: v for k, v in json_obj.items() if k != "checksum"}
    encoded = _canonical_json(filtered)
    return hashlib.sha256(encoded).digest()

def _validate_change(change: Any, depth: int) -> bool:
    """Validate a single change entry with depth tracking."""
    if depth > MAX_JSON_DEPTH:
        return False
    if not isinstance(change, dict):
        return False
    keys = set(change.keys())
    if keys not in ({"path", "op", "value"}, {"path", "op"}):
        return False

    path = change.get("path")
    op = change.get("op")

    if not isinstance(path, str) or len(path) > MAX_PATH_LENGTH:
        return False
    if not isinstance(op, str) or op not in ALLOWED_OPS:
        return False
    if op != "delete" and "value" not in change:
        return False

    # Recursively validate value size/depth if present
    if "value" in change:
        if not _validate_json_value(change["value"], depth + 1):
            return False

    return True

def _validate_json_value(value: Any, depth: int) -> bool:
    """Recursively validate JSON value size and depth."""
    if depth > MAX_JSON_DEPTH:
        return False

    if isinstance(value, dict):
        if len(value) > 1000:  # Reasonable object size limit
            return False
        return all(
            isinstance(k, str) and len(k) <= MAX_PATH_LENGTH and _validate_json_value(v, depth + 1)
            for k, v in value.items()
        )
    elif isinstance(value, list):
        if len(value) > 1000:  # Reasonable array size limit
            return False
        return all(_validate_json_value(v, depth + 1) for v in value)
    elif isinstance(value, str):
        return len(value) <= 65536  # 64 KiB per string
    elif isinstance(value, (int, float, bool)) or value is None:
        return True
    return False

def parse_device_config_delta(compressed_payload: bytes, expected_device_id: bytes) -> dict | None:
    """
    Parse a compressed JSON configuration delta for an IoT device.

    The delta is a zlib-compressed JSON object containing:
    - 'device_id': string (exactly 32 hex characters, 16 bytes) identifying the target device
    - 'sequence': unsigned integer (monotonically increasing config version)
    - 'timestamp': unsigned integer (UNIX epoch seconds)
    - 'changes': array of change objects, each with:
        - 'path': string (configuration path, max 128 chars, e.g. "network.wifi.ssid")
        - 'op': string (one of "set", "delete", "increment")
        - 'value': JSON value (new value for "set"/"increment", absent for "delete")
    - 'checksum': string (64 hex characters, 32 bytes, SHA-256 of the uncompressed JSON
      object with the 'checksum' field removed, encoded as canonical JSON with sorted keys)

    The `compressed_payload` comes from the configuration management backend
    and may originate from an untrusted administrative interface or compromised
    edge gateway. The `expected_device_id` is provided by the caller from the
    device's provisioning record as a 16-byte value.

    Args:
        compressed_payload: Zlib-compressed JSON configuration delta.
        expected_device_id: 16-byte device identifier from provisioning record.

    Returns:
        Dict with keys 'sequence', 'timestamp', 'changes' on success.
        Returns None if decompression fails, JSON is malformed, structure is
        invalid, device_id mismatches, checksum fails, or limits are exceeded.
    """
    # Enforce compressed size limit before any processing
    if len(compressed_payload) > MAX_COMPRESSED_SIZE:
        return None

    # Decompress with strict size limit to prevent decompression bombs
    try:
        decompressor = zlib.decompressobj()
        decompressed = b""
        chunk_size = 8192
        for i in range(0, len(compressed_payload), chunk_size):
            chunk = compressed_payload[i:i + chunk_size]
            decompressed += decompressor.decompress(chunk)
            if len(decompressed) > MAX_UNCOMPRESSED_SIZE:
                return None
        decompressed += decompressor.flush()
        if len(decompressed) > MAX_UNCOMPRESSED_SIZE:
            return None
        # Ensure all input was consumed (no trailing garbage)
        if decompressor.unused_data:
            return None
    except (zlib.error, OSError, MemoryError):
        return None

    # Parse JSON with size/depth validation after parsing
    try:
        decoded_str = decompressed.decode('utf-8')
        parsed = json.loads(decoded_str)
    except (UnicodeDecodeError, json.JSONDecodeError, MemoryError):
        return None

    # Validate top-level structure
    if not isinstance(parsed, dict):
        return None

    required_keys = {"device_id", "sequence", "timestamp", "changes", "checksum"}
    if set(parsed.keys()) != required_keys:
        return None

    # Validate device_id (hex string, 32 chars = 16 bytes)
    device_id_str = parsed.get("device_id")
    if not isinstance(device_id_str, str) or len(device_id_str) != 32:
        return None
    try:
        device_id = bytes.fromhex(device_id_str)
    except ValueError:
        return None
    if len(device_id) != REQUIRED_DEVICE_ID_LEN:
        return None
    if not hmac.compare_digest(device_id, expected_device_id):
        return None

    # Validate sequence and timestamp
    sequence = parsed.get("sequence")
    timestamp = parsed.get("timestamp")
    if not isinstance(sequence, int) or sequence < 0:
        return None
    if not isinstance(timestamp, int) or timestamp < 0:
        return None

    # Validate changes array
    changes = parsed.get("changes")
    if not isinstance(changes, list) or len(changes) > MAX_CHANGES:
        return None

    for change in changes:
        if not _validate_change(change, 1):
            return None

    # Validate checksum (hex string, 64 chars = 32 bytes)
    checksum_str = parsed.get("checksum")
    if not isinstance(checksum_str, str) or len(checksum_str) != 64:
        return None
    try:
        checksum = bytes.fromhex(checksum_str)
    except ValueError:
        return None
    if len(checksum) != REQUIRED_CHECKSUM_LEN:
        return None

    expected_checksum = _compute_checksum(parsed)
    if not hmac.compare_digest(checksum, expected_checksum):
        return None

    return {
        "sequence": sequence,
        "timestamp": timestamp,
        "changes": changes
    }
