from lxml import etree
from typing import Dict, Any, Optional
import os


def get_achievement_progress(
    player_id: str,
    category: str,
    tier: str,
    xml_path: str = "data/achievements.xml"
) -> Dict[str, Any]:
    """
    Retrieve a player's progress for achievements matching the given category and tier.

    The function queries an XML document containing achievement definitions and
    cross-references them with the player's recorded progress stored in a parallel
    XML structure. Both category and tier are used to filter the achievement set.

    Args:
        player_id: Unique identifier for the player (e.g., "player_12345").
            This value comes from the authenticated session; treat as trusted.
        category: Achievement category to filter by (e.g., "combat", "exploration",
            "crafting", "social"). This value comes from the admin panel UI dropdown
            but may be tampered with by a malicious admin user; treat as untrusted.
        tier: Achievement tier to filter by (e.g., "bronze", "silver", "gold",
            "platinum", "diamond"). This value comes from the admin panel UI dropdown
            but may be tampered with by a malicious admin user; treat as untrusted.
        xml_path: Path to the achievements XML file. Defaults to "data/achievements.xml".

    Returns:
        A dictionary mapping achievement IDs to progress information. Each value is a
        dict with keys: "name" (str), "description" (str), "current" (int), "target" (int),
        "completed" (bool), "unlocked_at" (str or None). Returns an empty dictionary if
        no achievements match the filters, the player has no progress records, or the
        XML file is missing or malformed.

    Example:
        >>> get_achievement_progress("player_123", "combat", "gold")
        {"ach_045": {"name": "Dragon Slayer", "description": "Defeat 10 dragons",
                     "current": 7, "target": 10, "completed": False, "unlocked_at": None}}
    """
    if not os.path.exists(xml_path):
        return {}

    try:
        tree = etree.parse(xml_path)
    except (etree.XMLSyntaxError, OSError):
        return {}

    root = tree.getroot()

    valid_categories = {"combat", "exploration", "crafting", "social", "pvp", "economy"}
    valid_tiers = {"bronze", "silver", "gold", "platinum", "diamond"}

    if category not in valid_categories or tier not in valid_tiers:
        return {}

    xpath_query = (
        "//achievement[@category=$cat and @tier=$tier]"
    )

    try:
        achievements = root.xpath(xpath_query, cat=category, tier=tier)
    except etree.XPathError:
        return {}

    progress_path = xml_path.replace("achievements.xml", f"progress/{player_id}.xml")
    progress_data = {}
    if os.path.exists(progress_path):
        try:
            prog_tree = etree.parse(progress_path)
            prog_root = prog_tree.getroot()
            for prog in prog_root.xpath("//progress"):
                ach_id = prog.get("achievement_id")
                if ach_id:
                    progress_data[ach_id] = {
                        "current": int(prog.get("current", "0")),
                        "completed": prog.get("completed", "false").lower() == "true",
                        "unlocked_at": prog.get("unlocked_at") or None,
                    }
        except (etree.XMLSyntaxError, OSError, ValueError):
            pass

    result = {}
    for ach in achievements:
        ach_id = ach.get("id")
        if not ach_id:
            continue

        prog = progress_data.get(ach_id, {})
        current = prog.get("current", 0)
        target_text = ach.get("target", "0")
        try:
            target = int(target_text)
        except ValueError:
            target = 0

        completed = prog.get("completed", False)
        if not completed and target > 0:
            completed = current >= target

        result[ach_id] = {
            "name": ach.get("name", ""),
            "description": ach.get("description", ""),
            "current": current,
            "target": target,
