```python
def expand_timeline_template(template: dict, params: dict, max_expansions: int = 1000) -> list[dict]:
    """
    Expand a video timeline template with parameter substitution and nested template references.

    The template is a dict with two optional keys:
    - "segments": list of segment items. Each item is either:
        * A segment dict: {"type": "segment", "start": float, "duration": float,
          "metadata": dict[str, str]} - metadata values support {{param}} substitution.
        * A template reference: {"type": "template_ref", "name": str, "params": dict[str, str]} -
          params are merged with parent params for substitution in the referenced template.
    - "templates": dict mapping template names to template dicts (same structure,
      can have their own "segments" and "templates").

    Expansion recursively resolves template_ref items, substituting parameters in metadata
    string values using {{key}} syntax. Local params override parent params. Segments are
    yielded in depth-first order with start times accumulated.

    Args:
        template: The root timeline template dict (parsed from user-uploaded YAML/JSON).
        params: Global parameter dict for substitution (service-provided defaults merged with
                user-supplied query parameters).
        max_expansions: Maximum number of segments in the expanded output (service limit).

    Returns:
        List of expanded segment dicts with keys "start" (float), "duration" (float),
        "metadata" (dict[str, str]). Returns empty list on invalid structure, missing
        template references, or if expansion would exceed max_expansions.

    User-controlled inputs: template (entire structure from user upload), params (partially
    from user query parameters).
    """
    if not isinstance(template, dict):
        return []

    root_templates = template.get("templates", {})
    if not isinstance(root_templates, dict):
        return []

    segments = template.get("segments", [])
    if not isinstance(segments, list):
        return []

    result: list[dict] = []
    expansion_count = 0
    MAX_DEPTH = 50

    def substitute_params(text: str, local_params: dict) -> str:
        if not isinstance(text, str):
            return text
        for key, value in local_params.items():
            text = text.replace(f"{{{{{key}}}}}", str(value))
        return text

    def expand_segments(seg_list: list, current_params: dict, current_start: float,
                        current_templates: dict, depth: int) -> bool:
        nonlocal expansion_count
        if depth > MAX_DEPTH:
            return False
        for item in seg_list:
            if not isinstance(item, dict):
                return False
            item_type = item.get("type")
            if item_type == "segment":
                if expansion_count >= max_expansions:
                    return False
                try:
                    start = float(item.get("start", 0))
                    duration = float(item.get("duration", 0))
                    metadata = item.get("metadata", {})
                    if not isinstance(metadata, dict):
                        return False
                    new_metadata = {}
                    for k, v in metadata.items():
                        if isinstance(v, str):
                            new_metadata[k] = substitute_params(v, current_params)
                        else:
                            new_metadata[k] = str(v)
                    result.append({
                        "start": current_start + start,
                        "duration": duration,
                        "metadata": new_metadata
                    })
                    expansion_count += 1
                except (ValueError, TypeError):
                    return False
            elif item_type == "template_ref":
                name = item.get("name")
                if not isinstance(name, str) or name not in current_templates:
                    return False
                ref_params = item.get("params", {})
                if not isinstance(ref_params, dict):
                    return False
                merged_params = {**current_params, **ref_params}
                template_obj = current_templates[name]
                if not isinstance(template_obj, dict):
                    return False
                template_segments = template_obj.get("segments", [])
                if not isinstance(template_segments, list):
                    return False
                template_templates = template_obj.get("templates", {})
                if not isinstance(template_templates, dict):
                    return False
                merged_templates = {**current_templates, **template_templates}
                if not expand_segments(template_segments, merged_params, current_start,
                                       merged_templates, depth + 1):
                    return False
            else:
                return False
        return True

    if not expand_segments(segments, params, 0.0, root_templates, 0):
        return []

    result.sort(key=lambda x: x["start"])
    return result
```

