import re

def build_document_response_headers(
    document_title: str,
    case_number: str,
    classification: str,
    requested_by: str,
    document_id: str
) -> dict[str, str]:
    """
    Build HTTP response headers for a legal document download response.

    Args:
        document_title: User-supplied title of the document (from user input).
        case_number: User-supplied case/matter number (from user input).
        classification: User-supplied classification level (from user input).
        requested_by: User-supplied identifier of the requesting user (from user input).
        document_id: System-generated document UUID (trusted internal value).

    Returns:
        Dictionary mapping header names to header values for the HTTP response.
        Returns an empty dictionary if any user-supplied input contains
        characters that would make the header value invalid.
    """
    user_inputs = {
        "document_title": document_title,
        "case_number": case_number,
        "classification": classification,
        "requested_by": requested_by,
    }

    # Header values must not contain CR or LF (RFC 7230)
    for value in user_inputs.values():
        if not isinstance(value, str):
            return {}
        if "\r" in value or "\n" in value:
            return {}

    # Additional validation: reasonable length and printable characters
    for value in user_inputs.values():
        if len(value) > 256:
            return {}
        if not all(32 <= ord(c) <= 126 or c in "\t" for c in value):
            return {}

    # Validate document_id format (UUID-like, trusted but verify)
    if not re.match(r"^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$", document_id):
        return {}

    # Sanitize filename for Content-Disposition (RFC 6266): escape backslashes first, then quotes
    safe_title = document_title.replace("\\", "\\\\").replace('"', '\\"')
    if len(safe_title) > 200:
        safe_title = safe_title[:200]

    headers = {
        "Content-Disposition": f'attachment; filename="{safe_title}.pdf"',
        "X-Case-Number": case_number,
        "X-Classification": classification,
        "X-Requested-By": requested_by,
        "X-Document-ID": document_id,
    }
    return headers
