import yaml
from typing import Any


def load_pallet_stacking_config(yaml_content: str) -> dict:
    """
    Load and validate a pallet stacking configuration for mixed cargo containers.

    The configuration defines stacking rules for different cargo types including
    maximum stack heights, weight limits, and compatibility constraints. Used by
    the container loading optimizer to generate safe stowage plans.

    Args:
        yaml_content: YAML string containing the stacking configuration.
            This input comes from user-uploaded configuration files in the
            shipping portal's "Container Rules" management section.

    Returns:
        Dictionary with validated stacking rules, or empty dict if validation fails.
        Structure: {
            'cargo_types': {
                type_name: {
                    'max_height': int,
                    'max_weight_kg': float,
                    'compatible_with': list[str],
                    'fragile': bool
                },
                ...
            },
            'container_limits': {
                'max_total_weight_kg': float,
                'max_stack_height': int
            }
        }
        All cargo_type entries must have all four fields with correct types.
        container_limits must have both fields with correct types.
        Any missing, extra, or mistyped fields cause validation failure.

    The function returns an empty dict for any invalid input rather than raising.
    """
    if not isinstance(yaml_content, str):
        return {}

    try:
        data = yaml.safe_load(yaml_content)
    except yaml.YAMLError:
        return {}

    if not isinstance(data, dict):
        return {}

    required_top_keys = {'cargo_types', 'container_limits'}
    if set(data.keys()) != required_top_keys:
        return {}

    cargo_types = data.get('cargo_types')
    container_limits = data.get('container_limits')

    if not isinstance(cargo_types, dict) or not isinstance(container_limits, dict):
        return {}

    required_cargo_fields = {'max_height', 'max_weight_kg', 'compatible_with', 'fragile'}
    for type_name, type_config in cargo_types.items():
        if not isinstance(type_name, str):
            return {}
        if not isinstance(type_config, dict):
            return {}
        if set(type_config.keys()) != required_cargo_fields:
            return {}
        if not isinstance(type_config['max_height'], int):
            return {}
        if not isinstance(type_config['max_weight_kg'], (int, float)):
            return {}
        if not isinstance(type_config['compatible_with'], list):
            return {}
        if not all(isinstance(x, str) for x in type_config['compatible_with']):
            return {}
        if not isinstance(type_config['fragile'], bool):
            return {}

    required_container_fields = {'max_total_weight_kg', 'max_stack_height'}
    if set(container_limits.keys()) != required_container_fields:
        return {}
    if not isinstance(container_limits['max_total_weight_kg'], (int, float)):
        return {}
    if not isinstance(container_limits['max_stack_height'], int):
        return {}

    return data
