import ast
import operator
from typing import Any


def evaluate_ws_frame_filter(filter_expr: str, frame_payload: dict, connection_context: dict) -> bool:
    """
    Evaluate a WebSocket frame filter expression against a frame payload and connection context.

    The filter expression is a user-provided string (received via the `filter` query parameter
    when establishing a WebSocket subscription) that defines a boolean condition on the frame
    payload and connection context. The expression language supports:
    - Attribute access on `payload` (the frame_payload dict) and `context` (the connection_context dict)
    - Comparison operators: ==, !=, <, >, <=, >=
    - Logical operators: and, or, not
    - Membership test: in

    The function returns True if the frame matches the filter (should be delivered to the client),
    False if it does not match (should be dropped), or False if the expression is invalid,
    references missing keys, or causes any evaluation error.

    Args:
        filter_expr: The filter expression string provided by the connecting client.
        frame_payload: The parsed JSON payload of the WebSocket frame (dict).
        connection_context: Dictionary containing connection metadata (user_id, subscriptions, etc.).

    Returns:
        True if the frame matches the filter, False otherwise (including on any error).
    """
    if not filter_expr or not filter_expr.strip():
        return False

    ops = {ast.Eq: operator.eq, ast.NotEq: operator.ne, ast.Lt: operator.lt,
           ast.Gt: operator.gt, ast.LtE: operator.le, ast.GtE: operator.ge,
           ast.And: lambda a, b: a and b, ast.Or: lambda a, b: a or b,
           ast.Not: operator.not_, ast.In: lambda a, b: a in b}

    def _get(obj, key):
        try:
            return obj.get(key) if isinstance(obj, dict) else (obj[key] if isinstance(obj, list) and isinstance(key, int) and 0 <= key < len(obj) else None)
        except Exception:
            return None

    def _eval(node, env):
        if isinstance(node, ast.Constant):
            return node.value
        if isinstance(node, ast.Name):
            if node.id in env:
                return env[node.id]
            raise ValueError("Unknown name")
        if isinstance(node, ast.Attribute):
            obj = _eval(node.value, env)
            if isinstance(obj, dict):
                return _get(obj, node.attr)
            raise ValueError("Invalid attr")
        if isinstance(node, ast.Subscript):
            obj = _eval(node.value, env)
            key = _eval(node.slice, env) if not isinstance(node.slice, ast.Constant) else node.slice.value
            return _get(obj, key)
        if isinstance(node, ast.BinOp) and type(node.op) in ops:
            return ops[type(node.op)](_eval(node.left, env), _eval(node.right, env))
        if isinstance(node, ast.UnaryOp) and type(node.op) in ops:
            return ops[type(node.op)](_eval(node.operand, env))
        if isinstance(node, ast.BoolOp) and type(node.op) in ops:
            vals = [_eval(v, env) for v in node.values]
            return vals[0] if not vals else __import__('functools').reduce(ops[type(node.op)], vals)
        if isinstance(node, ast.Compare):
            left = _eval(node.left, env)
            for op, comp in zip(node.ops, node.comparators):
                right = _eval(comp, env)
                if type(op) not in ops or not ops[type(op)](left, right):
                    return False
                left = right
            return True
        raise ValueError("Disallowed node")

    try:
        return bool(_eval(ast.parse(filter_expr, mode='eval').body, {'payload': frame_payload, 'context': connection_context}))
    except Exception:
        return False
