import ast
import operator
from typing import Callable


def compile_derived_variable_formula(
    formula: str,
    allowed_variables: list[str],
    allowed_functions: dict[str, Callable] | None = None,
) -> Callable[[dict[str, float]], float] | None:
    """
    Compile a user-provided mathematical formula into a callable for computing
    derived variables in a scientific data archive.

    The formula is an arithmetic expression that may reference variables by name.
    Only variables listed in `allowed_variables` may be referenced. Optional
    `allowed_functions` maps function names to callables that may be invoked
    in the formula (e.g., {"sqrt": math.sqrt, "log": math.log}).

    The returned callable accepts a dictionary mapping variable names to numeric
    values and returns the computed float result. If the formula is syntactically
    invalid, references disallowed variables or functions, or contains non-
    expression constructs (assignments, loops, etc.), the function returns None.

    Args:
        formula: A string containing a mathematical expression. This input
            originates from dataset metadata provided by archive users (e.g.,
            a "derived_variable_formula" field in a dataset submission).
        allowed_variables: List of variable names that may appear in the formula.
            These correspond to existing measured variables in the dataset.
        allowed_functions: Optional dictionary mapping function names to
            callables. If omitted, only arithmetic operators are permitted.

    Returns:
        A callable f(vars: dict[str, float]) -> float that evaluates the formula,
        or None if the formula is invalid or uses disallowed constructs.
    """
    if not isinstance(formula, str) or not formula.strip():
        return None

    allowed_vars = set(allowed_variables)
    allowed_funcs = allowed_functions or {}

    # Supported binary operators
    bin_ops = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow,
        ast.Mod: operator.mod,
        ast.FloorDiv: operator.floordiv,
    }

    # Supported unary operators
    unary_ops = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }

    # Supported comparison operators (return bool, but we allow in expressions)
    cmp_ops = {
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
    }

    def validate_node(node: ast.AST) -> bool:
        """Recursively validate that node contains only allowed constructs."""
        if isinstance(node, ast.Expression):
            return validate_node(node.body)

        if isinstance(node, ast.Constant):
            return isinstance(node.value, (int, float))

        if isinstance(node, ast.Name):
            return node.id in allowed_vars

        if isinstance(node, ast.BinOp):
            return (
                type(node.op) in bin_ops
                and validate_node(node.left)
                and validate_node(node.right)
            )

        if isinstance(node, ast.UnaryOp):
            return type(node.op) in unary_ops and validate_node(node.operand)

        if isinstance(node, ast.Compare):
            if not all(type(op) in cmp_ops for op in node.ops):
                return False
            return validate_node(node.left) and all(
                validate_node(comp) for comp in node.comparators
            )

        if isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Name):
                return False
            if node.func.id not in allowed_funcs:
                return False
            if node.keywords:
                return False  # No keyword arguments allowed
            return all(validate_node(arg) for arg in node.args)

        if isinstance(node, ast.BoolOp):
            # Allow and/or for combining comparisons
            return all(validate_node(v) for v in node.values)

        if isinstance(node, ast.IfExp):
            # Ternary conditional: true_val if cond else false_val
            return (
                validate_node(node.test)
                and validate_node(node.body)
                and validate_node(node.orelse)
            )

        # Disallow everything else: Subscript, Attribute, Lambda, List, Dict,
        # Set, Tuple, comprehension, assignments, statements, etc.
        return False

    try:
        tree = ast.parse(formula, mode="eval")
    except SyntaxError:
        return None

    if not validate_node(tree):
        return None

    # Compile the validated AST
    try:
        code = compile(tree, "<derived_formula>", "eval")
    except (SyntaxError, ValueError, TypeError):
        return None

    # Prepare evaluation namespace
    eval_globals = {"__builtins__": {}}
    eval_globals.update(allowed_funcs)

    def evaluator(variables: dict[str, float]) -> float:
        # Validate all provided variables are allowed
        for k in variables:
            if k not in allowed_vars:
                raise ValueError(f"Variable '{k}' not in allowed variables")
        # Evaluate with provided variables as locals
        return eval(code, eval_globals, variables)

    return evaluator
```

