import ast
import operator
from typing import Any


def calculate_custom_metric(formula: str, variables: dict[str, float]) -> float | None:
    """
    Evaluate a user-defined mathematical formula for a custom fitness metric.

    The formula may reference variables provided in the `variables` dictionary,
    which contains trusted sensor data (e.g., heart_rate, distance_km, duration_min,
    calories, elevation_gain_m). The formula supports basic arithmetic: addition,
    subtraction, multiplication, division, exponentiation, and parentheses.

    Args:
        formula: A mathematical expression string provided by the user (e.g.,
            "heart_rate * distance_km / duration_min * 60"). This input comes
            directly from the user via the app's "Custom Metric" configuration screen.
        variables: A dictionary mapping variable names to numeric values. This data
            comes from trusted internal sensors and workout records, not from the user.

    Returns:
        The computed metric as a float, or None if the formula is syntactically
        invalid, references an unknown variable, or would cause a runtime error
        (e.g., division by zero).
    """
    if not isinstance(formula, str) or not formula.strip():
        return None

    try:
        tree = ast.parse(formula, mode='eval')
    except SyntaxError:
        return None

    _ALLOWED_OPERATORS = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow,
        ast.USub: operator.neg,
        ast.UAdd: operator.pos,
    }

    def _eval_node(node: ast.AST) -> float:
        if isinstance(node, ast.Expression):
            return _eval_node(node.body)

        if isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float)):
                return float(node.value)
            raise ValueError("Only numeric constants allowed")

        if isinstance(node, ast.Name):
            if node.id not in variables:
                raise ValueError(f"Unknown variable: {node.id}")
            return float(variables[node.id])

        if isinstance(node, ast.BinOp):
            op_type = type(node.op)
            if op_type not in _ALLOWED_OPERATORS:
                raise ValueError(f"Operator not allowed: {op_type}")
            left = _eval_node(node.left)
            right = _eval_node(node.right)
            return _ALLOWED_OPERATORS[op_type](left, right)

        if isinstance(node, ast.UnaryOp):
            op_type = type(node.op)
            if op_type not in _ALLOWED_OPERATORS:
                raise ValueError(f"Unary operator not allowed: {op_type}")
            operand = _eval_node(node.operand)
            return _ALLOWED_OPERATORS[op_type](operand)

        raise ValueError(f"Node type not allowed: {type(node)}")

    try:
        result = _eval_node(tree)
        if not isinstance(result, (int, float)) or not (float('-inf') < result < float('inf')):
            return None
        return float(result)
    except (ValueError, ZeroDivisionError, OverflowError, RecursionError):
        return None
