import ast
from typing import Any, Dict

_ALLOWED_KEYS = {'text', 'word_count', 'author_id', 'tags', 'created_at', 'metadata'}
_ALLOWED_NAMES = {'item', 'True', 'False', 'None'}
_ALLOWED_NODE_TYPES = {
    ast.Expression, ast.BoolOp, ast.Compare, ast.BinOp, ast.UnaryOp,
    ast.Name, ast.Constant, ast.Subscript, ast.Load,
    ast.Index,
    ast.And, ast.Or, ast.Not, ast.Eq, ast.NotEq, ast.Lt, ast.LtE,
    ast.Gt, ast.GtE, ast.Is, ast.IsNot, ast.In, ast.NotIn,
    ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Mod, ast.Pow,
    ast.USub, ast.UAdd, ast.List, ast.Tuple, ast.Dict, ast.Set,
}

def evaluate_content_rule(rule_expression: str, content_item: Dict[str, Any], rule_name: str) -> bool:
    """
    Evaluate a content moderation rule expression against a content item.

    Args:
        rule_expression: A Python boolean expression string defining the rule
            (e.g., "item['word_count'] > 1000 and 'profanity' not in item['text']").
            This input comes from site administrators via the rule management UI.
        content_item: Dictionary with content data (keys: 'text', 'word_count', 'author_id',
            'tags', 'created_at', 'metadata').
        rule_name: Identifier for the rule (used in logging).

    Returns:
        True if the rule matches (expression evaluates to truthy), False otherwise
        (including on any evaluation error or invalid expression).
    """
    try:
        tree = ast.parse(rule_expression, mode='eval')
    except SyntaxError:
        return False

    for node in ast.walk(tree):
        if type(node) not in _ALLOWED_NODE_TYPES:
            return False
        if isinstance(node, ast.Name) and node.id not in _ALLOWED_NAMES:
            return False
        if isinstance(node, ast.Call):
            return False
        if isinstance(node, ast.Attribute):
            return False
        if isinstance(node, ast.Subscript):
            if not (isinstance(node.value, ast.Name) and node.value.id == 'item'):
                return False
            slice_node = node.slice
            if isinstance(slice_node, ast.Index):
                slice_node = slice_node.value
            if not (isinstance(slice_node, ast.Constant) and isinstance(slice_node.value, str)):
                return False
            if slice_node.value not in _ALLOWED_KEYS:
                return False

    try:
        code = compile(tree, f'<rule:{rule_name}>', 'eval')
        result = eval(code, {'__builtins__': {}}, {'item': content_item})
        return bool(result)
    except Exception:
        return False
