import ast
import operator
from typing import Any


def evaluate_ticket_scoring_expression(
    expression: str,
    ticket: dict[str, Any],
    context: dict[str, Any]
) -> float:
    """
    Evaluate a ticket scoring expression to compute a numeric priority score.

    The expression is a user-provided formula string configured by helpdesk analysts
    to define custom ticket prioritization rules. It has access to ticket fields
    and runtime context variables.

    Supported expression syntax:
    - Arithmetic: +, -, *, /, //, %, **
    - Comparisons: ==, !=, <, <=, >, >=
    - Boolean: and, or, not
    - Parentheses for grouping
    - Attribute access on ticket/context values (e.g., ticket.priority)
    - Subscript access on dict values (e.g., ticket['custom_field'])
    - Function calls: min, max, abs, round, len
    - Ternary conditional: x if cond else y
    - Numeric literals (int, float) and string literals

    Variables available in the expression:
    - All keys from the `ticket` dict (e.g., 'priority', 'age_hours', 'sla_breached')
    - All keys from the `context` dict (e.g., 'business_hours_factor', 'current_time')
    - If a key exists in both, `context` takes precedence.

    Args:
        expression: The scoring formula string provided by the analyst. Empty or
            whitespace-only string returns 0.0.
        ticket: Dictionary of ticket attributes. Typical keys include:
            'priority' (int 1-5), 'age_hours' (float), 'sla_breached' (bool),
            'requester_tier' (str), 'custom_fields' (dict), etc.
        context: Dictionary of runtime context. Typical keys include:
            'business_hours_factor' (float), 'current_time' (float timestamp),
            'queue_weight' (float), etc.

    Returns:
        The computed score as a float. Returns 0.0 if expression is empty,
        invalid, or evaluation fails for any reason (division by zero, missing
        variable, type error, etc.). Never raises an exception.
    """
    if not expression or not expression.strip():
        return 0.0

    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
        ast.USub: operator.neg,
        ast.UAdd: operator.pos,
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
        ast.And: lambda a, b: a and b,
        ast.Or: lambda a, b: a or b,
        ast.Not: operator.not_,
    }

    allowed_functions = {
        'min': min,
        'max': max,
        'abs': abs,
        'round': round,
        'len': len,
    }

    allowed_attributes = {
        'real', 'imag', 'numerator', 'denominator',  # numeric attributes
    }

    def _eval(node: ast.AST, variables: dict[str, Any]) -> Any:
        if isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float, str, bool, type(None))):
                return node.value
            raise ValueError(f"Unsupported constant type: {type(node.value)}")

        if isinstance(node, ast.Name):
            if node.id in variables:
                return variables[node.id]
            raise NameError(f"Undefined variable: {node.id}")

        if isinstance(node, ast.BinOp):
            if type(node.op) not in allowed_operators:
                raise ValueError(f"Unsupported binary operator: {type(node.op).__name__}")
            left = _eval(node.left, variables)
            right = _eval(node.right, variables)
            return allowed_operators[type(node.op)](left, right)

        if isinstance(node, ast.UnaryOp):
            if type(node.op) not in allowed_operators:
                raise ValueError(f"Unsupported unary operator: {type(node.op).__name__}")
            operand = _eval(node.operand, variables)
            return allowed_operators[type(node.op)](operand)

        if isinstance(node, ast.Compare):
            if len(node.ops) != 1 or len(node.comparators) != 1:
                raise ValueError("Chained comparisons not supported")
            if type(node.ops[0]) not in allowed_operators:
                raise ValueError(f"Unsupported comparison: {type(node.ops[0]).__name__}")
            left = _eval(node.left, variables)
            right = _eval(node.comparators[0], variables)
            return allowed_operators[type(node.ops[0])](left, right)

        if isinstance(node, ast.BoolOp):
            if isinstance(node.op, ast.And):
                for value in node.values:
                    if not _eval(value, variables):
                        return False
                return True
            if isinstance(node.op, ast.Or):
                for value in node.values:
                    if _eval(value, variables):
                        return True
                return False
            raise ValueError(f"Unsupported boolean operator: {type(node.op).__name__}")

        if isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.Not):
            return not _eval(node.operand, variables)

        if isinstance(node, ast.IfExp):
            test = _eval(node.test, variables)
            return _eval(node.body, variables) if test else _eval(node.orelse, variables)

        if isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Name):
                raise ValueError("Only direct function calls allowed")
            if node.func.id not in allowed_functions:
                raise ValueError(f"Function not allowed: {node.func.id}")
            if node.keywords:
                raise ValueError("Keyword arguments not supported")
            args = [_eval(arg, variables) for arg in node.args]
            return allowed_functions[node.func.id](*args)

        if isinstance(node, ast.Subscript):
            value = _eval(node.value, variables)
            if isinstance(node.slice, ast.Constant):
                key = node.slice.value
            elif isinstance(node.slice, ast.Index):  # Python <3.9 compat
                key = _eval(node.slice.value, variables)
            else:
                key = _eval(node.slice, variables)
            try:
                return value[key]
            except Exception:
                raise KeyError(f"Subscript failed for key: {key}")

        if isinstance(node, ast.Attribute):
            value = _eval(node.value, variables)
            if node.attr.startswith('_'):
                raise AttributeError(f"Private attribute access denied: {node.attr}")
            if node.attr not in allowed_attributes and not hasattr(type(value), node.attr):
                raise AttributeError(f"Attribute not allowed: {node.attr}")
            return getattr(value, node.attr)

        raise ValueError(f"Unsupported AST node: {type(node).__name__}")

    try:
        tree = ast.parse(expression.strip(), mode='eval')
        merged_vars = {**ticket, **context}
        result = _eval(tree.body, merged_vars)
        return float(result)
    except Exception:
        return 0.0
