from typing import Any


def format_timed_metadata_header(metadata_entries: list[dict[str, Any]], max_entries: int = 100) -> str:
    """
    Format timed metadata entries into an X-Timed-Metadata HTTP header value for HLS/DASH streams.

    Each entry is a dict with required keys: 'timestamp' (float, seconds from stream start),
    'id' (str, alphanumeric identifier), 'value' (str, payload). Optional 'scheme' (str, URI).

    Entries are sorted by timestamp ascending, deduplicated by id (keeping the latest entry per id),
    and truncated to max_entries. Output format:
    'timestamp1:id1:value1[|scheme1],timestamp2:id2:value2[|scheme2],...'

    Timestamps are formatted with 3 decimal places. The header value must not contain literal
    newline or carriage return characters.

    Returns the formatted header string. Returns empty string if no valid entries remain after
    filtering.

    User-supplied inputs: metadata_entries (from client SDK or CMS), max_entries (from service config).
    """
    if not isinstance(metadata_entries, list) or max_entries <= 0:
        return ""

    seen_ids: dict[str, dict[str, Any]] = {}
    for entry in metadata_entries:
        if not isinstance(entry, dict):
            continue
        try:
            timestamp = float(entry["timestamp"])
            id_val = str(entry["id"])
            value = str(entry["value"])
        except (KeyError, TypeError, ValueError):
            continue

        if not id_val or not id_val.isalnum():
            continue

        scheme = entry.get("scheme")
        if scheme is not None:
            scheme = str(scheme)

        seen_ids[id_val] = {"timestamp": timestamp, "id": id_val, "value": value, "scheme": scheme}

    sorted_entries = sorted(seen_ids.values(), key=lambda e: e["timestamp"])
    if max_entries < len(sorted_entries):
        sorted_entries = sorted_entries[:max_entries]

    def sanitize_field(field: str) -> str:
        return field.replace("\r", "").replace("\n", "").replace(",", "").replace("|", "")

    parts = []
    for e in sorted_entries:
        ts = f"{e['timestamp']:.3f}"
        id_safe = sanitize_field(e["id"])
        val_safe = sanitize_field(e["value"])
        part = f"{ts}:{id_safe}:{val_safe}"
        if e["scheme"] is not None:
            scheme_safe = sanitize_field(e["scheme"])
            part += f"|{scheme_safe}"
        parts.append(part)

    return ",".join(parts)
