from typing import Callable
import re

def compile_message_template(template: str, allowed_placeholders: set[str]) -> Callable[[dict], str] | None:
    """
    Compile a user-provided message template into a rendering function for chat theming.

    The template language supports:
    - Placeholders: {placeholder_name} where placeholder_name must be in allowed_placeholders
    - Conditional blocks: {?placeholder_name}content{/?placeholder_name} rendered only if the
      placeholder's value is truthy (non-empty string, non-zero number, non-empty list, etc.)
    - Literal braces: {{ and }} produce literal { and } characters in output
    - All other characters are treated as literal text

    Args:
        template: User-provided template string (comes from user input via chat theme settings).
        allowed_placeholders: Set of placeholder names that are permitted in the template.
            Typically includes values like 'username', 'message', 'timestamp', 'channel', 'user_id'.

    Returns:
        A callable that accepts a dict mapping placeholder names to values and returns the
        formatted string, or None if the template is invalid (contains disallowed placeholders,
        unmatched conditional blocks, malformed syntax, or placeholders not in allowed_placeholders).
        The returned callable never raises; missing placeholders in the data dict render as empty string.
    """
    # Validate template syntax and extract structure without code execution
    # Token types: ('literal', text), ('placeholder', name), ('cond_start', name), ('cond_end', name)
    tokens = []
    i = 0
    cond_stack = []

    while i < len(template):
        if template[i] == '{':
            if i + 1 < len(template) and template[i + 1] == '{':
                # Literal open brace
                tokens.append(('literal', '{'))
                i += 2
            elif i + 1 < len(template) and template[i + 1] == '?':
                # Conditional start: {?name}
                j = template.find('}', i + 2)
                if j == -1:
                    return None  # Unclosed conditional start
                name = template[i + 2:j]
                if not name or not re.fullmatch(r'[a-zA-Z_][a-zA-Z0-9_]*', name):
                    return None  # Invalid placeholder name
                if name not in allowed_placeholders:
                    return None  # Disallowed placeholder
                tokens.append(('cond_start', name))
                cond_stack.append(name)
                i = j + 1
            elif i + 2 < len(template) and template[i + 1] == '/' and template[i + 2] == '?':
                # Conditional end: {/?name}
                j = template.find('}', i + 3)
                if j == -1:
                    return None  # Unclosed conditional end
                name = template[i + 3:j]
                if not cond_stack or cond_stack[-1] != name:
                    return None  # Mismatched conditional end
                cond_stack.pop()
                tokens.append(('cond_end', name))
                i = j + 1
            else:
                # Regular placeholder: {name}
                j = template.find('}', i + 1)
                if j == -1:
                    return None  # Unclosed placeholder
                name = template[i + 1:j]
                if not name or not re.fullmatch(r'[a-zA-Z_][a-zA-Z0-9_]*', name):
                    return None  # Invalid placeholder name
                if name not in allowed_placeholders:
                    return None  # Disallowed placeholder
                tokens.append(('placeholder', name))
                i = j + 1
        elif template[i] == '}':
            if i + 1 < len(template) and template[i + 1] == '}':
                # Literal close brace
                tokens.append(('literal', '}'))
                i += 2
            else:
                return None  # Stray closing brace
        else:
            # Literal text - collect until next brace
            j = i
            while j < len(template) and template[j] != '{' and template[j] != '}':
                j += 1
            tokens.append(('literal', template[i:j]))
            i = j

    if cond_stack:
        return None  # Unclosed conditional blocks

    # Build a safe renderer function from validated tokens
    def render(data: dict) -> str:
        result = []
        cond_stack_render = []  # Stack of (name, is_truthy) for nested conditionals

        for token_type, value in tokens:
            if token_type == 'literal':
                # Only output literals if we're not inside a false conditional
                if not any(not truthy for _, truthy in cond_stack_render):
                    result.append(value)
            elif token_type == 'placeholder':
                if not any(not truthy for _, truthy in cond_stack_render):
                    val = data.get(value, '')
                    result.append(str(val) if val is not None else '')
            elif token_type == 'cond_start':
                truthy = bool(data.get(value, ''))
                cond_stack_render.append((value, truthy))
            elif token_type == 'cond_end':
                if cond_stack_render and cond_stack_render[-1][0] == value:
                    cond_stack_render.pop()

        return ''.join(result)

    return render
