import ast
import operator
from typing import Callable


class _FormulaValidator(ast.NodeVisitor):
    """Validates that an AST contains only allowed constructs for workout formulas."""

    _BINOPS = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
    }
    _UNOPS = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }
    _CMPOPS = {
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
    }
    _BOOL_OPS = (ast.And, ast.Or)

    def __init__(self, allowed_variables: set[str]) -> None:
        self.allowed_variables = allowed_variables
        self.errors: list[str] = []

    def visit(self, node: ast.AST) -> None:
        if isinstance(node, ast.Constant):
            if not isinstance(node.value, (int, float)):
                self.errors.append(f"Only numeric constants allowed, got {type(node.value).__name__}")
        elif isinstance(node, ast.Name):
            if node.id not in self.allowed_variables:
                self.errors.append(f"Variable '{node.id}' is not allowed")
        elif isinstance(node, ast.BinOp):
            if type(node.op) not in self._BINOPS:
                self.errors.append(f"Binary operator {type(node.op).__name__} not allowed")
            self.visit(node.left)
            self.visit(node.right)
        elif isinstance(node, ast.UnaryOp):
            if type(node.op) not in self._UNOPS:
                self.errors.append(f"Unary operator {type(node.op).__name__} not allowed")
            self.visit(node.operand)
        elif isinstance(node, ast.Compare):
            for op in node.ops:
                if type(op) not in self._CMPOPS:
                    self.errors.append(f"Comparison operator {type(op).__name__} not allowed")
            self.visit(node.left)
            for comparator in node.comparators:
                self.visit(comparator)
        elif isinstance(node, ast.BoolOp):
            if type(node.op) not in self._BOOL_OPS:
                self.errors.append(f"Boolean operator {type(node.op).__name__} not allowed")
            for value in node.values:
                self.visit(value)
        elif isinstance(node, ast.IfExp):
            self.visit(node.test)
            self.visit(node.body)
            self.visit(node.orelse)
        elif isinstance(node, ast.Expression):
            self.visit(node.body)
        else:
            self.errors.append(f"AST node type {type(node).__name__} not allowed")


class _FormulaEvaluator(ast.NodeVisitor):
    """Evaluates a validated AST against a variable mapping."""

    _BINOPS = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.Pow: operator.pow,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
    }
    _UNOPS = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }
    _CMPOPS = {
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
    }

    def __init__(self, variables: dict[str, float]) -> None:
        self.variables = variables

    def visit(self, node: ast.AST) -> float | bool:
        if isinstance(node, ast.Constant):
            return node.value
        elif isinstance(node, ast.Name):
            return self.variables[node.id]
        elif isinstance(node, ast.BinOp):
            left = self.visit(node.left)
            right = self.visit(node.right)
            return self._BINOPS[type(node.op)](left, right)
        elif isinstance(node, ast.UnaryOp):
            operand = self.visit(node.operand)
            return self._UNOPS[type(node.op)](operand)
        elif isinstance(node, ast.Compare):
            left = self.visit(node.left)
            for op, comparator in zip(node.ops, node.comparators):
                right = self.visit(comparator)
                if not self._CMPOPS[type(op)](left, right):
                    return False
                left = right
            return True
        elif isinstance(node, ast.BoolOp):
            values = [self.visit(v) for v in node.values]
            if isinstance(node.op, ast.And):
                return all(values)
            return any(values)
        elif isinstance(node, ast.IfExp):
            return self.visit(node.body) if self.visit(node.test) else self.visit(node.orelse)
        elif isinstance(node, ast.Expression):
            return self.visit(node.body)
        raise ValueError(f"Unexpected node type: {type(node).__name__}")


def compile_workout_metric_formula(formula: str, allowed_variables: list[str]) -> Callable[[dict], float]:
    """
    Compile a user-defined workout metric formula into a callable function.

    This function takes a mathematical formula string provided by the user (e.g., from a
    fitness tracker's "custom metric" configuration screen) and returns a function that
    evaluates the formula against a dictionary of real-time workout variables.

    The formula may reference variables from `allowed_variables` (e.g., "heart_rate",
    "speed", "cadence", "power", "elevation"). Only basic arithmetic operations (+, -, *, /,
    **, //, %) and parentheses are supported. Comparison operators (>, <, >=, <=, ==, !=)
    and boolean operators (and, or, not) are also supported for conditional expressions
    using the ternary form: `value_if_true if condition else value_if_false`.

    Args:
        formula: A string containing the mathematical/formula expression. This input comes
            directly from the user via the fitness tracker's custom metric editor.
        allowed_variables: A list of variable names that the formula is permitted to
            reference. This is defined by the application based on available sensor data.

    Returns:
        A callable that accepts a single dict argument mapping variable names to numeric
        values, and returns the computed metric as a float. If the formula is invalid,
        contains disallowed constructs, or references variables not in `allowed_variables`,
        returns a function that always returns 0.0.

    Example:
        >>> fn = compile_workout_metric_formula("heart_rate * 0.6 + speed * 2.5", ["heart_rate", "speed"])
        >>> fn({"heart_rate": 150, "speed": 12.5})
        121.25
    """
    allowed_set = set(allowed_variables)

    try:
        tree = ast.parse(formula, mode="eval")
    except SyntaxError:
        return lambda _: 0.0

    validator = _FormulaValidator(allowed_set)
    validator.visit(tree)
    if validator.errors:
        return lambda _: 0.0

    def evaluator(variables: dict) -> float:
        try:
            # Ensure all required variables are present and numeric
            for var in allowed_set:
                if var not in variables:
                    return 0.0
                if not isinstance(variables[var], (int, float)):
                    return 0.0
            eval_visitor = _FormulaEvaluator(variables)
            result = eval_visitor.visit(tree)
            return float(result)
        except (KeyError, TypeError, ValueError, ZeroDivisionError, OverflowError):
            return 0.0

    return evaluator
