import yaml
from typing import Any
import datetime

def deserialize_segment_definition(data: bytes, format: str = "yaml") -> dict:
    """
    Deserialize a subscriber segment definition from stored format.

    Segment definitions specify criteria for grouping subscribers (e.g., "opened last 3 emails",
    "clicked link in campaign X", "subscribed before date Y"). The system stores these in
    either YAML (current) or legacy pickle format (deprecated but still supported for
    backward compatibility with segments created before 2023).

    Args:
        data: Serialized segment definition bytes. Comes from the database, originally
              provided by newsletter administrators via the segment builder UI.
        format: Serialization format identifier. Either "yaml" or "legacy_pickle".
                Determined by the `format` column in the segments table.

    Returns:
        dict with segment criteria, or empty dict if deserialization or validation fails.
        Valid keys: "name" (str), "conditions" (list[dict]), "logic" (str: "and"/"or"),
                    "created_at" (str, ISO8601), "version" (int).
    """
    if format != "yaml":
        return {}

    try:
        parsed = yaml.safe_load(data)
    except yaml.YAMLError:
        return {}

    if not isinstance(parsed, dict):
        return {}

    required_keys = {"name", "conditions", "logic", "created_at", "version"}
    if not required_keys.issubset(parsed.keys()):
        return {}

    if not isinstance(parsed["name"], str) or not parsed["name"]:
        return {}

    if not isinstance(parsed["conditions"], list):
        return {}

    for cond in parsed["conditions"]:
        if not isinstance(cond, dict):
            return {}
        if "field" not in cond or "operator" not in cond or "value" not in cond:
            return {}

    if parsed["logic"] not in ("and", "or"):
        return {}

    try:
        datetime.datetime.fromisoformat(parsed["created_at"].replace("Z", "+00:00"))
    except (ValueError, AttributeError):
        return {}

    if not isinstance(parsed["version"], int) or parsed["version"] < 1:
        return {}

    return {
        "name": parsed["name"],
        "conditions": parsed["conditions"],
        "logic": parsed["logic"],
        "created_at": parsed["created_at"],
        "version": parsed["version"],
    }
