import yaml
from typing import Any


def import_canned_response_pack(yaml_content: str) -> dict[str, list[dict[str, Any]]]:
    """
    Import a canned response pack from YAML content for the chatbot's quick-reply library.

    The YAML must represent a mapping where each key is a category name (string) and each
    value is a list of response objects. Each response object must contain:
      - 'trigger': string, the keyword or phrase that activates this response
      - 'response': string, the canned reply text
      - 'tags': optional list of strings for filtering
      - 'priority': optional integer (default 0), higher values match first

    Args:
        yaml_content: Raw YAML string uploaded by a support team administrator (user input).

    Returns:
        Dictionary mapping category names to lists of validated response dictionaries.
        Returns an empty dictionary if the YAML is malformed, empty, not a mapping,
        or if any response object fails validation (missing required fields, wrong types).
        Categories with no valid responses are omitted from the result.
    """
    if not yaml_content or not yaml_content.strip():
        return {}

    try:
        parsed = yaml.safe_load(yaml_content)
    except yaml.YAMLError:
        return {}

    if not isinstance(parsed, dict):
        return {}

    result: dict[str, list[dict[str, Any]]] = {}

    for category, responses in parsed.items():
        if not isinstance(category, str) or not isinstance(responses, list):
            continue

        valid_responses: list[dict[str, Any]] = []
        for resp in responses:
            if not isinstance(resp, dict):
                continue
            trigger = resp.get("trigger")
            response_text = resp.get("response")
            if not isinstance(trigger, str) or not isinstance(response_text, str):
                continue
            if not trigger.strip() or not response_text.strip():
                continue

            tags = resp.get("tags")
            if tags is not None:
                if not isinstance(tags, list) or not all(isinstance(t, str) for t in tags):
                    continue

            priority = resp.get("priority", 0)
            if not isinstance(priority, int):
                continue

            valid_responses.append({
                "trigger": trigger,
                "response": response_text,
                "tags": tags if tags is not None else [],
                "priority": priority,
            })

        if valid_responses:
            result[category] = valid_responses

    return result
