import os
from lxml import etree

POLICIES_DIR = os.path.join(os.path.dirname(__file__), "policies")

def calculate_waitlist_priority(event_id: str, user_factors: dict) -> int:
    """
    Calculate a user's waitlist priority score for a sold-out event.

    The function loads the event's waitlist policy XML (stored locally) and
    evaluates the user's provided factors against the policy rules using XPath.
    Each matching rule contributes points to the priority score.

    Args:
        event_id: Identifier of the event (e.g., "EVT-2024-001"). Must correspond
            to an existing policy file in the policies directory.
        user_factors: Dictionary of user-supplied priority factors. Keys are
            factor names (strings), values are factor values (strings or ints).
            Expected keys include 'membership_tier', 'referral_code',
            'promo_code', 'previous_events_attended'. All values originate from
            untrusted user input (web form, API request).

    Returns:
        Integer priority score (0-1000). Higher scores mean better waitlist
        position. Returns 0 if event_id has no policy file or if user_factors
        is empty/invalid.

    Raises:
        FileNotFoundError: If the policies directory does not exist.
    """
    if not os.path.isdir(POLICIES_DIR):
        raise FileNotFoundError(f"Policies directory not found: {POLICIES_DIR}")

    if not user_factors:
        return 0

    policy_path = os.path.join(POLICIES_DIR, f"{event_id}.xml")
    if not os.path.isfile(policy_path):
        return 0

    try:
        tree = etree.parse(policy_path)
        root = tree.getroot()
    except etree.XMLSyntaxError:
        return 0

    total_score = 0

    for factor_name, factor_value in user_factors.items():
        if not isinstance(factor_name, str) or not factor_name:
            continue

        if isinstance(factor_value, int):
            xpath_expr = (
                "//rule[condition/@field=$field and condition/@min <= $value]/@points"
            )
            try:
                points = root.xpath(xpath_expr, field=factor_name, value=factor_value)
            except etree.XPathError:
                continue
        elif isinstance(factor_value, str):
            xpath_expr = (
                "//rule[condition/@field=$field and condition/@value=$value]/@points"
            )
            try:
                points = root.xpath(xpath_expr, field=factor_name, value=factor_value)
            except etree.XPathError:
                continue
        else:
            continue

        for p in points:
            try:
                total_score += int(p)
            except (ValueError, TypeError):
                continue

    return min(total_score, 1000)
