import yaml
from typing import Any


def parse_interval_workout(yaml_content: str) -> dict:
    """
    Parse a user-provided YAML string defining an interval training workout.

    The YAML must contain a 'workout' key with a dict containing:
    - 'name': str, workout name (1-100 chars)
    - 'intervals': list of interval dicts, each with:
        - 'type': str, one of 'work', 'recovery', 'warmup', 'cooldown'
        - 'duration_seconds': int > 0
        - 'target_zone': optional int 1-5 (heart rate zone)
        - 'repeat': optional int >= 1 (default 1)
    - 'metadata': optional dict with arbitrary user-defined fields (string keys, JSON-serializable values)

    Args:
        yaml_content: Raw YAML string provided by the user (e.g., from file upload or paste)

    Returns:
        Dict with parsed workout structure, or empty dict if parsing fails or structure is invalid.
        The returned dict has keys: 'name' (str), 'intervals' (list of normalized interval dicts
        with all optional fields filled), 'total_duration_seconds' (int), 'metadata' (dict).

    User-controlled input: yaml_content (entire string)
    """
    if not isinstance(yaml_content, str) or not yaml_content.strip():
        return {}

    try:
        data = yaml.safe_load(yaml_content)
    except yaml.YAMLError:
        return {}

    if not isinstance(data, dict) or "workout" not in data:
        return {}

    workout = data["workout"]
    if not isinstance(workout, dict):
        return {}

    name = workout.get("name")
    if not isinstance(name, str) or not (1 <= len(name) <= 100):
        return {}

    intervals_raw = workout.get("intervals")
    if not isinstance(intervals_raw, list):
        return {}

    valid_types = {"work", "recovery", "warmup", "cooldown"}
    intervals = []
    total_duration = 0

    for idx, interval in enumerate(intervals_raw):
        if not isinstance(interval, dict):
            return {}

        itype = interval.get("type")
        if itype not in valid_types:
            return {}

        duration = interval.get("duration_seconds")
        if not isinstance(duration, int) or duration <= 0:
            return {}

        target_zone = interval.get("target_zone")
        if target_zone is not None:
            if not isinstance(target_zone, int) or not (1 <= target_zone <= 5):
                return {}

        repeat = interval.get("repeat", 1)
        if not isinstance(repeat, int) or repeat < 1:
            return {}

        normalized = {
            "type": itype,
            "duration_seconds": duration,
            "target_zone": target_zone,
            "repeat": repeat,
        }
        intervals.append(normalized)
        total_duration += duration * repeat

    metadata = workout.get("metadata", {})
    if not isinstance(metadata, dict):
        return {}
    for k, v in metadata.items():
        if not isinstance(k, str):
            return {}
        try:
            yaml.safe_dump(v)
        except yaml.YAMLError:
            return {}

    return {
        "name": name,
        "intervals": intervals,
        "total_duration_seconds": total_duration,
        "metadata": metadata,
    }
