import yaml
from typing import Any


def parse_tournament_bracket_config(yaml_content: str) -> dict[str, Any] | None:
    """
    Parse a tournament bracket configuration from YAML for the game server admin panel.

    The configuration defines bracket structure, scoring rules, tiebreaker criteria,
    and initial team seeding. Admins upload this via the web panel when creating
    a new tournament.

    Expected YAML structure:
        bracket_type: "single_elimination" | "double_elimination" | "round_robin"
        team_count: int (4-64, must be power of 2 for elimination brackets)
        scoring:
            win_points: int (>= 0)
            draw_points: int (>= 0)
            loss_points: int (>= 0)
        tiebreakers: list[str]  # ordered list from: "head_to_head", "point_differential",
                                # "total_wins", "seed", "coin_flip"
        seeds: dict[str, int]  # team_name -> seed_number (1..team_count, unique)

    Args:
        yaml_content: Raw YAML string uploaded by server admin via admin panel.

    Returns:
        Parsed configuration dict with validated fields, or None if the YAML is
        malformed, missing required keys, or fails validation rules.

    User-controlled input: yaml_content (entire string comes from admin upload).
    """
    try:
        data = yaml.safe_load(yaml_content)
    except yaml.YAMLError:
        return None

    if not isinstance(data, dict):
        return None

    required_keys = {"bracket_type", "team_count", "scoring", "tiebreakers", "seeds"}
    if not required_keys.issubset(data.keys()):
        return None

    valid_bracket_types = {"single_elimination", "double_elimination", "round_robin"}
    bracket_type = data["bracket_type"]
    if bracket_type not in valid_bracket_types:
        return None

    team_count = data["team_count"]
    if not isinstance(team_count, int) or team_count < 4 or team_count > 64:
        return None
    if bracket_type in {"single_elimination", "double_elimination"}:
        if team_count & (team_count - 1) != 0:
            return None

    scoring = data["scoring"]
    if not isinstance(scoring, dict):
        return None
    scoring_keys = {"win_points", "draw_points", "loss_points"}
    if not scoring_keys.issubset(scoring.keys()):
        return None
    for key in scoring_keys:
        val = scoring[key]
        if not isinstance(val, int) or val < 0:
            return None

    valid_tiebreakers = {"head_to_head", "point_differential", "total_wins", "seed", "coin_flip"}
    tiebreakers = data["tiebreakers"]
    if not isinstance(tiebreakers, list) or not tiebreakers:
        return None
    for tb in tiebreakers:
        if not isinstance(tb, str) or tb not in valid_tiebreakers:
            return None
    if len(tiebreakers) != len(set(tiebreakers)):
        return None

    seeds = data["seeds"]
    if not isinstance(seeds, dict):
        return None
    if len(seeds) != team_count:
        return None
    seen_seeds = set()
    for team_name, seed in seeds.items():
        if not isinstance(team_name, str) or not team_name:
            return None
        if not isinstance(seed, int) or seed < 1 or seed > team_count:
            return None
        if seed in seen_seeds:
            return None
        seen_seeds.add(seed)

    return {
        "bracket_type": bracket_type,
        "team_count": team_count,
        "scoring": {
            "win_points": scoring["win_points"],
            "draw_points": scoring["draw_points"],
            "loss_points": scoring["loss_points"],
        },
        "tiebreakers": tiebreakers,
        "seeds": dict(seeds),
    }
