import lxml.etree
from typing import Dict, List, Any


def parse_alert_routing_policy(xml_content: str) -> Dict[str, Any]:
    """
    Parse an alert routing policy from XML content.

    The policy defines how alerts are routed to notification channels based on
    severity, label selectors, and time windows. The function extracts routing
    rules and default channels for the alerting engine.

    Args:
        xml_content: XML string containing the routing policy definition.
            This input comes from users (e.g., uploaded via API or UI).

    Returns:
        Dictionary with keys:
        - 'rules': list of rule dicts, each with 'name' (str), 'severity' (str or None),
          'label_selector' (str or None), 'time_window' (str or None), 'channels' (list of str)
        - 'default_channels': list of channel name strings
        - 'timezone': timezone string (e.g., 'UTC', 'America/New_York')
        Returns empty dict on any parsing error or if root element is not 'routing_policy'.
    """
    if not xml_content or not xml_content.strip():
        return {}

    # Reject any XML containing a DOCTYPE declaration (defense against XXE)
    if '<!DOCTYPE' in xml_content.upper():
        return {}

    try:
        parser = lxml.etree.XMLParser(
            resolve_entities=False,
            no_network=True,
            load_dtd=False,
            remove_blank_text=True
        )
        root = lxml.etree.fromstring(xml_content.encode('utf-8'), parser=parser)
    except (lxml.etree.XMLSyntaxError, ValueError, UnicodeError):
        return {}

    if root.tag != 'routing_policy':
        return {}

    result: Dict[str, Any] = {
        'rules': [],
        'default_channels': [],
        'timezone': root.get('timezone', 'UTC')
    }

    default_channels_elem = root.find('default_channels')
    if default_channels_elem is not None:
        for ch in default_channels_elem.findall('channel'):
            if ch.text and ch.text.strip():
                result['default_channels'].append(ch.text.strip())

    rules_elem = root.find('rules')
    if rules_elem is not None:
        for rule_elem in rules_elem.findall('rule'):
            name = rule_elem.get('name')
            if not name or not name.strip():
                continue

            channels_attr = rule_elem.get('channels', '')
            channels = [c.strip() for c in channels_attr.split(',') if c.strip()]

            rule = {
                'name': name.strip(),
                'severity': rule_elem.get('severity') or None,
                'label_selector': rule_elem.get('label_selector') or None,
                'time_window': rule_elem.get('time_window') or None,
                'channels': channels
            }
            result['rules'].append(rule)

    return result
