import ast
import operator
import math
from typing import Any


def evaluate_grade_adjustment_formula(formula: str, student_context: dict[str, float]) -> float | None:
    """
    Evaluate a teacher-defined grade adjustment formula using student-specific context values.

    This function computes adjusted grades for students with extenuating circumstances
    (medical leave, athletic travel, family emergencies) by applying a configurable
    arithmetic formula provided by the course instructor.

    The formula is a mathematical expression that may reference variables from the
    student_context dictionary. Supported operations: +, -, *, /, //, %, **, unary +/-,
    parentheses, and numeric literals. Variable names must be valid Python identifiers.

    Args:
        formula: A mathematical expression string defined by the teacher (e.g.,
            "base_score * 0.9 + participation_bonus" or "(homework_avg * 0.4) + (exam_avg * 0.6)").
            This comes from the course configuration set by instructors.
        student_context: A mapping of variable names to numeric values for a specific student.
            Keys include 'base_score', 'homework_avg', 'exam_avg', 'participation_bonus',
            'attendance_rate', 'days_absent', 'medical_days', 'travel_days'. Values originate
            from student records, self-reported absence forms, and automated attendance systems.

    Returns:
        The computed adjustment factor as a float (e.g., 0.95 for a 5% reduction, 1.0 for no change),
        or None if the formula is syntactically invalid, references undefined variables,
        contains disallowed constructs, or evaluation produces a non-finite result.

    The function never raises exceptions; all error conditions return None.
    """
    if not isinstance(formula, str) or not formula.strip():
        return None
    if not isinstance(student_context, dict):
        return None

    try:
        tree = ast.parse(formula.strip(), mode='eval')
    except SyntaxError:
        return None

    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
    }

    allowed_nodes = (
        ast.Expression, ast.BinOp, ast.UnaryOp, ast.Constant, ast.Name,
        ast.Load, *allowed_operators.keys()
    )

    for node in ast.walk(tree):
        if not isinstance(node, allowed_nodes):
            return None
        if isinstance(node, ast.Name):
            if node.id not in student_context:
                return None
            if not isinstance(student_context[node.id], (int, float)):
                return None
        if isinstance(node, ast.Constant):
            if not isinstance(node.value, (int, float)):
                return None
        if isinstance(node, ast.BinOp):
            if type(node.op) not in allowed_operators:
                return None
        if isinstance(node, ast.UnaryOp):
            if type(node.op) not in allowed_operators:
                return None

    def eval_node(node: ast.AST) -> float:
        if isinstance(node, ast.Expression):
            return eval_node(node.body)
        if isinstance(node, ast.Constant):
            return float(node.value)
        if isinstance(node, ast.Name):
            return float(student_context[node.id])
        if isinstance(node, ast.BinOp):
            left = eval_node(node.left)
            right = eval_node(node.right)
            op_func = allowed_operators[type(node.op)]
            try:
                result = op_func(left, right)
            except (ZeroDivisionError, OverflowError, ValueError):
                return float('nan')
            return float(result)
        if isinstance(node, ast.UnaryOp):
            operand = eval_node(node.operand)
            op_func = allowed_operators[type(node.op)]
            try:
                result = op_func(operand)
            except (OverflowError, ValueError):
                return float('nan')
            return float(result)
        return float('nan')

    try:
        result = eval_node(tree)
    except (RecursionError, MemoryError):
        return None

    if not math.isfinite(result):
        return None

    return result
