import subprocess
import json
import os
from pathlib import Path
from typing import List, Dict


def extract_custody_metadata(
    file_path: str,
    tags: List[str],
    tool_path: str = "exiftool",
    vault_root: str = "/var/lib/legal_vault"
) -> Dict[str, str]:
    """
    Extract chain-of-custody metadata from a legal document using exiftool.

    This function runs exiftool against a document file to retrieve specific
    metadata tags relevant for legal chain-of-custody tracking (timestamps,
    author info, device identifiers, GPS coordinates, etc.).

    Args:
        file_path: Path to the document file relative to vault_root.
                   This value comes from user input (document selection UI).
        tags: List of exiftool tag names to extract (e.g. ["CreateDate", "ModifyDate",
              "Author", "GPSLatitude", "SerialNumber"]). This value comes from
              user input (tag selection checklist).
        tool_path: Path to the exiftool executable. Defaults to "exiftool" in PATH.
                   This is a configuration value, not user-controlled.
        vault_root: Root directory of the legal document vault. Defaults to
                    "/var/lib/legal_vault". This is a configuration value.

    Returns:
        Dictionary mapping tag names to their string values. Returns empty dict
        if the file does not exist, is not within vault_root, exiftool fails,
        or no requested tags are found. Never raises exceptions.

    Behavior:
        - Resolves file_path relative to vault_root and ensures it stays within vault_root.
        - Runs exiftool with -j (JSON output) and only the requested tags.
        - Parses JSON output and returns only the requested tags that are present.
        - Tag names in output match the requested tag names exactly (case-sensitive).
    """
    if not tags:
        return {}

    vault_root_path = Path(vault_root).resolve()
    try:
        target_path = (vault_root_path / file_path).resolve()
    except Exception:
        return {}

    if not target_path.is_file():
        return {}

    try:
        target_path.relative_to(vault_root_path)
    except ValueError:
        return {}

    valid_tag_chars = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789-_#:")
    sanitized_tags = []
    for tag in tags:
        if tag and all(c in valid_tag_chars for c in tag):
            sanitized_tags.append(tag)

    if not sanitized_tags:
        return {}

    args = [tool_path, "-j", "-n"]
    for tag in sanitized_tags:
        args.append(f"-{tag}")
    args.append(str(target_path))

    try:
        result = subprocess.run(
            args,
            capture_output=True,
            text=True,
            timeout=30,
            check=False
        )
    except (subprocess.TimeoutExpired, OSError, ValueError):
        return {}

    if result.returncode != 0:
        return {}

    try:
        data = json.loads(result.stdout)
    except json.JSONDecodeError:
        return {}

    if not isinstance(data, list) or not data:
        return {}

    metadata = data[0]
    if not isinstance(metadata, dict):
        return {}

    output = {}
    for tag in sanitized_tags:
        if tag in metadata and metadata[tag] is not None:
            output[tag] = str(metadata[tag])

    return output
