import yaml
from typing import Dict, List, Any


def parse_eir_damage_codes(yaml_content: str) -> Dict[str, List[str]]:
    """
    Parse carrier-specific Equipment Interchange Receipt (EIR) damage code mappings
    from a legacy YAML format used by terminal operating systems.

    Args:
        yaml_content: Raw YAML string provided by the carrier's legacy TOS (Terminal
                      Operating System). Contains mappings from ISO 9897 standard
                      damage location/type codes to carrier-specific alphanumeric
                      codes. Expected format:
                          DAMAGE_CODE_MAP:
                            "1A": ["CNT-DMG-001", "CNT-DMG-002"]
                            "2B": ["CHS-SCR-010"]
                      The top-level key must be "DAMAGE_CODE_MAP". This input
                      originates from carrier-uploaded files (user-controlled).

    Returns:
        Dictionary mapping standard ISO 9897 codes (str) to lists of carrier-
        specific codes (list[str]). Returns empty dict if the YAML is malformed,
        missing the required top-level key, or contains non-string values.

    Note:
        The function does not raise exceptions; all error conditions yield an
        empty dictionary.
    """
    if not yaml_content or not isinstance(yaml_content, str):
        return {}

    try:
        # Use safe_load to prevent arbitrary object deserialization
        parsed = yaml.safe_load(yaml_content)
    except yaml.YAMLError:
        return {}

    if not isinstance(parsed, dict):
        return {}

    damage_map = parsed.get("DAMAGE_CODE_MAP")
    if not isinstance(damage_map, dict):
        return {}

    result: Dict[str, List[str]] = {}
    for std_code, carrier_codes in damage_map.items():
        if not isinstance(std_code, str):
            continue
        if not isinstance(carrier_codes, list):
            continue
        # Validate all carrier codes are strings
        valid_codes = [code for code in carrier_codes if isinstance(code, str)]
        if valid_codes:
            result[std_code] = valid_codes

    return result
