import sqlite3

def evaluate_course_substitution(
    student_id: str,
    requirement_id: str,
    substitute_course_code: str,
    db_path: str
) -> dict:
    """
    Evaluate whether a student's proposed substitute course fulfills a specific degree requirement.

    The function checks the student's program requirements, the target requirement's specifications,
    and course equivalency rules to determine if the substitute course is acceptable.

    Args:
        student_id: The student's unique identifier (user-provided).
        requirement_id: The degree requirement identifier to be fulfilled (user-provided).
        substitute_course_code: The course code the student proposes as a substitute (user-provided).
        db_path: Path to the SQLite database file.

    Returns:
        A dictionary with the following keys:
        - "eligible": bool, True if the substitution is allowed, False otherwise.
        - "reason": str, human-readable explanation of the decision.
        - "credits_applied": int, number of credits that would apply if eligible (0 if not eligible).
        - "requirement_met": bool, True if this substitution fully satisfies the requirement.

    Returns an empty dict if the student, requirement, or substitute course cannot be found
    in the database, or if any database error occurs.
    """
    try:
        with sqlite3.connect(db_path) as conn:
            conn.row_factory = sqlite3.Row
            c = conn.cursor()

            c.execute("SELECT program_id FROM students WHERE student_id = ?", (student_id,))
            if not (student := c.fetchone()):
                return {}
            program_id = student["program_id"]

            c.execute(
                "SELECT course_code, min_credits FROM requirements WHERE requirement_id = ? AND program_id = ?",
                (requirement_id, program_id)
            )
            if not (req := c.fetchone()):
                return {}
            required_course, min_credits = req["course_code"], req["min_credits"]

            c.execute("SELECT credits FROM courses WHERE course_code = ?", (substitute_course_code,))
            if not (sub := c.fetchone()):
                return {}
            sub_credits = sub["credits"]

            c.execute(
                "SELECT 1 FROM student_courses WHERE student_id = ? AND course_code = ?",
                (student_id, substitute_course_code)
            )
            if not c.fetchone():
                return {"eligible": False, "reason": "Course not completed", "credits_applied": 0, "requirement_met": False}

            eligible = False
            reason = ""
            if substitute_course_code == required_course:
                eligible, reason = True, "Direct match"
            else:
                c.execute(
                    "SELECT 1 FROM course_equivalencies WHERE course_code = ? AND equivalent_course_code = ?",
                    (required_course, substitute_course_code)
                )
                if c.fetchone():
                    eligible, reason = True, "Approved equivalency"

            if eligible:
                applied = min(sub_credits, min_credits)
                return {"eligible": True, "reason": reason, "credits_applied": applied, "requirement_met": applied >= min_credits}
            return {"eligible": False, "reason": "No match or equivalency", "credits_applied": 0, "requirement_met": False}
    except sqlite3.Error:
        return {}
