```python
import ast
import operator
from typing import Any, Dict, Set

# Allowed AST node types for safe evaluation
_ALLOWED_NODE_TYPES: Set[type] = {
    ast.Expression, ast.BoolOp, ast.UnaryOp, ast.Compare,
    ast.Name, ast.Constant, ast.Attribute, ast.Subscript,
    ast.List, ast.Tuple, ast.Set, ast.Dict,
    ast.Call, ast.Load, ast.And, ast.Or, ast.Not,
    ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE,
    ast.In, ast.NotIn, ast.Is, ast.IsNot,
    ast.Index, ast.Slice,
}

# Allowed built-in functions and methods
_ALLOWED_FUNCTIONS: Set[str] = {
    'len', 'str', 'int', 'float', 'bool',
    'startswith', 'endswith', 'contains', 'lower', 'upper',
}

# Allowed method names on string objects
_ALLOWED_STR_METHODS: Set[str] = {
    'startswith', 'endswith', 'lower', 'upper', 'strip',
    'split', 'replace', 'find', 'index', 'count',
}

# Allowed method names on list objects
_ALLOWED_LIST_METHODS: Set[str] = {
    'count', 'index',
}

# Operator mappings for evaluation
_BIN_OPS = {
    ast.And: operator.and_,
    ast.Or: operator.or_,
    ast.Add: operator.add,
    ast.Sub: operator.sub,
    ast.Mult: operator.mul,
    ast.Div: operator.truediv,
}

_CMP_OPS = {
    ast.Eq: operator.eq,
    ast.NotEq: operator.ne,
    ast.Lt: operator.lt,
    ast.LtE: operator.le,
    ast.Gt: operator.gt,
    ast.GtE: operator.ge,
    ast.In: lambda a, b: a in b,
    ast.NotIn: lambda a, b: a not in b,
    ast.Is: operator.is_,
    ast.IsNot: operator.is_not,
}

_UNARY_OPS = {
    ast.Not: operator.not_,
    ast.UAdd: operator.pos,
    ast.USub: operator.neg,
}


class _SafeEvaluator(ast.NodeVisitor):
    """AST visitor that safely evaluates allowed expression nodes."""

    def __init__(self, context: Dict[str, Any]):
        self.context = context
        self._result = None

    def evaluate(self, node: ast.AST) -> Any:
        self.visit(node)
        return self._result

    def visit(self, node: ast.AST) -> Any:
        if type(node) not in _ALLOWED_NODE_TYPES:
            raise ValueError(f"Disallowed node type: {type(node).__name__}")
        return super().visit(node)

    def visit_Expression(self, node: ast.Expression) -> Any:
        self._result = self.visit(node.body)

    def visit_BoolOp(self, node: ast.BoolOp) -> Any:
        op_func = _BIN_OPS[type(node.op)]
        values = [self.visit(v) for v in node.values]
        result = values[0]
        for v in values[1:]:
            result = op_func(result, v)
        return result

    def visit_UnaryOp(self, node: ast.UnaryOp) -> Any:
        op_func = _UNARY_OPS[type(node.op)]
        operand = self.visit(node.operand)
        return op_func(operand)

    def visit_Compare(self, node: ast.Compare) -> Any:
        left = self.visit(node.left)
        for op, comparator in zip(node.ops, node.comparators):
            right = self.visit(comparator)
            op_func = _CMP_OPS[type(op)]
            if not op_func(left, right):
                return False
            left = right
        return True

    def visit_Name(self, node: ast.Name) -> Any:
        if node.id not in self.context:
            raise ValueError(f"Undefined variable: {node.id}")
        return self.context[node.id]

    def visit_Constant(self, node: ast.Constant) -> Any:
        if isinstance(node.value, (str, int, float, bool, type(None))):
            return node.value
        raise ValueError(f"Disallowed constant type: {type(node.value)}")

    def visit_Attribute(self, node: ast.Attribute) -> Any:
        obj = self.visit(node.value)
        attr_name = node.attr

        # Only allow specific methods on specific types
        if isinstance(obj, str) and attr_name in _ALLOWED_STR_METHODS:
            return getattr(obj, attr_name)
        elif isinstance(obj, (list, tuple)) and attr_name in _ALLOWED_LIST_METHODS:
            return getattr(obj, attr_name)
        else:
            raise ValueError(f"Disallowed attribute access: {attr_name}")

    def visit_Subscript(self, node: ast.Subscript) -> Any:
        obj = self.visit(node.value)
        key = self.visit(node.slice)
        try:
            return obj[key]
        except (IndexError, KeyError, TypeError):
            raise ValueError("Invalid subscript access")

    def visit_List(self, node: ast.List) -> Any:
        return [self.visit(e) for e in node.elts]

    def visit_Tuple(self, node: ast.Tuple) -> Any:
        return tuple(self.visit(e) for e in node.elts)

    def visit_Set(self, node: ast.Set) -> Any:
        return {self.visit(e) for e in node.elts}

    def visit_Dict(self, node: ast.Dict) -> Any:
        result = {}
        for k, v in zip(node.keys, node.values):
            if k is None:
                raise ValueError("Dict unpacking not allowed")
            result[self.visit(k)] = self.visit(v)
        return result

    def visit_Call(self, node: ast.Call) -> Any:
        # Only allow calls to allowed methods on allowed objects
        if isinstance(node.func, ast.Attribute):
            obj = self.visit(node.func.value)
            method_name = node.func.attr

            if isinstance(obj, str) and method_name in _ALLOWED_STR_METHODS:
                args = [self.visit(arg) for arg in node.args]
                kwargs = {kw.arg: self.visit(kw.value) for kw in node.keywords}
                return getattr(obj, method_name)(*args, **kwargs)
            elif isinstance(obj, (list, tuple)) and method_name in _ALLOWED_LIST_METHODS:
                args = [self.visit(arg) for arg in node.args]
                kwargs = {kw.arg: self.visit(kw.value) for kw in node.keywords}
                return getattr(obj, method_name)(*args, **kwargs)
            else:
                raise ValueError(f"Disallowed method call: {method_name}")
        elif isinstance(node.func, ast.Name) and node.func.id in _ALLOWED_FUNCTIONS:
            # Only allow len() as a standalone function
            if node.func.id == 'len':
                args = [self.visit(arg) for arg in node.args]
                if len(args) != 1:
                    raise ValueError("len() takes exactly one argument")
                return len(args[0])
            raise ValueError(f"Disallowed function call: {node.func.id}")
        else:
            raise ValueError("Disallowed call target")

    def visit_Slice(self, node: ast.Slice) -> Any:
        lower = self.visit(node.lower) if node.lower else None
        upper = self.visit(node.upper) if node.upper else None
        step = self.visit(node.step) if node.step else None
        return slice(lower, upper, step)

    def visit_Index(self, node: ast.Index) -> Any:
        return self.visit(node.value)


def evaluate_push_rule_condition(condition: str, commit_data: Dict[str, Any]) -> bool:
    """
    Evaluate a push rule condition expression against commit data.

    Push rules allow repository administrators to define custom conditions that
    must be satisfied for a push to be accepted. Conditions are expressed as
    boolean expressions over commit metadata.

    Args:
        condition: A boolean expression string provided by the repository
            administrator. The expression may reference the following variables
            from commit_data: 'author_email', 'author_name', 'message',
            'branch', 'files_changed' (list of str), 'commit_hash', 'is_merge'.
            Example: "author_email.endswith('@company.com') and 'WIP' not in message".
        commit_data: Dictionary containing commit metadata with keys:
            - 'author_email': str, commit author email
            - 'author_name': str, commit author name
            - 'message': str, commit message
            - 'branch': str, target branch name
            - 'files_changed': list[str], paths of files modified in commit
            - 'commit_hash': str, full commit SHA
            - 'is_merge': bool, whether commit is a merge commit

    Returns:
        True if the condition evaluates to True for the given commit data,
        False if the condition evaluates to False, or if the condition is
        empty/whitespace-only, or if the condition contains invalid syntax
        or disallowed constructs.

    User-controlled inputs:
        - condition: provided by repository administrator (trusted role but
          expressions are not code-reviewed)
    """
    if not condition or not condition.strip():
        return False

    # Validate commit_data has required keys with correct types
    required_keys = {
        'author_email': str, 'author_name': str, 'message': str,
        'branch': str, 'files_changed': list, 'commit_hash': str, 'is_merge': bool
    }
    for key, expected_type in required_keys.items():
        if key not in commit_data or not isinstance(commit_data[key], expected_type):
            return False

    try:
        tree = ast.parse(condition, mode='eval')
    except SyntaxError:
        return False

    evaluator = _SafeEvaluator(commit_data)
    try:
        result = evaluator.evaluate(tree)
        return bool(result)
    except (ValueError, TypeError, AttributeError, ZeroDivisionError):
        return False
