import ast
import operator
from typing import Any


def evaluate_shelf_rule(rule_expression: str, book_metadata: dict) -> bool:
    """
    Evaluate a shelf organization rule against a book's metadata.

    Shelf rules are simple boolean expressions written by librarians to automate
    book placement. The expression can reference book metadata fields like
    'genre', 'author', 'year', 'publisher', 'isbn', 'tags' (list), and
    'rating' (float). Supported operators: and, or, not, ==, !=, <, >, <=, >=,
    in, contains (for strings/lists).

    Args:
        rule_expression: A rule string provided by the librarian (user input).
        book_metadata: Dictionary with book's metadata fields.

    Returns:
        True if the book matches the rule, False otherwise. Returns False
        on any evaluation error or if rule references unknown fields.
    """
    allowed_fields = {
        'genre', 'author', 'year', 'publisher', 'isbn', 'tags', 'rating'
    }

    binary_ops = {
        ast.And: lambda a, b: a and b,
        ast.Or: lambda a, b: a or b,
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
        ast.In: lambda a, b: a in b,
    }

    unary_ops = {
        ast.Not: operator.not_,
    }

    def eval_node(node: ast.AST) -> Any:
        if isinstance(node, ast.BoolOp):
            if type(node.op) not in binary_ops:
                raise ValueError("Unsupported boolean operator")
            op_func = binary_ops[type(node.op)]
            result = eval_node(node.values[0])
            for val in node.values[1:]:
                result = op_func(result, eval_node(val))
            return result

        if isinstance(node, ast.UnaryOp):
            if type(node.op) not in unary_ops:
                raise ValueError("Unsupported unary operator")
            return unary_ops[type(node.op)](eval_node(node.operand))

        if isinstance(node, ast.Compare):
            left = eval_node(node.left)
            for op, comparator in zip(node.ops, node.comparators):
                if type(op) not in binary_ops:
                    raise ValueError("Unsupported comparison operator")
                right = eval_node(comparator)
                if not binary_ops[type(op)](left, right):
                    return False
                left = right
            return True

        if isinstance(node, ast.Name):
            if node.id not in allowed_fields:
                raise ValueError(f"Unknown field: {node.id}")
            if node.id not in book_metadata:
                raise ValueError(f"Missing field: {node.id}")
            return book_metadata[node.id]

        if isinstance(node, ast.Constant):
            if isinstance(node.value, (str, int, float, bool, type(None))):
                return node.value
            raise ValueError("Unsupported constant type")

        if isinstance(node, ast.List):
            return [eval_node(el) for el in node.elts]

        if isinstance(node, ast.Tuple):
            return tuple(eval_node(el) for el in node.elts)

        if isinstance(node, ast.Call):
            if not isinstance(node.func, ast.Name):
                raise ValueError("Only simple function calls allowed")
            if node.func.id == 'contains':
                if len(node.args) != 2:
                    raise ValueError("contains() takes 2 arguments")
                container = eval_node(node.args[0])
                item = eval_node(node.args[1])
                if isinstance(container, (str, list, tuple)):
                    return item in container
                raise ValueError("contains() requires string, list, or tuple")
            raise ValueError(f"Unknown function: {node.func.id}")

        raise ValueError(f"Unsupported AST node: {type(node).__name__}")

    try:
        if not rule_expression or not rule_expression.strip():
            return False
        tree = ast.parse(rule_expression, mode='eval')
        return bool(eval_node(tree.body))
    except (SyntaxError, ValueError, TypeError, KeyError, AttributeError):
        return False
