import ast
import operator
from typing import Any, Callable, Dict, List, Union

def compute_custom_grade_component(
    formula: str,
    student_scores: Dict[str, Union[int, float]],
    grading_config: Dict[str, Union[int, float, List[Union[int, float]]]]
) -> float:
    """
    Evaluate a custom grade formula for a single student.

    The formula is a restricted expression that may reference variables from
    student_scores and grading_config, use arithmetic operators, comparison
    operators (returning 1.0 for true, 0.0 for false), ternary expressions,
    and a specific set of allowed functions.

    Allowed functions:
    - min(*args), max(*args): minimum/maximum of numeric arguments
    - abs(x): absolute value
    - round(x, ndigits=0): round to nearest integer or ndigits
    - sum(*args): sum of all arguments
    - avg(*args): arithmetic mean of arguments (returns 0 if no args)
    - drop_lowest(n, *scores): sum of scores after dropping n lowest values
    - cap(value, maximum): min(value, maximum)
    - floor(value, minimum): max(value, minimum)

    Variables available in the formula:
    - All keys from student_scores (numeric values)
    - All keys from grading_config (numeric values or lists of numbers)

    Arguments:
    - formula: A string expression provided by a teacher via the grading portal UI.
      Example: "avg(homework) * 0.3 + exam * 0.5 + cap(bonus, 5)"
    - student_scores: Dictionary mapping score names to numeric values, sourced
      from the student's record in the database.
    - grading_config: Dictionary mapping config names to numeric values or lists,
      sourced from the course grading configuration.

    Returns:
    - The computed grade component as a float.
    - Returns 0.0 if the formula is syntactically invalid, references unknown
      variables, uses disallowed constructs, or raises an evaluation error.
    """
    # Build variable namespace: flatten lists from grading_config as individual variables
    variables: Dict[str, Any] = {}
    variables.update(student_scores)
    for key, value in grading_config.items():
        if isinstance(value, list):
            # Expose list as-is for functions like avg, sum, drop_lowest
            variables[key] = [float(v) for v in value]
        else:
            variables[key] = float(value)

    # Allowed functions with safe implementations
    def safe_avg(*args: float) -> float:
        if not args:
            return 0.0
        flat_args = []
        for arg in args:
            if isinstance(arg, (list, tuple)):
                flat_args.extend(float(x) for x in arg)
            else:
                flat_args.append(float(arg))
        return sum(flat_args) / len(flat_args) if flat_args else 0.0

    def safe_sum(*args: float) -> float:
        total = 0.0
        for arg in args:
            if isinstance(arg, (list, tuple)):
                total += sum(float(x) for x in arg)
            else:
                total += float(arg)
        return total

    def safe_drop_lowest(n: float, *scores: float) -> float:
        n_int = int(n)
        flat_scores = []
        for s in scores:
            if isinstance(s, (list, tuple)):
                flat_scores.extend(float(x) for x in s)
            else:
                flat_scores.append(float(s))
        if n_int >= len(flat_scores):
            return 0.0
        return sum(sorted(flat_scores)[n_int:])

    def safe_cap(value: float, maximum: float) -> float:
        return min(float(value), float(maximum))

    def safe_floor(value: float, minimum: float) -> float:
        return max(float(value), float(minimum))

    allowed_functions: Dict[str, Callable] = {
        'min': min,
        'max': max,
        'abs': abs,
        'round': round,
        'sum': safe_sum,
        'avg': safe_avg,
        'drop_lowest': safe_drop_lowest,
        'cap': safe_cap,
        'floor': safe_floor,
    }

    # AST node validator
    class FormulaValidator(ast.NodeVisitor):
        def __init__(self):
            self.errors: List[str] = []

        def visit(self, node: ast.AST) -> None:
            allowed_types = (
                ast.Expression, ast.BinOp, ast.UnaryOp, ast.Compare,
                ast.IfExp, ast.Call, ast.Name, ast.Constant,
                ast.Load, ast.Add, ast.Sub, ast.Mult, ast.Div,
                ast.FloorDiv, ast.Mod, ast.Pow, ast.USub, ast.UAdd,
                ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE,
                ast.keyword, ast.List, ast.Tuple,
            )
            if not isinstance(node, allowed_types):
                self.errors.append(f"Disallowed node type: {type(node).__name__}")
                return
            super().visit(node)

        def visit_Name(self, node: ast.Name) -> None:
            if node.id not in variables and node.id not in allowed_functions:
                self.errors.append(f"Unknown variable or function: {node.id}")
            self.generic_visit(node)

        def visit_Call(self, node: ast.Call) -> None:
            if not isinstance(node.func, ast.Name):
                self.errors.append("Only direct function calls allowed")
                return
            if node.func.id not in allowed_functions:
                self.errors.append(f"Disallowed function: {node.func.id}")
            # No keyword arguments allowed
            if node.keywords:
                self.errors.append("Keyword arguments not allowed")
            self.generic_visit(node)

        def visit_Constant(self, node: ast.Constant) -> None:
            if not isinstance(node.value, (int, float)):
                self.errors.append(f"Only numeric constants allowed, got {type(node.value).__name__}")
            self.generic_visit(node)

    # Parse and validate
    try:
        tree = ast.parse(formula, mode='eval')
    except SyntaxError:
        return 0.0

    validator = FormulaValidator()
    validator.visit(tree)
    if validator.errors:
        return 0.0

    # Safe evaluator
    class SafeEvaluator(ast.NodeVisitor):
        def visit_Expression(self, node: ast.Expression) -> Any:
            return self.visit(node.body)

        def visit_BinOp(self, node: ast.BinOp) -> Any:
            left = self.visit(node.left)
            right = self.visit(node.right)
            ops = {
                ast.Add: operator.add,
                ast.Sub: operator.sub,
                ast.Mult: operator.mul,
                ast.Div: operator.truediv,
                ast.FloorDiv: operator.floordiv,
                ast.Mod: operator.mod,
                ast.Pow: operator.pow,
            }
            op_func = ops.get(type(node.op))
            if op_func is None:
                raise ValueError(f"Unsupported operator: {type(node.op).__name__}")
            return op_func(left, right)

        def visit_UnaryOp(self, node: ast.UnaryOp) -> Any:
            operand = self.visit(node.operand)
            ops = {ast.USub: operator.neg, ast.UAdd: operator.pos}
            op_func = ops.get(type(node.op))
            if op_func is None:
                raise ValueError(f"Unsupported unary operator: {type(node.op).__name__}")
            return op_func(operand)

        def visit_Compare(self, node: ast.Compare) -> Any:
            if len(node.ops) != 1 or len(node.comparators) != 1:
                raise ValueError("Chained comparisons not allowed")
            left = self.visit(node.left)
            right = self.visit(node.comparators[0])
            ops = {
                ast.Eq: operator.eq,
                ast.NotEq: operator.ne,
                ast.Lt: operator.lt,
                ast.LtE: operator.le,
                ast.Gt: operator.gt,
                ast.GtE: operator.ge,
            }
            op_func = ops.get(type(node.ops[0]))
            if op_func is None:
                raise ValueError(f"Unsupported comparison: {type(node.ops[0]).__name__}")
            return 1.0 if op_func(left, right) else 0.0

        def visit_IfExp(self, node: ast.IfExp) -> Any:
            test = self.visit(node.test)
            if test:
                return self.visit(node.body)
            return self.visit(node.orelse)

        def visit_Call(self, node: ast.Call) -> Any:
            func = allowed_functions[node.func.id]
            args = [self.visit(arg) for arg in node.args]
            return func(*args)

        def visit_Name(self, node: ast.Name) -> Any:
            return variables[node.id]

        def visit_Constant(self, node: ast.Constant) -> Any:
            return float(node.value)

        def visit_List(self, node: ast.List) -> Any:
            return [self.visit(elt) for elt in node.elts]

        def visit_Tuple(self, node: ast.Tuple) -> Any:
            return tuple(self.visit(elt) for elt in node.elts)

    try:
        evaluator = SafeEvaluator()
        result = evaluator.visit(tree)
        return float(result)
    except Exception:
        return 0.0
