import re
from typing import Any


def _is_safe_regex(pattern: str) -> bool:
    """
    Heuristic check for regex patterns vulnerable to catastrophic backtracking.
    Rejects patterns with nested quantifiers, excessive alternation with quantifiers,
    or other constructs known to cause exponential runtime on crafted inputs.
    """
    try:
        re.compile(pattern)
    except re.error:
        return False

    # Nested quantifiers: (a+)+, (a*)*, (a?)+, etc.
    if re.search(r'\([^)]*[\+\*]\{[^}]*[\+\*]\)', pattern):
        return False
    if re.search(r'\([^)]*[\+\*]\)[\+\*]\{', pattern):
        return False
    if re.search(r'\([^)]*[\+\*]\)[\+\*]', pattern):
        return False

    # Excessive alternation inside a quantified group: (a|aa|aaa...)+
    # Count alternations; if many and the group is followed by a quantifier, reject.
    if pattern.count('|') > 5:
        # Look for a closing parenthesis followed by a quantifier (+, *, ?, {)
        if re.search(r'\)[\+\*\?\{]', pattern):
            return False
        # Also check for overlapping prefixes (heuristic)
        parts = pattern.split('|')
        if len(parts) > 5:
            prefixes = []
            for p in parts:
                # Strip leading '(' and trailing ')', take first literal char
                stripped = p.lstrip('(').rstrip(')')
                # Find first non-metacharacter
                for ch in stripped:
                    if ch not in '^$.*+?{}[]\\|()':
                        prefixes.append(ch)
                        break
                else:
                    prefixes.append('')
            if prefixes and all(p == prefixes[0] for p in prefixes):
                return False

    # Pattern length heuristic
    if len(pattern) > 500:
        return False
    return True


def apply_header_sanitization_rules(headers: dict[str, str], rules: list[dict[str, Any]]) -> dict[str, str]:
    """
    Apply header sanitization rules to a dictionary of HTTP headers.

    Each rule specifies a regex pattern to match header names, an action to take,
    and optional replacement text. Rules are applied in order; later rules can
    match headers added or modified by earlier rules.

    Args:
        headers: Dictionary of header name -> value pairs from the incoming request.
                 Header names are case-insensitive per RFC 7230; this function
                 preserves the original casing in the output.
        rules: List of rule dictionaries. Each rule must contain:
            - 'pattern' (str): Regular expression pattern to match against header names.
                               Provided by the API administrator via gateway configuration.
            - 'action' (str): One of 'redact', 'remove', 'transform'.
            - 'replacement' (str, optional): Required when action is 'transform'; the
                               replacement string for re.sub. May contain backreferences.

    Returns:
        A new dictionary with headers processed according to the rules:
        - 'redact': Header value replaced with '***REDACTED***'.
        - 'remove': Header omitted from output.
        - 'transform': Header value replaced by re.sub(pattern, replacement, value).

    User inputs: The `rules` list (including all regex patterns) comes from the
                 API administrator via gateway configuration.
    """
    if not isinstance(headers, dict):
        return {}
    if not isinstance(rules, list):
        return {str(k): str(v) for k, v in headers.items() if isinstance(k, str)}

    compiled_rules = []
    for rule in rules:
        if not isinstance(rule, dict):
            continue
        pattern = rule.get('pattern')
        action = rule.get('action')
        if not isinstance(pattern, str) or action not in ('redact', 'remove', 'transform'):
            continue
        if not _is_safe_regex(pattern):
            continue
        try:
            compiled = re.compile(pattern, re.IGNORECASE)
        except re.error:
            continue
        replacement = rule.get('replacement')
        if action == 'transform' and not isinstance(replacement, str):
            continue
        compiled_rules.append((compiled, action, replacement))

    result = {}
    for name, value in headers.items():
        if not isinstance(name, str):
            continue
        current_name = name
        current_value = str(value)
        for compiled, action, replacement in compiled_rules:
            if compiled.search(current_name):
                if action == 'redact':
                    current_value = '***REDACTED***'
                elif action == 'remove':
                    current_value = None
                    break
                elif action == 'transform' and replacement is not None:
                    try:
                        current_value = compiled.sub(replacement, current_value)
                    except re.error:
                        # Invalid backreference or other substitution error: skip this rule
                        pass
        if current_value is not None:
            result[current_name] = current_value
    return result
