import yaml

def load_exercise_substitution_rules(yaml_content: str) -> dict[str, list[dict]]:
    """
    Parse and validate a user-provided YAML string defining exercise substitution rules.

    The YAML must represent a dictionary mapping primary exercise names (strings) to
    lists of substitution options. Each substitution option is a dictionary with keys:
    - 'exercise': alternative exercise name (non-empty string)
    - 'equipment': required equipment name (string) or null for bodyweight
    - 'difficulty_adjustment': positive float multiplier for intensity (default 1.0)
    - 'injury_tags': list of injury type strings this substitution avoids (default [])
    - 'progression_level': integer from 1 to 5 indicating minimum progression level (default 1)

    Invalid entries (missing keys, wrong types, out-of-range values) are skipped.
    If the top-level structure is not a dictionary, or parsing fails, returns empty dict.

    Args:
        yaml_content: Raw YAML string provided by the user (e.g., from an imported file).

    Returns:
        Dictionary mapping primary exercise names to lists of validated substitution
        option dictionaries with normalized keys and default values applied.

    User-controlled input: yaml_content (entire string).
    """
    if not isinstance(yaml_content, str) or not yaml_content.strip():
        return {}

    try:
        parsed = yaml.safe_load(yaml_content)
    except yaml.YAMLError:
        return {}

    if not isinstance(parsed, dict):
        return {}

    result: dict[str, list[dict]] = {}

    for primary_exercise, substitutions in parsed.items():
        if not isinstance(primary_exercise, str) or not primary_exercise.strip():
            continue
        if not isinstance(substitutions, list):
            continue

        valid_subs: list[dict] = []
        for sub in substitutions:
            if not isinstance(sub, dict):
                continue

            exercise_name = sub.get('exercise')
            if not isinstance(exercise_name, str) or not exercise_name.strip():
                continue

            equipment = sub.get('equipment')
            if equipment is not None and not isinstance(equipment, str):
                continue

            diff_adj = sub.get('difficulty_adjustment', 1.0)
            if not isinstance(diff_adj, (int, float)) or diff_adj <= 0:
                diff_adj = 1.0

            injury_tags = sub.get('injury_tags', [])
            if not isinstance(injury_tags, list) or not all(isinstance(t, str) for t in injury_tags):
                injury_tags = []

            prog_level = sub.get('progression_level', 1)
            if not isinstance(prog_level, int) or not (1 <= prog_level <= 5):
                prog_level = 1

            valid_subs.append({
                'exercise': exercise_name.strip(),
                'equipment': equipment.strip() if isinstance(equipment, str) else None,
                'difficulty_adjustment': float(diff_adj),
                'injury_tags': [t.strip() for t in injury_tags if isinstance(t, str) and t.strip()],
                'progression_level': prog_level,
            })

        if valid_subs:
            result[primary_exercise.strip()] = valid_subs

    return result
