import ast
import math
from typing import Any


def evaluate_custom_metric(expression: str, metric_values: dict[str, float]) -> float | None:
    """
    Evaluate a user-defined custom metric expression against a set of logged metric values.

    This function is used in the notebook server's experiment tracking feature to compute
    derived metrics from base metrics logged during training runs. Users can define custom
    metrics as mathematical expressions referencing previously logged metric names.

    Args:
        expression: A mathematical expression string provided by the user (e.g.,
            "(precision + recall) / 2", "f1 * 0.7 + accuracy * 0.3", "sqrt(mse)").
            This input comes directly from the user via the notebook UI.
        metric_values: A dictionary mapping metric names to their numeric values,
            populated from the experiment tracking database for the current run.

    Returns:
        The computed float value of the expression if evaluation succeeds, or None if
        the expression references unknown metrics, contains invalid syntax, or would
        produce a non-numeric result.

    The expression may reference metric names as variables (alphanumeric + underscore),
    use basic arithmetic operators (+, -, *, /, **), parentheses, and functions from
    the math module (sqrt, log, exp, sin, cos, tan, abs, min, max).
    """
    allowed_functions = {
        "sqrt": math.sqrt,
        "log": math.log,
        "exp": math.exp,
        "sin": math.sin,
        "cos": math.cos,
        "tan": math.tan,
        "abs": abs,
        "min": min,
        "max": max,
    }

    try:
        tree = ast.parse(expression, mode="eval")
    except SyntaxError:
        return None

    if not _validate_ast(tree, metric_values, allowed_functions):
        return None

    safe_globals = {"__builtins__": {}}
    safe_locals = {**metric_values, **allowed_functions}

    try:
        result = eval(compile(tree, "<expression>", "eval"), safe_globals, safe_locals)
    except (ZeroDivisionError, ValueError, OverflowError, TypeError, NameError):
        return None

    if not isinstance(result, (int, float)) or math.isnan(result) or math.isinf(result):
        return None

    return float(result)


def _validate_ast(node: ast.AST, metric_values: dict[str, float], allowed_functions: dict[str, Any]) -> bool:
    allowed_node_types = {
        ast.Expression,
        ast.BinOp,
        ast.UnaryOp,
        ast.Call,
        ast.Name,
        ast.Constant,
        ast.Load,
        # Operator nodes visited by ast.walk()
        ast.Add,
        ast.Sub,
        ast.Mult,
        ast.Div,
        ast.Pow,
        ast.Mod,
        ast.UAdd,
        ast.USub,
    }

    allowed_unary_ops = {ast.UAdd, ast.USub}
    allowed_binary_ops = {ast.Add, ast.Sub, ast.Mult, ast.Div, ast.Pow, ast.Mod}

    for n in ast.walk(node):
        if type(n) not in allowed_node_types:
            return False

        if isinstance(n, ast.Call):
            if not isinstance(n.func, ast.Name):
                return False
            if n.func.id not in allowed_functions:
                return False
            if n.keywords:
                return False
        elif isinstance(n, ast.Name):
            if n.id not in metric_values and n.id not in allowed_functions:
                return False
        elif isinstance(n, ast.Constant):
            if not isinstance(n.value, (int, float)):
                return False
        elif isinstance(n, ast.UnaryOp):
            if type(n.op) not in allowed_unary_ops:
                return False
        elif isinstance(n, ast.BinOp):
            if type(n.op) not in allowed_binary_ops:
                return False

    return True
