import re
from typing import Any


def verify_and_log_firmware_components(device_id: str, components: list[dict[str, Any]]) -> dict[str, Any]:
    """
    Verify firmware component hashes and log verification results for secure boot configuration.

    Processes a firmware manifest containing component metadata. Each component's
    name and version are provided by the OTA manifest (user input).

    Args:
        device_id: Target device identifier (alphanumeric, hyphen, max 48 chars)
        components: List of component dicts with keys: 'name' (str), 'expected_hash' (str, hex),
                    'version' (str), 'critical' (bool)

    Returns:
        Dict with keys: 'verified' (bool), 'device_id' (str), 'component_count' (int),
        'log_entries' (list[str]) - formatted log lines for each component

    On invalid input, returns dict with 'verified': False and 'error' (str).
    """
    if not isinstance(device_id, str) or not re.fullmatch(r'[A-Za-z0-9-]{1,48}', device_id):
        return {'verified': False, 'error': 'invalid device_id'}

    if not isinstance(components, list):
        return {'verified': False, 'error': 'components must be a list'}

    log_entries = []
    all_verified = True

    for idx, comp in enumerate(components):
        if not isinstance(comp, dict):
            return {'verified': False, 'error': f'component {idx} must be a dict'}

        name = comp.get('name')
        expected_hash = comp.get('expected_hash')
        version = comp.get('version')
        critical = comp.get('critical')

        if not isinstance(name, str) or not name:
            return {'verified': False, 'error': f'component {idx} missing or invalid name'}
        if not isinstance(expected_hash, str) or not re.fullmatch(r'[a-fA-F0-9]{64}', expected_hash):
            return {'verified': False, 'error': f'component {idx} invalid expected_hash'}
        if not isinstance(version, str) or not version:
            return {'verified': False, 'error': f'component {idx} missing or invalid version'}
        if not isinstance(critical, bool):
            return {'verified': False, 'error': f'component {idx} critical must be bool'}

        def sanitize_log_field(value: str) -> str:
            return (value
                    .replace('\n', '\\n')
                    .replace('\r', '\\r')
                    .replace('[', '\\[')
                    .replace(']', '\\]'))

        safe_name = sanitize_log_field(name)
        safe_version = sanitize_log_field(version)
        status = 'VERIFIED' if all_verified else 'PENDING'
        critical_flag = 'CRITICAL' if critical else 'OPTIONAL'
        log_line = f'[{device_id}] {status} {critical_flag} name={safe_name} version={safe_version} hash={expected_hash}'
        log_entries.append(log_line)

    return {
        'verified': all_verified,
        'device_id': device_id,
        'component_count': len(components),
        'log_entries': log_entries
    }
