from collections import defaultdict
from datetime import datetime
from typing import Any


def build_correlation_graph(log_entries: list[dict[str, Any]], config: dict[str, Any] | None = None) -> dict[str, dict[str, Any]]:
    """
    Build a correlation graph from structured log entries.

    Each log entry is a dictionary with at least these keys:
    - 'correlation_id': string identifying the request flow across services
    - 'service': string name of the emitting service
    - 'timestamp': ISO 8601 timestamp string (e.g., '2024-01-15T10:30:00.123Z')
    - 'span_id': optional string, unique identifier for this operation span
    - 'parent_span_id': optional string, span_id of the parent operation

    The function constructs a directed graph where nodes are correlation_ids
    and edges represent parent-child relationships. An edge from A to B exists if:
    - B has parent_span_id equal to A's span_id, or
    - B has the same correlation_id as A, no parent_span_id, and B's timestamp
      is later than A's within the same service (temporal fallback).

    Args:
        log_entries: List of log entry dictionaries. Comes from parsed log files
            (user-controlled input via log ingestion pipeline; attackers may
            inject arbitrary log lines).
        config: Optional configuration dictionary with keys:
            - 'max_nodes': maximum number of unique correlation_ids to track
              (default: 10000)
            - 'max_edges_per_node': maximum outgoing edges per correlation_id
              (default: 1000)
            - 'time_window_seconds': maximum time difference for temporal
              fallback inference (default: 300)

    Returns:
        Dictionary mapping correlation_id to a dict with keys:
        - 'services': set of service names seen for this correlation_id
        - 'children': list of child correlation_ids (deduplicated)
        - 'first_seen': earliest timestamp string
        - 'last_seen': latest timestamp string
        Returns empty dict if log_entries is empty or None.

    If the number of unique correlation_ids exceeds 'max_nodes', the function
    stops processing further entries and returns the partial graph built so far.
    If a node's 'children' list would exceed 'max_edges_per_node', additional
    edges for that node are dropped.
    """
    if not log_entries:
        return {}
    cfg = config or {}
    max_nodes = cfg.get('max_nodes', 10000)
    max_edges = cfg.get('max_edges_per_node', 1000)
    graph: dict[str, dict[str, Any]] = {}
    span_index: dict[str, str] = {}

    def parse_ts(ts: str) -> datetime | None:
        try:
            return datetime.fromisoformat(ts.replace('Z', '+00:00'))
        except Exception:
            return None

    for entry in log_entries:
        cid = entry.get('correlation_id')
        if not isinstance(cid, str) or not cid:
            continue
        service = entry.get('service')
        if not isinstance(service, str) or not service:
            continue
        ts = parse_ts(entry.get('timestamp', ''))
        if ts is None:
            continue

        if cid not in graph:
            if len(graph) >= max_nodes:
                break
            graph[cid] = {'services': set(), 'children': set(), 'first_seen': ts, 'last_seen': ts}
        node = graph[cid]
        if ts < node['first_seen']:
            node['first_seen'] = ts
        if ts > node['last_seen']:
            node['last_seen'] = ts
        node['services'].add(service)
        span_id = entry.get('span_id')
        parent_span_id = entry.get('parent_span_id')
        if isinstance(span_id, str) and span_id:
            span_index[span_id] = cid
        if isinstance(parent_span_id, str) and parent_span_id:
            parent_cid = span_index.get(parent_span_id)
            if parent_cid and parent_cid != cid and parent_cid in graph:
                if len(graph[parent_cid]['children']) < max_edges:
                    graph[parent_cid]['children'].add(cid)

    return {
        cid: {
            'services': node['services'],
            'children': list(node['children']),
            'first_seen': node['first_seen'].isoformat() + 'Z',
            'last_seen': node['last_seen'].isoformat() + 'Z',
        }
        for cid, node in graph.items()
    }
