import ast
import operator
from typing import Dict, Any


def compute_photo_quality_score(formula: str, metrics: Dict[str, float]) -> float:
    """
    Compute a photo quality score using a user-defined arithmetic formula.

    Args:
        formula: User-provided arithmetic expression using metric names as variables.
                 Example: "sharpness * 0.4 + exposure * 0.3 + composition * 0.3"
                 Supported operators: +, -, *, /, parentheses. Metric names must be valid
                 Python identifiers consisting of ASCII letters, digits, and underscores.
        metrics: Dictionary of metric names to float values (e.g.,
                 {"sharpness": 0.8, "exposure": 0.9, "composition": 0.7}).
                 Provided by the system's photo analysis pipeline; not user-controlled.

    Returns:
        The computed score as a float, or 0.0 if formula is invalid, contains unsupported
        constructs, references unknown metrics, or would raise a math error (e.g., division by zero).

    User-controlled input: formula (from user preferences for auto-curation rules).
    """
    if not formula or not isinstance(formula, str):
        return 0.0

    # Whitelist of allowed operators
    allowed_operators = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.USub: operator.neg,
        ast.UAdd: operator.pos,
    }

    try:
        tree = ast.parse(formula, mode='eval')
    except (SyntaxError, ValueError, TypeError):
        return 0.0

    def eval_node(node: ast.AST) -> float:
        if isinstance(node, ast.Expression):
            return eval_node(node.body)
        elif isinstance(node, ast.Constant):
            if isinstance(node.value, (int, float)):
                return float(node.value)
            raise ValueError("Only numeric constants allowed")
        elif isinstance(node, ast.Name):
            if node.id not in metrics:
                raise ValueError(f"Unknown metric: {node.id}")
            return float(metrics[node.id])
        elif isinstance(node, ast.BinOp):
            op_type = type(node.op)
            if op_type not in allowed_operators:
                raise ValueError(f"Unsupported operator: {op_type}")
            left = eval_node(node.left)
            right = eval_node(node.right)
            if op_type == ast.Div and right == 0:
                raise ZeroDivisionError("Division by zero")
            return allowed_operators[op_type](left, right)
        elif isinstance(node, ast.UnaryOp):
            op_type = type(node.op)
            if op_type not in allowed_operators:
                raise ValueError(f"Unsupported unary operator: {op_type}")
            operand = eval_node(node.operand)
            return allowed_operators[op_type](operand)
        else:
            raise ValueError(f"Unsupported AST node: {type(node).__name__}")

    try:
        result = eval_node(tree)
        if not isinstance(result, (int, float)) or not (result == result):  # NaN check
            return 0.0
        return float(result)
    except (ValueError, ZeroDivisionError, RecursionError, OverflowError):
        return 0.0
