import yaml
import re
from typing import Any


def parse_transformation_rules(config_yaml: str) -> list[dict]:
    """
    Parse and validate API gateway request transformation rules from YAML.

    The gateway applies these rules in order to incoming requests before forwarding
    to upstream services. Each rule specifies match conditions and a list of
    transformation actions.

    Args:
        config_yaml: YAML string containing a list of transformation rule objects.
            Each rule object must have:
            - 'match': dict with optional 'path_regex' (str) and/or 'methods' (list of str)
            - 'actions': list of action dicts, each requiring 'type' (str) and type-specific fields:
                * 'add_header': requires 'name' (str) and 'value' (str)
                * 'remove_header': requires 'name' (str)
                * 'rewrite_path': requires 'pattern' (str) and 'replacement' (str)
                * 'add_query_param': requires 'name' (str) and 'value' (str)

    Returns:
        List of validated rule dicts with normalized structure. Returns empty list
        if the YAML is invalid, not a list, or any rule/action fails validation.

    User input: config_yaml is provided by gateway administrators via the config
    management API or uploaded configuration files.
    """
    if not isinstance(config_yaml, str) or not config_yaml.strip():
        return []

    try:
        parsed = yaml.safe_load(config_yaml)
    except yaml.YAMLError:
        return []

    if not isinstance(parsed, list):
        return []

    valid_rules = []
    valid_action_types = {'add_header', 'remove_header', 'rewrite_path', 'add_query_param'}
    required_fields = {
        'add_header': {'name', 'value'},
        'remove_header': {'name'},
        'rewrite_path': {'pattern', 'replacement'},
        'add_query_param': {'name', 'value'},
    }

    for rule in parsed:
        if not isinstance(rule, dict):
            continue

        match = rule.get('match')
        if match is not None and not isinstance(match, dict):
            continue

        if match:
            path_regex = match.get('path_regex')
            if path_regex is not None:
                if not isinstance(path_regex, str):
                    continue
                try:
                    re.compile(path_regex)
                except re.error:
                    continue

            methods = match.get('methods')
            if methods is not None:
                if not isinstance(methods, list) or not all(isinstance(m, str) for m in methods):
                    continue
                if not all(m.upper() in {'GET', 'POST', 'PUT', 'DELETE', 'PATCH', 'HEAD', 'OPTIONS'} for m in methods):
                    continue

        actions = rule.get('actions')
        if not isinstance(actions, list):
            continue

        valid_actions = []
        for action in actions:
            if not isinstance(action, dict):
                continue

            action_type = action.get('type')
            if action_type not in valid_action_types:
                continue

            missing = required_fields[action_type] - set(action.keys())
            if missing:
                continue

            if not all(isinstance(action[k], str) for k in required_fields[action_type]):
                continue

            if action_type == 'rewrite_path':
                try:
                    re.compile(action['pattern'])
                except re.error:
                    continue

            valid_actions.append({k: action[k] for k in {'type'} | required_fields[action_type]})

        if not valid_actions:
            continue

        normalized_rule = {'actions': valid_actions}
        if match:
            normalized_match = {}
            if match.get('path_regex'):
                normalized_match['path_regex'] = match['path_regex']
            if match.get('methods'):
                normalized_match['methods'] = [m.upper() for m in match['methods']]
            if normalized_match:
                normalized_rule['match'] = normalized_match

        valid_rules.append(normalized_rule)

    return valid_rules
