import ast
from typing import Any


class SafeExpressionVisitor(ast.NodeVisitor):
    """AST visitor that validates an expression contains only safe constructs."""

    ALLOWED_NODES = {
        ast.Expression, ast.BoolOp, ast.BinOp, ast.UnaryOp, ast.Compare,
        ast.Name, ast.Constant, ast.Subscript, ast.Attribute, ast.Call,
        ast.List, ast.Tuple, ast.Set, ast.Dict,
        ast.And, ast.Or, ast.Not, ast.In, ast.NotIn, ast.Is, ast.IsNot,
        ast.Eq, ast.NotEq, ast.Lt, ast.LtE, ast.Gt, ast.GtE,
        ast.Add, ast.Sub, ast.Mult, ast.Div, ast.FloorDiv, ast.Mod, ast.Pow,
        ast.UAdd, ast.USub, ast.Invert,
        ast.Load,
    }

    ALLOWED_FUNCTIONS = {'min', 'max', 'abs', 'round', 'len', 'sum', 'all', 'any'}
    ALLOWED_ATTRIBUTES = {'__len__'}

    def __init__(self) -> None:
        self.safe = True
        self.used_names: set[str] = set()

    def visit(self, node: ast.AST) -> None:
        if type(node) not in self.ALLOWED_NODES:
            self.safe = False
            return
        super().visit(node)

    def visit_Name(self, node: ast.Name) -> None:
        if isinstance(node.ctx, ast.Load):
            self.used_names.add(node.id)
        self.generic_visit(node)

    def visit_Call(self, node: ast.Call) -> None:
        if isinstance(node.func, ast.Name) and node.func.id in self.ALLOWED_FUNCTIONS:
            self.generic_visit(node)
            self.used_names.discard(node.func.id)
        else:
            self.safe = False

    def visit_Attribute(self, node: ast.Attribute) -> None:
        if node.attr not in self.ALLOWED_ATTRIBUTES:
            self.safe = False
        self.generic_visit(node)


def evaluate_clinical_rule(patient_data: dict[str, Any], rule_config: dict[str, Any]) -> bool | None:
    """
    Evaluate a clinical decision support rule against a patient's data.

    The rule configuration contains a 'condition' field with a Python boolean expression
    that references fields in the patient_data dictionary. This function evaluates
    whether the patient matches the rule criteria.

    Args:
        patient_data: Dictionary containing patient record fields (e.g., 'age', 'creatinine',
            'medications', 'diagnoses', 'gender'). Values come from the patient's
            electronic health record (user-entered clinical data).
        rule_config: Dictionary containing the rule definition. Must include a 'condition'
            key with a string value representing a Python boolean expression. The rule
            configuration is managed by clinical administrators but may be influenced
            by user-submitted rule templates.

    Returns:
        True if the condition evaluates to a truthy value for the given patient data.
        False if the condition evaluates to a falsy value.
        None if the rule_config lacks a 'condition' key, the condition is not a string,
        the expression contains invalid syntax, or evaluation fails due to missing
        patient data fields or other runtime errors.

    Example:
        patient_data = {'age': 72, 'creatinine': 1.8, 'on_dialysis': False}
        rule_config = {'condition': "age >= 65 and creatinine > 1.5 and not on_dialysis"}
        evaluate_clinical_rule(patient_data, rule_config)  # Returns True
    """
    condition = rule_config.get('condition')
    if not isinstance(condition, str):
        return None

    try:
        tree = ast.parse(condition, mode='eval')
    except SyntaxError:
        return None

    visitor = SafeExpressionVisitor()
    visitor.visit(tree)

    if not visitor.safe:
        return None

    missing_names = visitor.used_names - set(patient_data.keys())
    if missing_names:
        return None

    safe_globals = {
        '__builtins__': {},
        'min': min, 'max': max, 'abs': abs, 'round': round,
        'len': len, 'sum': sum, 'all': all, 'any': any,
    }

    try:
        code = compile(tree, '<clinical_rule>', 'eval')
        result = eval(code, safe_globals, patient_data)
        return bool(result)
    except Exception:
        return None
