import ast
import operator
from typing import Callable, Optional


def compile_waitlist_priority_formula(formula: str, allowed_variables: list[str]) -> Optional[Callable[[dict], float]]:
    """
    Compile a waitlist priority formula into a callable priority function.

    The formula is a Python expression string that references student attributes
    from the allowed_variables list. The returned callable takes a student dict
    and returns a numeric priority score (higher = better priority).

    Args:
        formula: A Python expression string provided by department admin (USER INPUT).
                 Example: "credits_completed * 0.1 + major_gpa * 10 + (100 if is_major else 0)"
        allowed_variables: List of variable names the formula may reference.
                           Typical values: ["credits_completed", "major_gpa", "is_major", "years_waiting"]

    Returns:
        A callable f(student_dict) -> float, or None if formula is invalid or empty.
        The callable returns 0.0 for missing variables or evaluation errors.

    User input: formula (provided by department admin via web form)
    """
    if not formula or not formula.strip():
        return None

    allowed_variables_set = set(allowed_variables)

    _BIN_OPS = {
        ast.Add: operator.add,
        ast.Sub: operator.sub,
        ast.Mult: operator.mul,
        ast.Div: operator.truediv,
        ast.FloorDiv: operator.floordiv,
        ast.Mod: operator.mod,
        ast.Pow: operator.pow,
    }
    _UNARY_OPS = {
        ast.UAdd: operator.pos,
        ast.USub: operator.neg,
        ast.Not: operator.not_,
        ast.Invert: operator.invert,
    }
    _COMPARE_OPS = {
        ast.Eq: operator.eq,
        ast.NotEq: operator.ne,
        ast.Lt: operator.lt,
        ast.LtE: operator.le,
        ast.Gt: operator.gt,
        ast.GtE: operator.ge,
        ast.Is: operator.is_,
        ast.IsNot: operator.is_not,
        ast.In: lambda a, b: a in b,
        ast.NotIn: lambda a, b: a not in b,
    }
    _BOOL_OPS = {
        ast.And: all,
        ast.Or: any,
    }
    _ALLOWED_FUNCTIONS = {
        "abs": abs,
        "min": min,
        "max": max,
        "round": round,
    }

    class FormulaValidator(ast.NodeVisitor):
        def __init__(self):
            self.valid = True

        def visit(self, node):
            if not self.valid:
                return
            method = f"visit_{node.__class__.__name__}"
            visitor = getattr(self, method, self.generic_visit)
            return visitor(node)

        def generic_visit(self, node):
            self.valid = False

        def visit_Expression(self, node):
            self.visit(node.body)

        def visit_BinOp(self, node):
            if type(node.op) not in _BIN_OPS:
                self.valid = False
                return
            self.visit(node.left)
            self.visit(node.right)

        def visit_UnaryOp(self, node):
            if type(node.op) not in _UNARY_OPS:
                self.valid = False
                return
            self.visit(node.operand)

        def visit_Compare(self, node):
            for op in node.ops:
                if type(op) not in _COMPARE_OPS:
                    self.valid = False
                    return
            self.visit(node.left)
            for comparator in node.comparators:
                self.visit(comparator)

        def visit_BoolOp(self, node):
            if type(node.op) not in _BOOL_OPS:
                self.valid = False
                return
            for value in node.values:
                self.visit(value)

        def visit_IfExp(self, node):
            self.visit(node.test)
            self.visit(node.body)
            self.visit(node.orelse)

        def visit_Call(self, node):
            if not isinstance(node.func, ast.Name):
                self.valid = False
                return
            if node.func.id not in _ALLOWED_FUNCTIONS:
                self.valid = False
                return
            for arg in node.args:
                self.visit(arg)
            for kw in node.keywords:
                self.valid = False
                return

        def visit_Name(self, node):
            if isinstance(node.ctx, ast.Load):
                if node.id not in allowed_variables_set:
                    self.valid = False

        def visit_Constant(self, node):
            if not isinstance(node.value, (int, float, bool, str, type(None))):
                self.valid = False

        def visit_List(self, node):
            for elt in node.elts:
                self.visit(elt)

        def visit_Tuple(self, node):
            for elt in node.elts:
                self.visit(elt)

    try:
        tree = ast.parse(formula, mode="eval")
    except SyntaxError:
        return None

    validator = FormulaValidator()
    validator.visit(tree)
    if not validator.valid:
        return None

    code = compile(tree, "<formula>", "eval")

    def priority_fn(student: dict) -> float:
        try:
            namespace = {var: student.get(var, 0) for var in allowed_variables}
            namespace.update(_ALLOWED_FUNCTIONS)
            result = eval(code, {"__builtins__": {}}, namespace)
            return float(result)
        except Exception:
            return 0.0

    return priority_fn
```
